pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact / near-exact fits are gold: reward heavily.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0; // tiny leftover is still excellent
    }

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (too small for typical future items) are heavily penalized.
    if post_residual >= 1 && post_residual <= 15 {
        score += 120.0; // dead space trap
    } else if post_residual <= 30 {
        score += 30.0;  // marginal usability
    } else if post_residual >= 60 {
        score -= 20.0;  // roomy leftover, flexible for future items
    }

    // Bonus if this leftover can still host a plausible next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0; // leftover too small for the known next item
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: mildly discourage spreading across many bins,
    // but only when the bin already has content (not the fresh-bin candidate).
    if bin_residual != bin_capacity {
        score += 0.5 * open_bins_count as f64;
    }

    // New-bin candidate handling: make the empty bin attractive only when
    // alternatives are poor. Slightly discourage it by default.
    if bin_residual == bin_capacity {
        score += 40.0;
        // But if no open bin fits well, the +40 can be outweighed by the
        // dead-space penalties above; also ease pressure late in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * progress;
    }

    // Slight tie-break toward bins tighter than the mean (better consolidated).
    if (bin_residual as f64) < mean_residual && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capf = bin_capacity as f64;
    let pr = post_residual;
    let mut score = pr as f64;

    // Tiered post-residual rewards: exact and near-exact fills dominate.
    if pr == 0 {
        score -= 300.0;
    } else if pr <= 3 {
        score -= 140.0;
    } else if pr <= 6 {
        score -= 70.0;
    } else if pr <= 18 {
        score -= 30.0;
    } else if pr <= 40 {
        score -= 8.0;
    }

    // Dead-space penalty: residuals too small for typical items are waste.
    if pr > 0 && pr < 20 {
        score += (20.0 - pr as f64) * (20.0 - pr as f64) * 0.55;
    }

    // Two-step lookahead: exact pair fill is excellent; proportional waste reward otherwise.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 180.0;
        } else if next_item_size + 1 == pr {
            score -= 95.0;
        } else if next_item_size <= pr {
            let waste = (pr - next_item_size) as f64;
            score -= waste * 1.8;
        } else {
            let miss = (next_item_size - pr) as f64;
            score += miss.min(50.0) * 0.55 + 6.0;
        }
    }

    // Pair-fill reward when bin can host item + next item together.
    if next_item_size > 0 {
        let pair = item_size as f64 + next_item_size as f64;
        if bin_residual as f64 >= pair {
            let slack = bin_residual as f64 - pair;
            score -= 30.0 - (slack / capf) * 22.0;
        }
    }

    // Consolidation pressure when many bins are open, stronger early.
    let progress = step_index as f64 / total_items.max(2) as f64;
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    score -= bin_pressure * 2.2 * (1.0 - progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Mean-residual anchoring, stronger later in the stream.
    score -= (0.25 + 0.15 * progress) * (mean_residual - pr as f64);

    // New-bin candidate: open only when lookahead is tight or alternatives are poor.
    if bin_residual == bin_capacity {
        let next_tight = next_item_size > 0 && mean_residual < next_item_size as f64;
        if next_tight || fitting_bins_count <= 1 {
            score -= 30.0;
        } else {
            score += 30.0 + 2.5 * bin_pressure;
        }
        // Large items fragment open bins; better to open fresh for them.
        if item_size as f64 > 0.6 * capf {
            score -= 12.0;
        }
        if next_item_size > 0 && (item_size as f64 + next_item_size as f64) > capf {
            score -= 14.0;
        }
        if progress > 0.7 && open_bins_count > 3 {
            score += 16.0 * progress;
        }
    }

    // Usable-pocket bonus: residual after placement that can host next item tightly.
    if next_item_size > 0 && pr >= next_item_size && pr - next_item_size > 0 && (pr - next_item_size) < item_size.max(next_item_size) {
        score -= 14.0;
    }

    // Penalize leaving residual that next item cannot use, but only if small.
    if next_item_size > pr && pr > 0 && pr < 30 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer tight fits (small post-residual), with a mild convex
    // (quadratic) penalty so large dead space is punished super-linearly.
    let mut score = pr + (pr * pr) / (2.0 * cap);

    // Stream-progress coupling: as the stream advances, dead space becomes
    // increasingly costly (fewer chances to fill it later), so grow the
    // quadratic weight smoothly with progress.
    let progress_weight = 1.0 + 2.0 * progress * progress;
    score += progress_weight * (pr * pr) / (4.0 * cap);

    // Smooth interaction: penalize bins whose residual is far from the mean
    // residual landscape (keeps residual distribution balanced).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev * (1.0 + progress);

    // Last-chance bonus: if this is the only bin that fits, strongly reward
    // using it (smooth exponential reward scaled by item relative size).
    if fitting_bins_count == 1 {
        let rel = item_size as f64 / cap;
        score -= 8.0 + 10.0 * rel * (1.0 - progress * 0.5);
    } else {
        // Mild reward for having alternatives, so-so bins are less attractive
        score += 0.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead coupling: reward this bin if the next item could fit into the
    // post-residual (chained packing), penalize otherwise.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 4.0 * (1.0 - nxt / cap);
        } else {
            // dead space that the next item cannot use
            score += 2.0 * (1.0 - nxt / cap) * (1.0 + progress);
        }
    }

    // New-bin candidate: a fresh bin has residual == capacity. Make it
    // attractive only when no good fit exists (large post_residual elsewhere
    // would waste space), otherwise keep it slightly worse than a decent fit.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        // Competitive baseline: slightly worse than a perfect fit (pr ~ 0),
        // better than any fit leaving large unusable residue.
        let waste_pressure = mean_residual / cap;
        score = 1.5 + 6.0 * waste_pressure * (1.0 - progress) + 2.0 * progress;
        // If next item is huge, a fresh bin chains well.
        if next_item_size > 0 && (next_item_size as f64) <= cap {
            score -= 1.0 * (next_item_size as f64 / cap);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
