pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever hold
    // another item (items >= 1, but practically small gaps below ~12 are near
    // unusable) are heavily penalized.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 25.0; // unusable gap penalty
    }

    // Reward tight fits: the closer post_residual is to 0 without being dead,
    // the better. Non-linear bonus for very snug placements.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 40.0;

    // Penalize wasteful placements: if post_residual is large relative to the
    // mean residual across open bins, this bin was a poor choice.
    if post_residual as f64 > mean_residual * 1.5 {
        score += (post_residual as f64 - mean_residual) * 2.0;
    }

    // Lookahead coupling: if the next item fits the post_residual, reward it;
    // if the next item almost fits (small miss), penalize slightly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual + 8 {
            score += (next_item_size - post_residual) as f64 * 3.0;
        }
    }

    // Open-bin pressure: discourage spreading across too many bins; but when
    // this is the last fitting bin, strongly favor using it over a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    } else {
        score += open_bins_count as f64 * 1.5;
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Make the empty bin moderately attractive so
    // poor fits (large post_residual on partially filled bins) lose to it,
    // but keep it worse than a tight fit on an existing bin.
    if bin_residual == bin_capacity {
        score = 55.0 + open_bins_count as f64 * 0.5;
        // If the next item is large, a fresh bin is more valuable.
        if next_item_size >= item_size {
            score -= 5.0;
        }
    }

    // Slight stream-progression term: late in the stream, prefer consolidating
    // into existing bins (closing out bins) rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

