        if dead_frac > 0.1 && dead_frac < 0.45 {
            let bump = (dead_frac - 0.275) * (dead_frac - 0.275);
            score += bump * 26.0 * (0.4 + 0.6 * (1.0 - progress));
        }
        if next_item_size > 0 && dead as u32 >= next_item_size {
