    score += 0.02 * mean_residual * (1.0 - fit_ratio);

    // Global fullness coupling: as stream progresses, tighten packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * fit_ratio;

    score
}

