pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Perfect fill: strongly reward residual == 0.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize "unusable" small gaps: gaps below the smallest plausible item
        // are dead space. Interface allows items down to size 1, but weight the
        // penalty by how small the gap is relative to capacity.
        let gap = post_residual as f64;
        let gap_ratio = gap / bin_capacity as f64;
        if gap < 10 {
            score += 45.0; // tiny unusable sliver
        } else if gap_ratio < 0.12 {
            score += 20.0; // likely dead space
        } else {
            // Usable gap: mild reward proportional to gap (keeps bins flexible)
            score -= 5.0 * gap_ratio;
        }
    }

    // Reward tight fits (small post_residual relative to item size)
    let item = item_size.max(1) as f64;
    let tightness = post_residual as f64 / item;
    score += 8.0 * tightness.min(2.0);

    // --- Lookahead coupling: if next item fits exactly in post_residual, big reward ---
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item still fits here: mild reward
        score -= 6.0;
    }

    // --- Open bins pressure: discourage hoarding many open bins ---
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64) * (1.5 + 3.0 * progress);

    // --- Last-chance bonus: if this is the only fitting bin, avoid opening a new one ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is fine early (fresh bin is flexible) but costly
        // when many bins are already open or late in the stream.
        score = bin_capacity as f64 * 0.5 + 18.0 + (open_bins_count as f64) * 2.0 + 10.0 * progress;
        // Allow opening if no open bin has a decent fit (all residuals tiny)
        if mean_residual < item * 0.5 && open_bins_count > 0 {
            score -= 30.0;
        }
    }

    // Slight preference for bins below mean residual (balance spreading)
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score -= 0.05 * dev;
    }

    score
}

