    }
    if pr > 0 && fitting_bins_count > 1 && (pr as f64) < 0.1 * capf && next_item_size > 0 && (next_item_size as f64) > pr as f64 {
        score += 4.5 * (1.0 - progress);
    }

    // Late-stream small-residual refinement.
    if progress > 0.85 && pr > 0 && pr <= 2 {
        score -= 21.0;
    }
    if progress > 0.8 && pr > 0 {
        score += (pr as f64) * (progress - 0.8) * 1.9;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small for the smallest
    // possible item (1) are pure waste; penalize small gaps super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual as i32) as f64 * 6.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving a gap that the lookahead item can exactly fill.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Penalize leaving a gap that is just barely too small for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Tight fit bonus relative to bin residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 25.0;

    // Open-bin pressure: discourage spreading across many bins when a
    // reasonably tight fit exists; encourage new bins only when this bin
    // would waste a lot.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64) * (1.5 + 2.0 * (1.0 - progress));

    // Mean residual coupling: bins far below mean residual are good candidates.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: make empty bins attractive only when the item is
    // large relative to capacity or open bins are numerous.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score = 70.0 - 40.0 * large_item + (open_bins_count as f64) * 2.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

