    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect match of next item into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward tight two-item packing: post_residual - next_item_size small is great
            let leftover = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - leftover / bin_capacity as f64);
            // Perfect chain: next item exactly fills the remainder
            if leftover == 0.0 {
                score -= 40.0;
            }
        } else {
            // Next item cannot use the dead space; penalize proportionally to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap.min(40.0);
        }
    } else {
        // Last item: just minimize waste
        score += 0.2 * post_residual as f64;
    }

    // Penalize large dead space relative to mean residual across open bins
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when item is large or stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 / bin_capacity as f64;
        let pull = 70.0 * big_item * (1.0 - progress) + 30.0 * big_item * (1.0 - big_item);
        // Next item likely fits the fresh residual too?
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= pull + 20.0;
