            score -= pull;
        }
    }

    // Mild preference for compacting into fuller bins as stream progresses
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 15.0 * fill_ratio * (step_index as f64 / total_items.max(1) as f64);

    score
}

