    score += dev * 0.12;

    // New-bin candidate: opening a new bin should only win when it's genuinely better.
    // Give it a mild handicap so consolidation is preferred unless fits are terrible.
    if bin_residual == bin_capacity {
        score += 8.0 + 3.0 * bin_pressure;
    }

    score
}

