    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = cap / 4.0;
    let eighth = cap / 8.0;

    // Dead-space penalty grows superlinearly for residuals in the "useless" band
    // (too small for the smallest plausible item class but not zero).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - pr * 4.0;
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic class of post_residual via integer division thresholds:
    // residuals that are multiples of common item sizes (10,20,25,50) are reusable.
    let harmonic = (post_residual % 10 == 0) as i32
        + (post_residual % 20 == 0) as i32
        + (post_residual % 25 == 0) as i32
        + (post_residual % 50 == 0) as i32;
    score -= harmonic as f64 * 8.0;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= (next_item_size as f64) * 0.3;
        } else {
            // next item cannot use this residual: penalize wasted space
            score += pr * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: prefer existing bins unless current bin fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin, reduced when many items remain (amortization)
        // or when open bins are nearly full on average.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_score = cap + 30.0;
        new_bin_score -= progress * 20.0;
        // If mean residual across open bins is small, opening fresh bin is attractive.
        new_bin_score -= mean_residual * 0.5;
        // If next item is large and mean residual small, new bin even better.
        if next_item_size >= 50 && mean_residual < 25.0 {
            new_bin_score -= 25.0;
        }
        score = new_bin_score;
    } else {
        // Mild bonus for tightening bins when many bins are open (bin consolidation).
        if open_bins_count > 4 {
            score -= (bin_residual - post_residual) as f64 * 0.1;
        }
        // Reward placing into bins whose residual is near a harmonic fraction.
        if (bin_residual as f64 - pr) >= 2.0 * eighth && pr <= quarter {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in small unusable gaps is heavily penalized.
    // A residual that is too small for the smallest plausible item (1..100, assume ~10 typical
    // but be safe with small items) is "dead space" — punish it quadratically.
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * (20.0 - post_residual as f64) * 0.8;
    }

    // Perfect fits get strong reward (subtract).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Coupling with open_bins_count: pressure to consolidate when many bins are open.
    let progress = step_index as f64 / (total_items.max(2) as f64);
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    score -= bin_pressure * 2.5 * (1.0 - progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it over opening new.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * next_item_size as f64;
    }

    // Penalize if post_residual is small but nonzero and cannot host next item (creates waste).
    if next_item_size > post_residual && post_residual > 0 && post_residual < 30 {
        score += 10.0;
    }

    // Mean residual deviation: prefer bins whose residual is close to the mean (balanced packing),
    // penalize outliers creating fragmentation.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.12;

    // New-bin candidate: opening a new bin should only win when it's genuinely better.
    // Give it a mild handicap so consolidation is preferred unless fits are terrible.
    if bin_residual == bin_capacity {
        score += 8.0 + 3.0 * bin_pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits exactly-ish: strong reward proportional to tightness of the 2-step fit.
        let lookahead_waste = (post_residual - next_item_size) as f64;
        score -= 40.0 + 0.5 * next_item_size as f64 - 0.3 * lookahead_waste;
    } else if next_item_size > post_residual {
        // Next item will NOT fit here after placement: penalize, scaled by how badly it misses.
        let miss = (next_item_size - post_residual) as f64;
        score += 10.0 + 0.4 * miss.min(50.0);
    }

    // Perfect 2-step fill (item + next item exactly fills bin) is ideal.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Penalize creating tiny dead space (<10) that nothing can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-high unless current residual is very tight.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.1;
    }

    // Early in the stream, be more willing to open bins for better long-run structure.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.3 {
        score += 5.0 * (1.0 - progress / 0.3);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: bonus grows quadratically as post_residual shrinks.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Penalize dead space that the lookahead item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Post-residual remains usable by next item -> mild reward.
            score -= 1.5 * (post_residual as f64 - next_item_size as f64).min(20.0);
        } else {
            // Dead space for the lookahead item -> penalty scaled by gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 1.2 * gap;
        }
        // Exact chain fit (item + next fills residual perfectly) is excellent.
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0 + 6.0 * progress;
    }

    // When many bins are open, consolidate into existing bins rather than opening more.
    score += 0.35 * open_bins_count as f64 * (1.0 - tightness);

    // Pull toward bins whose residual is near the mean residual (keeps bin pool balanced,
    // leaving large residuals concentrated in few bins for big future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.25 * dev;

    // Late in the stream, fill existing bins aggressively; early, keep flexibility.
    score -= 6.0 * progress * tightness;

    // New-bin candidate: neutral-ish baseline so it only wins when existing fits are poor.
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64 + 4.0 - 3.0 * progress;
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;                       // normalized post residual in [0,1]
    let fill = 1.0 - norm_pr;                     // how full the bin becomes

    // Base: prefer small post residual, with smooth polynomial shaping
    let mut score = norm_pr * (1.0 + 0.8 * norm_pr);

    // Non-linear coupling with stream progress: tighter fits matter more later
    score -= 0.6 * fill * fill * (0.5 + 0.5 * progress);

    // Dead-space penalty grows non-linearly as residual shrinks below typical next-item size
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let waste = (nxt - pr).max(0.0) / cap;
        score += 1.2 * waste * waste * (1.0 + progress);
        // Reward bins whose residual still accommodates the lookahead item
        if pr >= nxt {
            score -= 0.5 * (pr - nxt) / cap * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 2.0 * (1.0 + progress);
    }

    // Scarcity coupling: when few bins can fit the item, prefer conserving them well
    let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
    score += 0.4 * scarcity * norm_pr;

    // Mild preference for consolidating into fewer bins as stream progresses
    score += 0.15 * (open_bins_count as f64).ln() * norm_pr * (0.3 + 0.7 * progress);

    // Smooth alignment with mean residual state (avoid leaving bins far from mean)
    let dev = (pr - mean_residual) / cap;
    score += 0.2 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward exact small-capacity fractions.
    let pr = post_residual;
    // Perfect fits / tiny residuals get strong reward.
    if pr == 0 {
        score -= 500.0;
    } else if pr <= 10 {
        score -= 200.0;
    } else if pr <= 25 {
        score -= 60.0;
    } else if pr <= 50 {
        score -= 10.0;
    }

    // Modulo-class harmonic penalty: residuals that are multiples of common
    // item-size classes are reusable; odd remainders are dead space.
    let resid_class = pr % 10;
    score -= (10 - resid_class) as f64 * 1.5;
    if pr % 25 == 0 { score -= 25.0; }
    if pr % 20 == 0 { score -= 15.0; }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 2.0;
        } else {
            // next item cannot use this residual: penalize proportionally
            score += (next_item_size - pr).min(pr) as f64 * 0.5;
        }
        // harmonic coupling: next item class vs residual class
        if pr >= next_item_size && (pr - next_item_size) % 10 == 0 {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }
    // Many fitting bins: mild penalty to prefer tighter alternatives (score
    // already tracks tightness via post_residual).

    // New-bin candidate handling: penalize opening a new bin unless current
    // fit is terrible or bin is fresh.
    if bin_residual == bin_capacity {
        // Fresh bin: baseline neutral-ish; opening early is wasteful if any
        // open bin gives small post_residual.
        score = cap * 0.6 + open_bins_count as f64 * 5.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= (bin_capacity - next_item_size) as f64 * 0.5;
        }
        if fitting_bins_count == 0 {
            score -= 400.0; // no alternative: must open
        }
    } else {
        // Using an existing bin is generally preferred.
        score -= 40.0;
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 30.0;

    // Mean residual coupling: if this bin's residual is far below mean,
    // it is a tight bin — favor using it up.
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Reward using bins that are already fairly full (low residual before placement).
    score -= 0.3 * (bin_capacity as f64 - bin_residual as f64);

    // Open-bin pressure: many open bins -> discourage spreading, favor filling existing bins.
    score += 0.8 * open_bins_count as f64;

    // Last chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // would leave a bad gap in every existing bin, or no bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 25.0;
        // If the item is large, a fresh bin is reasonable.
        if item_size >= 50 {
            score -= 20.0;
        }
        // If the next item is large too, keeping a fresh bin may pay off.
        if next_item_size >= 50 {
            score -= 10.0;
        }
        // If only one bin fits the item elsewhere, don't open a new bin.
        if fitting_bins_count >= 1 {
            score += 30.0;
        }
    } else {
        // Placing into an existing bin is generally preferred.
        score -= 15.0;
        // Lookahead: if next item fits exactly in the post-residual, reward this placement.
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) == 0 {
            score -= 35.0;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0;
        }
        // Penalize leaving a gap much larger than typical item sizes (wasted space).
        if post_residual > 60 {
            score += 5.0;
        }
    }

    // Mean residual coupling: when average residuals are high, prefer bins below the mean
    // (consolidate full bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // Slight stream-position adaptation: early on, be more willing to open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post_residual quadratically.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Aggressive 2-step lookahead: reward if next item fits the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Bonus proportional to how well the next item uses the leftover space.
            let next_fit = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - next_fit / bin_capacity as f64);
        } else if next_item_size <= bin_residual {
            // Next item fits this bin but not after placing current item:
            // prefer ordering that keeps room for the next item if possible.
            score += 3.0;
        }
        // Perfect chain: post_residual exactly equals next item size.
        if post_residual == next_item_size {
            score -= 8.0;
        }
    }

    // Relative-to-mean coupling: prefer bins with residual close to item need
    // (small residual bins first, avoid wasting big-residual bins on small items).
    if (bin_residual as f64) > mean_residual + 20.0 && item_size < 40 {
        score += 6.0;
    }

    // Last chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize opening new bins when many open bins can still fit the item.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 5.0 + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
