    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = post;

    // Reward tight fits: penalize proportionally wasted space
    score += 0.5 * (post / cap) * post;

    // Lookahead: if the next item fits into post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 0.6 * next_item_size as f64;
    } else if next_item_size > 0 {
        // next item cannot join this bin: mild penalty if we leave large dead space
        score += 0.3 * (post - cap * 0.1).max(0.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: prefer it only when no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = cap - 45.0 * pressure + 10.0 * (fitting_bins_count as f64);
        // late in the stream, consolidating is cheaper
        score -= 15.0 * progress;
    }

    // Global state coupling: many open bins with high mean residual -> prefer filling existing bins
    if open_bins_count > 2 && mean_residual > 20.0 {
        score -= 0.05 * mean_residual;
    }

    // Early stream: slightly favor opening bins to spread load (keeps options open)
    score += 8.0 * (1.0 - progress) * (open_bins_count as f64).min(5.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
