    let norm_pr = pr / cap;
    let mut score = pr;
    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 40.0 * poly;
    // Reward tight fits (low post residual), stronger late in stream
    score -= 12.0 * (1.0 - norm_pr) * (0.5 + 0.5 * progress);
    // Penalize creating residual that next item cannot use
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        score += 0.15 * gap * (1.0 - progress);
        if next_item_size as f64 <= pr && next_item_size as f64 > 0.0 {
