    // Mild penalty for spreading across many bins
    score += 0.3 * open_bins_count as f64 * norm_pr;
    // Encourage bins with residuals near mean (balance)
    score += 0.05 * (pr - mean_residual).abs();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by common item sizes
    // (10, 20, 25, 50) are more likely to be filled by future items.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward "harmonic" residuals that are exact divisors of capacity
    if post_residual > 0 {
        if bin_capacity % post_residual == 0 {
            score -= 8.0; // perfectly reusable chunk (e.g. 50, 25, 20, 10)
        } else if post_residual % 10 == 0 {
            score -= 4.0; // decile-aligned residual
        } else {
            score += 3.0; // awkward leftover
        }
    } else {
        score -= 20.0; // perfect closure of the bin
    }

    // Lookahead: does next_item_size fit exactly or nearly in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Harmonic match: next item leaves another clean residual
            let next_res = post_residual - next_item_size;
            let match_bonus = if next_res == 0 {
                14.0
            } else if bin_capacity % next_res.max(1) == 0 {
                9.0
            } else if next_res % 10 == 0 {
                5.0
            } else {
                0.0
            };
            score -= match_bonus + slack * 0.05;
        } else {
            // next item won't fit here; penalize mildly unless residual is tiny
            score += (next_item_size - post_residual) as f64 * 0.03;
        }
    } else {
        // last item: prefer tightest fit
        score -= 10.0;
    }

    // Integer-division threshold classes on post_residual
    let cls = post_residual / 10; // decile class 0..=10
    score += match cls {
        0 => -6.0,                 // nearly full: excellent
        1 => -3.0,
        2 => 0.0,
        3 => 2.0,                  // mid-range residual: mediocre
        4 => 3.0,
        5 => -2.0,                 // exactly half: still very reusable
        6 => 2.0,
        7 => 4.0,
        8 => 5.0,
        9 => 4.0,
        _ => 0.0,                  // empty bin handled below
    };

    // New-bin candidate: only prefer it when no open bin is a good harmonic fit
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 6.0;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: must open
        } else if fitting_bins_count == 1 {
            score += 2.0; // last-chance bin exists; slight nudge to use it
        } else {
            score += 8.0 * (fitting_bins_count as f64).ln().max(1.0);
        }
    } else if fitting_bins_count == 1 {
        // this is the only bin that fits: strong reward to avoid opening a bin
        score -= 12.0;
    }

    // Late in the stream, consolidate aggressively into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0 * (1.0 - pr / cap);

    // Prefer bins that are emptier than average early on (balance load),
    // but tighter than average later.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    if progress < 0.5 {
        score += dev * 3.0;
    } else {
        score -= dev * 2.0;
    }

    // Tiny penalty on very large items going into nearly-full bins to avoid overflow-risk waste
    if item_size > bin_capacity * 3 / 4 && post_residual > 0 && post_residual < 10 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever hold
    // another item (items >= 1, but practically small gaps below ~12 are near
    // unusable) are heavily penalized.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 25.0; // unusable gap penalty
    }

    // Reward tight fits: the closer post_residual is to 0 without being dead,
    // the better. Non-linear bonus for very snug placements.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 40.0;

    // Penalize wasteful placements: if post_residual is large relative to the
    // mean residual across open bins, this bin was a poor choice.
    if post_residual as f64 > mean_residual * 1.5 {
        score += (post_residual as f64 - mean_residual) * 2.0;
    }

    // Lookahead coupling: if the next item fits the post_residual, reward it;
    // if the next item almost fits (small miss), penalize slightly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual + 8 {
            score += (next_item_size - post_residual) as f64 * 3.0;
        }
    }

    // Open-bin pressure: discourage spreading across too many bins; but when
    // this is the last fitting bin, strongly favor using it over a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    } else {
        score += open_bins_count as f64 * 1.5;
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Make the empty bin moderately attractive so
    // poor fits (large post_residual on partially filled bins) lose to it,
    // but keep it worse than a tight fit on an existing bin.
    if bin_residual == bin_capacity {
        score = 55.0 + open_bins_count as f64 * 0.5;
        // If the next item is large, a fresh bin is more valuable.
        if next_item_size >= item_size {
            score -= 5.0;
        }
    }

    // Slight stream-progression term: late in the stream, prefer consolidating
    // into existing bins (closing out bins) rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (-diff / 12.0).exp(); // strong bonus for perfect/near-perfect fit for next item
        // Penalize post-residuals that are small but unusable (>0 but < next item)
        if post_residual > 0 && (next_item_size as u32) > post_residual {
            score += 0.5 * post_residual as f64; // dead space penalty
        }
        // Slight preference to leave room >= next_item_size over leaving less
        if post_residual >= next_item_size {
            score -= 4.0;
        }
    }

    // Relative to mean residual: prefer bins with residuals tighter than average (good packing),
    // penalize placing into bins far above mean residual (wasteful bins).
    score += 0.35 * (bin_residual as f64 - mean_residual).max(-50.0).min(50.0);

    // Last chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild penalty when many bins are open (encourage consolidation), unless new-bin candidate.
    if bin_residual != bin_capacity {
        score += 0.15 * open_bins_count as f64;
    } else {
        // New-bin candidate: only attractive when current item is large and no tight fit exists
        score += 5.0 + 0.1 * item_size as f64;
    }

    // Late-stream tightening: prioritize filling bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor placements leaving small residuals.
    let cap_f = bin_capacity as f64;
    let fill_ratio = 1.0 - (post_residual as f64) / cap_f;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize dead space that becomes unusable (post_residual smaller than min item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual > 0 && post_residual < item_size {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward bins whose post_residual fits the next item (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_quality = 1.0 - (post_residual - next_item_size) as f64 / cap_f;
        score -= 20.0 * chain_quality;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Penalize stranding the next item with unusable slivers.
        score += 12.0;
    }

    // Prefer bins with residual close to mean residual (balanced usage),
    // mildly, so we don't fragment one bin while others stay large.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate handling: opening a new bin should only win when the
    // item fits nowhere with reasonable tightness, or few bins are open.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; discounted early in the stream or when
        // many bins already exist (opening is cheap relative to fragmentation).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_cost = 70.0 + 30.0 * progress;
        if open_bins_count < 3 {
            new_bin_cost -= 25.0;
        }
        // If next item is huge, a fresh bin gives flexibility.
        if next_item_size >= 60 {
            new_bin_cost -= 10.0;
        }
        score = new_bin_cost + (item_size as f64) * 0.1;
    }

    // Late-stream consolidation: near the end, avoid opening bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.9 && bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Penalize dead space more sharply as stream progresses (non-linear in pr_norm)
    score += cap * (pr_norm * pr_norm) * (0.5 + 1.5 * progress);

    // Reward tight fits (small post_residual) with smooth cubic decay bonus
    score -= 30.0 * (1.0 - pr_norm).powi(3);

    // Last-chance bin: strong smooth reward scaled by progress
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward bins whose post_residual can host the next item (smooth kernel)
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        let slack = (pr - next_item_size as f64) / cap;
        score -= 12.0 * (1.0 - slack).powi(2);
    } else if next_item_size > 0 {
        score += 8.0 * progress;
    }

    // Mild penalty when bin is far from mean residual (dispersion control)
    score += 0.15 * (pr - mean_residual).abs();

    // New-bin candidate: smooth adaptive threshold
    if bin_residual == bin_capacity {
        score = cap * (0.35 + 0.45 * progress) - 10.0 * (1.0 - pr_norm);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: partition capacity space into
    // capacity/8-sized classes via integer division thresholds.
    let class = post_residual / (bin_capacity / 8);
    match class {
        0 => { score -= 30.0; }             // near-perfect fit, tiny dead space
        1 => { score -= 12.0; }             // still very tight
        2 => { score -= 4.0; }              // decent
        3 => { score += 0.0; }
        4 => { score += 6.0; }              // wasteful half-ish bin
        5 => { score += 14.0; }
        6 => { score += 24.0; }
        _ => { score += 40.0; }             // nearly untouched bin
    }

    // Modulo arithmetic: residuals divisible by small harmonics (4, 8, 12)
    // are more reusable by typical item sizes.
    if post_residual % 4 == 0 { score -= 3.0; }
    if post_residual % 8 == 0 { score -= 3.0; }
    if post_residual % 12 == 0 { score -= 2.0; }

    // If the next item fits exactly into the post residual, strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // Perfect cascade: next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 20.0;
        }
        // Harmonic class of next item relative to post residual.
        let gap = post_residual - next_item_size;
        if gap / (bin_capacity / 8) <= 1 {
            score -= 6.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this bin's remainder; penalize proportionally.
        score += (next_item_size as f64).min(post_residual as f64) * 0.1;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: penalize so we only open when open bins are truly bad.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But early in the stream, having multiple bins open is fine.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if open_bins_count == 0 || (progress < 0.2 && open_bins_count < 3) {
            score -= 30.0;
        }
    }

    // Tie-break toward consolidating residuals near the mean.
    score += ((post_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;

    // Perfect / near-perfect fills are strongly preferred.
    if pr == 0 {
        score -= 500.0;
    } else if pr <= 10 {
        score -= 120.0;
    } else if pr <= 25 {
        score -= 40.0;
    } else if pr <= 50 {
        score -= 8.0;
    }

    // Modulo-class harmonic reward: residuals aligned to common size classes stay reusable.
    let resid_class = pr % 10;
    score -= (10 - resid_class) as f64 * 1.5;
    if pr % 25 == 0 { score -= 20.0; }
    if pr % 20 == 0 { score -= 12.0; }

    // Two-step lookahead: reward bins where the next item fits well after placement.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 250.0; // perfect 2-step fill
        } else if next_item_size <= pr {
            let lookahead_waste = (pr - next_item_size) as f64;
            score -= 30.0 + 0.4 * next_item_size as f64 - 0.3 * lookahead_waste;
            if lookahead_waste as u32 % 10 == 0 {
                score -= 15.0; // coupled harmonic fit
            }
        } else {
            let miss = (next_item_size - pr).min(pr) as f64;
            score += 8.0 + 0.5 * miss;
        }
    }

    // Tiny dead space is unusable: penalize.
    if pr > 0 && pr < 10 {
        score += 20.0;
    }

    // Relative to mean residual: prefer tighter-than-average bins.
    score -= (mean_residual - pr as f64).max(0.0) * 0.4;

    // Last-chance bin: strongly avoid opening a new bin when only one fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: mostly avoid unless there is no alternative or the
    // current fit is very poor.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.6 + open_bins_count as f64 * 5.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= (bin_capacity - next_item_size) as f64 * 0.5;
        }
        if fitting_bins_count == 0 {
            score -= 400.0; // must open a bin
        } else if pr > 50 && fitting_bins_count <= 2 {
            // Poor fits available: opening a fresh bin can be better long-run.
            score -= 60.0;
        }
    } else {
        score -= 35.0; // mild preference to use existing bins
    }

    // Stream progression: consolidate more aggressively late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 25.0;

    // Early stream: slight willingness to open structured bins.
    if progress < 0.25 {
        score += 4.0 * (1.0 - progress / 0.25);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let mut score = pr as f64;

    // Perfect fits / tiny residuals get strong reward.
    if pr == 0 {
        score -= 500.0;
    } else if pr <= 10 {
        score -= 200.0;
    } else if pr <= 25 {
        score -= 60.0;
    } else if pr <= 50 {
        score -= 10.0;
    }

    // Modulo-class harmonic penalty: reusable residuals are rewarded.
    let resid_class = pr % 10;
    score -= (10 - resid_class) as f64 * 1.5;
    if pr % 25 == 0 { score -= 25.0; }
    if pr % 20 == 0 { score -= 15.0; }

    // Lookahead: next item fit into post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 2.0;
        } else {
            score += (next_item_size - pr).min(pr) as f64 * 0.5;
        }
        if pr >= next_item_size && (pr - next_item_size) % 10 == 0 {
            score -= 20.0;
        }
        // MUTATION: two-step lookahead — reward residuals that can still
        // host the next item plus a small complement (pairing potential).
        if next_item_size < pr {
            let rem = pr - next_item_size;
            if rem >= item_size.min(50) {
                score -= 12.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // MUTATION: waste-normalized tightness — replace raw post_residual
    // dominance with a waste ratio term so large bins are judged fairly.
    let waste = (bin_residual - item_size) as f64 / cap;
    score -= waste * 25.0;

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // MUTATION: scale the opening threshold with stream progress —
        // late in the stream, prefer squeezing into existing bins harder;
        // early, allow opening to build well-shaped bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_score = cap * 0.55 + open_bins_count as f64 * 5.0 + progress * 80.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            new_score -= (bin_capacity - next_item_size) as f64 * 0.5;
        }
        if fitting_bins_count == 0 {
            new_score -= 400.0;
        }
        // MUTATION: penalize opening a new bin when the mean residual of
        // open bins could still absorb several items.
        new_score += (mean_residual / cap).min(1.0) * 30.0;
        score = new_score;
    } else {
        score -= 40.0;
    }

    // Stream progression: late consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 30.0;

    // Mean residual coupling.
    score -= (mean_residual - pr as f64).max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;
    let pr = post_residual;

    // Perfect fits / tiny residuals get strong reward.
    if pr == 0 {
        score -= 500.0;
    } else if pr <= 10 {
        score -= 200.0;
    } else if pr <= 25 {
        score -= 60.0;
    } else if pr <= 50 {
        score -= 10.0;
    }

    // Modulo-class harmonic penalty: reusable residuals rewarded, dead space penalized.
    let resid_class = pr % 10;
    score -= (10 - resid_class) as f64 * 1.5;
    if pr % 25 == 0 { score -= 25.0; }
    if pr % 20 == 0 { score -= 15.0; }

    // Lookahead: exact fit for next item is a big win; otherwise reward
    // proportionally to how much of the residual the next item consumes.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size <= pr {
            let fill_ratio = next_item_size as f64 / pr as f64;
            score -= (pr - next_item_size) as f64 * 2.0;
            // NEW: reward high fill ratio of the post-residual, so residuals
            // that the next item nearly fills beat residuals that stay bulky.
            score -= fill_ratio * 25.0;
        } else {
            score += (next_item_size - pr).min(pr) as f64 * 0.5;
        }
        if pr >= next_item_size && (pr - next_item_size) % 10 == 0 {
            score -= 20.0;
        }
        // NEW: two-item lookahead coupling — if the item after this placement
        // could pair with the leftover, mildly favor it.
        if pr > next_item_size {
            let after = pr - next_item_size;
            if after >= item_size.min(next_item_size) && item_size.min(next_item_size) > 0 {
                score -= 8.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // NEW: scarcity-aware pressure — when few bins can fit the item, protect
    // those options and discourage wasteful new-bin openings.
    if fitting_bins_count >= 2 && fitting_bins_count <= 3 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Fresh bin: base cost grows with open bins (prefer consolidation),
        // but shrink when the mean residual shows open bins are nearly full.
        let mean_tightness = (mean_residual / cap).clamp(0.0, 1.0);
        score = cap * 0.6 + open_bins_count as f64 * 5.0 * (1.0 - mean_tightness);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= (bin_capacity - next_item_size) as f64 * 0.5;
        }
        if fitting_bins_count == 0 {
            score -= 400.0; // no alternative: must open
        } else {
            // NEW: if an open bin leaves a small post-residual, opening a new
            // bin is wasteful — penalize proportionally to the best alternative.
            score += (60.0 - pr.min(60)) as f64 * 1.0;
        }
    } else {
        // Using an existing bin is generally preferred.
        score -= 40.0;
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 30.0;

    // Mean residual coupling: tight bins (below mean) are favored.
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
