    }

    // Modulo-class harmonic reward: residuals near multiples of common item classes.
    let resid_class = pr % 10;
    score -= (10 - resid_class) as f64 * 1.2;
    if pr % 25 == 0 { score -= 20.0; }
    if pr % 20 == 0 { score -= 12.0; }

