    if pr == 0 {
        score -= 500.0;
    } else if pr <= 8 {
        score -= 210.0;
    } else if pr <= 25 {
        score -= 60.0;
    } else if pr <= 50 {
        score -= 10.0;
    }

    // Dead-space penalty: gaps too small to be useful are heavily punished.
