        score += (12 - pr) as f64 * 25.0;
    }

    // Residual class bonus: prefer residuals aligned to common item sizes.
    let resid_class = pr % 10;
    score -= (10 - resid_class) as f64 * 1.5;

    // Lookahead: exact next-item fit is gold; near-miss is penalized.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 2.0;
            if (pr - next_item_size) % 10 == 0 {
                score -= 20.0;
            }
        } else {
            score += (next_item_size - pr).min(pr) as f64 * 0.5;
        }
    }

