    if next_item_size > 0 && pr >= item_size + next_item_size {
        score -= 25.0;
    }

    // Last fitting bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    } else {
        score += open_bins_count as f64 * 1.5;
    }

    // Dead space after placement vs next item.
    let dead = bin_residual as f64 - item_size as f64;
    if dead > 0.0 {
