    if next_item_size > 0 && pr == next_item_size + 1 {
        score -= 15.0;
    }

    // Large-but-unusable residual: penalize harder (waste detection).
    if pr > 0 && next_item_size > 0 && pr < next_item_size && pr > 40 {
        score += 14.0;
