            score -= 7.0 * (overshoot / capf) * (1.0 + progress);
        }
    }

    // Late-stream squeeze — tighten preference for minimal post-residual near end.
    if progress > 0.85 && pr > 0 {
        score += pr as f64 * 0.35 * (progress - 0.85) * 6.67;
    }

    // NEW: combined residual-fit index — reward bins whose post-residual is a
    // small fraction of capacity AND close to the next item, non-linearly.
    if pr > 0 && next_item_size > 0 {
        let frac = pr as f64 / capf;
        let align = 1.0 - ((pr as f64 - next_item_size as f64).abs() / capf);
        score -= 20.0 * (1.0 - frac) * align.max(0.0) * (0.5 + progress);
    }

    // NEW: penalize leaving residuals in the "dead zone" that future items rarely
    // fill: just above half-capacity when mean residual is small.
    if pr > 0 && pr as f64 > 0.5 * capf && mean_residual < 0.3 * capf {
        score += 10.0 + 8.0 * ((pr as f64 - 0.5 * capf) / capf);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: quantize post_residual into capacity/8 buckets.
    let quantum = bin_capacity / 8;
    let class = post_residual / quantum;
    let class_center = (class * quantum + quantum / 2) as f64;
    // Penalize post_residuals far from "useful" class centers (items 1..100 => small leftovers are dead space).
    let dead = (post_residual as f64 - class_center).abs();
    score += 0.6 * dead;

    // Perfect fits (post_residual == 0) heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Tiny dead space (unusable for items >= 1... but 1..100 means anything >0 can be used).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Modulo logic: leftover congruent to common small sizes (e.g. 25, 50, 75, 10, 20) is reusable.
    let pr = post_residual;
    if pr % 50 == 0 && pr > 0 {
        score -= 12.0;
    } else if pr % 25 == 0 && pr > 0 {
        score -= 6.0;
    } else if pr % 10 == 0 && pr > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: reward if next_item_size fits exactly in the post residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score += 0.25 * slack;
            // harmonic bonus if next item leaves another nice class
            let npr = pr - next_item_size;
            if npr % 25 == 0 || npr % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // next item cannot fit here: mild penalty proportional to overflow
            score += 2.0 + 0.05 * ((next_item_size - pr) as f64);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when current bins are crowded
    // or the fit here is terrible. Empty-bin call has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // baseline cost of a fresh bin; reduced late in the stream or when few bins fit
        let mut new_bin_penalty = 30.0 + post_residual as f64;
        new_bin_penalty -= 20.0 * progress;
        if fitting_bins_count == 0 {
            new_bin_penalty -= 50.0;
        }
        if open_bins_count == 0 {
            new_bin_penalty -= 40.0;
        }
        // if mean residual across open bins is large, discourage opening new bins
        new_bin_penalty += 0.3 * mean_residual;
        score = new_bin_penalty;
    } else {
        // Prefer bins with residuals below the mean (tighter packing).
        score += 0.2 * (bin_residual as f64 - mean_residual);
    }

    // Progress modulation: as stream advances, value tight fits more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual;
