    // Tiered post-residual rewards: exact and near-exact fills dominate.
    if pr == 0 {
        score -= 540.0;
    } else if pr <= 3 {
        score -= 262.0;
    } else if pr <= 4 {
        score -= 240.0;
    } else if pr <= 16 {
        score -= 88.0;
    } else if pr <= 40 {
        score -= 18.0;
    } else if pr <= 66 {
        score -= 4.0;
    }

