    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 330.0;
        } else if next_item_size + 1 == pr {
            score -= 190.0;
        } else if next_item_size <= pr {
            let waste = (pr - next_item_size) as f64;
            score -= waste * 2.3;
            if (waste as u32) % 10 == 0 {
                score -= 24.0;
            }
        } else {
            let miss = (next_item_size - pr) as f64;
            score += miss.min(50.0) * 0.68 + 8.0;
        }
    }

