            score -= dead * (0.055 + 0.05 * rem_frac) + dead_frac * dead_frac * 46.0;
        }
        if dead < 0.05 * capf && open_bins_count > 2 {
            score += 5.0 * (1.0 - dead / (0.05 * capf));
        }
        if dead_frac > 0.55 && next_item_size > 0 && (next_item_size as f64) > dead {
            score += 9.0 * dead_frac;
        }
        // Complementary: penalize mid-range dead space that neither next item
        // nor typical residuals can absorb (fragmentation pocket).
        if next_item_size > 0 && (next_item_size as f64) < dead && dead < 0.35 * capf {
            score += (dead - next_item_size as f64) * 0.22;
        }
    }

    // New-bin candidate logic: open only when lookahead is tight or no alternatives,
    // and prefer opening for large items that would fragment an open bin.
    if bin_residual == bin_capacity {
        let next_tight = next_item_size > 0 && mean_residual < next_item_size as f64;
        if next_tight || fitting_bins_count <= 1 {
            score -= 32.0;
        } else {
            score += 36.0;
        }
        if open_bins_count > 0 && fitting_bins_count > 1 && step_index > total_items / 2 {
            score += 25.0;
        }
        if item_size as f64 > 0.6 * capf {
            score -= 12.0;
        }
        if next_item_size > 0 && (item_size as f64 + next_item_size as f64) > capf {
            score -= 16.0;
        }
        if item_size as f64 > 0.75 * capf && mean_residual < 0.25 * capf {
            score -= 23.0;
        }
        if fitting_bins_count > 1 && mean_residual < item_size as f64 * 0.4 {
            score += 11.0;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.7 && open_bins_count > 3 {
            score += 18.0 * progress;
        }
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 6.0 + (next_item_size as f64 - mean_residual) * 0.12;
