    if next_item_size > 0 && pr >= next_item_size && pr - next_item_size > 0 && (pr - next_item_size) < item_size.max(next_item_size) {
        score -= 18.0;
    }

    // Usable-floor bonus: residuals above next-item size stay attractive early.
    if pr > 0 {
        let usable_floor = (next_item_size.max(1) as f64).min(0.35 * capf);
        if (pr as f64) >= usable_floor {
            score -= 8.0 * (1.0 - progress) * ((pr as f64) / capf);
        }
        // Complementary: bonus when pr can be exactly consumed by next item
        // even if not equal (e.g. pr divisible by small next items).
        if next_item_size > 0 && pr % next_item_size == 0 && pr > next_item_size {
            score -= 7.0 * (1.0 - progress);
        }
    }

    score
}

