    // Open-bin pressure: many open bins -> discourage spreading into
    // bins with large residuals; consolidate instead.
    let open_pressure = (open_bins_count as f64).ln() * 6.0;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
