    // Lookahead coupling: if the next item fits exactly in the post
    // residual, big bonus for this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / 100.0);
