    // Reward leaving a residual smaller than both item and next item (usable pocket).
    if next_item_size > 0 && pr >= next_item_size && pr - next_item_size > 0 && (pr - next_item_size) < item_size.max(next_item_size) {
        score -= 18.0;
    }

    // Usable-floor bonus: residuals above next-item size stay attractive early.
    if pr > 0 {
        let usable_floor = (next_item_size.max(1) as f64).min(0.35 * capf);
