    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0; // chained perfect fill
        } else if next_item_size < pr && pr - next_item_size < 10 {
            score += 8.0; // would create fresh dead space
        } else if next_item_size < pr && (pr - next_item_size) % 10 == 0 {
            score -= 10.0; // harmonic alignment with lookahead
        }
        // Item classes: odd/even pairing via integer division thresholds
        let cls_next = next_item_size / 20; // coarse class 0..=5
        let cls_post = pr / 20;
        if cls_next == cls_post && pr >= next_item_size {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
