        let gap = (next_item_size - pr) as f64 / capf;
        score += waste_frac * 58.0 + gap * 32.0;
    } else if pr > 0 && next_item_size > 0 {
        let tightness = 1.0 - ((pr - next_item_size) as f64 / capf);
        score -= (pr as f64 / capf) * 20.0 * tightness;
    }

    // Small endgame residuals are nearly perfect fills.
    if progress > 0.85 && pr <= 2 && pr > 0 {
        score -= 20.0;
    }

    score
}

