    // Dead-space penalty for residuals too small for the smallest plausible item,
    // scaled by stream progress (early on, waste is more forgivable).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += (2.0 + 8.0 * progress) as f64;
    }

    // Global state coupling: if mean residual is high, prefer filling existing bins
    // (consolidation); if mean residual is low, opening a bin is less costly.
    let mean_gap = mean_residual - post_residual as f64;
    score += 0.05 * mean_gap;

    // New-bin candidate handling: it must lose to decent fits but win over bad ones.
    if bin_residual == bin_capacity {
        let mut base = 12.0 + 0.3 * open_bins_count as f64;
        // Late in the stream, opening bins is cheaper than wasting capacity.
        base -= 10.0 * progress;
        // If the item fits very poorly everywhere else, new bin becomes attractive:
        // approximate by rewarding new bin when item is large relative to capacity.
        base -= 6.0 * (item_size as f64 / bin_capacity as f64);
        // If only this candidate fits, new bin is the only option.
        if fitting_bins_count == 0 {
            base -= 50.0;
        }
        score += base;
    }

    score
