            score -= 130.0;
        } else if next_item_size <= pr {
            let waste = (pr - next_item_size) as f64;
            score -= waste * 2.0;
            // Reward waste landing on round numbers (likely to match future items).
            if (waste as u32) % 10 == 0 && waste > 0.0 {
                score -= 20.0;
            }
        } else {
            let miss = (next_item_size - pr) as f64;
            score += miss.min(50.0) * 0.6 + 6.5;
