    // Dead-space-aware term: penalize dead space that next item cannot fill.
    let dead = bin_residual as f64 - item_size as f64;
    let progress = step_index as f64 / total_items.max(2) as f64;
    if dead > 0.0 {
        let dead_frac = dead / capf;
        if next_item_size > 0 && dead < next_item_size as f64 {
            score += 10.0 + dead * 0.15;
        } else {
            let rem_frac = ((total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64).min(1.0);
            score -= dead * (0.05 + 0.05 * rem_frac) + dead_frac * dead_frac * 40.0;
        }
        if dead_frac > 0.2 && dead_frac < 0.55 {
