    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    let poly = tightness * tightness * (1.0 + 2.0 * progress);
    score -= 40.0 * poly;

    // Penalize dead space quadratically, scaled by stream progress (early dead space is cheaper).
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * dead * dead * (0.5 + progress);

    // Last-chance bonus: strongly favor this bin if it is the only one that fits.
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * progress;
