    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            score += 5.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Discourage opening new bins when many open bins already have room, weighted by progress.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
        score += 20.0 * open_pressure * (0.3 + progress) + mean_residual * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 and integer-division tiers.
    let r = post_residual % 10;
    let tier = post_residual / 10;

    // Penalize small unusable remainders (dead space classes).
    if r > 0 && r < 10 {
        let dead_penalty = match r {
            1..=3 => 12.0,
            4..=6 => 6.0,
            _ => 2.0,
