        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += dead_penalty * (0.5 + progress);
    }

    // Reward low tiers (tight fills), with harmonic decay.
    score -= (tier as f64).powi(2) * 1.5;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Harmonic class match: next item leaves a good residue too.
            let nr = (post_residual - next_item_size) % 10;
            if nr == 0 {
                score -= 10.0;
            } else if nr >= 7 {
                score -= 4.0;
            } else {
                score += 3.0;
            }
        } else {
            // Next item cannot use this bin's remainder: penalize large leftover.
            score += (post_residual as f64 - cap * 0.1).max(0.0) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer opening fresh bin only if residual is tiny elsewhere.
    if bin_residual == bin_capacity {
        // Neutral baseline slightly above a good fit; adjusted by stream state.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap * 0.55 - 15.0 * (1.0 - progress) + (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin can host both current and next item harmonically.
            if item_size + next_item_size <= bin_capacity {
                score -= 12.0;
            }
        }
    }

    // Mild preference toward bins with residual close to mean (balance).
    score += ((bin_residual as f64 - mean_residual) / cap).abs() * 4.0;

    score
}

