    // Dead-space penalty: residuals too small for typical items are waste.
    if pr > 0 && pr < 20 {
        score += (20.0 - pr as f64) * (20.0 - pr as f64) * 0.55;
    }

    // Two-step lookahead.
    if next_item_size > 0 {
        if next_item_size == pr {
