    if next_item_size > 0 && pr as f64 == next_item_size as f64 {
        score -= 12.0 * (1.0 - progress);
    }

    // NEW: penalize bins whose post-residual falls in the awkward 6..=12 dead zone
    // (too small for most items, too large to ignore) unless next item uses it.
    if pr >= 6 && pr <= 12 && !(next_item_size > 0 && next_item_size <= pr) {
        score += (12.0 - pr as f64) * 2.4 * (1.0 - progress);
    }

    // NEW: reward near-perfect compaction when bin would be nearly full after placement.
    if pr > 0 && (pr as f64) <= 0.03 * capf {
        score -= 26.0 * (0.5 + 0.5 * progress);
    }

    // NEW: when several bins fit, prefer the one whose dead space best matches the
    // average item demand implied by mean residual; avoid hoarding large residuals.
    if fitting_bins_count > 2 && dead > 0.0 {
        let ideal = mean_residual.max(1.0);
        let dev = (dead - ideal).abs();
        score += dev * 0.09;
    }

    score
}

