pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capf = bin_capacity as f64;
    let pr = post_residual;
    let mut score = pr as f64;

    // Fine-grained post-residual rewards.
    if pr == 0 {
        score -= 540.0;
    } else if pr <= 3 {
        score -= 262.0;
    } else if pr <= 5 {
        score -= 130.0;
    } else if pr <= 16 {
        score -= 82.0;
    } else if pr <= 40 {
        score -= 15.0;
    } else if pr <= 66 {
        score -= 3.8;
    }

    // Dead-space penalty: residuals too small for typical items are waste.
    if pr > 0 && pr < 20 {
        score += (20.0 - pr as f64) * (20.0 - pr as f64) * 0.55;
    }

    // Two-step lookahead.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 335.0;
        } else if next_item_size + 1 == pr {
            score -= 186.0;
        } else if next_item_size <= pr {
            let waste = (pr - next_item_size) as f64;
            score -= waste * 2.3;
            if (waste as u32) % 10 == 0 {
                score -= 24.0;
            }
        } else {
            let miss = (next_item_size - pr) as f64;
            score += miss.min(50.0) * 0.68 + 7.5;
        }
    }

    // Dead-space analysis on the current bin before placement.
    let dead = bin_residual as f64 - item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    if dead > 0.0 {
        let dead_frac = dead / capf;
        if next_item_size > 0 && dead < next_item_size as f64 {
            score += 12.0 + dead * 0.18;
            score += (next_item_size as f64 - dead) * 0.9;
        } else if next_item_size > 0 && dead as u32 == next_item_size {
            score -= 50.0;
        } else {
            let rem = if total_items > step_index { (total_items - step_index) as f64 } else { 0.0 };
            let rem_frac = (rem / total_items.max(1) as f64).min(1.0);
            score -= dead * (0.055 + 0.05 * rem_frac) + dead_frac * dead_frac * 44.0;
        }
        if dead < 0.05 * capf && open_bins_count > 2 {
            score += 5.0 * (1.0 - dead / (0.05 * capf));
        }
        if dead > 0.0 && dead < 4.0 && pr > 4 {
            score += 14.0;
        }
        if dead_frac > 0.2 && dead_frac < 0.55 {
            score += dead_frac * (1.0 - progress) * 17.0;
        }
        if dead_frac > 0.55 && next_item_size > 0 && (next_item_size as f64) > dead {
            score += 9.0 * dead_frac;
        }
        if dead_frac >= 0.55 && dead_frac < 0.75 && next_item_size > 0 && (next_item_size as f64) <= dead * 0.5 {
            score -= 6.0 * dead_frac * (1.0 - progress);
        }
        if dead_frac > 0.1 && dead_frac < 0.45 {
            let bump = (dead_frac - 0.275) * (dead_frac - 0.275);
            score += bump * 26.0 * (0.4 + 0.6 * (1.0 - progress));
        }
        if next_item_size > 0 && dead as u32 >= next_item_size {
            let after = dead as u32 - next_item_size;
            if after == 0 || after <= 2 {
                score -= 22.0;
            } else if after as f64 <= 0.04 * capf {
                score -= 9.0;
            }
        }
        // Borrowed: late-stream dead-space pressure.
        if dead_frac > 0.3 && progress > 0.6 {
            score += dead_frac * (progress - 0.6) * 30.0;
        }
        if dead_frac > 0.05 && dead_frac < 0.25 && progress > 0.35 {
            score += dead_frac * (progress - 0.35) * 22.0;
        }
        if next_item_size > 0 && dead > next_item_size as f64 && dead <= next_item_size as f64 + 3.0 {
            score -= 16.0 * (1.0 - progress);
        }
        if next_item_size > 0 && (dead as u32) % next_item_size == 0 && dead >= next_item_size as f64 && dead <= 2.0 * next_item_size as f64 {
            score -= 12.0 * (1.0 - progress);
        }
    }

    // Pair-fill reward when bin can host item + next item together.
    if next_item_size > 0 {
        let pair = item_size as f64 + next_item_size as f64;
        if bin_residual as f64 >= pair {
            let slack = bin_residual as f64 - pair;
            score -= 38.0 - (slack / capf) * 28.0;
        }
    }

    // Consolidation pressure when many bins are open, stronger early.
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    score -= bin_pressure * 2.2 * (1.0 - progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Mean-residual anchoring, stronger later in the stream.
    score -= (0.38 + 0.17 * progress) * (mean_residual - pr as f64);

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let next_tight = next_item_size > 0 && mean_residual < next_item_size as f64;
        if next_tight || fitting_bins_count <= 1 {
            score -= 32.0;
        } else {
            score += 36.0 + 1.5 * bin_pressure;
        }
        if open_bins_count > 0 && fitting_bins_count > 1 && progress > 0.5 {
            score += 25.0;
        }
        if item_size as f64 > 0.6 * capf {
            score -= 12.0;
        }
        if next_item_size > 0 && (item_size as f64 + next_item_size as f64) > capf {
            score -= 16.0;
        }
        if item_size as f64 > 0.78 * capf && mean_residual < 0.22 * capf {
            score -= 26.0;
        }
        if item_size as f64 > 0.85 * capf && mean_residual < 0.12 * capf {
            score -= 30.0;
        }
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 6.0 + (next_item_size as f64 - mean_residual) * 0.12;
        }
        if fitting_bins_count > 1 && mean_residual < item_size as f64 * 0.4 {
            score += 11.0;
        }
        if progress > 0.7 && open_bins_count > 3 {
            score += 18.0 * progress;
        }
        let spread = (mean_residual - item_size as f64).abs();
        if spread < 0.08 * capf && fitting_bins_count > 2 {
            score += 9.0;
        }
        if item_size as f64 > mean_residual * 1.6 && fitting_bins_count > 1 && open_bins_count > 2 {
            score -= 14.0 * (1.0 - progress);
        }
        if next_item_size > 0 && next_item_size as f64 > 0.5 * capf && mean_residual > 0.3 * capf {
            score -= 10.0;
        }
        // Borrowed: extra new-bin guards from the best heuristic.
        if fitting_bins_count > 1 && dead > 0.35 * capf && item_size as f64 > mean_residual * 1.25 {
            score -= 10.0 * (1.0 - progress);
        }
        if item_size as f64 > 0.93 * capf {
            score -= 20.0;
        }
        let rem_items = if total_items > step_index { (total_items - step_index) as f64 } else { 0.0 };
        if rem_items > 0.15 * total_items.max(1) as f64 && mean_residual < 0.5 * (next_item_size.max(1) as f64) {
            score -= 14.0 * (1.0 - progress);
        }
        if fitting_bins_count > 2 && mean_residual > 0.55 * capf {
            score += 7.0 * (1.0 - progress);
        }
    }

    // Usable-pocket bonus: residual after placement that can host next item tightly.
    if next_item_size > 0 && pr >= next_item_size && pr - next_item_size > 0 && (pr - next_item_size) < item_size.max(next_item_size) {
        score -= 18.0;
    }

    // Usable floor reward: residual large enough to be reusable.
    if pr > 0 {
        let usable_floor = (next_item_size.max(1) as f64).min(0.35 * capf);
        if (pr as f64) >= usable_floor {
            score -= 8.0 * (1.0 - progress) * ((pr as f64) / capf);
        }
    }

    // Penalize leaving residual that next item cannot use.
    if pr > 0 && (pr as f64) < 0.5 * (next_item_size.max(1) as f64) && fitting_bins_count > 1 {
        score += 6.0 * (1.0 - progress);
    }

    // Late-stream tight-fill emphasis.
    if progress > 0.85 && pr <= 2 && pr > 0 {
        score -= 20.0;
    }
    if progress > 0.8 && pr > 0 {
        score += (pr as f64) * 0.35 * (progress - 0.8) * 5.0;
    }

    score
}

