pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (harmonic closure of capacity).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Harmonic class analysis of post_residual: residues that are "usable"
    // by common item sizes get a bonus; awkward residues are penalized.
    let pr = post_residual;
    let residue_class = pr % 10;
    let awkward = matches!(residue_class, 1 | 2 | 3 | 8 | 9);
    if pr > 0 && pr < 10 {
        // Tiny unusable slivers are dead space regardless of class.
        score += 6.0;
    } else if awkward {
        score += 4.0;
    } else {
        score -= 2.0;
    }

    // Integer-division thresholds: post_residual in "half", "third", "quarter" bands.
    let half = cap / 2.0;
    if (post_residual as f64) > half {
        score -= 3.0; // bin still roomy, good target
    }

    // Lookahead coupling: if next item fits the post-residual exactly (or near),
    // reward; if next item cannot use the leftover, penalize slightly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0;
        } else if next_item_size <= pr {
            let waste = pr - next_item_size;
            if waste <= 10 {
                score -= 6.0;
            }
        } else {
            score += 3.0; // leftover likely dead for the next item
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        // But if item is large and would leave awkward residue in any bin,
        // a fresh bin with full flexibility can be attractive.
        if item_size > 60 {
            score -= 10.0;
        }
    }

    // Mild pressure to consolidate as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += mean_residual * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item size
    // (1) are pure waste, but gaps below the next item's size are unusable soon.
    if post_residual > 0 {
        if next_item_size > 0 && post_residual < next_item_size {
            // Gap can't host the lookahead item: penalize proportionally.
            score += 12.0 + (next_item_size - post_residual) as f64 * 0.5;
        }
        if post_residual < item_size {
            // Gap smaller than current item: likely terminal dead space.
            score += 6.0;
        }
    }

    // Reward tight fits (best-fit core, sharpened).
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= tightness * 15.0;

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidating into
    // existing bins rather than spawning more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 1.5 * (0.5 + progress);

    // Prefer bins whose residual is close to the mean (keeps bin states uniform,
    // leaving large residual bins for large future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate: only attractive when the item is large relative to
    // remaining residuals or no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin.
        let mut new_bin_score = bin_capacity as f64 - item_size as f64;
        new_bin_score += open_bins_count as f64 * 2.0;
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            new_bin_score -= 10.0; // fresh bin can also host next item
        }
        if fitting_bins_count <= 1 {
            new_bin_score -= 20.0; // poor alternatives: opening is fine
        }
        score = score.max(new_bin_score);
    }

    score
}

