pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward small post_residual disproportionately.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tight * tight;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: reward if next item fits in post_residual (chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    }
    // Penalize leaving residual that only a huge dead zone would waste.
    if next_item_size > post_residual && post_residual > 0 {
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += 4.0 * waste_frac;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Compare against mean residual: bins below mean residual are tighter, favor them.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Late in stream: be conservative, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * tight;

    // New-bin candidate: penalize opening new bins, more when many bins open or item fits well elsewhere.
    if bin_residual == bin_capacity {
        let base = 12.0 + 0.8 * open_bins_count as f64;
        let escape = if fitting_bins_count > 0 {
            15.0 * (1.0 - (item_size as f64 / bin_capacity as f64))
        } else {
            0.0
        };
        score += base + escape;
    }

    // Small fragmentation penalty scaled by residual size.
    if post_residual > 0 && post_residual < 10 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream, waste is cheap (bins plentiful); later, tight fits matter.
    let norm_pr = pr / cap;
    let coupling = norm_pr * norm_pr * (1.0 + 3.0 * progress) + 0.5 * norm_pr * progress;
    score += 20.0 * coupling;

    // Penalize opening a new bin when other bins fit (smoothly, by fitting count).
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new_bin {
        let fit_pressure = 1.0 / (1.0 + fitting_bins_count as f64);
        score += 45.0 * fit_pressure * (0.5 + 0.5 * progress);
        score += 8.0 * progress;
    }

    // Reward last-chance bins (only fitting bin) strongly.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0 + 25.0 * progress;
    }

    // Lookahead: reward leaving space that can still host the next item.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_quality = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 12.0 * fit_quality * fit_quality;
    } else if next_item_size > 0 {
        // Penalize residuals that strand the next item.
        score += 6.0 * progress;
    }

    // Mild bonus for bins tighter than the mean residual (consolidation).
    let dev = (mean_residual - pr) / cap;
    score -= 5.0 * dev;

    score
}

