pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins that end up nearly full.
    let fill = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 35.0 * fill.powi(4);

    // Harmonic class logic on post_residual modulo 10:
    // residuals that are exact multiples of 10 align with the item-size grid
    // (sizes 10..80), so they remain reusable by future items.
    let cls = post_residual % 10;
    score -= match cls {
        0 => 15.0,
        1 => 10.0,
        2 => 7.0,
        3 => 5.0,
        4 => 3.0,
        5 => 2.0,
        _ => 0.0,
    };

    // Dead-space penalty: residuals of 1..9 are nearly unusable
    // since minimum item size is 10.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item
    // (chain packing), penalize bins that strand the lookahead item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / 100.0);
        } else {
            score += 4.0;
        }
    }

    // Last-chance rescue: if this is the only open bin that fits, use it
    // rather than opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // No open bin fits: opening a new bin is mandatory.
            score = -100.0;
        } else {
            // Default: prefer existing bins. Raise the bar for opening a new bin;
            // large items get a mild discount (big items fit anywhere later,
            // but small items leave flexible residuals in fresh bins).
            score = 45.0 + item_size as f64 * 0.2;
            if item_size >= 60 {
                score -= 12.0;
            }
            // Late in the stream, consolidating into existing bins matters more.
            let progress = step_index as f64 / total_items as f64;
            score += 15.0 * progress;
        }
    }

    // Mild consolidation pressure: when many bins are open, prefer the bin
    // closest to the mean residual (steers toward uniform draining).
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: residuals too small to hold the
    // smallest plausible item (<= 10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Residuals that can only fit tiny items are semi-dead space.
    if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // this placement is excellent (chained fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item is slightly larger than post residual, we create
    // a blocking residual -> mild penalty.
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, using it
    // avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: prefer spreading load when many bins are open,
    // but only mildly; tight fits dominate.
    score += (open_bins_count as f64) * 0.15;

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += (mean_residual - (bin_residual as f64)) * 0.3;

    // New-bin candidate: make it attractive only when no open bin fits
    // well (post residual would be small/dead) or when item is large.
    if bin_residual == bin_capacity {
        // Base new-bin score: slightly above a good fit.
        score = cap - item_size as f64 + 25.0;
        // If item is large relative to capacity, opening a fresh bin is fine.
        if item_size as f64 > 0.6 * cap {
            score -= 20.0;
        }
        // If many bins open and mean residual is high, opening new bin
        // is wasteful -> penalize.
        score += (open_bins_count as f64) * 0.5 + mean_residual * 0.2;
        // Early stream: favor filling existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
