        score -= 560.0;
    } else if pr <= 3 {
        score -= 268.0;
    } else if pr <= 5 {
        score -= 134.0;
    } else if pr <= 16 {
        score -= 84.0;
    } else if pr <= 40 {
        score -= 15.0;
    } else if pr <= 66 {
        score -= 3.8;
    }

    // Dead-space penalty for residuals too small for typical items.
    if pr > 0 && pr < 20 {
        score += (20.0 - pr as f64) * (20.0 - pr as f64) * 0.55;
    }

    // Two-step lookahead: exact pair fill is excellent; proportional waste reward otherwise.
    if next_item_size > 0 {
