pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize post_residual that is too small to be useful for future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space
    }

    // Lookahead: bonus if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item won't fit here; penalize small leftovers
            score += (post_residual as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize spreading across many open bins when mean residual is high
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins with residual below mean residual (compact bins)
    score += 0.2 * ((bin_residual as f64) - mean_residual);

    // Time horizon: early on, be conservative (favor tight fits more); late, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;
    if bin_residual == bin_capacity {
        // new-bin candidate: acceptable early, penalized late
        score += 15.0 * progress + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.87;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer tight fits (small post-residual), with a mild convex
    // (quadratic) penalty so large dead space is punished super-linearly.
    let mut score = pr + (pr * pr) / (2.0 * cap);

    // Stream-progress coupling: as the stream advances, dead space becomes
    // increasingly costly (fewer chances to fill it later), so grow the
    // quadratic weight smoothly with progress.
    let progress_weight = 1.0 + 2.0 * progress * progress;
    score += progress_weight * (pr * pr) / (4.0 * cap);

    // Smooth interaction: penalize bins whose residual is far from the mean
    // residual landscape (keeps residual distribution balanced).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev * (1.0 + progress);

    // Last-chance bonus: if this is the only bin that fits, strongly reward
    // using it (smooth exponential reward scaled by item relative size).
    if fitting_bins_count == 1 {
        let rel = item_size as f64 / cap;
        score -= 8.0 + 10.0 * rel * (1.0 - progress * 0.5);
    } else {
        // Mild reward for having alternatives, so-so bins are less attractive
        score += 0.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead coupling: reward this bin if the next item could fit into the
    // post-residual (chained packing), penalize otherwise.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 4.0 * (1.0 - nxt / cap);
        } else {
            // dead space that the next item cannot use
            score += 2.0 * (1.0 - nxt / cap) * (1.0 + progress);
        }
    }

    // New-bin candidate: a fresh bin has residual == capacity. Make it
    // attractive only when no good fit exists (large post_residual elsewhere
    // would waste space), otherwise keep it slightly worse than a decent fit.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        // Competitive baseline: slightly worse than a perfect fit (pr ~ 0),
        // better than any fit leaving large unusable residue.
        let waste_pressure = mean_residual / cap;
        score = 1.5 + 6.0 * waste_pressure * (1.0 - progress) + 2.0 * progress;
        // If next item is huge, a fresh bin chains well.
        if next_item_size > 0 && (next_item_size as f64) <= cap {
            score -= 1.0 * (next_item_size as f64 / cap);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "reusable" is the leftover space?
    // Residuals in coarse classes (multiples of 10) are more likely to fit
    // future items drawn from a wide distribution.
    let class = post_residual / 10;
    let class_bonus = match class {
        0 => -40.0, // perfect fill
        1 => -12.0, // 10-19: fits most small items
        2 => -6.0,
        3 => 0.0,
        4 => 4.0,
        _ => 8.0,   // large leftovers are wasteful
    };
    score += class_bonus;

    // Exact-fit reward: post_residual zero is gold.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            // next item cannot use the leftover: penalize proportional to waste
            score += (next_item_size as f64 - post_residual as f64).min(40.0) * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is huge
    // or open bins are very full on average.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 30.0 - 25.0 * pressure;
        if item_size >= 60 {
            score -= 10.0;
        }
        // late in the stream, consolidation is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * (1.0 - progress);
    }

    // Slight preference for tighter bins overall.
    score += (bin_residual as f64 - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is unusable
    // (min item size 1 -> actually treat gaps < 12 as near-dead, scaled).
    if post_residual > 0 && post_residual < 12 {
        score += 40.0 + (12 - post_residual) as f64 * 3.0;
    } else if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 60.0;
    }

    // Reward tight fits relative to bin residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize leaving a gap just below next_item_size (blocks the lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    } else if next_item_size > 0 && post_residual == next_item_size {
        // Residual exactly matches next item: excellent chaining.
        score -= 30.0;
    }

    // Open-bin pressure: prefer compacting into fewer bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: make empty bin attractive only when
    // existing residuals are poor (mean residual small means bins are tight,
    // so opening fresh space is reasonable; large mean residual favors reuse).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, offset by mean residual quality.
        score = 55.0 - mean_residual * 0.8 + open_bins_count as f64 * 2.0;
        if next_item_size > 0 && next_item_size >= 50 {
            // Big next item: fresh bin gives flexibility.
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
    }

    // Late-stream compaction: as the stream ends, squeeze usage.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
