pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual exactly
    // matches the next item size (perfect chaining).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match gets a big bonus; near matches get a partial bonus.
        if gap == 0.0 {
            score -= 60.0;
        } else if (post_residual as f64) >= next_item_size as f64 {
            // Next item still fits here after this placement: good chain.
            score -= (30.0 * (1.0 - gap / bin_capacity as f64)).max(0.0);
        } else {
            // Next item would NOT fit: penalize dead space that can't chain.
            score += 8.0 + gap * 0.35;
        }

        // Pair-fit bonus: item + next item fill bin almost completely.
        let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
        if pair_fill > 0.95 && post_residual as f64 >= next_item_size as f64 {
            score -= 25.0;
        }
    }

    // Compare against mean residual: prefer bins that stay near the mean
    // (balanced packing) and penalize leaving outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.12;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer tighter bins generally (best-fit flavor on top of lookahead).
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    // Mild pressure to consolidate as the stream matures.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.10 * progress;

    // Discard tiny unusable residuals (dead space < smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capf = bin_capacity as f64;
    let pr = post_residual;
    let mut score = pr as f64;
    let progress = step_index as f64 / total_items.max(2) as f64;
    let rem_items = if total_items > step_index { (total_items - step_index) as f64 } else { 0.0 };
    let rem_frac = (rem_items / total_items.max(1) as f64).min(1.0);

    // Tiered post-residual rewards (deepened exact fills).
    if pr == 0 {
        score -= 560.0;
    } else if pr <= 3 {
        score -= 262.0;
    } else if pr <= 5 {
        score -= 130.0;
    } else if pr <= 16 {
        score -= 80.0;
    } else if pr <= 40 {
        score -= 15.0;
    } else if pr <= 66 {
        score -= 3.8;
    }

    // Dead-space penalty for residuals too small for typical items.
    if pr > 0 && pr < 20 {
        score += (20.0 - pr as f64) * (20.0 - pr as f64) * 0.55;
    }

    // Two-step lookahead: exact pair fill is excellent; proportional waste reward otherwise.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 335.0;
        } else if next_item_size + 1 == pr {
            score -= 186.0;
        } else if next_item_size <= pr {
            let waste = (pr - next_item_size) as f64;
            score -= waste * 2.4;
            if (waste as u32) % 10 == 0 {
                score -= 24.0;
            }
        } else {
            let miss = (next_item_size - pr) as f64;
            score += miss.min(50.0) * 0.68 + 7.5;
        }
    }

    // Dead-space analysis after placement, combined with remaining-stream awareness.
    let dead = bin_residual as f64 - item_size as f64;
    if dead > 0.0 {
        let dead_frac = dead / capf;
        if next_item_size > 0 && dead < next_item_size as f64 {
            score += 12.0 + dead * 0.18 + (next_item_size as f64 - dead) * 0.9;
        } else if next_item_size > 0 && dead as u32 == next_item_size {
            score -= 50.0;
        } else {
            score -= dead * (0.055 + 0.05 * rem_frac) + dead_frac * dead_frac * 46.0;
        }
        if dead < 0.05 * capf && open_bins_count > 2 {
            score += 5.0 * (1.0 - dead / (0.05 * capf));
        }
        if dead > 0.0 && dead < 4.0 && pr > 4 {
            score += 14.0;
        }
        if dead_frac > 0.2 && dead_frac < 0.55 {
            score += dead_frac * (1.0 - progress) * 17.0;
        }
        if dead_frac > 0.55 && next_item_size > 0 && (next_item_size as f64) > dead {
            score += 9.0 * dead_frac;
        }
        if dead_frac >= 0.55 && dead_frac < 0.75 && next_item_size > 0 && (next_item_size as f64) <= dead * 0.5 {
            score -= 6.0 * dead_frac * (1.0 - progress);
        }
        // Mid-range dead-space bump: penalize awkward pockets.
        if dead_frac > 0.1 && dead_frac < 0.45 {
            let bump = (dead_frac - 0.275) * (dead_frac - 0.275);
            score += bump * 26.0 * (0.4 + 0.6 * (1.0 - progress));
        }
        // After-next-item leftover shaping.
        if next_item_size > 0 && dead as u32 >= next_item_size {
            let after = dead as u32 - next_item_size;
            if after == 0 || after <= 2 {
                score -= 24.0;
            } else if after as f64 <= 0.04 * capf {
                score -= 9.0;
            }
        }
        if dead_frac > 0.3 && progress > 0.6 {
            score += dead_frac * (progress - 0.6) * 30.0;
        }
        if dead_frac > 0.05 && dead_frac < 0.25 && progress > 0.35 {
            score += dead_frac * (progress - 0.35) * 22.0;
        }
        if next_item_size > 0 && dead > next_item_size as f64 && dead <= next_item_size as f64 + 3.0 {
            score -= 16.0 * (1.0 - progress);
        }
        if next_item_size > 0 && (dead as u32) % next_item_size == 0 && dead >= next_item_size as f64 && dead <= 2.0 * next_item_size as f64 {
            score -= 12.0 * (1.0 - progress);
        }
        if next_item_size > 0 && dead as f64 >= next_item_size as f64 && dead as f64 <= 1.5 * next_item_size as f64 && progress > 0.5 {
            score -= 8.0 * (1.0 - progress);
        }
        if dead_frac >= 0.45 && dead_frac <= 0.5 && next_item_size > 0 && (next_item_size as f64) >= dead * 0.5 && (next_item_size as f64) <= dead {
            score -= 10.0 * (1.0 - progress);
        }
    }

    // Pair-fill reward when bin can host item + next item together (tight pair preferred).
    if next_item_size > 0 {
        let pair = item_size as f64 + next_item_size as f64;
        if bin_residual as f64 >= pair {
            let slack = bin_residual as f64 - pair;
            score -= 38.0 - (slack / capf) * 28.0;
        }
    }

    // Consolidation pressure when many bins are open, stronger early.
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    score -= bin_pressure * 2.4 * (1.0 - progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 48.0;
    }

    // Mean-residual anchoring, stronger later in the stream.
    score -= (0.38 + 0.17 * progress) * (mean_residual - pr as f64);

    // Residual-vs-mean-ratio shaping: prefer post residual near fleet mean.
    if pr > 0 {
        let dev = ((pr as f64) - mean_residual).abs() / capf;
        score += dev * 8.0 * (1.0 - progress);
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let next_tight = next_item_size > 0 && mean_residual < next_item_size as f64;
        if next_tight || fitting_bins_count <= 1 {
            score -= 32.0;
        } else {
            score += 36.0 + 1.5 * bin_pressure;
        }
        if fitting_bins_count > 1 && progress > 0.5 {
            score += 25.0;
        }
        // Large items fragment open bins; better to open fresh for them.
        if item_size as f64 > 0.6 * capf {
            score -= 12.0;
        }
        if next_item_size > 0 && (item_size as f64 + next_item_size as f64) > capf {
            score -= 16.0;
        }
        if item_size as f64 > 0.78 * capf && mean_residual < 0.22 * capf {
            score -= 26.0;
        }
        if item_size as f64 > 0.85 * capf && mean_residual < 0.12 * capf {
            score -= 30.0;
        }
        if item_size as f64 > 0.93 * capf {
            score -= 20.0;
        }
        if progress > 0.7 && open_bins_count > 3 {
            score += 18.0 * progress;
        }
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 6.0 + (next_item_size as f64 - mean_residual) * 0.12;
        }
        let spread = (mean_residual - item_size as f64).abs();
        if spread < 0.08 * capf && fitting_bins_count > 2 {
            score += 9.0;
        }
        if item_size as f64 > mean_residual * 1.6 && fitting_bins_count > 1 && open_bins_count > 2 {
            score -= 14.0 * (1.0 - progress);
        }
        if next_item_size > 0 && next_item_size as f64 > 0.5 * capf && mean_residual > 0.3 * capf {
            score -= 10.0;
        }
        if fitting_bins_count > 1 && dead as f64 > 0.35 * capf && item_size as f64 > mean_residual * 1.25 {
            score -= 10.0 * (1.0 - progress);
        }
        if rem_items > 0.15 * total_items.max(1) as f64 && mean_residual < 0.5 * (next_item_size.max(1) as f64) {
            score -= 14.0 * (1.0 - progress);
        }
        if fitting_bins_count > 2 && mean_residual > 0.55 * capf {
            score += 7.0 * (1.0 - progress);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && mean_residual < (item_size as f64 + next_item_size as f64).min(capf) {
            score -= 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 0.85 && next_item_size as f64 <= mean_residual && progress > 0.4 {
            score -= 7.0 * (1.0 - progress);
        }
        // Prefer fresh bin when remaining stream is long and open bins are nearly full.
        if rem_items > 0.1 * total_items.max(1) as f64 && mean_residual < item_size as f64 * 1.1 && fitting_bins_count > 1 {
            score -= 9.0 * (1.0 - progress);
        }
    }

    // Usable-pocket bonus: residual after placement that can host next item tightly.
    if next_item_size > 0 && pr >= next_item_size && pr - next_item_size > 0 && (pr - next_item_size) < item_size.max(next_item_size) {
        score -= 16.0;
    }

    // Penalize leaving residual that next item cannot use, but only if small.
    if next_item_size > pr && pr > 0 && pr < 30 {
        score += 8.0;
    }

    // Usable-floor bonus: post residual above next-item floor is worth keeping.
    if pr > 0 {
        let usable_floor = (next_item_size.max(1) as f64).min(0.35 * capf);
        if (pr as f64) >= usable_floor {
            score -= 8.0 * (1.0 - progress) * ((pr as f64) / capf);
        }
    }
    if pr > 0 && (pr as f64) < 0.5 * (next_item_size.max(1) as f64) && fitting_bins_count > 1 {
        score += 6.0 * (1.0 - progress);
    }
    if pr > 0 && fitting_bins_count > 1 && (pr as f64) < 0.1 * capf && next_item_size > 0 && (next_item_size as f64) > pr as f64 {
        score += 4.0 * (1.0 - progress);
    }

    // Late-stream fine finishing: reward near-exact closes.
    if progress > 0.85 && pr <= 2 && pr > 0 {
        score -= 22.0;
    }
    if progress > 0.8 && pr > 0 {
        score += (pr as f64) * 0.35 * (progress - 0.8) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // Next item won't fit here; penalize leaving awkward gaps.
            score += 6.0 * (1.0 - fit_ratio);
        }
    } else {
        // Last item: waste minimization dominates.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when the item is huge or state is crowded.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        let waste = (bin_capacity - item_size) as f64;
        score += 35.0 - 10.0 * progress - 3.0 * crowding + 0.15 * waste;
        // A new bin is fine if the item nearly fills it.
        if item_size >= 90 {
            score -= 30.0;
        }
    }

    // Mild preference for fuller bins when many bins are open.
    score += 0.02 * mean_residual * (1.0 - fit_ratio);

    // Global fullness coupling: as stream progresses, tighten packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with stream-dependent curvature
    let mut score = norm_pr * (1.0 + 0.5 * progress * norm_pr);

    // Smooth non-linear coupling of post-residual with stream progress
    score += 0.35 * norm_pr * norm_pr * (1.0 - progress);
    score -= 0.25 * (norm_pr * (1.0 - norm_pr)).sqrt() * progress;

    // Penalize dead space relative to mean residual (smooth quadratic)
    let dead = (pr - mean_residual).abs() / cap;
    score += 0.2 * dead * dead * (1.0 + progress);

    // Last-chance bonus: smooth reward when this is the only fitting bin
    if fitting_bins_count <= 1 {
        score -= 0.6 * (1.0 - progress);
    }

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        let gap_norm = gap / cap;
        if pr >= nxt {
            score -= 0.3 * (1.0 - gap_norm) * (1.0 - progress);
        } else {
            score += 0.15 * gap_norm * gap_norm;
        }
    }

    // Mild penalty for spreading across many open bins late in stream
    score += 0.05 * (open_bins_count as f64).ln() * norm_pr * progress;

    // New-bin candidate: neutral-ish score so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score = cap * 0.5 + 0.3 * (1.0 - progress) * mean_residual / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "dead zones" (small, unusable remainders) should be penalized.
    let dead = if post_residual == 0 { 0.0 }
        else if post_residual < 10 { 60.0 }        // tiny dead space
        else if post_residual < 20 { 25.0 }        // hard to fill
        else if post_residual <= 30 { 0.0 }        // sweet spot (small items 10..30 fit)
        else if post_residual <= 50 { 8.0 }
        else { 0.0 };
    score += dead;

    // Reward perfect / near-perfect packing.
    if post_residual == 0 { score -= 200.0; }

    // Lookahead: if the next item can fit in the post residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0 + (post_residual - next_item_size) as f64;
    } else if next_item_size > post_residual {
        // Next item cannot use the leftover: mild penalty proportional to waste risk.
        score += (next_item_size.saturating_sub(post_residual)) as f64 * 0.3;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New empty bin candidate: only attractive when it's genuinely better
    // than squeezing into a poor fit. Penalize opening new bins, more so
    // when several bins already fit the item or residuals are still large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 150.0
            + (open_bins_count as f64) * 5.0
            + progress * 40.0;
        if fitting_bins_count >= 1 { new_bin_score += 60.0; }
        if next_item_size > 0 && next_item_size <= item_size {
            // next item is small: fresh bin still has room, slight discount
            new_bin_score -= 20.0;
        }
        score += new_bin_score;
    }

    // Prefer bins whose residual is already small (tight fits first),
    // scaled by how far below the mean residual this bin sits.
    score += (bin_residual as f64 - mean_residual) * 0.25;

    // Modulo-class bonus: leftover that is a multiple of a common small item
    // size (10/20) is more reusable.
    if post_residual % 10 == 0 && post_residual > 0 { score -= 12.0; }
    if post_residual % 20 == 0 && post_residual > 0 { score -= 8.0; }

