        score -= 560.0;
    } else if pr <= 3 {
        score -= 268.0;
    } else if pr <= 5 {
        score -= 134.0;
    } else if pr <= 16 {
        score -= 86.0;
    } else if pr <= 40 {
        score -= 16.0;
    } else if pr <= 66 {
        score -= 4.0;
    }

    // Dead-space penalty for residuals too small for typical items.
