    // New-bin candidate handling: neutral baseline, slightly discouraged
    // unless the item fits poorly everywhere (handled via last-chance logic below).
    if bin_residual == bin_capacity {
        score += 40.0;
        // If next item is large, opening a fresh bin is more attractive
        if next_item_size > 0 && next_item_size >= post_residual {
            score -= 25.0;
        }
        return score;
    }

    // --- 2-step lookahead core ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-chain: bin becomes exactly full after next item
            score -= 120.0;
