        // Last item: prefer exact closure
        if post_residual == 0 {
            score -= 150.0;
        }
    }

    // --- Tightness of current placement ---
    let tight = item_size as f64 / bin_residual as f64;
    score -= 25.0 * tight * tight;

    // --- Relative residual context ---
    // Prefer bins whose residual deviates favorably from the mean:
    // tight bins (below-mean residual) are precious, use them well.
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 5.0;
    }

    // --- Last-chance bonus: only bin that fits, avoid opening new bin ---
    if fitting_bins_count == 1 {
        score -= 45.0;
        // Extra pull if the chain works here too
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Slight preference for using fewer bins overall
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
