pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer tight fit (small post_residual).
    let mut score = post;

    // Dead-space penalty: residuals too small for any plausible item are wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0 * (1.0 - post / 10.0);
    }

    // Lookahead coupling: reward if next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            // Slack that can host next item: reward proportional to how snugly it fits.
            let snug = 1.0 - ((post - nx) / cap);
            score -= 18.0 * snug;
        } else {
            // Next item won't fit here: mild penalty scaled by how badly.
            score += 8.0 * (nx - post) / cap;
        }
    }

    // Last-chance bonus: only bin that fits -> strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // With alternatives, prefer bins where this item is a better relative fit.
        let fill = 1.0 - (bin_residual as f64) / cap;
        score -= 10.0 * fill;
    }

    // Prefer bins below mean residual when many bins open (balance load),
    // above mean when few bins open (consolidate).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    if open_bins_count > 4 {
        score += 6.0 * dev;
    } else {
        score -= 4.0 * dev;
    }

    // Time horizon: early on, allow opening new bins (mild penalty for new-bin reuse),
    // late in stream, strongly discourage opening new bins -> penalize high residual less.
    let new_bin = (bin_residual as u32 == bin_capacity) as f64;
    score += new_bin * (15.0 - 20.0 * progress) * (1.0 + (open_bins_count as f64).ln().max(0.0));

    // Slight preference for fuller bins as stream progresses.
    score -= progress * (bin_capacity as f64 - bin_residual as f64) * 0.3;

    score
}

