    }

    // Tiny post-residual with many fitting bins is wasteful fragmentation.
    if pr > 0 && fitting_bins_count > 1 && (pr as f64) < 0.1 * capf && next_item_size > 0 && (next_item_size as f64) > pr as f64 {
        score += 4.5 * (1.0 - progress);
    }
    // pr + dead together can't host next item -> wasted pocket.
    if pr > 0 && dead > 0.0 && next_item_size > 0 && (pr as f64 + dead) <= next_item_size as f64 && progress > 0.3 {
        score += 9.0 * (1.0 - progress);
    }
    // Very small pr with alternatives available.
    if pr > 0 && (pr as f64) < 0.06 * capf && fitting_bins_count > 2 {
        score += 5.0 * (1.0 - progress);
    }
    // pr exactly divisible by next item is reusable.
    if pr > 0 && next_item_size > 0 && (pr as u32) % next_item_size == 0 && pr >= next_item_size {
        score -= 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: exponential bonus as post_residual -> 0
    score -= 60.0 * (-post_residual as f64 / 8.0).exp();

    // Harmonic class of post_residual: residual classes mod 10 and mod 25
    // Small residuals (<10) are near-dead space; penalize mildly beyond base.
    let dead_class = (post_residual < 10) as i32;
    // Residuals in [10..=20] are "reusable by small items" class: reward
    let reusable_small = (post_residual >= 10 && post_residual <= 20) as i32;
    // Exact half-capacity class is highly reusable
    let half_class = (post_residual == bin_capacity / 2) as i32;

    if dead_class == 1 {
        score += 15.0;
    }
    if reusable_small == 1 {
        score -= 10.0;
    }
    if half_class == 1 {
        score -= 25.0;
    }

    // Integer division threshold coupling: post_residual / item_size ratio
    let ratio = post_residual as f64 / (item_size.max(1) as f64);
    score -= 8.0 * (1.0 - (1.0 / (1.0 + ratio))).min(1.0);

    // Lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > post_residual {
        // next item won't fit here anyway; prefer leaving large residual
        score += 5.0 + (post_residual as f64) * 0.05;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening new bins, more when many open
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 + 6.0 * (open_bins_count as f64) + 20.0 * progress;
        // But if mean residual across open bins is too small to fit typical items,
        // opening fresh is fine: reduce penalty
        if mean_residual < item_size as f64 * 1.2 {
            score -= 55.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference to spread load when many bins open and residual large
    if open_bins_count > 3 && post_residual > bin_capacity / 3 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capf = bin_capacity as f64;
    let pr = post_residual;
    let dead = bin_residual as f64 - item_size as f64;
    let dead_frac = if dead > 0.0 { dead / capf } else { 0.0 };
    let progress = step_index as f64 / total_items.max(2) as f64;
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    let mut score = pr as f64;

    // Tiered post-residual rewards: exact and near-exact fills dominate.
    if pr == 0 {
        score -= 420.0;
    } else if pr <= 3 {
        score -= 200.0;
    } else if pr <= 6 {
        score -= 100.0;
    } else if pr <= 18 {
        score -= 40.0;
    } else if pr <= 40 {
        score -= 10.0;
    } else if pr <= 66 {
