pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect chain match bonus
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Post-residual exactly matches next item: ideal chaining
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Next item fits: bonus scaled by how much slack remains after that
            let slack_after_next = post_residual - next_item_size;
            score -= 20.0 - (slack_after_next as f64) * 0.3;
        } else {
            // Next item won't fit: penalize wasted residual
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    } else {
        // Last item: just minimize residual
        score -= 5.0;
    }

    // Tight fit reward: low post_residual relative to item size
    score -= (item_size as f64) * 0.15;

    // Penalize bins whose residual is far below the mean (already packed tight,
    // likely to become dead space) unless this is a very tight fit
    if (post_residual as f64) < mean_residual * 0.5 && post_residual > 0 {
        score += 3.0;
    }

    // Last chance: only this bin fits -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: discourage opening a new bin unless all open bins
    // would leave large residuals (poor fits) or late in the stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fits = open_bins_count as f64 * 0.5;
        score += 30.0 - poor_fits - progress * 10.0;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 35.0; // next item is huge, fresh bin useful
        }
    }

    // Mild reward for using bins that are already partially filled
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: fraction of bin filled by this item.
    let fill = item_size as f64 / cap;
    score -= 60.0 * fill * fill;

    // Penalize small post-residuals that become dead space unless next item fits.
    if post_residual > 0 {
        let dead = post_residual as f64;
        let next_fits = next_item_size > 0 && next_item_size <= post_residual;
        if !next_fits {
            // dead space penalty scaled by how far below smallest plausible item (1..100 unknown; use relative)
            score += 0.8 * (dead / cap) * (dead / cap) * 100.0;
        } else {
            // next item fits: reward good chaining
            let chain_tightness = next_item_size as f64 / dead;
            score -= 20.0 * chain_tightness;
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Many open bins: prefer consolidating into fuller bins (low residual).
    let fullness = (bin_residual as f64) / cap;
    score += (open_bins_count as f64).ln().max(0.0) * 8.0 * fullness;

    // Global mean residual coupling: if mean residual is high, encourage using bins
    // with residual near mean (avoid fragmenting); if low, be picky.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Time horizon: early in stream, be conservative (favor tight fits more);
    // late in stream, allow opening new bins less (favor existing bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 30.0 * progress * (1.0 - fullness);

    // New-bin candidate handling: neutral baseline with slight penalty so it is
    // only chosen when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 25.0 + 20.0 * (1.0 - progress);
        // If next item is large, a fresh bin may be valuable.
        if next_item_size as f64 / cap > 0.6 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr_norm = pr / cap; // 0..1
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    // Early stream: prefer tight fits (low post_residual); later: tolerate larger residuals
    // because lookahead lets us plan. Smooth cubic interaction.
    let coupling = pr_norm * (1.0 - 3.0 * prog2 + 2.0 * prog3); // smooth S'-like weight
    score += 8.0 * coupling;

    // Lookahead: if next item fits in post_residual, reward this bin (subtract).
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_ratio = next_item_size as f64 / pr.max(1.0);
        score -= 6.0 * fit_ratio * (1.0 - progress);
    } else if next_item_size > 0 {
        // Dead space penalty scaled by how badly next item misses, smooth quadratic.
        let miss = (next_item_size as f64 - pr) / cap;
        score += 4.0 * miss * miss * cap;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Prefer bins with residuals close to mean (balance), smooth quadratic.
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Penalize very small unusable residuals (dead space) smoothly.
    if pr < 10.0 && pr > 0.0 {
        score += (10.0 - pr) * (10.0 - pr) * 0.1;
    }

    // New-bin candidate: mild bias so it's chosen only when open bins look bad.
    if bin_residual == bin_capacity {
        score += 3.0 + 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: small residues are "dead space".
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class boundaries via integer division on capacity fractions.
    let class = post_residual / 10; // harmonic decade class 0..=10
    match class {
        0 => score -= 25.0,          // perfect fit: residue < 10 is gold
        1 => score -= 15.0,          // near-perfect
        2 | 3 => score += 3.0,       // awkward mid-small residue
        4 | 5 => score += 8.0,       // dead zone: nothing 10..80 fits well
        _ => {}
    }

    // Coupling with next item: does next_item_size land in this post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here: reward proportionally to snugness.
            let snug = 1.0 - ((post_residual - next_item_size) as f64) / cap;
            score -= 12.0 * snug;
        } else {
            // Next item cannot use this bin: penalize large leftover residues.
            score += pr * 0.05;
        }
    } else {
        // Last item: minimize waste outright.
        score = pr;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: neutral-ish, but allow it when open bins are crowded
    // or the fit here would be terrible.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / cap);
        score = cap as f64 * 0.5 + crowd * 2.0;
        if post_residual == bin_capacity && next_item_size > 0 && next_item_size > mean_residual as u32 {
            score -= 10.0; // stream has large items; fresh bin useful
        }
    }

    // Late-stream pressure: consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - pr).max(-30.0).min(30.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that cannot fit even the smallest conceivable item is pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0) + 25.0;
    }

    // Dead space relative to the lookahead item: if the next item cannot use
    // this leftover space, the gap is likely to become permanent waste.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + 0.25 * post_residual as f64;
    }

    // Perfect fit reward: leaving exactly zero residual is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward placements that leave room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.2 * next_item_size as f64;
    }

    // Open-bin pressure: with many open bins, prefer tightening existing bins
    // rather than spreading items; penalize bins that stay loosely filled.
    score += 0.6 * open_bins_count as f64;

    // If this bin is the only one that fits, strongly favor using it to avoid
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make opening a new bin costly unless the current bin
    // would be left with severe dead space or the fit is poor.
    if bin_residual == bin_capacity {
        score += 55.0 + 0.5 * open_bins_count as f64;
        // But if every existing bin would end with a tiny dead gap, opening a
        // fresh bin is attractive.
        if post_residual > 0 && post_residual < 10 {
            score -= 70.0;
        }
    }

    // Mild preference for filling bins that are already tight relative to mean.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Early-stream exploration: fewer bins early means compounding savings.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills: small post_residual is good, but a post_residual
    // that exactly matches the next item's size is even better (2-step lookahead).
