        score -= 20.0;
    }

    // Penalize wasting a nearly-empty (new) bin on a tiny item when other bins fit.
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - item_size as f64 / bin_capacity as f64);
    }

    // Slight preference for filling bins as the stream progresses (fewer open bins).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
