pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score as post_residual approaches 0.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 35.0 * tightness * tightness;

    // Perfect fill is highly desirable.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: penalize if the leftover space can't fit the next item (dead space),
    // reward if the next item fits the post-residual (chain packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
        } else if post_residual > 0 && post_residual < 10 {
            score += 8.0; // tiny dead space
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 6.0 * (post_residual as f64 / next_item_size as f64);
        }
    }

    // Penalize creating unusable residual below the minimum item size (1..100 range guard: <10).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Global state coupling: when many bins are open with high mean residual,
    // discourage opening new bins; encourage consolidating into existing space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty grows with open bins and mean residual.
        score += 25.0 + 2.0 * open_bins_count as f64 + 0.15 * mean_residual;
        // Early in the stream, new bins are cheaper; late, prefer consolidation.
        score += 20.0 * (1.0 - progress);
    } else {
        // Existing bin: slight reward scaling with mean residual (absorbing slack).
        score -= 0.05 * mean_residual;
    }

    // Prefer filling bins that are already partially depleted (low residual relative to capacity).
    score -= 10.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // Mild item-size interaction: large items should go into large-residual bins.
    let large_item = item_size as f64 / bin_capacity as f64;
    score += 15.0 * large_item * (post_residual as f64 / bin_capacity as f64);

    score
}

