pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Normalized post-residual in [0,1]
    let norm_post = post / cap;

    // Smooth polynomial coupling: penalize large post_residual, more so later in the stream
    let mut score = post;

    // Quadratic/cubic waste penalty growing with stream progress
    let poly = norm_post * norm_post * (1.0 + norm_post);
    score += 30.0 * progress * poly * cap;

    // Reward tight fits (small post_residual) smoothly
    score -= (1.0 - norm_post) * (1.0 - norm_post) * 8.0;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Penalize bins far from mean residual (smooth dispersion term)
    let mean_post = mean_residual - item_size as f64;
    let disp = (post - mean_post) / cap;
    score += 6.0 * disp * disp * cap;

    // Lookahead: reward residual that can still host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 5.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 4.0 * (nxt - post) / cap * (1.0 - progress);
        }
    }

    // Mild preference for consolidating into fewer bins when many are open
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_post);

    // New-bin candidate: penalize opening a new bin, unless residual would be small
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * progress - 10.0 * (1.0 - norm_post);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into
    // "reusable" classes (multiples of common small item sizes), penalize dead zones.
    let pr = post_residual;
    if pr > 0 {
        let class = pr % 10;
        // residuals near multiples of 10 are more likely to be filled later
        let harmony = (5 - ((class as i32) - 5).abs()) as f64; // peak at class=0
        score -= 2.0 * harmony;
    } else {
        // perfect fill: strong reward
        score -= 60.0;
    }

    // Dead-space penalty: small unusable post_residual (< 10, min item size)
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && pr >= next_item_size {
        let diff = pr - next_item_size;
        if diff == 0 {
            score -= 50.0;
        } else if diff < 10 {
            score += 15.0; // leads to dead space next step
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // next item won't fit here: mild penalty, scaled by tightness
        score += (next_item_size as f64) * 0.15;
    }

    // Last-chance bin: avoid wasting the only fitting bin on a bad fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: prefer existing bins unless fit is poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // opening a new bin costs; make it attractive only when current fit is bad
        let fit_quality = (bin_capacity - item_size) as f64; // residual if placed here
        let pressure = (open_bins_count as f64) * 0.5;
        score += 40.0 - pressure + 0.3 * fit_quality;
        // late in stream, opening bins is cheaper (less future to serve)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress;
    }

    // Tight fits are good: reward small post_residual relative to item
    if item_size > 0 {
        score -= (item_size as f64) * 0.1;
    }

    // Integer-division threshold: bins whose residual after placement keeps
    // a "half-capacity harmonic" (pr in [40,60]) are flexible
    if pr >= 40 && pr <= 60 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
