        score += 6.5 * (1.0 - progress);
    }

    // Late-stream fine finishing: reward near-exact closes.
    if progress > 0.85 && pr <= 2 && pr > 0 {
        score -= 21.0;
    }
    if progress > 0.8 && pr > 0 {
        score += (pr as f64) * 0.38 * (progress - 0.8) * 5.0;
    }

    // Tiny post-residual with many fitting bins is wasteful fragmentation.
    if pr > 0 && fitting_bins_count > 1 && (pr as f64) < 0.1 * capf && next_item_size > 0 && (next_item_size as f64) > pr as f64 {
        score += 4.5 * (1.0 - progress);
    }
    // pr + dead together can't host next item -> wasted pocket.
    if pr > 0 && dead > 0.0 && next_item_size > 0 && (pr as f64 + dead) <= next_item_size as f64 && progress > 0.3 {
        score += 9.0 * (1.0 - progress);
    }
    // Very small pr with alternatives available.
    if pr > 0 && (pr as f64) < 0.06 * capf && fitting_bins_count > 2 {
        score += 5.0 * (1.0 - progress);
    }
    // pr exactly divisible by next item is reusable.
    if pr > 0 && next_item_size > 0 && (pr as u32) % next_item_size == 0 && pr >= next_item_size {
        score -= 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 15.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
    } else if next_item_size > post_residual {
        score += 10.0;
    }

    // Prefer bins tighter than average (good fits).
    score += ((bin_residual as f64) - mean_residual) * 0.3;

    score
}

