pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual), especially when item nearly fills the bin.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 22.0 * tightness * tightness;

    // Penalize dead space: residuals too small to be useful for future items.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 18.0 * (10.0 - dead) / 10.0; // tiny slivers are wasted space
        }
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 14.0 - 0.08 * slack_after_next as f64;
        } else {
            // Next item won't fit here after placement: mild penalty unless bin is nearly full anyway.
            score += 6.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

