    // (keeps a diverse residual portfolio; avoids systematically fragmenting).
    let dev = ((bin_residual as f64) - mean_residual).abs();
    score += 0.9 * dev;

    // Time horizon: late in the stream, favor consolidation over opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
