    // New-bin candidate handling: an empty bin should only win when the item is large
    // or the current fit is poor / lookahead is bad.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64) / (bin_capacity as f64);
        score += 10.0 - 14.0 * large_item; // bias against new bin for small items
        if fitting_bins_count <= 1 {
            score -= 8.0; // no good alternative: new bin is fine
        }
        if next_item_size > 0 && (next_item_size as u32) > post_residual {
            score -= 4.0; // next item is big; fresh bin gives room
        }
    }

    score
}

