pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues near capacity multiples matter.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity wasted after placement.
    let waste_frac = pr / cap;
    score += 40.0 * waste_frac * waste_frac;

    // Integer-division threshold classes on post_residual.
    // Class 0: pr <= 10 (dead space, unusable by any item) -> strongly reward.
    // Class 1: 10 < pr <= 20 -> mild dead space.
    // Class 2: pr > 20 -> usable leftover, penalize moderately.
    if post_residual <= 10 {
        score -= 12.0;
    } else if post_residual <= 20 {
        score -= 4.0;
    } else {
        score += 3.0;
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            // Perfect chaining: next item exactly fills remainder.
            if post_residual == next_item_size {
                score -= 15.0;
            } else {
                // Reward proportional to how well next item consumes the leftover.
                let fill = nxt / pr.max(1.0);
                score -= 10.0 * fill;
                // Modulo coupling: next item's size class vs post residual class.
