                let post_class = post_residual / 20;
                if next_class == post_class {
                    score -= 3.0;
                }
            }
        } else {
            // Next item cannot use this leftover; penalize if leftover is stranded.
            score += 4.0 * (1.0 - waste_frac);
        }
    } else {
        // Last item: minimize final residual aggressively.
        score += 0.5 * pr;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: neutral-to-slightly-high baseline.
    if bin_residual == bin_capacity {
        // A new bin's post_residual == capacity - item_size; keep it competitive
        // only when existing bins fit poorly. Penalize mildly so tight fits win.
        score += 6.0;
        // Early in the stream, opening bins is cheaper; late, discourage.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 * progress;
        // If many bins are open, discourage adding more.
        score += 0.4 * open_bins_count as f64;
    }

    // Crowd the emptiest bins: prefer bins whose residual deviates below mean.
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score -= 0.15 * dev;
    }

    // Harmonic residue bonus: post_residual divisible structure.
    match post_residual % 25 {
        0 => score -= 5.0,           // exact quarter classes -> clean splits
        5 | 10 | 15 | 20 => score -= 1.0,
        _ => {}
    }

    score
}

