        if next_tight || fitting_bins_count <= 1 {
            score -= 34.0;
        } else {
            score += 38.0 + 1.5 * bin_pressure;
        }
        if fitting_bins_count > 1 && progress > 0.5 {
            score += 26.0;
        }
        if item_size as f64 > 0.6 * capf {
            score -= 13.0;
        }
        if next_item_size > 0 && (item_size as f64 + next_item_size as f64) > capf {
            score -= 17.0;
        }
        if item_size as f64 > 0.78 * capf && mean_residual < 0.22 * capf {
            score -= 27.0;
        }
        if item_size as f64 > 0.85 * capf && mean_residual < 0.12 * capf {
            score -= 32.0;
        }
        if item_size as f64 > 0.93 * capf {
            score -= 21.0;
        }
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 6.0 + (next_item_size as f64 - mean_residual) * 0.13;
        }
        if fitting_bins_count > 1 && mean_residual < item_size as f64 * 0.4 {
            score += 12.0;
        }
        if progress > 0.7 && open_bins_count > 3 {
            score += 19.0 * progress;
        }
        let spread = (mean_residual - item_size as f64).abs();
        if spread < 0.08 * capf && fitting_bins_count > 2 {
            score += 9.5;
        }
        if item_size as f64 > mean_residual * 1.6 && fitting_bins_count > 1 && open_bins_count > 2 {
            score -= 15.0 * (1.0 - progress);
        }
        if next_item_size > 0 && next_item_size as f64 > 0.5 * capf && mean_residual > 0.3 * capf {
            score -= 10.5;
        }
        // Fresh-bin lookahead: avoid opening a bin that strands a large residual.
        if next_item_size > 0 && item_size as f64 > 0.55 * capf && (capf - item_size as f64) < next_item_size as f64 && mean_residual >= item_size as f64 {
            score += 24.0 * (1.0 - progress);
        }
        let rem_items = (total_items.saturating_sub(step_index)) as f64;
        if rem_items > 0.15 * total_items.max(1) as f64 && mean_residual < 0.5 * (next_item_size.max(1) as f64) {
            score -= 15.0 * (1.0 - progress);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && mean_residual < (item_size as f64 + next_item_size as f64).min(capf) {
            score -= 6.5 * (1.0 - progress);
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 0.85 && next_item_size as f64 <= mean_residual && progress > 0.4 {
            score -= 8.0 * (1.0 - progress);
        }
    }

    // Usable-floor bonus: post-residual big enough to host next item.
    if pr > 0 {
        let usable_floor = (next_item_size.max(1) as f64).min(0.35 * capf);
        if (pr as f64) >= usable_floor {
            score -= 8.5 * (1.0 - progress) * ((pr as f64) / capf);
        }
    }
    if pr > 0 && (pr as f64) < 0.5 * (next_item_size.max(1) as f64) && fitting_bins_count > 1 {
        score += 6.5 * (1.0 - progress);
    }

    // Late-stream tightness.
    if progress > 0.85 && pr <= 2 && pr > 0 {
        score -= 21.0;
    }
    if progress > 0.8 && pr > 0 {
        score += pr as f64 * 0.38 * (progress - 0.8) * 5.0;
    }
    if pr > 0 && fitting_bins_count > 1 && (pr as f64) < 0.1 * capf && next_item_size > 0 && (next_item_size as f64) > pr as f64 {
        score += 4.5 * (1.0 - progress);
    }
    if pr > 0 && dead > 0.0 && next_item_size > 0 && (pr as f64 + dead) <= next_item_size as f64 && progress > 0.3 {
        score += 9.0 * (1.0 - progress);
    }
    if pr > 0 && (pr as f64) < 0.06 * capf && fitting_bins_count > 2 {
        score += 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly (or nearly) matches the next item's size.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        let gap = (pr - nr).abs();
        if gap == 0.0 {
            score -= 500.0; // exact chain fit
        } else if pr >= nr {
            // next item fits: prefer minimal leftover after chaining
            score -= 200.0 / (1.0 + (pr - nr) / nr);
        } else {
            // next item does not fit: penalize proportionally to shortfall
            score += (nr - pr) * 1.5;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless post_residual is large enough
    // to plausibly host the next item (lookahead-aware opening).
    if bin_residual == bin_capacity {
        let base_new = 300.0;
        let lookahead_ok = next_item_size > 0 && (post_residual as f64) >= next_item_size as f64;
        if lookahead_ok {
            score = base_new - 50.0;
        } else {
            score = base_new + (fitting_bins_count as f64) * 40.0;
        }
        // late in the stream, consolidating is cheaper
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 50.0;
    }

    // Mild penalty for many open bins to encourage consolidation
    score += open_bins_count as f64 * 0.5;

    score
}

