    // another item (min item size = 1, but tiny gaps are practically useless)
    // are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0; // gap 1 -> +56, gap 9 -> +24
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
