        score -= 10.0;
    }

    // Fit quality: fraction of the bin's free space consumed by this item.
    let free = (bin_residual.max(1)) as f64;
    let fill_ratio = item_size as f64 / free;
    score -= fill_ratio * 25.0;

    // Dead-space shape penalty: post_residual that cannot host the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage opening a new one,
    // mildly encourage packing into existing bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score += 20.0 + (open_bins_count as f64) * 3.0;
        // A new bin is acceptable if existing residuals are small (poor fits).
        if mean_residual < item_size as f64 * 0.5 {
            score -= 25.0;
        }
    } else {
        // Existing bin gets a small bonus scaled by open-bin pressure.
        score -= (open_bins_count as f64) * 1.5;
    }

    // Late in the stream, consolidate: prefer tight packing into open bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual != bin_capacity {
            score -= progress * 12.0;
        } else {
            score += progress * 12.0;
        }
    }

    score
