pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Slack after also fitting the next item — the tighter this combined fit,
            // the better (minimize leftover slack after two items).
            let two_step_slack = post_residual - next_item_size;
            score -= 30.0 + 0.5 * two_step_slack as f64;
        } else {
            // Next item cannot follow into this bin: penalize proportionally to the shortfall.
            let shortfall = next_item_size - post_residual;
            score += 0.8 * shortfall as f64;
        }
    }

    // Perfect fit bonus: leaving zero residual is ideal.
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Penalize small dead space that is unlikely to be usable
        // (below the minimum plausible item size band).
        let dead = post_residual as f64;
        if dead < 20.0 {
            score += 1.5 * (20.0 - dead);
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably.
