        score -= 25.0;
    }

    // New-bin candidate (empty bin): only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 40.0 + 0.1 * open_bins_count as f64;
    }

    // Late-stream tightening: as the stream progresses, prefer tighter packings.
