    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Exact or near-exact fill: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead (k=2): reward bins whose post_residual can host the next item well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space for the next item: penalize proportionally.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.25 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize spreading across many open bins when mean residual is high
    // (encourages consolidating into fuller bins).
    if open_bins_count > 0 {
        let fullness = 1.0 - mean_residual / bin_capacity as f64;
        score -= 8.0 * fullness;
    }

    // Time horizon: early in stream, be more willing to open new bins
    // (new-bin candidate gets a mild boost late, penalty early).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base attractiveness plus late-stream penalty.
        score = score * 0.9 + 12.0 + 15.0 * progress;
        // If item fits poorly anywhere, new bin looks better: compare against residual.
        if bin_capacity - item_size <= 10 {
            score -= 20.0;
        }
    } else {
        // Open bins get slightly better late in the stream.
        score -= 5.0 * progress;
    }

    // Mild penalty for leaving very small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

