        score -= 30.0;
    }

    // Lookahead: if next item fits exactly into post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
