        // Prefer new bin if the item is large and no bin fits well.
        if item_size > bin_capacity / 2 {
            score -= 5.0;
        }
    }

    // Global state coupling: when mean residual is high, favor bins below it
    // (consolidate), when mean residual is low, spread slightly.
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.05 * diff;
    }

    // Time horizon: late in stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    // Slight preference for bins with residuals close to item size (exact-ish fit).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.02 * gap;

    score
}

