        score -= 0.6 * item_size as f64 * (0.5 + progress);
    }

    // Lookahead: reward leaving space that still fits the next item
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 0.35 * next_item_size as f64 * (1.0 - norm_pr * norm_pr);
    } else if next_item_size > post_residual {
        score += 0.15 * next_item_size as f64 * norm_pr;
    }

    // Slight preference for tight fills relative to mean residual
    score -= 0.2 * (mean_residual - pr).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
