    let mod20 = post_residual % 20;
    let mod25 = post_residual % 25;

    // Dead-space penalty: residuals that are small but not zero are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward residuals that fall into "harmonic" classes likely to be exactly filled by future items.
    if mod10 == 0 {
        score -= 6.0;
    } else if mod20 == 0 {
        score -= 5.0;
    } else if mod25 == 0 {
        score -= 4.0;
    }

    // Lookahead: does next item fit into post_residual exactly or well?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect follow-up fill
