        } else {
            // next item cannot follow; residual likely terminal dead space
            score += 0.05 * (post_residual as f64);
        }
    }

    // Fraction of capacity wasted after placement
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 10.0 * waste_frac * waste_frac;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer tight fits generally (best-fit core)
    score -= 0.3 * (item_size as f64);

    // New-bin candidate handling: only attractive early in the stream or when open bins are crowded
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score = 55.0 + 40.0 * progress + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 30.0; // forced open
        }
    }

    // Mild pressure toward consolidating into bins with low mean residual spread
    if (post_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

