pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small dead space" classes get penalized, "usable" classes rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity left after placement
    let frac = pr / cap;

    // Class A: post_residual <= 10 -> dead space penalty (quadratic)
    if post_residual <= 10 {
        score += (10.0 - pr) * 3.0;
    }
    // Class B: 10 < post_residual <= 25 -> mildly undesirable
    else if post_residual <= 25 {
        score += (25.0 - pr) * 0.5;
    }
    // Class C: 25 < post_residual <= 50 -> neutral to good, reward tight fits
    else if post_residual <= 50 {
        score -= (50.0 - pr) * 0.8;
    }
    // Class D: large residual -> reward keeping room for future items
    else {
        score -= (pr - 50.0) * 0.3;
    }

    // Integer-division harmonic classes on post_residual
    let class = post_residual / 10;
    match class {
        0 => score += 8.0,          // 0..9: near-dead
        1 => score += 3.0,          // 10..19
        2 => score -= 1.0,          // 20..29
        3 => score -= 4.0,          // 30..39 sweet spot
        4 => score -= 3.0,          // 40..49
        5 => score -= 2.0,          // 50..59
        _ => score -= 1.0,          // large residual
    }

    // Modulo-5 class: leftovers divisible by 5 pair well with typical item sizes
    if post_residual % 5 == 0 {
        score -= 2.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let leftover_after_next = post_residual - next_item_size;
            score -= (leftover_after_next as f64).min(20.0) * 0.4;
        } else {
            // next item won't fit here; penalize large residuals less if stream late
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += (next_item_size - post_residual) as f64 * 0.2 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a base opening cost,
    // reduced late in the stream or when few bins fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut open_cost = 20.0 + 10.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            open_cost -= 30.0; // forced open
        } else if fitting_bins_count == 1 {
            open_cost += 10.0; // keep the last-chance bin alive
        }
        // mean residual high -> existing bins are roomy, opening is fine
        open_cost -= (mean_residual / cap).min(1.0) * 5.0;
        score += open_cost;
    }

    // Prefer bins tighter than average (best-fit flavor)
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Slight pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.05;

    score
}

