        }
        if item_size as f64 > 0.93 * capf {
            score -= 21.0;
        }
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 6.0 + (next_item_size as f64 - mean_residual) * 0.13;
        }
        if fitting_bins_count > 1 && mean_residual < item_size as f64 * 0.4 {
            score += 12.0;
        }
        if progress > 0.7 && open_bins_count > 3 {
            score += 19.0 * progress;
        }
        let spread = (mean_residual - item_size as f64).abs();
        if spread < 0.08 * capf && fitting_bins_count > 2 {
            score += 9.5;
        }
        if item_size as f64 > mean_residual * 1.6 && fitting_bins_count > 1 && open_bins_count > 2 {
            score -= 15.0 * (1.0 - progress);
        }
        if next_item_size > 0 && next_item_size as f64 > 0.5 * capf && mean_residual > 0.3 * capf {
            score -= 10.5;
        }
        if fitting_bins_count > 1 && dead > 0.35 * capf && item_size as f64 > mean_residual * 1.25 {
            score -= 11.0 * (1.0 - progress);
        }
        let rem_items = if total_items > step_index { (total_items - step_index) as f64 } else { 0.0 };
        if rem_items > 0.15 * total_items.max(1) as f64 && mean_residual < 0.5 * (next_item_size.max(1) as f64) {
            score -= 15.0 * (1.0 - progress);
        }
        if fitting_bins_count > 2 && mean_residual > 0.55 * capf {
            score += 7.5 * (1.0 - progress);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && mean_residual < (item_size as f64 + next_item_size as f64).min(capf) {
            score -= 6.5 * (1.0 - progress);
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 0.85 && next_item_size as f64 <= mean_residual && progress > 0.4 {
            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && item_size as f64 > 0.55 * capf && (capf - item_size as f64) < next_item_size as f64 && fitting_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 24.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0 && pr == next_item_size && fitting_bins_count > 0 {
            score -= 12.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fitting_bins_count > 0 && mean_residual >= next_item_size as f64 && mean_residual < next_item_size as f64 + 5.0 {
            score -= 9.0 * (1.0 - progress);
        }
        if open_bins_count > 4 && fitting_bins_count > 1 && mean_residual > 0.45 * capf {
            score += 5.0 * progress;
        }
    }

    // Usable-floor bonus: post residual above next-item floor is worth keeping.
    if pr > 0 {
        let usable_floor = (next_item_size.max(1) as f64).min(0.35 * capf);
        if (pr as f64) >= usable_floor {
            score -= 8.5 * (1.0 - progress) * ((pr as f64) / capf);
        }
    }
    if pr > 0 && (pr as f64) < 0.5 * (next_item_size.max(1) as f64) && fitting_bins_count > 1 {
        score += 6.5 * (1.0 - progress);
    }

    // Late-stream fine finishing: reward near-exact closes.
    if progress > 0.85 && pr <= 2 && pr > 0 {
        score -= 21.0;
    }
    if progress > 0.8 && pr > 0 {
        score += (pr as f64) * 0.38 * (progress - 0.8) * 5.0;
    }

    // Tiny post-residual with many fitting bins is wasteful fragmentation.
    if pr > 0 && fitting_bins_count > 1 && (pr as f64) < 0.1 * capf && next_item_size > 0 && (next_item_size as f64) > pr as f64 {
        score += 4.5 * (1.0 - progress);
    }
    // Very small pr with alternatives available.
    if pr > 0 && (pr as f64) < 0.06 * capf && fitting_bins_count > 2 {
        score += 5.0 * (1.0 - progress);
    }
    // pr + dead together can't host next item -> wasted pocket.
    if pr > 0 && dead > 0.0 && next_item_size > 0 && (pr as f64 + dead) <= next_item_size as f64 && progress > 0.3 {
        score += 8.7 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Near-perfect match (small slack after the lookahead item would fit).
    else if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 5 {
        score -= 15.0;
    }

    // Dead space: residual left is too small for the next item (wasted gap).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Penalize more if gap is far below next item (unusable dead space).
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Penalize leaving a large residual relative to mean (this bin stays "greedy" while others starve).
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.3;

    // Last-chance bin: strongly reward using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when the item fits poorly everywhere else
    // (i.e., placing here would leave a large dead gap).
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin can also serve the next item
        }
    }

    // Late in the stream, consolidate: prefer tighter fits slightly more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream: later items should prefer reusing existing bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin = bin_residual == bin_capacity;

    // Reward tight fits: small post_residual relative to capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items (unusable gap)
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 40.0; // tiny unusable sliver
        } else if dead < 30.0 {
            score += 0.3 * (30.0 - dead);
        }
    }

    // Lookahead: check if next item could fit in the post residual
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            // Good: leaves room for the next item -> reward proportionally
            let slack = post_residual as f64 - next_item_size as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Bad: next item won't fit here; penalize more if we leave a big gap anyway
            score += 8.0 + 0.15 * (post_residual as f64 - (bin_residual as f64 - next_item_size as f64)).abs();
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && !new_bin {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer the fullest bin (smallest residual)
        score += 0.1 * (bin_residual as f64 - mean_residual);
    }

    // New-bin decision: open a new bin only when existing fits are poor
    if new_bin {
        // Base penalty grows with stream progress (late stream: consolidate)
        score += 30.0 + 40.0 * progress;
        // But if current bin would leave a horrible fit (large post residual that
        // matches nothing), opening fresh is attractive
        if post_residual > 0 && (post_residual as f64) < 20.0 {
            score -= 20.0; // shouldn't happen for empty bin, keep symmetric guard
        }
        // If many bins are open already, discourage adding more
        score += 2.0 * (open_bins_count as f64).sqrt();
        // If next item is huge, a fresh bin keeps flexibility
        if next_item_size >= 60 {
            score -= 10.0;
        }
    } else {
        // Reward using bins that are already heavily loaded (fill-before-open)
        let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 18.0 * fill_ratio;
        // Early stream: slightly encourage opening bins to build a diverse pool
        if progress < 0.2 {
            score += 5.0 * (1.0 - progress * 5.0);
        }
    }

    // Global coupling: when mean residual is high, prefer consuming the fullest bins
    score += 0.05 * mean_residual * (1.0 - fill_ratio_of(bin_residual, bin_capacity));

    // Small deterministic tie-breaker keyed on residual parity structure
    score += ((bin_residual % 7) as f64) * 0.01;

    score
}

#[inline]
fn fill_ratio_of(residual: u32, capacity: u32) -> f64 {
    1.0 - (residual as f64 / capacity as f64)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
