pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Core waste term: non-linear (super-linear) penalty on leftover space.
    let mut score = (post / cap).powf(1.4) * 100.0;

    // Smooth interaction: waste matters more as the stream matures.
    score *= 1.0 + 0.8 * progress * (post / cap);

    // Reward tight fits: subtract proportional to fill ratio, non-linearly.
    let fill = item / cap;
    score -= 60.0 * fill.powf(2.0);

    // Lookahead coupling: if the next item fits the post-residual, reward this bin.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let combo = (item + next_item_size as f64) / cap;
        score -= 25.0 * combo.powf(1.5);
    } else if next_item_size > 0 {
        // Penalize if leftover is dead space for the next item but not tiny.
        score += 8.0 * (post / cap).powf(1.2);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize opening a fresh bin, more when good fits exist
    // or when the item is small (wasting capacity on small items is costly).
    if bin_residual == bin_capacity {
        score += 40.0 + 25.0 * (1.0 - fill) + 10.0 * progress;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    } else {
        // Existing bin: mild bonus for reducing bin count pressure.
        score -= 5.0 * (1.0 - progress);
    }

    // Deviation from mean residual: prefer bins whose residual is already low
    // (consolidating space), as a smooth quadratic coupling.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev - 4.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
