        if open_bins_count > 4 && fitting_bins_count > 1 && mean_residual > 0.45 * capf {
            score += 5.0 * progress;
        }
    }

    // Usable-floor bonus: post residual above next-item floor is worth keeping.
    if pr > 0 {
        let usable_floor = (next_item_size.max(1) as f64).min(0.35 * capf);
        if (pr as f64) >= usable_floor {
            score -= 8.5 * (1.0 - progress) * ((pr as f64) / capf);
        }
    }
    if pr > 0 && (pr as f64) < 0.5 * (next_item_size.max(1) as f64) && fitting_bins_count > 1 {
        score += 6.5 * (1.0 - progress);
    }

    // Late-stream fine finishing: reward near-exact closes.
    if progress > 0.85 && pr <= 2 && pr > 0 {
        score -= 21.0;
    }
    if progress > 0.8 && pr > 0 {
        score += (pr as f64) * 0.38 * (progress - 0.8) * 5.0;
    }

    // Tiny post-residual with many fitting bins is wasteful fragmentation.
    if pr > 0 && fitting_bins_count > 1 && (pr as f64) < 0.1 * capf && next_item_size > 0 && (next_item_size as f64) > pr as f64 {
        score += 4.5 * (1.0 - progress);
    }
    // Very small pr with alternatives available.
    if pr > 0 && (pr as f64) < 0.06 * capf && fitting_bins_count > 2 {
        score += 5.0 * (1.0 - progress);
    }
    // pr exactly divisible by next item is reusable.
    if pr > 0 && next_item_size > 0 && (pr as u32) % next_item_size == 0 && pr >= next_item_size {
        score -= 6.2 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: quarters of capacity
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter; // 0..4
    // Reward tight fits: lower class => better
    score -= (4 - class.min(4)) as f64 * 2.0;

    // Dead-space penalty for unusable slivers (< smallest plausible item)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: strongly reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // extra harmonic coupling: next item leaves another tight remainder
            let next_post = post_residual - next_item_size;
            if next_post / quarter == 0 {
                score -= 5.0;
            }
        } else {
            // post_residual wasted if next item cannot use it
            score += 3.0;
        }
    }

    // Last-chance bin: avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate: neutral-ish, penalize slightly unless open bins are bad fits
    if bin_residual == bin_capacity {
        score = cap - post + 20.0 - (fitting_bins_count as f64 * 2.0);
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Prefer filling bins with high residual among many open bins
    score -= (bin_residual as f64 / cap) * 2.0;
    score += (open_bins_count as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
