    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Tight fit reward relative to residual: fraction of residual consumed.
    if bin_residual > 0 {
        let fill_frac = item_size as f64 / bin_residual as f64;
        score -= 40.0 * fill_frac * fill_frac;
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual < next_item_size && post_residual < 10 {
            score += 30.0; // dead space relative to upcoming item
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: penalize opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
        // If this bin is the only fitting option, opening a new bin is bad.
        if fitting_bins_count == 1 {
            score += 100.0;
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins first).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Early stream: keep options open slightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - fill_frac_if(bin_residual, item_size));

    score
}

