    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = fitting_bins_count as f64;

    // Base: prefer small post residual (tight fit)
    let mut score = pr / cap;

    // Non-linear penalty on large dead space (quadratic coupling)
    let dead = pr / cap;
    score += 1.8 * dead * dead;

    // Smooth interaction: tight fits matter more as stream progresses
    let tightness = 1.0 - pr / cap;
    score -= 0.9 * tightness * tightness * (0.5 + progress);

    // Penalize scarce fitting options less if this bin fits well (last-chance bonus, smooth)
    let scarcity = 1.0 / fit;
    score += 0.6 * scarcity * (1.0 - tightness);

    // Lookahead coupling: reward residual that can still host the next item (smooth ramp)
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let compat = (pr - nxt).max(0.0) / cap;
        score -= 0.7 * compat * (1.0 - compat);
        // Penalize exact-just-enough residuals that starve the next item
        let starve = 1.0 - ((pr - nxt).abs() / cap).min(1.0);
        score += 0.4 * starve * starve * progress;
    }

    // New-bin candidate handling: smooth bonus/penalty vs mean residual of open bins
    let is_new = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new {
        // Opening a new bin is attractive when open bins are fragmented (low mean residual)
        let frag = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score -= 0.5 * frag * frag + 0.3 * progress;
        // But discourage opening when a very tight fit exists among open bins
        score += 0.25 * (1.0 - item / cap);
    } else {
        // Mild penalty for spreading across many open bins
        score += 0.02 * (open_bins_count as f64).ln().max(0.0) * (1.0 - tightness);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
