pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: capacity split into 5 classes
    let class = post_residual / (bin_capacity / 5);
    match class {
        0 => score -= 30.0,                    // near-perfect fit, tiny dead space
        1 => score -= 12.0,                    // good residual, usable by mid items
        2 => score -= 4.0,                     // neutral
        3 => score += 6.0,                     // awkward residual band
        _ => score += 14.0,                    // large leftover = poor fit
    }

    // Lookahead coupling: reward if next item fits into post_residual exactly-ish
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 3 {
                score -= 20.0;                 // perfect chain placement
            } else if slack <= 10 {
                score -= 10.0;
            } else {
                score -= 3.0;
            }
        } else {
            score += 5.0;                      // next item can't use this bin
        }
    } else {
        // Last item: minimize leftover aggressively
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless nothing fits well
    if bin_residual == bin_capacity {
        let good_fit_exists = post_residual == 0 || (next_item_size > 0 && next_item_size <= post_residual);
        let pressure = (item_size as f64 / bin_capacity as f64) * 40.0;
        if good_fit_exists || fitting_bins_count == 0 {
            score -= 10.0;                     // fresh bin is fine early / when nothing fits
        } else {
            score += 30.0 + pressure;          // prefer stuffing an existing bin
        }
    }

    // Mean-residual coupling: if open bins are generally tight, prefer tight placements
    let tightness = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    score -= tightness * 8.0 * (post_residual as f64 / bin_capacity as f64);

    // Progress bias: late in stream, prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 % 7.0);

    // Modulo harmonic penalty: residuals that waste divisible chunks are worse
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 6.0;                          // round residuals attract future items
    }
    if post_residual % 3 == 0 && post_residual < 30 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste; the smaller the unusable gap, the harsher the penalty.
    if post_residual == 0 {
        // Perfect fit: heavily reward closing a bin exactly.
        score -= 60.0;
    } else if post_residual < 10 {
        // Unusable dead space zone: penalize proportionally to how "wasted" it is.
        score += (10 - post_residual) as f64 * 6.0;
    } else if post_residual < 20 {
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Lookahead coupling: if the next item fits the post-residual, this placement
    // chains well; reward it. If next item almost fits but not quite, mild penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else if next_item_size <= bin_residual && post_residual < next_item_size {
            // We consumed space the next item could have used elsewhere.
            score += 4.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // ones rather than spreading; with few bins, be more permissive.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual != bin_capacity {
        score -= 8.0 + pressure * 2.5;
    } else {
        // New-bin candidate: penalize opening a bin unless it's forced
        // (no other fitting bins) or the current placement creates dead space.
        let forced = fitting_bins_count == 0;
        let dead = post_residual > 0 && post_residual < 10;
        if forced {
            score -= 20.0;
        } else if dead {
            score -= 2.0;
        } else {
            score += 15.0 + pressure * 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild preference for bins already below mean residual (tighter bins first).
    score += (post_residual as f64 - mean_residual) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
