                score -= 16.0 * (1.0 - progress);
            } else if dead > nf && dead < nf + 2.0 {
                score -= 8.0;
            }
        }
        // Tiny sliver that next item cannot use: penalize.
        if dead_frac > 0.02 && dead_frac < 0.08 && next_item_size > 0 && (next_item_size as f64) > dead {
            score += (0.08 - dead_frac) * 30.0 * (1.0 - progress);
        }
        // Wide pockets with big next item unusable.
        if dead_frac > 0.55 && next_item_size > 0 && (next_item_size as f64) > dead {
            score += 9.5 * dead_frac;
