            let gap = nxt - post;
            score += 8.0 * (gap / bin_capacity as f64);
        }
    }

    // Compare post_residual relative to mean residual across open bins.
    let diff = post_residual as f64 - mean_residual;
    score += 0.35 * diff;

    // Penalize small unusable dead space (< smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: default moderate cost; open only if placement elsewhere is bad.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Late in stream, prefer reusing bins even more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
    }

    // Slight preference for tighter existing fits (smaller residual before placement).
    score += 0.15 * (bin_residual as f64 - item_size as f64 - post_residual as f64).abs();

    score
}

