}

#[inline]
fn progress(step_index: usize, total_items: usize) -> f64 {
    step_index as f64 / total_items.max(1) as f64
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 12.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize leaving dead space that the next item cannot use.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Dead space for the lookahead item: penalize proportionally.
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        } else {
            // Lookahead fits into the leftover: reward.
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack / bin_capacity as f64);
        }
    }

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Many open bins: prefer consolidating into bins with below-average residual
    // (i.e., fuller bins), to keep other bins' residual large and usable.
    if open_bins_count > 1 {
        let dev = mean_residual - bin_residual as f64;
        score += 0.05 * dev * open_bins_count as f64;
    }

    // Time horizon: early in the stream, be conservative (avoid waste);
    // later, allow more aggressive packing since fewer items remain.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - fit_ratio);

    // New-bin candidate: only attractive when it enables a better long-run layout,
    // i.e., when open bins are crowded and mean residual is small relative to item.
    if bin_residual == bin_capacity {
        let pressure = if mean_residual > 0.0 {
            (item_size as f64 / mean_residual).min(2.0)
        } else {
            2.0
        };
        // Baseline cost of a fresh bin, discounted by pressure.
        score = 30.0 + 25.0 * (1.0 - pressure / 2.0);
        // Late in stream, opening a bin is cheaper since fewer items remain.
        score -= 20.0 * progress;
        // If this bin is the only fitting option, opening is natural.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let r = bin_residual as f64;
    let it = item_size as f64;

    // Base: prefer tight fits, but make the penalty on wasted space grow super-linearly.
    let waste = pr / cap;
    let mut score = pr as f64 * (1.0 + 2.0 * waste * waste);

    // Smooth stream-progress coupling: early on, tolerate loose fits (keep bins flexible);
    // later, tighten aggressively since fewer items remain to fill leftovers.
    let flexibility = (1.0 - progress).powi(2);
    score -= 12.0 * flexibility * (pr / cap);

    // Reward near-perfect fills with a smooth quadratic bonus.
    let perfect = 1.0 - (pr / cap).powi(2);
    score -= 8.0 * perfect * perfect;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (pr / cap);
    }

    // If many bins fit, prefer the one whose post-residual matches the next item smoothly.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.3 * gap * gap / cap;
        // Bonus if next item fits exactly into the post-residual.
        if next_item_size as f64 <= pr {
            score -= 5.0 * (1.0 - gap / cap);
        }
    } else {
        // Last item: fill as much as possible.
        score -= 20.0 * (it / cap);
    }

    // Mild penalty for spreading across many open bins when mean residual is already low.
    let density = mean_residual / cap;
    score += 0.5 * (open_bins_count as f64).ln() * (1.0 - density);

    // New-bin candidate handling: an empty bin has large residual; make it unattractive
    // unless no open bin fits well (post_residual small relative to capacity is good).
    if bin_residual == bin_capacity {
        score = cap - it + 10.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

