    // Usable residuals are those >= some plausible small item (>=1), but
    // "awkward" residuals are small ones (1..=9) that typical items can't fill.
    if pr > 0 && pr < 10 {
        score += 60.0; // nearly-dead space penalty
    }

    // Class residuals by quarter-capacity buckets: prefer leaving large,
    // reusable chunks (3rd/4th quarter) over mid slivers.
    let quarter = (bin_capacity / 4).max(1);
    let class = pr / quarter; // 0..4
    score += match class {
        0 => 40.0,
        1 => 25.0,
        2 => 5.0,
        _ => -10.0,
