            let chain_left = pr - next_item_size;
            // reward tight chains, penalize large leftover after chain
            score -= 80.0 - (chain_left as f64) * 0.8;
        } else {
            // next item cannot reuse this residual: penalize proportionally
            score += (next_item_size as f64 - prf).min(50.0) * 0.5;
        }
