    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are bad.
    if bin_residual == bin_capacity {
        score += 120.0;
        // allow new bin late in stream when many bins open and mean residual high
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= mean_residual * 0.3 * progress;
