pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 {
        // A gap is "dead" if it's smaller than the smallest plausible item (1..100, assume ~10 typical floor).
        let dead_threshold = 10u32;
        if post_residual < dead_threshold {
            score += 60.0; // tiny unusable slivers are pure waste
        } else if post_residual < dead_threshold * 2 {
            score += 25.0; // marginal gaps: risky
        }
    } else {
        // Perfect fill is excellent.
        score -= 80.0;
    }

    // Reward using the last bin that can fit the item (avoid opening a new bin unnecessarily).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Pressure on number of open bins: prefer filling existing bins when many are open.
    let open_pressure = open_bins_count as f64 * 2.0;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // blocks the lookahead item: penalize
    }

    // New-bin candidate: only attractive when current bins have poor fits or high residual spread.
    if bin_residual == bin_capacity {
        // Base penalty to prefer existing bins, modulated by how wasteful existing options are.
        let waste = (mean_residual - post_residual as f64).max(0.0);
        score += 20.0 - waste.min(20.0);
        // If many bins are open, discourage opening yet another.
        score += open_bins_count as f64 * 1.5;
        // If this bin is the only fitting option besides a new bin, discourage new bin.
        if fitting_bins_count == 1 {
