        }
    }

    // Progress-based mild tightening: later in stream, be more conservative with dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 * 0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward if the next item fits into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 60.0 + 0.5 * next_item_size as f64;
        // Extra reward when next item fills the bin completely afterward (2-step perfect chain).
        if next_item_size == post_residual {
            score -= 300.0;
        }
    } else if next_item_size > 0 {
        // Penalize dead space the next item cannot use, scaled by how wasted it is.
        let waste = post_residual.saturating_sub(0) as f64;
        score += 0.3 * waste;
    }

    // Compare post_residual against mean residual: leaving a residual below mean
    // means we are consuming the "easy" space; penalize leaving large residuals
    // relative to the mean only if it creates outlier dead space.
    if post_residual as f64 > mean_residual + 10.0 {
        score += 0.5 * (post_residual as f64 - mean_residual - 10.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let avg_open = mean_residual;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bin when existing residuals are small relative to item+next needs.
        let need = item_size as f64 + next_item_size as f64;
        if avg_open < need * 0.6 {
            score -= 150.0 * (1.0 - progress);
        } else {
            score += 250.0;
        }
    }

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.5 * open_bins_count as f64;

    score
}

