        score += 4.5 * (1.0 - progress);
    }
    // Very small pr with alternatives available.
    if pr > 0 && (pr as f64) < 0.06 * capf && fitting_bins_count > 2 {
        score += 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for any plausible future item (1..=100).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 40 {
        score += 3.0 * (1.0 - (post_residual as f64) / 40.0); // mildly awkward zone
    }

    // Lookahead: if the next item fits exactly in the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chaining
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item won't fit here; slight penalty proportional to overflow
            let over = (next_item_size - post_residual) as f64;
            score += 0.05 * over;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin would leave a bad fit
    // or no open bin fits well; otherwise penalize opening bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = (bin_capacity - item_size) as f64;
        // New bin is good if item is large (low waste) and many bins open (spread load)
        score = waste + 15.0;
        score -= 8.0 * (item_size as f64 / bin_capacity as f64);
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative
        }
        if open_bins_count > 3 && progress < 0.7 {
            score += 5.0; // discourage bin explosion early-mid stream
        }
        if next_item_size > 0 && next_item_size <= post_residual_of_new(item_size, bin_capacity) {
            score -= 6.0;
        }
    }

    // Global state: prefer bins whose residual deviates from the mean toward fullness.
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score -= 4.0 * dev; // favor fuller-than-average bins

    // Mild preference for fewer open bins overall.
    score += 0.02 * open_bins_count as f64;

    score
}

