    let norm_pr = pr / cap;

    // Base: quadratic penalty on post_residual (prefer tight fits)
    let mut score = pr * (1.0 + 0.5 * norm_pr * (1.0 - progress));

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, tight fits matter more; early, leftover space is cheaper.
    let coupling = norm_pr * norm_pr * (progress * progress) * cap;
    score += 2.0 * coupling;

    // Interaction with mean residual: penalize bins far from the fleet mean residual
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev * cap * (0.5 + progress);

    // Lookahead: reward if next item fits the post-residual (smooth kernel)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = (pr - nxt) / cap;
        if fit_gap >= 0.0 {
            score -= 15.0 * (1.0 - fit_gap) * (1.0 + progress);
        } else {
            score += 5.0 * (-fit_gap) * cap * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Many open bins: mild preference to consolidate into existing bins
    let ob = open_bins_count as f64;
    score -= (ob / (ob + 5.0)) * 8.0 * (1.0 - norm_pr);

    // New-bin candidate: penalize proportionally to how many open bins could fit
    if bin_residual == bin_capacity {
        score += 20.0 + 5.0 * fitting_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: rewards residuals that fall into
    // "usable" integer-division classes, penalizes dead-space classes.
    let class = post_residual / 10; // integer division threshold classes 0..10
    match class {
        0 => score -= 30.0,                    // near-perfect fill
        1 => score -= 20.0,                    // small but usable gap
        2 | 3 => score -= 12.0,                // medium gap, fits mid items
        4 | 5 => score -= 4.0,                 // half-ish residual
        6 | 7 => score += 6.0,                 // awkward gap
        8 | 9 => score += 10.0,                // large gap: poor packing
        _ => score -= 25.0,                    // empty bin candidate (post_residual == capacity)
    }

    // Modulo arithmetic on capacity fractions: bins whose residual after fit is
    // congruent to small values mod 10 pack well with typical item sizes.
    let m = post_residual % 10;
    if m == 0 {
        score -= 8.0;
    } else if m >= 7 {
        score += 4.0;
    }

    // Lookahead coupling: if the next item fits the post residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 0.5;
        // Harmonic pair: item + next exactly fills capacity (mod class alignment)
        if (item_size + next_item_size) % bin_capacity == 0 {
            score -= 40.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use this gap: penalize proportional to dead space
        score += post_residual as f64 * 0.15;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is only good when current
    // open bins are mostly full (low mean residual) or few bins fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_residual / bin_capacity as f64;
        // Penalize opening new bins when existing residuals are large and usable.
        score += 20.0 + 60.0 * pressure - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    // Slight preference for bins with residual close to item (tight fit) via
    // harmonic distance: |residual - item| mod-classed.
    let diff = bin_residual as i64 - item_size as i64;
    if diff >= 0 && (diff as u32) % 20 <= 5 {
        score -= 6.0;
    }

    // Mild crowding bonus: reusing bins keeps open_bins_count low.
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100 range,
    // but tiny gaps < ~12 are effectively unusable) are heavily penalized.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0;
    } else if post_residual >= 12 && post_residual < 25 {
        score += 18.0;
    }

    // Perfect or near-perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward leaving a gap that exactly accommodates the lookahead item (k=2 coupling).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size && (post_residual - next_item_size) < 12 {
            score += 12.0; // would create dead space after the next item
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few bins,
    // tolerate opening new ones less.
    score += (open_bins_count as f64) * 1.5;

    // New-bin candidate (empty bin): prefer it only when the item is large relative
    // to typical residual or no meaningful fit exists elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 40.0
            + (open_bins_count as f64) * 2.0
            - mean_residual * 0.4
            - (item_size as f64) * 0.3
            - progress * 10.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step lookahead match: residual after placement
    // exactly matches the next item's size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match bonus: next item almost fills the leftover space.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 / (1.0 + gap);
    }

    // Penalize post-residuals that are dead space (too small for typical items).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 25.0;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Prefer bins tighter than the mean residual (compact packing).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Mild encouragement to reuse existing bins rather than open new ones,
    // weakening as the stream progresses.
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Slight bonus for filling bins more completely.
    score -= 0.2 * (item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
