        }
        if next_item_size > 0 && dead > next_item_size as f64 && dead <= next_item_size as f64 + 3.0 {
            score -= 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 && (dead as u32) % next_item_size == 0 && dead >= next_item_size as f64 && dead <= 2.0 * next_item_size as f64 {
            score -= 13.0 * (1.0 - progress);
        }
        if next_item_size > 0 && dead as f64 >= next_item_size as f64 && dead as f64 <= 1.5 * next_item_size as f64 && progress > 0.5 {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && dead_frac >= 0.45 && dead_frac <= 0.5 && (next_item_size as f64) >= dead * 0.5 && (next_item_size as f64) <= dead {
            score -= 11.0 * (1.0 - progress);
        }
        if next_item_size > 0 && dead as f64 >= 2.0 * next_item_size as f64 && dead as f64 <= 2.5 * next_item_size as f64 && progress > 0.45 {
            score -= 7.0 * (1.0 - progress);
        }
        if next_item_size > 0 && dead_frac < 0.12 && dead >= next_item_size as f64 {
            score -= 5.0 * (1.0 - dead_frac / 0.12) * (1.0 - progress);
        }
        if dead_frac > 0.15 && mean_residual > dead {
            score += (mean_residual - dead).min(40.0) * 0.09 * (1.0 - progress);
        }
        if next_item_size > 1 && dead as u32 >= 2 * next_item_size && (dead as u32) % next_item_size == 0 {
            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && dead as f64 > next_item_size as f64 && dead as f64 <= next_item_size as f64 + 6.0 {
            let gap = dead as f64 - next_item_size as f64;
            score += gap * (1.6 + 0.9 * gap) * (1.0 - progress);
        }
        if next_item_size > 0 {
            let nf = next_item_size as f64;
            if dead >= nf + mean_residual.min(nf) && dead <= nf + nf {
                score -= 16.0 * (1.0 - progress);
            } else if dead > nf && dead < nf + 2.0 {
                score -= 8.0;
            }
        }
        if dead_frac > 0.02 && dead_frac < 0.08 && next_item_size > 0 && (next_item_size as f64) > dead {
            score += (0.08 - dead_frac) * 30.0 * (1.0 - progress);
        }
    }

    // Pair-fill reward when bin can host item + next item together.
    if next_item_size > 0 {
        let pair = item_size as f64 + next_item_size as f64;
        if bin_residual as f64 >= pair {
