pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Non-linear polynomial coupling: dead-space penalty grows super-linearly
    // for medium residuals (unusable gaps), but small residuals are cheap.
    let poly = x * x * (3.0 - 2.0 * x); // smoothstep-like shaping
    score += 8.0 * poly * (0.5 + 0.5 * progress);

    // Tight fits are rewarded quadratically.
    let tightness = 1.0 - x;
    score -= 6.0 * tightness * tightness * (1.0 - progress);

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // Prefer bins whose residual is near the mean (balanced packing),
    // with a smooth Gaussian-like coupling.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev * (1.0 + progress);

    // Lookahead: if next item fits exactly into the post residual, reward;
    // if post residual is too small for the next item, penalize slightly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fit_quality = 1.0 - (pr - nx) / cap;
            score -= 5.0 * fit_quality * fit_quality;
        } else {
            score += 2.0 * (1.0 - progress);
        }
    }

    // Mild penalty for proliferating bins late in the stream.
    score += (open_bins_count as f64).ln() * 0.5 * progress;

    score
}

