        if next_item_size > 0 && next_item_size as f64 > 0.5 * capf && mean_residual > 0.3 * capf {
            score -= 10.5;
        }
        // Poor fits available: fresh bin attractive.
        if fitting_bins_count > 1 && mean_residual < item_size as f64 * 0.4 {
            score += 12.0;
        }
        // Fragmenting a wide-open bin for a large item when a deep pocket exists elsewhere.
        if fitting_bins_count > 1 && dead > 0.35 * capf && item_size as f64 > mean_residual * 1.25 {
            score -= 11.0 * (1.0 - progress);
        }
        // Large item leaving no room for next: fresh bin pairs better.
        if next_item_size > 0 && item_size as f64 > 0.55 * capf && (capf - item_size as f64) < next_item_size as f64 && mean_residual >= item_size as f64 {
            score += 24.0 * (1.0 - progress);
        }
        // Exact next-item post-residual match on a fresh bin.
        if next_item_size > 0 && pr > 0 && pr == next_item_size {
            score -= 12.0 * (1.0 - progress);
        }
        // Mean residual barely fits next item: don't open fresh.
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && mean_residual < next_item_size as f64 + 5.0 {
            score -= 9.0 * (1.0 - progress);
        }
        if open_bins_count > 4 && fitting_bins_count > 1 && mean_residual > 0.45 * capf {
            score += 5.0 * progress;
        }
    }

    // Usable-pocket bonus: residual after placement that can host next item tightly.
    if next_item_size > 0 && pr >= next_item_size && pr - next_item_size > 0 && (pr - next_item_size) < item_size.max(next_item_size) {
        score -= 16.0;
    }

    // Penalize leaving residual that next item cannot use, but only if small.
    if next_item_size > pr && pr > 0 && pr < 30 {
        score += 8.0;
    }

    // Usable-floor bonus: post residual above next-item floor is worth keeping.
    if pr > 0 {
        let usable_floor = (next_item_size.max(1) as f64).min(0.35 * capf);
        if (pr as f64) >= usable_floor {
            score -= 8.5 * (1.0 - progress) * ((pr as f64) / capf);
        }
    }
    if pr > 0 && (pr as f64) < 0.5 * (next_item_size.max(1) as f64) && fitting_bins_count > 1 {
        score += 6.5 * (1.0 - progress);
    }

    // Late-stream fine finishing: reward near-exact closes.
    if progress > 0.85 && pr <= 2 && pr > 0 {
        score -= 21.0;
    }
    if progress > 0.8 && pr > 0 {
        score += (pr as f64) * 0.38 * (progress - 0.8) * 5.0;
    }

    // Tiny post-residual with many fitting bins is wasteful fragmentation.
    if pr > 0 && fitting_bins_count > 1 && (pr as f64) < 0.1 * capf && next_item_size > 0 && (next_item_size as f64) > pr as f64 {
        score += 4.5 * (1.0 - progress);
    }
    // pr + dead together can't host next item -> wasted pocket.
    if pr > 0 && dead > 0.0 && next_item_size > 0 && (pr as f64 + dead) <= next_item_size as f64 && progress > 0.3 {
        score += 8.7 * (1.0 - progress);
    }
    // Very small pr with alternatives available.
    if pr > 0 && (pr as f64) < 0.06 * capf && fitting_bins_count > 2 {
        score += 5.0 * (1.0 - progress);
    }
    // pr exactly divisible by next item is reusable.
    if pr > 0 && next_item_size > 0 && (pr as u32) % next_item_size == 0 && pr >= next_item_size {
        score -= 6.2 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit classes get strong rewards.
    let pr = post_residual;
    if pr == 0 {
        score -= 100.0; // perfect fit
    } else if pr <= 5 {
        score -= 40.0;
    } else if pr % 10 == 0 {
        score -= 15.0; // "clean" residual class (divisible by 10)
    } else if pr < 10 {
        score += 25.0; // dead space: too small for most items
    }

    // Integer-division thresholds on post_residual vs next item class.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (pr as u64) >= (next_item_size as u64) {
            // next item fits here too -> reward chained fit
            score -= 20.0 + 0.5 * ni;
            // harmonic coupling: both residuals in same decade class
            if pr / 10 == (pr - next_item_size) / 10 {
                score -= 10.0;
            }
        } else {
            // next item won't fit: penalize proportionally to wasted chain
            score += 0.3 * (ni - pr as f64);
        }
    }

    // Last-chance bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly unless current bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap * 0.9 + 10.0 * progress * open_bins_count as f64;
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 20.0; // open bins are nearly full; new bin is fine
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 15.0;
        }
    }

    // Mild tie-break toward tighter bins via mean residual comparison.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A residual is "dead" if it cannot fit the smallest plausible item (<= ~10)
    // or if it cannot fit the lookahead item.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // unusable sliver
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0; // gap wasted w.r.t. lookahead
        } else {
            score -= 8.0; // usable gap, mild reward
        }
    } else {
        score -= 50.0; // perfect fill
    }

    // Reward tight fits (large item fraction of the bin).
    let fill_ratio = item_size as f64 / cap_f;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // and encourage consolidating into existing space.
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        score += 35.0 + 6.0 * open_pressure; // new-bin candidate penalty
    } else {
        score -= 3.0 * open_pressure.min(20.0) * (bin_residual as f64 / cap_f);
    }

    // Prefer bins whose residual deviates favorably from the mean:
    // placing into a bin with below-mean residual balances residuals.
    let res = bin_residual as f64;
    if bin_residual != bin_capacity {
        score -= 0.5 * (mean_residual - res).max(0.0);
        score += 0.3 * (res - mean_residual).max(0.0);
    }

    // Lookahead synergy: if the next item fits exactly into post_residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / cap_f);
    }

    // Early stream: be slightly more conservative about opening bins early
    // since many items remain.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress);
    }

    score
}

