pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when post_residual closely matches next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        // perfect fit bonus for next item
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Relative to mean residual: prefer bins with residual near mean (balanced usage),
    // but strongly prefer tight fits (small post_residual).
    score += 0.4 * (post_residual as f64 - mean_residual).abs();

    // Penalize leaving dead space that nothing (min size 1..10) can use well.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // nearly full bin is good
    }
    if post_residual > 60 {
        score += 10.0; // wasteful large leftover
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bin would leave a bad fit
    // for the next item, or few bins open early in the stream.
    if bin_residual == bin_capacity {
        let bad_fit = next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() > 30;
        if bad_fit {
            score -= 15.0;
        }
        if open_bins_count == 0 {
            score -= 50.0;
        }
        // early stream: opening bins is cheap-ish; late stream: avoid sprawl
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
