    // Base: prefer minimal post_residual (tight fit).

    // Strongly reward near-perfect fits.
    if post_residual <= 2 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0 / post_residual as f64;
    }

    // Penalize dead space that no future item can use (items are >= 1,
    // so only exact zero residual is truly dead; still discourage tiny slivers).
    if post_residual > 0 && post_residual < 3 {
        score -= 5.0;
    }

    // Lookahead (k=2): reward bins whose post_residual can host next item,
    // penalize when the next item would then be stranded.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 4.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Wasted chain opportunity: penalize proportionally to the gap.
            score += 0.05 * (next_item_size as f64 - post_residual as f64);
        }
        // Perfect two-item packing: item + next exactly fills the bin.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many fitting bins: this placement is not scarce; mild penalty for
    // fragmenting a large-residual bin that could serve bigger items later.
    if fitting_bins_count > 3 && post_residual > 30 {
        score += 0.1 * (post_residual as f64 - 30.0);
    }

    // Global state coupling: if mean residual across open bins is high,
    // we can afford looser fits; if low, be frugal with remaining space.
    let mr = if mean_residual.is_finite() { mean_residual } else { 0.0 };
    score += 0.05 * (post_residual as f64 - mr);

    // Time horizon: early in the stream, keep bins flexible (penalize
    // small residuals that constrain future large items); late in the
    // stream, prioritize closing bins out tightly.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - t) * 0.08 * post_residual as f64;
    score -= t * 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading; with few open bins, opening a new bin is cheaper.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: the empty bin's natural score is
    // (capacity - item_size). Make it attractive only when no open bin
    // offers a decent fit, by adding a moderate opening cost.
    if bin_residual == bin_capacity {
        score += 10.0 + 10.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
