pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: wasted space after placement, normalized.
    let mut score = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fills (low post_residual); later, tolerate slack
    // slightly more but penalize mid-range residuals super-linearly.
    let p2 = pr / cap * (pr / cap);
    let coupling = p2 * (0.5 + 1.5 * progress) + (pr / cap) * (1.0 - progress) * (1.0 - progress);
    score += 2.0 * coupling;

    // Lookahead: reward bins whose residual can host the next item,
    // with a smooth quadratic term for near-exact continuation.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let fit_next = if next_item_size as f64 <= pr { 1.0 } else { 0.0 };
        score -= 1.2 * fit_next * (1.0 - gap / cap) * (1.0 - gap / cap);
        score += 0.4 * (gap / cap);
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 1.5 + progress;
    }

    // Crowding effect: with many open bins, mildly prefer consolidating
    // into bins with low mean residual deviation (tighter packing).
    let dev = (pr - mean_residual) / cap;
    score += 0.3 * dev * dev * (open_bins_count as f64).ln().max(1.0);

    // New-bin candidate: penalize opening a fresh bin unless current
    // options are poor (post_residual large relative to capacity).
    if bin_residual == bin_capacity {
        score += 0.8 + 2.5 * (1.0 - (pr / cap)) * (1.0 - (pr / cap));
    }

    // Small smooth bonus for exact fills.
    score -= 1.0 * (-pr as f64 / (cap * 0.15)).exp();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
