pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: reward residuals that are
    // "nice" fractions of capacity (usable by future items).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Class the post-residual into harmonic bands of capacity.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let eighth = bin_capacity / 8;

    // Dead-space penalty: residuals too small to fit the smallest plausible item
    // (small items ~1..10) are wasted. Penalize residuals in (0, 10).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Harmonic reward bands: residuals that are multiples of common item classes
    // (10, 20, 25, 50) are more likely reusable.
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 40.0;
    } else if post_residual % 25 == 0 && post_residual > 0 {
        score -= 25.0;
    } else if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    // Integer-division threshold on post_residual: bins left with >= half
    // capacity are valuable; bins left with tiny-but-nonzero space are not.
    if post_residual >= half {
        score -= 20.0;
    } else if post_residual >= quarter {
        score -= 8.0;
    } else if post_residual >= eighth {
        score += 4.0;
    }

    // Coupling with lookahead: if the next item fits exactly into the
    // post-residual, strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            // Prefer bins where the chain leaves a good residual again.
            let chain_residual = post_residual - next_item_size;
            if chain_residual % 10 == 0 {
                score -= 12.0;
            }
            score -= (chain_residual as f64) * 0.15;
        } else {
            // Next item cannot follow in this bin; mild penalty if this bin
            // would then be nearly empty of usable space.
            if post_residual < 10 {
                score += 20.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate handling: empty bin gets a baseline score of capacity.
    // Make opening a new bin attractive only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; subtract a little so a truly bad open-bin fit
        // (huge post residual waste, tiny dead space) loses to a fresh bin.
        score = cap * 0.9 - (open_bins_count as f64) * 0.5;
        // If the item is large relative to capacity, a fresh bin is fine.
        if item_size * 2 >= bin_capacity {
            score -= 10.0;
        }
        // Early in the stream, opening bins is cheap.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 8.0;
    }

    // Spread-aware tiebreak: prefer bins whose residual deviates favorably
    // from the mean (this bin is tighter than average -> use it up).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.3;
    }

    // Modulo harmonic class on item size: items in "awkward" classes (e.g. 33, 34, 51)
    // pair well with complements; encourage placing them where the complement
    // matches a harmonic class.
    let complement = bin_capacity - item_size;
    if bin_residual >= complement && bin_residual < complement + 10 {
        score -= 18.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
