pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        let diff = (post - nxt).abs();
        if diff == 0.0 {
            score -= 60.0; // perfect 2-step match: place here
        } else if nxt <= post {
            // next item still fits after this placement: mild reward, tighter post is better
            score -= 25.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // next item would NOT fit after this placement: penalize proportionally
            score += 15.0 * (1.0 - post / bin_capacity as f64);
        }
    }

    // Penalize creating unusable dead space relative to mean residual.
    let dead = post_residual as f64 - mean_residual;
    if dead > 0.0 {
        score += 0.3 * dead;
    } else {
        score += 0.15 * dead; // reward keeping residual near/below mean
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Favor fuller bins overall (tight fit preference).
    score -= 0.4 * (item_size as f64 / bin_residual.max(1) as f64) * 10.0;

    // New-bin candidate: only attractive when current bins are crowded or residual is tiny.
    if bin_residual == bin_capacity {
        let pressure = if open_bins_count == 0 { 1.0 } else { mean_residual / bin_capacity as f64 };
        if next_item_size > 0 && (post_residual as f64).abs() < f64::EPSILON {
            score += 50.0; // never open a new bin when an exact match exists elsewhere
        }
        if pressure < 0.25 {
            score -= 30.0 * (0.25 - pressure) / 0.25; // crowded bins -> open new bin is fine
        } else {
            score += 80.0; // plenty of residual space -> prefer existing bins
        }
    }

    // Slight late-stream tightening: waste matters more as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.2 * post_residual as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post-residuals (non-linear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Lookahead coupling: if the next item fits into the post-residual, reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 18.0 * (slack_after_next as f64 / bin_capacity as f64);
        } else {
            // Post-residual too small for next item: penalize dead space.
            let dead = if post_residual < next_item_size { next_item_size - post_residual } else { 0 };
            score += 0.15 * dead as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when good alternatives exist.
    if bin_residual == bin_capacity {
        let fit_pressure = 1.0 / (fitting_bins_count.max(1) as f64);
        score += 12.0 * fit_pressure;
        // Early in the stream, opening bins is fine; late, prefer consolidation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
        // If mean residual across open bins is large, prefer filling those bins.
        score += 0.3 * mean_residual;
    }

    // Mild penalty for wasting space relative to the mean residual (fragmentation control).
    if post_residual as f64 > mean_residual {
        score += 0.1 * (post_residual as f64 - mean_residual);
    }

    // Slight preference for bins that are already partially filled.
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: post residual, mildly discounted early, penalized more late
    let mut score = pr * (0.9 + 0.35 * progress);

    // Non-linear polynomial coupling of residual with progress
    score += 30.0 * norm_pr * norm_pr * (1.0 + progress);
    score -= 18.0 * norm_pr * norm_item * (1.0 - progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Lookahead: favor bins whose post-residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (norm_pr - norm_next) * (norm_pr - norm_next);
        score -= 12.0 * (1.0 - slack) * (0.5 + 0.5 * progress);
    } else if next_item_size > 0 {
        score += 8.0 * progress;
    }

    // Last-chance bin: strongly reward using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 15.0 * progress;
    }

    // New-bin candidate: prefer opening early, penalize late (keep bins closed)
    if bin_residual == bin_capacity {
        score += 6.0 * open_bins_count as f64 * (1.0 - progress) - 10.0 * progress;
    }

    // Pull toward mean residual state for diversity of open capacities
    score += 0.08 * (pr - mean_residual) * (pr - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
