pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo capacity fractions.
    // Residuals that are "harmonic" (multiples of common small item sizes)
    // are more likely to be filled later, so penalize less.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -30.0 // perfect fit: best possible outcome
    } else if pr % 10 == 0 {
        -6.0
    } else if pr % 20 == 0 || pr % 25 == 0 {
        -4.0
    } else if pr % 5 == 0 {
        -2.0
    } else {
        3.0 // awkward residual, penalize
    };
    score += harmonic_bonus;

    // Integer-division thresholds: classify post_residual into dead-space bands.
    let band = pr / 25; // 0..=4
    score += match band {
        0 => -4.0,          // residual < 25: nearly closed bin, good
        1 => 0.0,
        2 => 1.5,
        3 => 3.0,
        _ => 0.0,           // large residual: neutral (item was small)
    };

    // Tight fit reward: fraction of bin consumed by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill * fill; // quadratic reward for big fill

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0;
        } else if next_item_size <= pr {
            // partial lookahead fit: reward proportional to how much it consumes
            score -= 8.0 * (next_item_size as f64 / pr.max(1) as f64);
        } else {
            // next item cannot use the residual: slight penalty scaled by wasted gap
            score += 0.05 * (next_item_size - pr) as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // offers a decent fit. Penalize opening new bins more when many are open
    // with slack (mean_residual high).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 45.0 + 0.5 * mean_residual + 0.3 * open_bins_count as f64 - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative: must open new bin
        }
    }

    // Mild preference to consolidate into bins below mean residual
    // (balance residual distribution).
    if (bin_residual as f64) < mean_residual {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
