pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: strict dead-space avoidance. Waste is post_residual that can never
    // be used again; small gaps (< 10, the smallest legacy item) are pure loss.
    let mut score = post_residual as f64;

    // Heavily penalize "unusable" tiny gaps (dead space) super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 12.0;
    }

    // Perfect fits are golden.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits the post-residual gap, this placement
    // chains nicely; reward it. If not, the gap risks becoming dead space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, favor consolidating into
    // existing bins; when few bins are open, tolerate spreading.
    score += open_bins_count as f64 * 2.0 * (0.5 + progress);

    // Prefer bins whose residual is already below the mean (tighter bins),
    // slightly biased by stream progress.
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.15;

    // Mild bonus for filling bins deeply as the stream matures.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capf = bin_capacity as f64;
    let pr = post_residual;
    let dead = bin_residual as f64 - item_size as f64;
    let dead_frac = if dead > 0.0 { dead / capf } else { 0.0 };
    let progress = step_index as f64 / total_items.max(2) as f64;
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    let mut score = pr as f64;

    // Tiered post-residual rewards: exact and near-exact fills dominate.
    if pr == 0 {
        score -= 470.0;
    } else if pr <= 3 {
        score -= 230.0;
    } else if pr <= 6 {
        score -= 115.0;
    } else if pr <= 18 {
        score -= 48.0;
    } else if pr <= 40 {
        score -= 12.0;
    } else if pr <= 66 {
        score -= 3.5;
    }

    // Dead-space penalty: residuals too small for typical items are waste.
    if pr > 0 && pr < 20 {
        score += (20.0 - pr as f64) * (20.0 - pr as f64) * 0.58;
    }

    // Two-step lookahead with modular waste bonus (from best-known).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size + 1 == pr {
            score -= 165.0;
        } else if next_item_size <= pr {
            let waste = (pr - next_item_size) as f64;
            score -= waste * 2.3;
            if (waste as u32) % 10 == 0 && waste > 0.0 {
                score -= 22.0;
            }
        } else {
            let miss = (next_item_size - pr) as f64;
            score += miss.min(50.0) * 0.66 + 7.0;
        }
    }

    // Dead-space shaping: prefer residuals that leave usable pockets for the next item.
    if dead > 0.0 {
        if next_item_size > 0 && dead < next_item_size as f64 {
            score += 10.0 + (next_item_size as f64 - dead) * 0.9;
        } else if next_item_size > 0 && dead as u32 == next_item_size {
            score -= 52.0;
        } else {
            let rem = if total_items > step_index { (total_items - step_index) as f64 } else { 0.0 };
            let rem_frac = (rem / total_items.max(1) as f64).min(1.0);
            score -= dead * (0.05 + 0.05 * rem_frac) + dead_frac * dead_frac * 44.0;
        }
        if next_item_size > 0 && dead as u32 >= next_item_size {
            let after = dead as u32 - next_item_size;
            if after == 0 || after <= 2 {
                score -= 23.0;
            } else if (after as f64) <= 0.04 * capf {
