        if post_residual >= next_item_size {
            let second = post_residual - next_item_size;
            score -= 10.0 * (1.0 - second as f64 / bin_capacity as f64);
        } else {
            // next item cannot follow in this bin: penalize tight fits that strand space
            score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: strongly prefer minimal residual
        score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Relative to mean residual: prefer bins whose remaining space deviates usefully
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: this is the only bin that fits -> avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 {
            (post_residual as i64 - next_item_size as i64).abs() as f64 / bin_capacity as f64
