    if bin_residual != bin_capacity {
        score -= 3.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Penalize creating large dead space that nothing (10..100) can use later
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

