        if fitting_bins_count > 2 && mean_residual > 0.55 * capf {
            score += 7.4 * (1.0 - progress);
        }
        // Mean residual can host item+next pair; prefer existing bin.
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && mean_residual < (item_size as f64 + next_item_size as f64).min(capf) {
            score -= 6.4 * (1.0 - progress);
        }
        // Next item nearly fills mean residual; don't fragment.
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 0.85 && next_item_size as f64 <= mean_residual && progress > 0.4 {
            score -= 8.0 * (1.0 - progress);
        }
        // Next item large and mean residual generous: don't open fresh.
        if next_item_size > 0 && next_item_size as f64 > 0.5 * capf && mean_residual > 0.3 * capf {
            score -= 10.5;
        }
        // Poor fits available: fresh bin attractive.
        if fitting_bins_count > 1 && mean_residual < item_size as f64 * 0.4 {
            score += 12.0;
        }
        // Fragmenting a wide-open bin for a large item when a deep pocket exists elsewhere.
        if fitting_bins_count > 1 && dead > 0.35 * capf && item_size as f64 > mean_residual * 1.25 {
            score -= 11.0 * (1.0 - progress);
        }
        // Large item whose complement is next item: fresh bin enables exact pair.
        if next_item_size > 0 && item_size as f64 > 0.55 * capf && (capf - item_size as f64) < next_item_size as f64 && mean_residual >= item_size as f64 {
            score += 24.0 * (1.0 - progress);
        }
        // Fresh bin leaves exact next-item residual: attractive.
        if next_item_size > 0 && pr == next_item_size {
            score -= 12.0 * (1.0 - progress);
        }
        // Mean residual is a near-perfect host for next item; keep it intact.
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && mean_residual < next_item_size as f64 + 5.0 {
            score -= 9.0 * (1.0 - progress);
        }
        if open_bins_count > 4 && fitting_bins_count > 1 && mean_residual > 0.45 * capf {
            score += 5.0 * progress;
        }
    }

    // Usable-pocket bonus: residual after placement that can host next item tightly.
    if next_item_size > 0 && pr >= next_item_size && pr - next_item_size > 0 && (pr - next_item_size) < item_size.max(next_item_size) {
        score -= 16.0;
    }

    // Penalize leaving residual that next item cannot use, but only if small.
    if next_item_size > pr && pr > 0 && pr < 30 {
        score += 8.0;
    }

    // Usable-floor bonus: post residual above next-item floor is worth keeping.
    if pr > 0 {
        let usable_floor = (next_item_size.max(1) as f64).min(0.35 * capf);
        if (pr as f64) >= usable_floor {
            score -= 8.4 * (1.0 - progress) * ((pr as f64) / capf);
        }
    }
    if pr > 0 && (pr as f64) < 0.5 * (next_item_size.max(1) as f64) && fitting_bins_count > 1 {
        score += 6.4 * (1.0 - progress);
    }

    // Late-stream fine finishing: reward near-exact closes.
    if progress > 0.85 && pr <= 2 && pr > 0 {
        score -= 21.0;
    }
    if progress > 0.8 && pr > 0 {
        score += (pr as f64) * 0.38 * (progress - 0.8) * 5.0;
    }

    // Tiny post-residual with many fitting bins is wasteful fragmentation.
    if pr > 0 && fitting_bins_count > 1 && (pr as f64) < 0.1 * capf && next_item_size > 0 && (next_item_size as f64) > pr as f64 {
        score += 4.6 * (1.0 - progress);
    }
    // pr + dead together can't host next item -> wasted pocket.
    if pr > 0 && dead > 0.0 && next_item_size > 0 && (pr as f64 + dead) <= next_item_size as f64 && progress > 0.3 {
        score += 8.7 * (1.0 - progress);
    }
    // Very small pr with alternatives available.
    if pr > 0 && (pr as f64) < 0.06 * capf && fitting_bins_count > 2 {
        score += 5.1 * (1.0 - progress);
    }
    // pr exactly divisible by next item is reusable.
    if pr > 0 && next_item_size > 0 && (pr as u32) % next_item_size == 0 && pr >= next_item_size {
        score -= 6.2 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), weighted by capacity fraction classes.
    let cap_f = bin_capacity as f64;
    let post_frac = post_residual as f64 / cap_f;

    // Harmonic class of post_residual: which capacity fraction band does it land in.
    // Residuals in [0,10) are near-perfect; [10,30) pairable with small items; [30,60) medium; [60,100) wasteful.
    if post_residual == 0 {
        score -= 500.0; // perfect fit, always take
    } else if post_residual <= 10 {
        score -= 120.0;
    } else if post_residual <= 30 {
        score -= 60.0;
    } else if post_residual <= 60 {
        score -= 20.0;
    } else {
        score += 40.0; // large dead space penalty
    }

    // Modulo arithmetic on post_residual: residual divisible by common item sizes (10/20/25/50)
    // is more reusable by future items -> reward.
    if post_residual % 10 == 0 { score -= 15.0; }
    if post_residual % 20 == 0 { score -= 10.0; }
    if post_residual % 25 == 0 { score -= 8.0; }
    if post_residual % 50 == 0 { score -= 12.0; }

    // Integer-division class: how many 10-unit slots remain; odd slots leave awkward space.
    let slots = post_residual / 10;
    if slots % 2 == 1 && post_residual > 0 { score += 6.0; }

    // Lookahead coupling: does the next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0; // chained perfect fit
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 90.0; // next item nearly fills leftover
            } else {
                score -= 25.0 * (1.0 - gap as f64 / cap_f);
            }
        } else {
            // next item cannot use this residual: penalize proportionally to wasted fraction
            score += 10.0 + post_frac * 30.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when open bins are crowded
    // or the fit into existing bins would be poor.
    if bin_residual == bin_capacity {
        // New bin starts with residual = capacity; discourage unless few fitting bins
        // or mean residual is small (existing bins nearly full).
        let crowding = mean_residual / cap_f; // low => open bins are full
        let pressure = (fitting_bins_count == 0) as i32 as f64
            + (crowding < 0.25) as i32 as f64
            + (open_bins_count == 0) as i32 as f64;
        score += 250.0 - 120.0 * pressure;
        // Also penalize more when the item is small (wasteful to open a bin for a tiny item)
        score += (100 - item_size.min(100)) as f64 * 0.5;
    } else {
        // Mild preference for fuller bins (best-fit reinforcement) with progress modulation.
        let fill = 1.0 - bin_residual as f64 / cap_f;
        score -= 20.0 * fill;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 5.0 * progress * fill;
        // Slight tie-break toward fewer open bins to encourage consolidation.
        score += 0.05 * open_bins_count as f64;
        // Deviation from mean residual: prefer bins whose residual is below mean (fuller than average).
        score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);
    }

    score
}

