pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest item (1) are pure waste,
    // but residuals that can't fit the *next* item are the real killer.
    if post_residual > 0 {
        if next_item_size > 0 && post_residual < next_item_size {
            // Gap is unusable for the lookahead item: strong dead-space penalty.
            let gap_ratio = (next_item_size - post_residual) as f64 / next_item_size as f64;
            score += 15.0 + 20.0 * gap_ratio;
        } else if post_residual < 10 {
            // Tiny sliver: likely unusable for most items.
            score += 12.0 * (1.0 - post_residual as f64 / 10.0);
        } else {
            // Usable gap: mild reward scaled by how well it matches next item.
            if next_item_size > 0 {
                let match_quality = 1.0 - ((post_residual as f64 - next_item_size as f64).abs() / bin_capacity as f64);
                score -= 5.0 * match_quality.max(0.0);
            }
        }
    }

    // Tight-fit reward: low post_residual relative to item size means efficient packing.
    if item_size > 0 {
        let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
        score -= 10.0 * tightness;
    }

    // Open-bins pressure: when many bins are open, prefer consolidating into existing bins;
    // when few bins are open, spreading is cheaper so soften the new-bin penalty.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, modulated by how badly existing bins fit.
        score += 8.0 * pressure;
        if next_item_size > 0 && post_residual >= next_item_size {
            // New bin preserves full flexibility for the next item.
            score -= 6.0;
        }
        if fitting_bins_count <= 1 {
            // No real alternative: opening a new bin is fine.
            score -= 10.0;
        }
    } else if fitting_bins_count == 1 {
        // Last chance bin: strongly favor using it rather than opening a new bin.
        score -= 14.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean, it's a
    // leftover fragment bin — using it up is good (cleans up fragmentation).
    let frag = mean_residual - bin_residual as f64;
    if frag > 0.0 {
        score -= 4.0 * (frag / bin_capacity as f64).min(1.0);
    } else {
        score += 2.0 * ((-frag) / bin_capacity as f64).min(1.0);
    }

    // Stream progression: late in the stream, waste tolerance drops (fewer future
    // items to fill gaps), so penalize residual creation more heavily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits aggressively
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Squared penalty on leftover space: punish dead space super-linearly
        score += (post_residual as f64).powi(2) * 0.05;

