        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 500.0;
            } else if next_item_size <= post_residual {
                // Reward proportionally to how well next item fills the remaining space
                let fill_ratio = next_item_size as f64 / post_residual as f64;
                score -= 200.0 * fill_ratio;
                // Extra bonus for a perfect chain (both residuals near zero)
                let second_residual = post_residual - next_item_size;
                score -= (bin_capacity as f64 - second_residual as f64) * 0.5;
            } else {
                // Next item does NOT fit in leftover: penalize creating unusable slivers
                let waste_ratio = post_residual as f64 / next_item_size as f64;
                score += 50.0 * waste_ratio;
            }
        }

        // Compare against mean residual: bins below mean residual are tighter fits,
        // prefer them (subtract); bins above mean waste capacity (add).
        let res_f = post_residual as f64;
        if mean_residual > 0.0 {
            score += (res_f - mean_residual) * 0.3;
        }

        // Last-chance bin: if this is the only bin that fits, strongly favor using it
        if fitting_bins_count == 1 {
            score -= 150.0;
        }

        // Penalize opening new bins when open bins exist and fit well
        let progress = step_index as f64 / total_items.max(1) as f64;
        if bin_residual == bin_capacity {
            // New-bin candidate: only attractive if item is large relative to capacity
            // and few bins are open
            let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 120.0;
            score -= large_item_bonus;
            score += open_bins_count as f64 * 10.0 * (0.5 + progress);
            // Discourage new bins when next item could share residual elsewhere
            if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
                score += 30.0;
            }
        } else {
            // Existing bin: slight preference scaling with number of open bins
            score -= open_bins_count as f64 * 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual nonlinearly.
    let fit_ratio = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Lookahead: penalize post_residual that cannot host the next item (dead space).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin remains useful for the lookahead item.
            score -= 6.0 * (next_item_size as f64 / cap);
        } else {
            // Dead space created relative to next item's need.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste;
        }
        // Bonus if placing here leaves room exactly matching next item.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open bin
    // fits well. Penalize it mildly when other fitting bins exist, encourage it when
    // the item would waste a lot of space in any existing bin.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 1 {
            score += 18.0;
        }
        // Large items in a fresh bin are fine (little waste expected later).
        score -= 0.15 * (item_size as f64);
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    } else {
        // Prefer bins whose residual deviates below the mean (tighter bins) —
        // keeps loose bins available for awkward future items.
        let dev = mean_residual - bin_residual as f64;
        score += 0.10 * dev;
        // Many open bins: encourage filling the emptiest ones to close bins out.
        let emptiness = (bin_residual as f64 - mean_residual).max(0.0);
        score += 0.05 * emptiness * (open_bins_count as f64).ln().max(1.0);
    }

    // Early stream: allow spreading to build a good bin portfolio.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 && bin_residual == bin_capacity {
        score -= 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: prefer tight fits (small post_residual), with a smooth non-linear
    // polynomial coupling of post_residual and stream progress.
    let mut score = pr_norm * (1.0 + 0.8 * progress) + 0.6 * pr_norm * pr_norm;

    // Dead-space penalty: residual too small to ever be useful (below min item size
    // of 1 => any residual >= 1 is potentially usable, but tiny residuals relative
    // to typical items are wasteful). Smooth quadratic in unusable fraction.
    let waste = ((it - pr).max(0.0)) / cap;
    score += 0.9 * waste * waste;

    // Last-chance bonus: if this is the only bin that fits, strongly reward using it.
    if fitting_bins_count == 1 {
        score -= 3.0;
    } else {
        // Crowding: with many fitting bins, mildly prefer spreading load evenly
        // (bin residual close to mean residual is slightly preferred).
        score += 0.15 * (pr - mean_residual).abs() / cap;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // reward this placement strongly (smooth kernel around the match).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 1.5 * (-gap / 8.0) * (-gap / 8.0);
        // Penalize leaving residuals that neither fit next item nor are large.
        if pr < next_item_size as f64 {
            score += 0.4 * (next_item_size as f64 - pr) / cap;
        }
    }

    // Late-stream consolidation: as the stream progresses, favor filling existing
    // bins over opening new ones (smooth cubic in progress).
    let open_f = open_bins_count as f64;
    score -= (1.0 - progress) * 0.0 + progress * progress * (1.0 - progress) * 2.0 * (open_f / (open_f + 5.0));

    // New-bin candidate: penalize opening a fresh bin unless existing fits are bad.
    if bin_residual == bin_capacity {
        score += 2.5 + 1.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
