pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let pr = post_residual;

    // --- Harmonic dead-space classes ---
    // Residuals below the minimum item size (10) are unusable dead space.
    if pr < 10 {
        score += 7.0;
    }
    // Perfect / near-perfect closures
    if pr == 0 {
        score -= 30.0;
    } else if pr <= 5 {
        score -= 12.0;
    }

    // --- Modulo arithmetic on post_residual ---
    // Residuals aligned to common size classes (multiples of 10) are more
    // likely to be exactly filled by future items -> reward them.
    if pr >= 10 && pr % 10 == 0 {
        score -= 3.5;
    }
    // Half-capacity harmonic class (50) is a classic reusable slot.
    if pr == 50 {
        score -= 2.0;
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if next_item_size == pr {
            // Next item exactly fills this bin: extremely desirable.
            score -= 22.0;
        } else if next_item_size <= pr {
            // Next item still fits here: mild reward for keeping capacity.
            score -= 2.5;
        } else {
            // Next item cannot use this residual: mild penalty.
            score += 3.0;
        }
        // Harmonic pair: item + next item sums to a multiple of 10
        if (item_size + next_item_size) % 10 == 0 && next_item_size <= pr {
            score -= 4.0;
        }
    }

    // --- Last-chance bin before opening a new one ---
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 9.0;
    }

    // --- New-bin candidate handling ---
    if is_new_bin {
        // Mild penalty: prefer reusing open bins when the fit is decent.
        score += 6.0;
        if fitting_bins_count == 0 {
            // No open bin can take the item: opening a new bin is mandatory.
            score -= 200.0;
        }
        // If every existing fit would strand a huge residual, prefer a fresh bin.
        if fitting_bins_count > 0 && pr < (bin_capacity as f64 * 0.35) as u32 {
            score -= 15.0;
        }
    }

    // --- Contextual scaling ---
    // Late in the stream, be slightly greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * progress * (1.0 - pr as f64 / bin_capacity as f64);

    // Slight preference to fill bins when many are open (bin consolidation).
    score += 0.05 * open_bins_count as f64;

    score
