pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    // A residual gap is "dead" if it is too small for any plausible item (min size 1,
    // but realistically gaps below ~10 waste capacity). Use a nonlinear penalty.
    let pr = post_residual as f64;
    if pr == 0.0 {
        // Perfect fit: strongly reward closing the bin exactly.
        score -= 60.0;
    } else if pr < 10.0 {
        // Tiny gap: nearly dead space -> heavy penalty.
        score += (10.0 - pr) * 8.0;
    } else if pr < 20.0 {
        // Small gap: partially dead -> moderate penalty.
        score += (20.0 - pr) * 3.0;
    } else {
        // Usable gap: mild reward for keeping flexibility, favor larger residuals.
        score -= (pr - 20.0) * 0.05;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits: reward proportionally to how well it fills the gap.
        let fill = next_item_size as f64 / pr;
        score -= 15.0 * fill;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Next item cannot use this gap: penalize if gap becomes dead space.
        if pr < next_item_size as f64 && pr < 30.0 {
            score += (30.0 - pr) * 1.5;
        }
    }

    // Open-bins pressure: discourage spreading across too many bins when few items remain.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += pressure * 0.4;

    // Mean residual coupling: if this bin's residual is far below mean, it is a poor
    // leftover candidate; if above mean, it is a good target for filling.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= dev * 20.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large relative
    // to capacity or all existing fits are bad. New bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin; a large item justifies it.
        score += 40.0 - (item_size as f64 / bin_capacity as f64) * 35.0;
        // If next item is small, a fresh bin wastes future flexibility less; slight relief.
        if next_item_size > 0 && next_item_size < 20 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size well.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as u32 >= next_item_size {
            // Perfect match: next item exactly fills the bin -> strong reward.
            let diff = (post_residual as f64 - next).abs();
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
            // Bonus if next item fits exactly (diff == 0).
            if diff == 0.0 {
                score -= 40.0;
            }
        } else {
            // Post-residual too small for next item: penalize dead space, scaled by how
            // unusable the leftover is relative to the smallest conceivable item.
            let dead = post_residual as f64;
            score += 8.0 * (dead / bin_capacity as f64);
        }
    } else {
        // Last item: simply minimize leftover.
        score += 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Tightness reward: bins that are nearly full are good targets.
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Relative-to-mean coupling: prefer bins whose post_residual sits near mean_residual
    // (keeps residual distribution balanced), penalize outliers.
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += 3.0 * (mean_gap / bin_capacity as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if lookahead suggests a fresh bin packs item + next item nicely, relax.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let slack = (bin_capacity - item_size - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild penalty for many open bins (encourage consolidation).
    score += 0.5 * open_bins_count as f64;

    score
}

