pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness * (item_size as f64 / bin_capacity as f64);

    // Lookahead: if next item fits the post-residual, big reward; penalize wasted residual
    // that the next item could have used.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            let waste_gap = (next_item_size - post_residual) as f64;
            score += 0.15 * waste_gap;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Penalize opening new bins when many bins already fit the item.
    if bin_residual == bin_capacity {
        score += 8.0 + 1.5 * fitting_bins_count as f64;
        // Early in the stream, opening bins is cheaper (more future to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 6.0 * (1.0 - progress);
    }

    // Prefer bins with residual below the mean (consolidate small leftovers).
    score += 0.08 * ((bin_residual as f64 - mean_residual).abs()) * (bin_residual as f64 / bin_capacity as f64);

    // Mild preference for fuller bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // Penalize leaving residuals that are too small to ever be useful (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capf = bin_capacity as f64;
    let pr = post_residual;
    let mut score = pr as f64;
    let progress = step_index as f64 / total_items.max(2) as f64;

    // Tiered post-residual rewards (tightened).
    if pr == 0 {
        score -= 560.0;
    } else if pr <= 3 {
        score -= 268.0;
    } else if pr <= 5 {
        score -= 134.0;
    } else if pr <= 16 {
        score -= 86.0;
    } else if pr <= 40 {
        score -= 16.0;
    } else if pr <= 66 {
        score -= 4.0;
    }

    // Dead-space penalty for residuals too small for typical items.
    if pr > 0 && pr < 20 {
        score += (20.0 - pr as f64) * (20.0 - pr as f64) * 0.58;
    }

    // Two-step lookahead: exact pair fill is excellent; proportional waste reward otherwise.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 350.0;
        } else if next_item_size + 1 == pr {
            score -= 195.0;
        } else if next_item_size <= pr {
            let waste = (pr - next_item_size) as f64;
            score -= waste * 2.4;
            if (waste as u32) % 10 == 0 {
                score -= 25.0;
            }
        } else {
            let miss = (next_item_size - pr) as f64;
            score += miss.min(50.0) * 0.7 + 7.5;
        }
    }

    let dead = bin_residual as f64 - item_size as f64;
    if dead > 0.0 {
        let dead_frac = dead / capf;
