    }
    // Very small pr with alternatives available.
    if pr > 0 && (pr as f64) < 0.06 * capf && fitting_bins_count > 2 {
        score += 5.0 * (1.0 - progress);
    }
    // pr exactly divisible by next item is reusable.
    if pr > 0 && next_item_size > 0 && (pr as u32) % next_item_size == 0 && pr >= next_item_size {
        score -= 6.2 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Core: post-residual cost, non-linearly warped by stream progress
    let mut score = pr * (1.0 + 0.6 * progress * (1.0 - progress) * 4.0);

    // Smooth polynomial penalty on small-but-nonzero residuals (dead space)
    let dead = norm_pr * (1.0 - norm_pr); // peaks at half-full residual
    score -= 8.0 * dead * dead * cap * 0.01;

    // Reward tight fits with smooth coupling to progress
    let tightness = 1.0 - (pr / cap);
    score -= tightness * tightness * (item_size as f64) * (1.0 + progress);

    // Lookahead coupling: residual that fits the next item is valuable
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        let fit_quality = 1.0 - ((pr - next_item_size as f64) / cap).abs();
        score -= 5.0 * fit_quality * (1.0 + 0.5 * progress);
    } else if next_item_size > 0 {
        score += 3.0 * (1.0 - progress) * (next_item_size as f64 / cap);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 + progress);
    }

    // Penalize scattering across many open bins vs mean residual alignment
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    let dev = (pr - mean_residual).abs();
    score += 0.02 * dev * (1.0 - progress);

    // New-bin candidate: prefer it only when item barely fits nothing well
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * (1.0 - progress) - 4.0 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo 10 as a "waste quantum"
    let post_class = (post_residual % 10) as f64;
    score += post_class * 0.7; // penalize non-aligned residuals

    // Integer-division harmonic band: post_residual / 10 (0..=10)
    let post_band = post_residual / 10;
    score += match post_band {
        0 => -8.0,   // perfect fill
        1 => -4.0,
        2 => -1.0,
        3 => 0.0,
        4 => 2.0,
        5 => 4.0,
        6 => 6.0,
        7 => 8.0,
        8 => 10.0,
        9 => 12.0,
        _ => 14.0,   // nearly empty bin used wastefully
    };

    // Lookahead coupling: if next item fits harmonically into post_residual, reward
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_fit_class = (post_residual % 10) == (next_item_size % 10);
            let next_band = (post_residual - next_item_size) / 10;
            score -= 3.0 + if next_fit_class { 2.0 } else { 0.0 } + (10 - next_band.min(10)) as f64 * 0.5;
        } else {
            // next item cannot follow here; slight penalty for blocking
            score += 1.5;
        }
    }

    // Last-chance bonus: only bin that fits -> strong reward to avoid new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a bin wastes the residual of all open bins
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_penalty = open_bins_count as f64 * 0.6;
        let waste = mean_residual / bin_capacity as f64;
        score = (bin_capacity - item_size) as f64 + open_penalty + waste * 10.0;
        // allow new bin late in stream when open bins are poorly packed
        if fitting_bins_count == 0 { score -= 20.0; }
        if progress > 0.7 && mean_residual < item_size as f64 * 1.2 { score -= 6.0; }
        if next_item_size > 0 && next_item_size > mean_residual { score -= 4.0; }
    }

    // Mean-residual harmony: prefer bins whose residual is close to mean (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item are worthless.
    if post_residual < 10 {
        score += 500.0; // unusable sliver
    } else if post_residual < 20 {
        score += 150.0;
    } else if post_residual < 40 {
        score += 40.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 50.0;
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; favor consolidation.
    let pressure = (open_bins_count as f64).ln() * 10.0;
    if bin_residual != bin_capacity {
        score -= pressure;
    } else {
        // New-bin candidate: penalize unless item is large relative to capacity
        // or it would leave a very poor residual elsewhere.
        score += pressure + 20.0;
        if item_size >= 70 {
            score -= 60.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_fit = (post_residual - next_item_size) as f64;
        score -= 80.0 / (1.0 + lookahead_fit / 10.0);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 30.0; // dead space relative to lookahead
    }

    // Early stream: be slightly conservative about opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.2 {
        score += 25.0;
    }

    // Mean residual coupling: if this bin is far below mean residual, it's a straggler — use it.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
