pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capf = bin_capacity as f64;
    let pr = post_residual;
    let mut score = pr as f64;
    let progress = step_index as f64 / total_items.max(2) as f64;

    // Tiered post-residual rewards.
    if pr == 0 {
        score -= 540.0;
    } else if pr <= 3 {
        score -= 268.0;
    } else if pr <= 5 {
        score -= 134.0;
    } else if pr <= 16 {
        score -= 86.0;
    } else if pr <= 40 {
        score -= 16.0;
    } else if pr <= 66 {
        score -= 4.0;
