        if item_size as f64 > 0.93 * capf {
            score -= 21.0;
        }
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 6.0 + (next_item_size as f64 - mean_residual) * 0.13;
        }
        if fitting_bins_count > 1 && mean_residual < item_size as f64 * 0.4 {
            score += 12.0;
        }
        if progress > 0.7 && open_bins_count > 3 {
            score += 19.0 * progress;
        }
        let spread = (mean_residual - item_size as f64).abs();
        if spread < 0.08 * capf && fitting_bins_count > 2 {
            score += 9.5;
        }
        if item_size as f64 > mean_residual * 1.6 && fitting_bins_count > 1 && open_bins_count > 2 {
            score -= 15.0 * (1.0 - progress);
        }
        if next_item_size > 0 && next_item_size as f64 > 0.5 * capf && mean_residual > 0.3 * capf {
            score -= 10.5;
        }
        // Fragmenting a wide-open bin for a large item when a deep pocket exists elsewhere.
        if fitting_bins_count > 1 && dead > 0.35 * capf && item_size as f64 > mean_residual * 1.25 {
            score -= 11.0 * (1.0 - progress);
        }
        let rem_items = if total_items > step_index { (total_items - step_index) as f64 } else { 0.0 };
        if rem_items > 0.15 * total_items.max(1) as f64 && mean_residual < 0.5 * (next_item_size.max(1) as f64) {
            score -= 15.0 * (1.0 - progress);
        }
        if fitting_bins_count > 2 && mean_residual > 0.55 * capf {
            score += 7.5 * (1.0 - progress);
        }
        // Mean residual can host item+next pair; prefer existing bin.
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && mean_residual < (item_size as f64 + next_item_size as f64).min(capf) {
            score -= 6.5 * (1.0 - progress);
        }
        // Next item nearly fills mean residual; don't fragment.
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 0.85 && next_item_size as f64 <= mean_residual && progress > 0.4 {
            score -= 8.0 * (1.0 - progress);
        }
        // Large item whose complement can't host next: prefer fresh bin.
        if next_item_size > 0 && item_size as f64 > 0.55 * capf && (capf - item_size as f64) < next_item_size as f64 && fitting_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 24.0 * (1.0 - progress);
        }
        // Exact pr == next item match with fresh bin is attractive.
        if next_item_size > 0 && pr > 0 && pr == next_item_size && fitting_bins_count > 0 {
            score -= 12.0 * (1.0 - progress);
        }
        // Mean residual barely above next item: don't fragment open bins.
        if next_item_size > 0 && fitting_bins_count > 0 && mean_residual >= next_item_size as f64 && mean_residual < next_item_size as f64 + 5.0 {
            score -= 9.0 * (1.0 - progress);
        }
        // With many open bins and generous mean residual, fresh bin is wasteful.
        if open_bins_count > 4 && fitting_bins_count > 1 && mean_residual > 0.45 * capf {
            score += 5.0 * progress;
        }
    }

    // Usable-floor bonus: post residual above next-item floor is worth keeping.
    if pr > 0 {
        let usable_floor = (next_item_size.max(1) as f64).min(0.35 * capf);
        if (pr as f64) >= usable_floor {
            score -= 8.5 * (1.0 - progress) * ((pr as f64) / capf);
        }
    }
    if pr > 0 && (pr as f64) < 0.5 * (next_item_size.max(1) as f64) && fitting_bins_count > 1 {
        score += 6.5 * (1.0 - progress);
    }

    // Late-stream fine finishing: reward near-exact closes.
    if progress > 0.85 && pr <= 2 && pr > 0 {
        score -= 21.0;
    }
    if progress > 0.8 && pr > 0 {
        score += (pr as f64) * 0.38 * (progress - 0.8) * 5.0;
    }

    // Tiny post-residual with many fitting bins is wasteful fragmentation.
    if pr > 0 && fitting_bins_count > 1 && (pr as f64) < 0.1 * capf && next_item_size > 0 && (next_item_size as f64) > pr as f64 {
        score += 4.5 * (1.0 - progress);
    }
    if pr > 0 && (pr as f64) < 0.06 * capf && fitting_bins_count > 2 {
        score += 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit core: reward tight fits.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness;

    // Penalize small unusable residuals (dead space below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits perfectly in the post-residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // If next item could fit in post-residual, mild reward; otherwise mild penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
        } else if next_item_size <= bin_residual && post_residual > next_item_size {
            score += 0.0;
        } else {
            score += 3.0;
        }
    }

    // New-bin candidate logic: opening a new bin is costly; only attractive when
    // existing fits are poor (large post_residual) or the item is huge.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fits = (post_residual as f64) / (bin_capacity as f64) * 100.0;
        score += 30.0 - poor_fits + 10.0 * progress;
        // Huge items nearly fill a fresh bin alone: allow opening.
        if item_size >= 70 {
            score -= 15.0;
        }
        // Many open bins with low mean residual: prefer reusing them.
        if open_bins_count > 2 && mean_residual > item_size as f64 {
            score += 20.0;
        }
    }

    // Prefer bins with residuals close to the item (relative waste ratio).
    if bin_residual != bin_capacity {
        let waste_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += 8.0 * waste_ratio;
    }

    // Mild penalty for spreading across many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: prefer small post-residual, with smooth non-linear shaping.
    let mut score = post * (1.0 + 0.5 * post / cap);

    // Non-linear polynomial coupling of post_residual with stream progress:
    // late in the stream, tighter fits matter more (waste compounds).
    let coupling = post / cap * (post / cap - 1.0); // in [-0.25, 0]
    score += coupling * (1.0 + 3.0 * progress * progress) * cap * 0.5;

    // Reward tight fits (small post residual relative to item).
    let tightness = item / (bin_residual.max(1) as f64);
    score -= tightness * item * 0.3;

    // Lookahead: if next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 6.0 + 4.0 * (next_item_size as f64 / post);
    } else if next_item_size > 0 {
        // penalize leaving residual that blocks a large next item
        score += 2.0 * (next_item_size as f64 / cap) * (1.0 - post / cap).abs();
    }

    // Last chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer filling bins in bins with below-average residual (consolidate waste).
    score -= 0.05 * (mean_residual - post);

    // Mild pressure to reuse existing bins as stream progresses / bins accumulate.
    score += 3.0 * progress + 0.05 * open_bins_count as f64;

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score = post * (1.0 + 0.5) + 10.0 - 12.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: quantize post_residual into 8 capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 8.0).floor() as i32; // 0..7

    // Reward tight fits strongly (small post_residual).
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    } else if post_residual <= 20 {
        score -= 12.0;
    }

    // Lookahead: does the next item fit exactly into the post-residual (harmonic pairing)?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0; // perfect harmonic pair
        } else if next_item_size <= post_residual {
            let nxt_class = ((next_item_size as f64 / bin_capacity as f64) * 8.0).floor() as i32;
            if nxt_class == class {
                score -= 40.0; // same harmonic class -> likely good future fit
            } else {
                score -= 8.0;
            }
        } else {
            // next item cannot fit here; leftover becomes dead space risk
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer filling the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin when open bins already fit well.
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus mild pressure from stream progress
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 + 20.0 * progress;
        // if an existing bin would be left nearly full, discourage new bin
        if bin_residual - item_size >= 0 && post_residual < 15 {
            score += 50.0;
        }
    } else {
        // reward using existing bins, scaled by how crowded the bin set is
        score -= 5.0 + (open_bins_count as f64).sqrt();
    }

    // Modulo arithmetic on post_residual: penalize awkward leftovers (dead zones)
    let r = post_residual;
    if r > 0 && r < 10 {
        // small residues < 10 are nearly dead space for items >= 10
        score += 20.0;
    }
    // residues that are multiples of common item sizes are reusable
    if r >= 10 && (r % 10 == 0 || r % 20 == 0 || r % 25 == 0 || r % 50 == 0) {
        score -= 15.0;
    }

    // Mild coupling to mean residual: prefer bins below mean (balance loads)
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero post_residual is nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits: fraction of residual consumed.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // If the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // If next item cannot fit in post residual but post residual is small, mild penalty.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 15 {
        score += 10.0;
    }

    // Pressure from number of open bins: discourage opening/spreading when many open.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Deviation from mean residual: prefer bins whose residual is close to the mean
    // (keeps residual profile balanced), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate: make it attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, reduced if current bin would leave big dead space.
        let dead = if post_residual > 0 && post_residual < 15 { 1.0 } else { 0.0 };
        score = 60.0 + 0.5 * open_bins_count as f64 - 25.0 * dead;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capf = bin_capacity as f64;
    let pr = post_residual;
    let mut score = pr as f64;
    let progress = step_index as f64 / total_items.max(2) as f64;

    // Tiered post-residual rewards.
    if pr == 0 {
        score -= 545.0;
    } else if pr <= 3 {
        score -= 258.0;
    } else if pr <= 5 {
        score -= 128.0;
    } else if pr <= 16 {
        score -= 80.0;
    } else if pr <= 40 {
        score -= 15.0;
    } else if pr <= 66 {
        score -= 4.0;
    }

    // Dead-space penalty for residuals too small for typical items.
    if pr > 0 && pr < 20 {
        score += (20.0 - pr as f64) * (20.0 - pr as f64) * 0.57;
    }

    // Two-step lookahead: exact pair fill is excellent; proportional waste reward otherwise.
    if next_item_size > 0 {
        if next_item_size == pr {
