    if next_item_size > 0 {
        let pair = item_size as f64 + next_item_size as f64;
        if bin_residual as f64 >= pair {
            let slack = bin_residual as f64 - pair;
            score -= 39.5 - (slack / capf) * 30.0;
        }
        if pr > 0 && (pr as f64) >= next_item_size as f64 && (pr as f64) < next_item_size as f64 + 4.0 {
            score -= 14.0 * (1.0 - progress);
