    score -= bin_pressure * 2.1 * (1.0 - progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 52.0;
    }

    // Mean-residual anchoring, stronger later in the stream.
    score -= (0.39 + 0.17 * progress) * (mean_residual - pr as f64);

    // Residual-vs-mean-ratio shaping: prefer post residual near fleet mean.
    if pr > 0 {
        let dev = ((pr as f64) - mean_residual).abs() / capf;
        score += dev * 8.0 * (1.0 - progress);
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let next_tight = next_item_size > 0 && mean_residual < next_item_size as f64;
