            score -= 7.8 * (1.0 - progress);
        }
        if next_item_size > 0 && next_item_size as f64 > 0.5 * capf && mean_residual > 0.3 * capf {
            score -= 10.0;
        }
        if fitting_bins_count > 1 && mean_residual < item_size as f64 * 0.4 {
            score += 11.5;
        }
        if fitting_bins_count > 1 && dead > 0.35 * capf && item_size as f64 > mean_residual * 1.25 {
            score -= 11.0 * (1.0 - progress);
        }
        // NEW: large item whose complement can't host next item -> fresh bin helps.
        if next_item_size > 0 && item_size as f64 > 0.55 * capf && (capf - item_size as f64) < next_item_size as f64 && mean_residual >= item_size as f64 {
