pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fit (small post_residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: next item exactly fills what remains
            let gap = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - gap / (bin_capacity as f64));
            // Exact chain bonus
            if gap == 0.0 {
                score -= 40.0;
            }
        } else {
            // Next item won't fit here: penalize wasting space that could chain
            let wasted = (next_item_size - post_residual) as f64;
            score += 0.15 * wasted;
        }
    }

    // Reward bins whose residual is below mean residual (tighter than average)
    let mean_gap = (bin_residual as f64) - mean_residual;
    score += 0.2 * mean_gap;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when decent existing fits exist, more so early on
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let decent_fit_exists = fitting_bins_count > 0
            && (bin_residual - item_size) as f64 > 0.5 * mean_residual;
        if decent_fit_exists {
            score += 15.0 + 10.0 * (1.0 - progress);
        }
        // New-bin baseline slightly above a good fit
        score += 5.0;
        // If item is large relative to capacity, opening fresh bin is fine
        if (item_size as f64) / (bin_capacity as f64) > 0.7 {
            score -= 10.0;
        }
    }

    // Mild penalty per open bin to encourage consolidation
    score += 0.05 * open_bins_count as f64;

    score
}

