    // which "companion item classes" (sizes 1..100) can still pair.
    let pr = post_residual;
    let class = pr % 10;
    let div = pr / 10;

    // Reward residuals that are exact multiples of 10 (many item classes fit).
    if class == 0 && pr > 0 {
        score -= 8.0;
    }
    // Penalize tiny dead space that nothing can use.
    if pr < 5 && pr > 0 {
        score += 25.0;
    }
    // Deep-dead-space zone (residual in 1..10 after a big item).
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 2.0;
    }

    // Integer-division threshold: residual bands by usefulness.
    if div == 0 && pr > 0 {
        score += 12.0; // residual < 10: nearly unusable
    } else if div >= 1 && div <= 3 {
        score -= 3.0 * div as f64; // 10..39: pairs with mid-size items
    } else if div >= 4 && div <= 6 {
        score -= 6.0; // 40..69: sweet spot for common sizes
    }

    // Lookahead coupling: does the next item fit into this post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item chains perfectly: strong reward, scaled by tightness.
            let tight = (pr - next_item_size) as f64;
            score -= 10.0 + 0.3 * tight.max(0.0);
            if pr == next_item_size {
                score -= 15.0; // perfect pair
            }
        } else {
            // Next item won't fit here: mild penalty unless residual still large.
            if pr < next_item_size {
                score += 4.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer filling bins whose residual is far below the mean (consolidation).
    score -= 0.4 * (mean_residual - post_residual as f64).max(0.0);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0
            && open_bins_count > 0
            && (item_size as f64 / cap) > 0.5
            && mean_residual < item_size as f64 + 5.0;
        if good_fit_exists {
            score += 40.0; // discourage new bin
        } else {
            score -= 5.0; // opening fresh is fine
        }
    }

    // Mild phase adjustment: late in stream, prefer tighter packing.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score += phase * (post_residual as f64) * 0.15;

    score
}

