            score -= 20.5;
        }
        if progress > 0.7 && open_bins_count > 3 {
            score += 18.5 * progress;
        }
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 6.0 + (next_item_size as f64 - mean_residual) * 0.128;
        }
        if fitting_bins_count > 1 && mean_residual < item_size as f64 * 0.4 {
            score += 12.0;
        }
        let spread = (mean_residual - item_size as f64).abs();
        if spread < 0.08 * capf && fitting_bins_count > 2 {
            score += 9.4;
        }
        if item_size as f64 > mean_residual * 1.58 && fitting_bins_count > 1 && open_bins_count > 2 {
            score -= 14.5 * (1.0 - progress);
        }
        let rem_items = if total_items > step_index { (total_items - step_index) as f64 } else { 0.0 };
        if rem_items > 0.15 * total_items.max(1) as f64 && mean_residual < 0.5 * (next_item_size.max(1) as f64) {
            score -= 14.5 * (1.0 - progress);
        }
        if fitting_bins_count > 2 && mean_residual > 0.55 * capf {
            score += 7.3 * (1.0 - progress);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && mean_residual < (item_size as f64 + next_item_size as f64).min(capf) {
            score -= 6.3 * (1.0 - progress);
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 0.85 && next_item_size as f64 <= mean_residual && progress > 0.4 {
            score -= 7.8 * (1.0 - progress);
        }
        // Fresh-bin lookahead: avoid opening a bin that strands a large residual.
        if next_item_size > 0 && item_size as f64 > 0.55 * capf && (capf - item_size as f64) < next_item_size as f64 && fitting_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 24.0 * (1.0 - progress);
        }
        if next_item_size > 0 && next_item_size as f64 > 0.5 * capf && mean_residual > 0.3 * capf {
            score -= 10.2;
        }
        if fitting_bins_count > 1 && dead as f64 > 0.35 * capf && item_size as f64 > mean_residual * 1.25 {
            score -= 11.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0 && pr == next_item_size && fitting_bins_count > 0 {
            score -= 12.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fitting_bins_count > 0 && mean_residual >= next_item_size as f64 && mean_residual < next_item_size as f64 + 5.0 {
            score -= 9.0 * (1.0 - progress);
        }
        if open_bins_count > 4 && fitting_bins_count > 1 && mean_residual > 0.45 * capf {
            score += 5.0 * progress;
        }
    }

    // Usable-pocket bonus: residual after placement that can host next item tightly.
    if next_item_size > 0 && pr >= next_item_size && pr - next_item_size > 0 && (pr - next_item_size) < item_size.max(next_item_size) {
        score -= 16.0;
    }

    if next_item_size > pr && pr > 0 && pr < 30 {
        score += 8.0;
    }

    // Usable-floor bonus.
    if pr > 0 {
        let usable_floor = (next_item_size.max(1) as f64).min(0.35 * capf);
        if (pr as f64) >= usable_floor {
            score -= 8.4 * (1.0 - progress) * ((pr as f64) / capf);
        }
    }
    if pr > 0 && (pr as f64) < 0.5 * (next_item_size.max(1) as f64) && fitting_bins_count > 1 {
        score += 6.4 * (1.0 - progress);
    }

    // Late-stream fine finishing.
    if progress > 0.85 && pr <= 2 && pr > 0 {
        score -= 21.0;
    }
    if progress > 0.8 && pr > 0 {
        score += (pr as f64) * 0.37 * (progress - 0.8) * 5.0;
    }

    if pr > 0 && fitting_bins_count > 1 && (pr as f64) < 0.1 * capf && next_item_size > 0 && (next_item_size as f64) > pr as f64 {
        score += 4.5 * (1.0 - progress);
    }
    if pr > 0 && dead > 0.0 && next_item_size > 0 && (pr as f64 + dead) <= next_item_size as f64 && progress > 0.3 {
        score += 8.8 * (1.0 - progress);
    }
    if pr > 0 && (pr as f64) < 0.06 * capf && fitting_bins_count > 2 {
        score += 5.0 * (1.0 - progress);
    }
    if pr > 0 && next_item_size > 0 && (pr as u32) % next_item_size == 0 && pr >= next_item_size {
        score -= 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Small non-zero gaps are nearly unusable: penalize them so that a
    // residual of 1..11 is worse than a moderately larger residual.
    let small_gap_thresh = 12.0;
    if post_residual > 0 && (post_residual as f64) < small_gap_thresh {
        score += (small_gap_thresh - post_residual as f64) * 1.5;
    }

    // Perfect fit: heavily reward closing a bin exactly.
    if post_residual == 0 {
        score -= 25.0;
    }

    // --- Lookahead chaining (k=2) ---
    if next_item_size > 0 {
        // Reward leaving a gap the next item can exactly-ish occupy.
        if post_residual > 0 && next_item_size <= post_residual {
            score -= 6.0;
            if next_item_size == post_residual {
                score -= 6.0; // perfect chain
            }
        }
        // Penalize a gap that the next item cannot use.
        if post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
            score += 2.0;
        }
    }

    // --- Last-chance pressure ---
    // If this is the ONLY open bin that fits the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin carries a fixed cost plus pressure that grows
        // with the number of already-open bins (consolidation pressure).
        score += 20.0 + 0.5 * open_bins_count as f64;
        // If open bins are sitting on lots of slack, prefer filling them
        // instead of spreading into a fresh bin.
        score += (mean_residual / 10.0).min(10.0);
        // If no open bin can fit the item at all, a new bin is essentially
        // unavoidable: soften the penalty.
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
    }

    // --- Prefer fuller bins when many bins are open ---
    let fill_fraction = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 0.05 * open_bins_count as f64 * fill_fraction;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capf = bin_capacity as f64;
    let pr = post_residual;
    let mut score = pr as f64;
    let progress = step_index as f64 / total_items.max(2) as f64;

    // Tiered post-residual rewards.
    if pr == 0 {
        score -= 560.0;
    } else if pr <= 3 {
        score -= 262.0;
    } else if pr <= 5 {
        score -= 130.0;
    } else if pr <= 16 {
        score -= 82.0;
    } else if pr <= 40 {
        score -= 16.0;
    } else if pr <= 66 {
        score -= 4.0;
    }

    // Dead-space penalty for residuals too small for typical items.
    if pr > 0 && pr < 20 {
        score += (20.0 - pr as f64) * (20.0 - pr as f64) * 0.58;
    }

    // Two-step lookahead: exact pair fill is excellent; proportional waste reward otherwise.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 350.0;
        } else if next_item_size + 1 == pr {
            score -= 190.0;
        } else if next_item_size <= pr {
            let waste = (pr - next_item_size) as f64;
            score -= waste * 2.4;
            if (waste as u32) % 10 == 0 {
                score -= 25.0;
            }
        } else {
            let miss = (next_item_size - pr) as f64;
            score += miss.min(50.0) * 0.7 + 7.4;
        }
    }

    let dead = bin_residual as f64 - item_size as f64;
    if dead > 0.0 {
        let dead_frac = dead / capf;
        if next_item_size > 0 && dead < next_item_size as f64 {
            score += 12.0 + dead * 0.18 + (next_item_size as f64 - dead) * 0.93;
        } else if next_item_size > 0 && dead as u32 == next_item_size {
            score -= 55.0;
        } else {
            let rem_frac = (1.0 - progress).min(1.0);
            score -= dead * (0.06 + 0.05 * rem_frac) + dead_frac * dead_frac * 46.0;
        }
        if dead < 0.05 * capf && open_bins_count > 2 {
            score += 5.0 * (1.0 - dead / (0.05 * capf));
        }
        if dead > 0.0 && dead < 4.0 && pr > 4 {
            score += 14.0;
        }
        if dead_frac > 0.2 && dead_frac < 0.55 {
            score += dead_frac * (1.0 - progress) * 18.0;
        }
        // Mid-range dead-space bump: penalize awkward pockets.
        if dead_frac > 0.1 && dead_frac < 0.45 {
            let bump = (dead_frac - 0.275) * (dead_frac - 0.275);
            score += bump * 28.0 * (0.4 + 0.6 * (1.0 - progress));
        }
        // After-next-item leftover shaping.
        if next_item_size > 0 && dead as u32 >= next_item_size {
            let after = dead as u32 - next_item_size;
            if after == 0 || after <= 2 {
                score -= 24.0;
            } else if after as f64 <= 0.04 * capf {
                score -= 10.0;
            }
        }
        if dead_frac > 0.3 && progress > 0.6 {
            score += dead_frac * (progress - 0.6) * 32.0;
        }
        // Small usable pockets late in stream are worth keeping.
        if dead_frac > 0.05 && dead_frac < 0.25 && progress > 0.35 {
            score += dead_frac * (progress - 0.35) * 23.0;
        }
        if next_item_size > 0 && dead > next_item_size as f64 && dead <= next_item_size as f64 + 3.0 {
            score -= 18.0 * (1.0 - progress);
        }
        // Dead space exactly divisible by next item is reusable.
        if next_item_size > 0 && (dead as u32) % next_item_size == 0 && dead >= next_item_size as f64 && dead <= 2.0 * next_item_size as f64 {
            score -= 13.0 * (1.0 - progress);
        }
        // Combined: dead fits next item exactly with margin.
        if next_item_size > 0 && dead as f64 >= next_item_size as f64 && dead as f64 <= 1.5 * next_item_size as f64 && progress > 0.5 {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && dead_frac >= 0.45 && dead_frac <= 0.5 && (next_item_size as f64) >= dead * 0.5 && (next_item_size as f64) <= dead {
            score -= 11.0 * (1.0 - progress);
        }
        // Dead space fits two next-items: reusable pocket.
        if next_item_size > 0 && dead as f64 >= 2.0 * next_item_size as f64 && dead as f64 <= 2.5 * next_item_size as f64 && progress > 0.45 {
            score -= 7.0 * (1.0 - progress);
        }
        if next_item_size > 0 && dead_frac < 0.12 && dead >= next_item_size as f64 {
            score -= 5.0 * (1.0 - dead_frac / 0.12) * (1.0 - progress);
        }
        // Mean residual comparison for pocket utility.
        if dead_frac > 0.15 && mean_residual > dead && dead > 0.0 {
            score += (mean_residual - dead).min(40.0) * 0.09 * (1.0 - progress);
        }
        // Dead hosts two next-items exactly: strong multi-fill pocket.
        if next_item_size > 1 && dead as u32 >= 2 * next_item_size && (dead as u32) % next_item_size == 0 {
            score -= 8.0 * (1.0 - progress);
        }
        // Slightly-too-big pocket for next item: graded penalty.
        if next_item_size > 0 && dead as f64 > next_item_size as f64 && dead as f64 <= next_item_size as f64 + 6.0 {
            let gap = dead as f64 - next_item_size as f64;
            score += gap * (1.6 + 0.9 * gap) * (1.0 - progress);
        }
        // Pocket covers next item plus a mean-residual-sized remainder.
        if next_item_size > 0 {
            let nf = next_item_size as f64;
            if dead >= nf + mean_residual.min(nf) && dead <= nf + nf {
                score -= 16.0 * (1.0 - progress);
            } else if dead > nf && dead < nf + 2.0 {
                score -= 8.0;
            }
        }
        if dead_frac > 0.02 && dead_frac < 0.08 && next_item_size > 0 && (next_item_size as f64) > dead {
            score += (0.08 - dead_frac) * 30.0 * (1.0 - progress);
        }
    }

    // Pair-fill reward when bin can host item + next item together.
    if next_item_size > 0 {
        let pair = item_size as f64 + next_item_size as f64;
        if bin_residual as f64 >= pair {
            let slack = bin_residual as f64 - pair;
            score -= 40.0 - (slack / capf) * 30.0;
        }
        if pr > 0 && (pr as f64) >= next_item_size as f64 && (pr as f64) < next_item_size as f64 + 4.0 {
            score -= 14.0 * (1.0 - progress);
        }
    }

    // Consolidation pressure when many bins are open, stronger early.
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    score -= bin_pressure * 2.0 * (1.0 - progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 52.0;
    }

    // Mean-residual anchoring, stronger later in the stream.
    score -= (0.4 + 0.17 * progress) * (mean_residual - pr as f64);

    // Residual-vs-mean-ratio shaping: prefer post residual near fleet mean.
    if pr > 0 {
        let dev = ((pr as f64) - mean_residual).abs() / capf;
        score += dev * 8.0 * (1.0 - progress);
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let next_tight = next_item_size > 0 && mean_residual < next_item_size as f64;
        if next_tight || fitting_bins_count <= 1 {
            score -= 34.0;
        } else {
            score += 38.0 + 1.5 * bin_pressure;
        }
        if fitting_bins_count > 1 && progress > 0.5 {
            score += 26.0;
        }
        // Large items fragment open bins; better to open fresh for them.
        if item_size as f64 > 0.6 * capf {
            score -= 13.0;
        }
        if next_item_size > 0 && (item_size as f64 + next_item_size as f64) > capf {
            score -= 17.0;
        }
        if item_size as f64 > 0.78 * capf && mean_residual < 0.22 * capf {
            score -= 27.0;
        }
        if item_size as f64 > 0.85 * capf && mean_residual < 0.12 * capf {
            score -= 32.0;
        }
        if item_size as f64 > 0.93 * capf {
            score -= 21.0;
        }
        if progress > 0.7 && open_bins_count > 3 {
            score += 19.0 * progress;
        }
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 6.0 + (next_item_size as f64 - mean_residual) * 0.13;
        }
        let spread = (mean_residual - item_size as f64).abs();
        if spread < 0.08 * capf && fitting_bins_count > 2 {
            score += 9.5;
        }
        if item_size as f64 > mean_residual * 1.6 && fitting_bins_count > 1 && open_bins_count > 2 {
            score -= 15.0 * (1.0 - progress);
        }
        let rem_items = if total_items > step_index { (total_items - step_index) as f64 } else { 0.0 };
        if rem_items > 0.15 * total_items.max(1) as f64 && mean_residual < 0.5 * (next_item_size.max(1) as f64) {
            score -= 15.0 * (1.0 - progress);
        }
        // With many open bins and generous mean residual, fresh bin is wasteful.
        if fitting_bins_count > 2 && mean_residual > 0.55 * capf {
            score += 7.5 * (1.0 - progress);
        }
        // Mean residual can host item+next pair; prefer existing bin.
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && mean_residual < (item_size as f64 + next_item_size as f64).min(capf) {
            score -= 6.5 * (1.0 - progress);
        }
        // Next item nearly fills mean residual; don't fragment.
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 0.85 && next_item_size as f64 <= mean_residual && progress > 0.4 {
            score -= 8.0 * (1.0 - progress);
        }
        // Next item large and mean residual generous: don't open fresh.
        if next_item_size > 0 && next_item_size as f64 > 0.5 * capf && mean_residual > 0.3 * capf {
            score -= 10.5;
        }
        // Poor fits available: fresh bin attractive.
        if fitting_bins_count > 1 && mean_residual < item_size as f64 * 0.4 {
            score += 12.0;
        }
        // Fragmenting a wide-open bin for a large item when a deep pocket exists elsewhere.
        if fitting_bins_count > 1 && dead > 0.35 * capf && item_size as f64 > mean_residual * 1.25 {
            score -= 11.0 * (1.0 - progress);
        }
        // Large item whose complement exceeds next item: fresh bin pairs better.
        if next_item_size > 0 && item_size as f64 > 0.55 * capf && (capf - item_size as f64) < next_item_size as f64 && fitting_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 24.0 * (1.0 - progress);
        }
        // Next item will exactly fill post residual here: keep this bin closed to others.
        if next_item_size > 0 && pr > 0 && pr == next_item_size && fitting_bins_count > 0 {
            score -= 12.0 * (1.0 - progress);
        }
        // Mean residual barely hosts next item: avoid fragmentation.
        if next_item_size > 0 && fitting_bins_count > 0 && mean_residual >= next_item_size as f64 && mean_residual < next_item_size as f64 + 5.0 {
            score -= 9.0 * (1.0 - progress);
        }
        if open_bins_count > 4 && fitting_bins_count > 1 && mean_residual > 0.45 * capf {
            score += 5.0 * progress;
        }
    }

    // Usable-pocket bonus: residual after placement that can host next item tightly.
    if next_item_size > 0 && pr >= next_item_size && pr - next_item_size > 0 && (pr - next_item_size) < item_size.max(next_item_size) {
        score -= 16.0;
    }

    // Penalize leaving residual that next item cannot use, but only if small.
    if next_item_size > pr && pr > 0 && pr < 30 {
        score += 8.0;
    }

    // Usable-floor bonus: post residual above next-item floor is worth keeping.
    if pr > 0 {
        let usable_floor = (next_item_size.max(1) as f64).min(0.35 * capf);
        if (pr as f64) >= usable_floor {
            score -= 8.5 * (1.0 - progress) * ((pr as f64) / capf);
        }
    }
    if pr > 0 && (pr as f64) < 0.5 * (next_item_size.max(1) as f64) && fitting_bins_count > 1 {
        score += 6.5 * (1.0 - progress);
    }

    // Late-stream fine finishing: reward near-exact closes.
    if progress > 0.85 && pr <= 2 && pr > 0 {
        score -= 21.0;
    }
    if progress > 0.8 && pr > 0 {
        score += (pr as f64) * 0.38 * (progress - 0.8) * 5.0;
    }

    // Tiny post-residual with many fitting bins is wasteful fragmentation.
    if pr > 0 && fitting_bins_count > 1 && (pr as f64) < 0.1 * capf && next_item_size > 0 && (next_item_size as f64) > pr as f64 {
        score += 4.5 * (1.0 - progress);
    }
    // pr + dead together can't host next item -> wasted pocket.
    if pr > 0 && dead > 0.0 && next_item_size > 0 && (pr as f64 + dead) <= next_item_size as f64 && progress > 0.3 {
        score += 8.7 * (1.0 - progress);
    }
    // Very small pr with alternatives available.
    if pr > 0 && (pr as f64) < 0.06 * capf && fitting_bins_count > 2 {
        score += 5.0 * (1.0 - progress);
    }
    // pr exactly divisible by next item is reusable.
    if pr > 0 && next_item_size > 0 && (pr as u32) % next_item_size == 0 && pr >= next_item_size {
        score -= 6.2 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Penalize dead space that no future item (min size 1..=10 heuristic) can use.
    if post_residual > 0 && post_residual < 5 {
        score += 15.0; // tiny unusable sliver
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; mildly prefer leaving larger residuals
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Global state: when many bins are open, discourage opening new ones
    // (make new-bin candidate expensive), encourage consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins exist and mean residual is usable.
        let mut new_bin_penalty = 20.0 + 3.0 * open_bins_count as f64;
        if mean_residual >= item_size as f64 {
            new_bin_penalty += 10.0 + mean_residual / bin_capacity as f64 * 15.0;
        }
        // Early in the stream, opening bins is cheaper; late, expensive.
        new_bin_penalty *= 0.5 + progress;
        // Exception: if the only fitting bin would leave a huge residual, allow new bin.
        if fitting_bins_count == 1 && post_residual > 60 {
            new_bin_penalty -= 45.0;
        }
        score += new_bin_penalty;
    } else {
        // Existing bin: favor bins whose residual is below mean (consolidate fuller bins).
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 6.0 * dev;
    }

    // Mild preference for balancing residual spread when few bins open.
    if open_bins_count > 1 {
        score += 0.5 * (bin_residual as f64 - mean_residual).abs() / bin_capacity as f64;
    }

