    if pr > 0 && fitting_bins_count > 1 && (pr as f64) < 0.1 * capf && next_item_size > 0 && (next_item_size as f64) > pr as f64 {
        score += 4.5 * (1.0 - progress);
    }
    if pr > 0 && (pr as f64) < 0.06 * capf && fitting_bins_count > 2 {
        score += 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits (small post_residual).
    score *= 1.0;

    // Harmonic class of post_residual: dead space in [1..=9] is nearly useless,
    // [10..=19] marginal; residuals that are multiples of small divisors are reusable.
    let pr = post_residual;
    let dead_penalty = if pr == 0 {
        -60.0 // perfect fit — strongly favored
    } else if pr < 10 {
        25.0 // unusable sliver
    } else if pr < 20 {
        8.0
    } else {
        0.0
    };
    score += dead_penalty;

    // Modulo-class bonus: residuals divisible by 10 or 25 are "harmonic" —
    // typical item sizes (multiples of 5/10) fit them cleanly later.
    let harmonic = (pr % 10 == 0) as f64 * 12.0 + (pr % 25 == 0) as f64 * 10.0;
    score -= harmonic;

    // Lookahead coupling: if the next item fits the post residual exactly or
    // nearly, reward this placement strongly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let gap = pr - next_item_size;
            score -= 20.0 * (1.0 - gap as f64 / 100.0);
        } else {
            // next item won't fit here; mild penalty scaled by overshoot class
            let over = (next_item_size - pr) % 10;
            score += 3.0 + over as f64;
        }
    }

    // Last-chance logic: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin, but less when the item is
    // large (poor fits in any residual are likely) or many bins are open with
    // high mean residual (fragmentation already present).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        score += 30.0
            - 25.0 * item_frac
            - 10.0 * (mean_residual / bin_capacity as f64).min(1.0)
            - 5.0 * progress;
    } else {
        // Slight preference for bins already below mean residual (consolidation).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
        // Prefer more-filled bins as the stream progresses.
        score -= (1.0 - bin_residual as f64 / bin_capacity as f64) * 6.0 * (0.5 + progress);
    }

    // Integer-division threshold: post_residual bucketed by quarters of capacity.
    let quarter = pr / (bin_capacity / 4);
    score -= (quarter as f64) * 2.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A post_residual that is too small to hold any plausible future item
    // (sizes 1..100, but conservatively < 10) is pure waste.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score += 8.0 * fit_ratio;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: penalize creating new bins when many are open.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Lookahead: if next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 20.0;
    }
    // If next item nearly fits (within small gap), mild penalty for near-miss.
    if next_item_size > 0 && (post_residual as u32) < next_item_size && (post_residual as u32) + 10 >= next_item_size {
        score += 12.0;
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (closing out tighter bins first keeps looser bins flexible).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Slight progression term: as stream advances, tighten packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for dead space: small post_residual is good (tight fit).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness;

    // 2-step lookahead: reward if the next item exactly fits the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining: this bin will be completed next step
        } else if next_item_size <= post_residual {
            // partial reward proportional to how much of the leftover the next item consumes
            let consume = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * consume;
        } else {
            // next item cannot use the leftover: penalize large unusable residue
            let waste = (next_item_size - post_residual) as f64 / bin_capacity as f64;
            score += 25.0 * waste;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean (best-fit style),
    // penalize bins looser than the mean unless lookahead favors them.
    let diff = post_residual as f64 - mean_residual;
    score += 0.3 * diff;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Early in the stream, be more willing to open fresh bins (spread large items);
    // late in the stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * (1.0 - progress);

    // Penalize opening a brand-new bin when many bins are already open and consolidation
    // is possible; the new-bin candidate has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
