pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post-residual so small leftovers dominate.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize leaving dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits in the post-residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Post-residual too small for next item: mild penalty proportional to waste.
        score += 0.1 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Many open bins: discourage opening new ones; encourage filling existing.
    let openness = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or mean residual is large.
        score += 20.0 + 8.0 * openness + 0.3 * mean_residual;
        // But if current bin fits poorly relative to mean residual, opening new bin can win.
        if post_residual as f64 > mean_residual * 0.8 && fitting_bins_count > 1 {
            score -= 10.0;
        }
    }

    // Time horizon: early in the stream, be more willing to spread items (keep flexibility);
    // late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    score += (1.0 - progress) * 0.05 * post_residual as f64;

    // Mild tie-break toward bins with larger residuals (pack big gaps first).
    score -= 0.02 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
