    let mut score = pr + 20.0 * poly;

    // Penalize bins that are worse than average residual, scaled by progress.
    score += progress * (pr - mean_residual).abs() * 0.3;

    // Reward tight fits: small post_residual relative to next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 10.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 5.0 * (nx - pr) / cap;
