    // Last-chance bonus when few fitting bins exist.
    if fitting_bins_count <= 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Slight penalty for spreading across many bins early.
    score += open_bins_count as f64 * 0.1 * progress;

    // New-bin candidate: mildly discouraged unless residual would be perfect.
    if bin_residual == bin_capacity {
        score += 3.0 - 6.0 * pr_norm;
    }

    score
}

