            score += 20.0;
        }
    }

    // Mild congestion penalty: prefer tightening bins when many are open
    score += 0.05 * open_bins_count as f64 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.1 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 12 {
        score += (12 - post_residual) as f64 * 8.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Reward tight fits (small relative waste).
        score -= (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 10.0;
    }

    // Penalize bins whose residual can't fit the next item (creates dead space for lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward bins that can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += open_bins_count as f64 * 1.5;
    score += mean_residual * 0.15;

    // New-bin candidate: prefer only when item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + item_size as f64 * 0.4 - progress * 10.0;
        if item_size >= 60 { score -= 20.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capf = bin_capacity as f64;
    let pr = post_residual;
    let dead = bin_residual as f64 - item_size as f64;
    let dead_frac = if dead > 0.0 { dead / capf } else { 0.0 };
    let progress = step_index as f64 / total_items.max(2) as f64;
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    let mut score = pr as f64;

    // Tiered post-residual rewards: exact and near-exact fills dominate.
    if pr == 0 {
        score -= 470.0;
    } else if pr <= 3 {
        score -= 230.0;
    } else if pr <= 6 {
        score -= 115.0;
    } else if pr <= 18 {
        score -= 48.0;
    } else if pr <= 40 {
        score -= 12.0;
    } else if pr <= 66 {
        score -= 3.5;
    }

    // Dead-space penalty: residuals too small for typical items are waste.
    if pr > 0 && pr < 20 {
        score += (20.0 - pr as f64) * (20.0 - pr as f64) * 0.58;
    }

    // Two-step lookahead with modular waste bonus.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size + 1 == pr {
            score -= 165.0;
        } else if next_item_size <= pr {
            let waste = (pr - next_item_size) as f64;
            score -= waste * 2.3;
            if (waste as u32) % 10 == 0 && waste > 0.0 {
                score -= 22.0;
            }
        } else {
            let miss = (next_item_size - pr) as f64;
            score += miss.min(50.0) * 0.66 + 7.0;
        }
    }

    // Dead-space shaping: prefer residuals that leave usable pockets for the next item.
    if dead > 0.0 {
        if next_item_size > 0 && dead < next_item_size as f64 {
            score += 10.0 + (next_item_size as f64 - dead) * 0.9;
        } else if next_item_size > 0 && dead as u32 == next_item_size {
            score -= 52.0;
        } else {
            let rem = if total_items > step_index { (total_items - step_index) as f64 } else { 0.0 };
            let rem_frac = (rem / total_items.max(1) as f64).min(1.0);
            score -= dead * (0.05 + 0.05 * rem_frac) + dead_frac * dead_frac * 44.0;
        }
        if next_item_size > 0 && dead as u32 >= next_item_size {
            let after = dead as u32 - next_item_size;
            if after == 0 || after <= 2 {
                score -= 23.0;
            } else if (after as f64) <= 0.04 * capf {
                score -= 9.5;
            }
        }
        if dead_frac > 0.1 && dead_frac < 0.45 {
            let bump = (dead_frac - 0.275) * (dead_frac - 0.275);
            score += bump * 27.0 * (0.4 + 0.6 * (1.0 - progress));
        }
        if dead_frac > 0.3 && progress > 0.6 {
            score += dead_frac * (progress - 0.6) * 31.0;
        }
        if dead_frac > 0.05 && dead_frac < 0.25 && progress > 0.35 {
            score += dead_frac * (progress - 0.35) * 21.0;
        }
        if next_item_size > 0 && dead > next_item_size as f64 && dead <= next_item_size as f64 + 3.0 {
            score -= 17.0 * (1.0 - progress);
        }
        if next_item_size > 0 && dead as f64 >= next_item_size as f64 && dead as f64 <= 1.5 * next_item_size as f64 && progress > 0.5 {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && dead as f64 > next_item_size as f64 && dead as f64 <= next_item_size as f64 + 6.0 {
            let gap = dead as f64 - next_item_size as f64;
            score += gap * (1.6 + 0.9 * gap) * (1.0 - progress);
        }
        if dead < 0.05 * capf && open_bins_count > 2 {
            score += 5.0 * (1.0 - dead / (0.05 * capf));
        }
        // NEW: two-copy dead-space anticipation — dead space that could host two copies of the next item.
        if next_item_size > 1 && dead as f64 >= 2.0 * next_item_size as f64 && dead as f64 <= 2.5 * next_item_size as f64 {
            score -= 8.0 * (1.0 - progress);
        }
        // NEW: tiny dead-space waste marker.
        if dead > 0.0 && dead < 4.0 && pr > 4 {
            score += 14.0;
        }
    }

    // Pair-fill reward when bin can host item + next item together.
    if next_item_size > 0 {
        let pair = item_size as f64 + next_item_size as f64;
        if bin_residual as f64 >= pair {
            let slack = bin_residual as f64 - pair;
            score -= 38.0 - (slack / capf) * 28.0;
        }
        if pr > 0 && (pr as f64) >= next_item_size as f64 && (pr as f64) < next_item_size as f64 + 4.0 {
            score -= 13.5 * (1.0 - progress);
        }
    }

    // Consolidation pressure when many bins are open, stronger early.
    score -= bin_pressure * 2.4 * (1.0 - progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Mean-residual anchoring, stronger later in the stream.
    score -= (0.35 + 0.16 * progress) * (mean_residual - pr as f64);

    // New-bin candidate: open only when lookahead is tight or alternatives are poor.
    if bin_residual == bin_capacity {
        let next_tight = next_item_size > 0 && mean_residual < next_item_size as f64;
        if next_tight || fitting_bins_count <= 1 {
            score -= 34.0;
        } else {
            score += 37.0 + 1.8 * bin_pressure;
        }
        if open_bins_count > 0 && fitting_bins_count > 1 && progress > 0.5 {
            score += 24.0;
        }
        // Large items fragment open bins; better to open fresh for them.
        if item_size as f64 > 0.6 * capf {
            score -= 14.0;
        }
        if item_size as f64 > 0.78 * capf && mean_residual < 0.22 * capf {
            score -= 27.0;
        }
        if item_size as f64 > 0.85 * capf && mean_residual < 0.12 * capf {
            score -= 32.0;
        }
        if item_size as f64 > 0.93 * capf {
            score -= 21.0;
        }
        if next_item_size > 0 && (item_size as f64 + next_item_size as f64) > capf {
            score -= 17.0;
        }
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 6.0 + (next_item_size as f64 - mean_residual) * 0.13;
        }
        if progress > 0.7 && open_bins_count > 3 {
            score += 19.0 * progress;
        }
        let spread = (mean_residual - item_size as f64).abs();
        if spread < 0.08 * capf && fitting_bins_count > 2 {
            score += 9.0;
        }
        if item_size as f64 > mean_residual * 1.6 && fitting_bins_count > 1 && open_bins_count > 2 {
            score -= 15.0 * (1.0 - progress);
        }
        if fitting_bins_count > 1 && mean_residual < item_size as f64 * 0.4 {
            score += 11.0;
        }
        if next_item_size > 0 && next_item_size as f64 > 0.5 * capf && mean_residual > 0.3 * capf {
            score -= 10.0;
        }
        if next_item_size > 0 && item_size as f64 > 0.55 * capf && (capf - item_size as f64) < next_item_size as f64 && mean_residual >= item_size as f64 {
            score += 22.0 * (1.0 - progress);
        }
        let rem_items = if total_items > step_index { (total_items - step_index) as f64 } else { 0.0 };
        if rem_items > 0.15 * total_items.max(1) as f64 && mean_residual < 0.5 * (next_item_size.max(1) as f64) {
            score -= 14.0 * (1.0 - progress);
        }
        if fitting_bins_count > 2 && mean_residual > 0.55 * capf {
            score += 7.0 * (1.0 - progress);
        }
        // NEW: pair-chain check — opening a fresh bin is bad if the next item fits the mean residual tightly.
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && mean_residual < (item_size as f64 + next_item_size as f64).min(capf) {
            score -= 6.5 * (1.0 - progress);
        }
        // NEW: near-miss lookahead — next item barely fits mean residual; prefer keeping open bins viable.
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 0.85 && next_item_size as f64 <= mean_residual && progress > 0.4 {
            score -= 8.0 * (1.0 - progress);
        }
    }

    // Usable-pocket bonus: residual after placement that can host next item tightly.
    if next_item_size > 0 && pr >= next_item_size && pr - next_item_size > 0 && (pr - next_item_size) < item_size.max(next_item_size) {
        score -= 15.0;
    }

    // Penalize leaving residual that next item cannot use, but only if small.
    if next_item_size > pr && pr > 0 && pr < 30 {
        score += 8.0;
    }
    if pr > 0 && (pr as f64) < 0.5 * (next_item_size.max(1) as f64) && fitting_bins_count > 1 {
        score += 6.0 * (1.0 - progress);
    }
    if pr > 0 && (pr as f64) < 0.06 * capf && fitting_bins_count > 2 {
        score += 5.0 * (1.0 - progress);
    }

    // NEW: usable-floor reward — residual large enough for the next item is valuable space.
    if pr > 0 {
        let usable_floor = (next_item_size.max(1) as f64).min(0.35 * capf);
        if (pr as f64) >= usable_floor {
            score -= 8.5 * (1.0 - progress) * ((pr as f64) / capf);
        }
    }
    // NEW: tiny-residual waste penalty when alternatives exist and next item is larger.
    if pr > 0 && fitting_bins_count > 1 && (pr as f64) < 0.1 * capf && next_item_size > 0 && (next_item_size as f64) > pr as f64 {
        score += 4.5 * (1.0 - progress);
    }

    // Late-stream small-residual refinement.
    if progress > 0.85 && pr > 0 && pr <= 2 {
        score -= 21.0;
    }
    if progress > 0.8 && pr > 0 {
        score += (pr as f64) * (progress - 0.8) * 1.9;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing the bin completely.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: if the next item exactly matches the
    // post-residual, this bin becomes a two-item perfect chain.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // Next item fits: mild reward proportional to tightness of the chain.
            score -= 40.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item will NOT fit here: this bin leaves dead space the
            // lookahead cannot use, penalize proportionally to wasted space.
            let waste = post_residual as f64;
            score += 15.0 * (waste / bin_capacity as f64) * (1.0 + (next_item_size as f64 - post_residual as f64) / 100.0);
        }
    }

    // Penalize small unusable residuals (< smallest plausible item) harder.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Relative-to-mean-residual coupling: prefer bins whose residual after
    // placement is below the mean (tighter packing), reward deviation.
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when no open bin fits well or the
    // stream is early (plenty of future items to fill it).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted early in the stream.
        score = 250.0 - 100.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 30.0; // fresh bin can host the next item too
        }
        if fitting_bins_count > 0 && mean_residual > 50.0 {
            score += 50.0; // existing bins are roomy; don't open another
        }
    }

    // Mild preference to fill bins with larger current items (better space usage).
    score -= 0.1 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
