pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportionally wasted space.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual too small to ever be useful.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
        } else if next_item_size <= bin_residual && next_item_size > post_residual {
            // This bin could have fit the next item if we packed differently — mild penalty.
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid opening new bins.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: make empty bins attractive only when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 18.0;
        // Cheaper to open a new bin when few bins are open or mean residual is fragmented.
        score -= 0.5 * open_bins_count as f64;
        if mean_residual > 40.0 {
            score += 10.0; // existing bins have plenty of room; avoid spreading
        }
        // If current item is large and next item is also large, fresh bin is good.
        if item_size >= 50 && next_item_size >= 50 {
            score -= 12.0;
        }
    }

    // Time horizon: early in stream, be more conservative (prefer filling existing bins);
    // later, allow more freedom.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    // Global fragmentation: many open bins with low mean residual -> consolidate.
    if open_bins_count > 3 && mean_residual < 25.0 {
        score -= 5.0;
    }

    // Small bonus for balancing residuals near mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
