pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr_norm = pr / cap;

    // Base: post-residual, scaled by smooth stream progress (later => tolerate less slack)
    let mut score = pr * (0.8 + 0.6 * progress);

    // Non-linear penalty on dead space: quartic coupling with progress
    score += 40.0 * pr_norm.powi(4) * (0.5 + progress);

    // Reward tight fits (small post_residual) with smooth exponential term
    score -= 25.0 * (-pr / 15.0).exp();

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // mild congestion penalty to spread load
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Coupling with mean residual: prefer bins whose residual deviates smoothly from mean
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Lookahead: reward leaving space compatible with next item (smooth interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_gap = (pr - nx).abs();
        score += 0.3 * fit_gap;
        // extra reward if next item fits exactly-ish
        score -= 20.0 * (-(fit_gap) / 10.0).exp();
    }

    // Mild penalty for opening new bins when many are open and progress is early
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) + 1.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    // Residuals that are "harmonically useful" (divisible into common small item
    // classes like 10/20/25/50) should be rewarded; awkward primes penalized.
    let pr = post_residual;
    let mut harmonic_bonus = 0.0;
    if pr > 0 {
        if pr % 50 == 0 { harmonic_bonus -= 18.0; }        // half-capacity class
        else if pr % 25 == 0 { harmonic_bonus -= 10.0; }   // quarter class
        else if pr % 20 == 0 { harmonic_bonus -= 8.0; }    // fifth class
        else if pr % 10 == 0 { harmonic_bonus -= 5.0; }    // tenth class
        else if pr % 5 == 0 { harmonic_bonus -= 2.0; }
        else { harmonic_bonus += 6.0; }                    // non-harmonic dead space
    }

    // Exact fit is perfect.
    if pr == 0 { harmonic_bonus -= 40.0; }

    // Integer-division threshold classes on post_residual:
    // tiny residuals (< small item min) are dead space -> penalize extra.
    let dead_class = pr / 10; // integer division threshold
    if dead_class == 0 && pr > 0 { harmonic_bonus += 12.0; }
    else if dead_class <= 2 { harmonic_bonus += 3.0; }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr { harmonic_bonus -= 30.0; }
        else if next_item_size <= pr {
            let slack = pr - next_item_size;
            // harmonic class of the slack after the lookahead item
            if slack % 10 == 0 { harmonic_bonus -= 12.0; }
            else if slack % 5 == 0 { harmonic_bonus -= 5.0; }
            else { harmonic_bonus += 4.0; }
        } else {
            // next item won't fit here regardless; slight penalty for tight fills
            harmonic_bonus += 2.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        harmonic_bonus -= 25.0;
    }

    // New-bin candidate handling: only attractive if item is huge relative to
    // capacity or all open bins fit poorly (post_residual would be awkward).
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / cap;
        // base new-bin cost: discourage spreading unless beneficial
        let mut nb = 15.0;
        if fit_ratio > 0.8 { nb -= 20.0; }                       // big item, fresh bin fine
        if next_item_size > 0 && next_item_size >= pr - item_size && pr - item_size < 10 { nb -= 15.0; }
        // if mean residual across open bins is small, open bins are nearly full anyway
        if mean_residual < 15.0 { nb -= 10.0; }
        nb += harmonic_bonus * 0.5;
        return nb;
    }

    // Mild preference to fill bins below mean residual (balance-aware packing).
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Progression: later in the stream, tighten up (prefer fuller bins more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0;

    score += harmonic_bonus;
    score
}

