    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 15.0 * (10.0 - gap as f64) / 10.0;
            } else {
                score += 0.1 * gap as f64;
            }
        } else {
            // Next item cannot fit here: residual becomes potential dead space.
            score += 5.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean residual coupling: prefer bins whose residual deviates from the mean
    // when this bin's residual is small (consolidate small leftovers).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive if the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        // A fresh bin is a good idea for large items or when no tight fit exists.
        if fit_ratio > 0.6 {
            score -= 10.0;
        } else {
            score += 20.0 + 30.0 * (1.0 - fit_ratio);
        }
        // Late in the stream, avoid opening bins for small leftovers.
        if progress > 0.8 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer bins with small post_residual (tight packing).
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward post_residual that exactly matches
    // the next item size (perfect chain), scaled by lookahead availability.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let match_reward = 60.0 * (1.0 - diff / bin_capacity as f64).powi(3);
        score -= match_reward;
        // Extra bonus for exact match.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize post_residual that is slightly too small to fit the next item
        // (dead space relative to lookahead).
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably
    // from the mean residual of open bins.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 25.0 * progress;
    }

    // New-bin candidate handling: it has bin_residual == bin_capacity, so its
    // post_residual is large; make it attractive only when no open bin offers
    // a decent fit, and less attractive early when consolidation is cheap.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 10.0 * (1.0 - progress); // discourage new bins early
        score -= 5.0 * (open_bins_count as f64).ln(); // slight preference when many bins open
    } else {
        // Reward using existing bins proportionally to how full they already are.
        score -= 0.2 * (bin_capacity - bin_residual) as f64;
    }

    score
}

