    // When many bins are open, prefer consolidating into fuller bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let congestion = (open_bins_count as f64).ln() / (1.0 + (mean_residual / 10.0));
    score += congestion * (1.0 - progress) * 2.0;

    // Mild time-decay pressure: late in stream, avoid opening new bins.
    if bin_residual == bin_capacity {
        score += 8.0 + 30.0 * progress;
        // Opening a new bin is fine if current fit is terrible (post_residual small but bin was empty).
        if post_residual > 0 && (post_residual as f64) < bin_capacity as f64 * 0.15 {
            score -= 10.0;
        }
    }

    // Prefer bins whose residual is close to the item (minimal waste).
    let waste = (bin_residual - item_size) as f64;
    score += 0.05 * waste;

    score
}

