pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Smooth polynomial coupling: penalize large residuals more strongly as the stream progresses
    let coupling = pr_norm * pr_norm * (0.5 + 1.5 * progress) * cap * 0.5;
    score += coupling;

    // Reward tight fits (small post_residual) with a non-linear discount
