    score -= tight_fit;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: bonus if the next item fits exactly into the resulting residual
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        if next_item_size as f64 <= pr {
            score -= 15.0 * (1.0 - diff / cap);
        } else {
            score += 5.0 + diff / cap * 10.0;
        }
    }

    // Penalize bins far from the mean residual (fragmentation signal)
    score += ((pr - mean_residual) / cap).abs() * 8.0 * (0.5 + progress);

    // Mild penalty for spreading across too many open bins
