    if bin_residual == bin_capacity {
        score += 25.0 + 30.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual (integer division buckets)
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let class = (post_residual / 10) as f64; // decade bucket of post residual

    // Reward small post residuals (tight fits), stronger for lower classes
    score -= (cap - post) * 0.15;
    score -= 12.0 / (1.0 + class);

    // Penalize dead space that no plausible item can fill
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic coupling with next item size: reward residuals that can host it
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 - slack * 0.2;
        } else {
            score += 6.0;
        }
    } else {
        // Last item: strongly prefer zero waste
        score -= post * 0.3;
    }

    // Last-chance bin: keep it alive if it fits well
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Modulo logic on residual vs item size classes (harmonic residue match)
    let r_mod = post_residual % 20;
    if r_mod == 0 {
        score -= 8.0; // round harmonics preferred
    } else if r_mod >= 15 {
        score += 4.0; // awkward leftover
    }

    // New-bin candidate: penalize opening unless current fits are bad
    if bin_residual == bin_capacity {
        score += 40.0;
        if post_residual == bin_capacity - item_size {
            // fresh bin: score = leftover space, discourage unless nothing else fits
            score += 20.0 * (1.0 - (fitting_bins_count as f64).recip());
        }
        // Late in stream, opening is cheaper than fragmenting
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 25.0 * progress;
    }

    // Fragmentation pressure: many open bins with high mean residual -> consolidate
    if open_bins_count > 2 && mean_residual > 30.0 {
        score += 0.1 * (mean_residual - post).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (too small for the smallest plausible item) are heavily penalized.
    if post_residual >= 1 && post_residual <= 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Small-but-usable gaps get a mild penalty, decaying with size.
    else if post_residual > 10 && post_residual < 30 {
        score += 0.35 * (30.0 - post_residual as f64);
    }

    // Reward residuals that can still accommodate a typical next item,
    // especially if the lookahead item actually fits.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // Extra reward when the gap is tight around the next item (good chaining).
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 10.0 {
                score -= 6.0 * (1.0 - slack / 10.0);
            }
        } else {
            // Gap cannot host the lookahead item: slight penalty.
            score += 4.0;
        }
    }

    // Pressure from number of open bins: discourage spreading across many bins
    // unless the fit is very tight; encourage consolidation when many bins are open.
    let open_pressure = open_bins_count as f64;
    score += 0.25 * open_pressure;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // If existing bins have large mean residual, opening new bins is wasteful.
        score += 0.4 * mean_residual;
        // Early in the stream, slightly favor reusing bins (future uncertainty).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
        // If the item is large and would leave a tight-but-usable gap in a fresh bin,
        // a new bin is reasonable.
        if item_size >= bin_capacity * 7 / 10 {
            score -= 20.0;
        }
    } else {
        // Reward tight fits relative to bin capacity.
        let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
        score -= 15.0 * tightness;
    }

    // Mean residual coupling: bins deviating far below the mean residual are
    // already well-filled; prefer them (their score drops).
    score -= 0.15 * (mean_residual - post_residual as f64).max(0.0);

    score
