        }
        // NEW: gap above next item scales with tightness.
        if next_item_size > 0 && dead > nf && dead <= nf + 6.0 {
            let gap = dead - nf;
            score += gap * (1.6 + 0.9 * gap) * (1.0 - progress);
        }
        // NEW: dead can host next item plus a mean-residual pocket.
        if next_item_size > 0 && dead >= nf + mean_residual.min(nf) && dead <= nf + nf {
