        }
        // NEW: large item whose complement is below next item -> fresh bin pairs better.
        if next_item_size > 0 && item_size as f64 > 0.55 * capf && (capf - item_size as f64) < nf && fitting_bins_count > 0 && mean_residual >= item_size as f64 {
