        // NEW: fresh bin leaves exact next-item complement.
        if next_item_size > 0 && pr > 0 && pr == next_item_size && fitting_bins_count > 0 {
            score -= 12.0 * (1.0 - progress);
        }
        // NEW: mean residual just above next item; existing bins can absorb it.
        if next_item_size > 0 && fitting_bins_count > 0 && mean_residual >= nf && mean_residual < nf + 5.0 {
            score -= 9.0 * (1.0 - progress);
        }
        if open_bins_count > 4 && fitting_bins_count > 1 && mean_residual > 0.45 * capf {
