pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }

    // Next item fits into the resulting residual: strong reward, scaled by tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.3;
    } else if next_item_size > 0 {
        // Next item cannot follow here: penalize proportionally to wasted space.
        score += (next_item_size as f64) * 0.4;
    }

    // Reward filling bins tighter than the current mean residual.
    score -= (mean_residual - post_residual as f64) * 0.25;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize the brand-new empty bin candidate, unless current bin would be badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (post_residual as f64) - mean_residual;
        if fragmentation > 15.0 {
            score -= 10.0; // opening a new bin avoids large dead space
        } else {
            score += 30.0; // prefer existing bins otherwise
        }
    }

    // Slight preference to consolidate into fewer bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);

    // Small noise-free tie-break: prefer smaller post residual squared.
    score += (post_residual as f64) * (post_residual as f64) * 0.001;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize tiny dead space that can never be reused (items >= 10 typically)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Strong reward: this is the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
