    }

    // Lookahead reward: next item can also fit in the leftover space
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Lookahead penalty: leftover is unusable for the known next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Late in the stream, prefer consolidating into bins with large mean slack
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= t * 5.0 * (mean_residual / bin_capacity as f64);

    // New-bin candidate: make it costly, scaled by how many bins are already open
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * open_bins_count as f64;
    }

    // Mild reward for using more of the bin's current space in one shot
    score += (bin_residual as f64 - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
