pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;
    let item_frac = item_size as f64 / cap;
    let next_frac = next_item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = prn * prn * (1.0 - progress) + prn * progress * progress;
    score += 12.0 * poly;

    // Reward near-perfect fits, smoothly scaled by progress
    let fit_quality = 1.0 - prn;
    score -= 8.0 * fit_quality * fit_quality * (0.5 + progress);

    // Lookahead: reward residuals that can host the next item
    if next_item_size > 0 && pr >= next_item_size as f64 {
        let gap = (pr - next_frac * cap) / cap;
        score -= 6.0 * (1.0 - gap * gap) * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 4.0 * (1.0 - progress);
    }

    // Last-chance bin: strong penalty to open new bins when only one fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly, less as stream progresses
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    // Penalize deviations from mean residual (fragmentation control)
    score += 0.3 * (pr - mean_residual).abs();

    // Slight preference for bins with larger fill early on
    score -= 3.0 * item_frac * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: which capacity fraction slot does the
    // post-placement residual fall into? Small classes are "harmonically clean"
    // (residual is a small multiple of a common item size) and get rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (pr / (cap / 8.0)).floor(); // 0..7 harmonic slot
    score -= (7.0 - class) * 2.0; // reward low post_residual classes

    // Dead-space penalty: residual too small to hold any plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Perfect fit: zero waste is ideal
    if post_residual == 0 {
        score -= 100.0;
    }

    // Coupling with lookahead: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item chains nicely: reward proportionally
            score -= (next_item_size as f64) * 0.5;
        } else {
            // next item won't fit here: penalize more the tighter the miss
            let miss = (next_item_size as f64) - pr;
            if miss < 20.0 {
                score += miss * 1.5;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a bin is expensive; only attractive
    // when no good fit exists (many bins but few fitting, or large item)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = cap * 0.9
            - scarcity * 30.0
            - (item_size as f64 / cap) * 10.0
            + open_bins_count as f64 * 1.0
            + (1.0 - progress) * 5.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0; // fresh bin can also host the next item
        }
    }

    // Mild preference to balance residuals across open bins
    score += (pr - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item can use are pure waste.
    // Items are 1..=100, but small gaps (< ~10) are near-unusable dead space: heavy penalty.
    if post_residual > 0 {
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 6.0; // tiny gap = dead space
        } else {
            // Reward gaps that exactly match a useful small-item size band; penalize awkward mid gaps.
            let gap = post_residual as f64;
            // awkward gaps: 11..=19 and 51..=59 style bands are hard to fill; add penalty
            let awkward = if gap < 20.0 { 12.0 - gap * 0.5 } else { 0.0 };
            score += awkward;
        }
    } else {
        // Perfect fit: strong reward
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0; // blocks the next item in this bin
    }

    // Tight fit reward: item fills a large fraction of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize new bins) — the new-bin candidate has bin_residual == bin_capacity.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New bin: penalize more as stream progresses and open bins grow.
        score += 8.0 + 25.0 * progress + 1.5 * open_bins_count as f64;
        // But if this bin is the last chance and fit would be terrible, new bin is fine.
        if fitting_bins_count == 1 {
            let waste = bin_residual.saturating_sub(item_size) as f64;
            if waste > 0.0 && (waste / bin_capacity as f64) > 0.6 {
                score -= 60.0;
            }
        }
    } else if fitting_bins_count == 1 {
        // Last chance: strongly favor using this bin over opening a new one.
        score -= 30.0;
    }

    // Prefer bins whose residual is close to the current mean residual (balance load),
    // slightly discouraging extreme fragmentation.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
