pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: reward bins whose residual could host the next item too.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0; // enables a chain placement
            if post_residual - next_item_size < 10 {
                score -= 8.0; // near-perfect two-item packing
            }
        } else {
            // Penalize leaving residual that is too small for typical items (dead space).
            score += (10.0f64.min(post_residual as f64)) * 0.6;
        }
    }

    // Last chance: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Crowding: with many open bins, prefer filling existing ones over spreading.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.8 * (0.5 + progress);

    // Mean residual coupling: if open bins are already loose, avoid making it worse.
    score += (post_residual as f64 - mean_residual) * 0.25;

    // New-bin candidate: acceptable early or when no open bin fits well.
    if bin_residual == bin_capacity {
        let escape = if fitting_bins_count == 0 { -50.0 } else { 0.0 };
        let early = 25.0 * (1.0 - progress);
        // Prefer new bin when residual spread is high (fragmentation).
        let frag = if mean_residual > 30.0 { 10.0 } else { 0.0 };
        score += 30.0 - early - escape - frag;
    }

    // Waste penalty scaled by item size (large items deserve good fits).
    score += (post_residual as f64) * (item_size as f64 / 100.0) * 0.5;

    score
}

