pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Non-linear coupling: post_residual polynomial modulated by progress.
    // Early in the stream, prefer tight fits (low post_residual) less aggressively;
    // late in the stream, dead space matters more.
    let progress_weight = 0.5 + 2.0 * progress * progress;
    score += progress_weight * (pr * pr) / cap;

    // Cubic dead-space penalty: small residuals (< item sizes) are dead space
    let dead = if pr > 0.0 && pr < item_size as f64 { 1.0 } else { 0.0 };
    score += 15.0 * dead * (1.0 + progress);

    // Smooth interaction between post_residual and mean_residual:
    // bins far below the mean residual are "wasted" placements unless tight fit.
    let mean_term = (pr - mean_residual) / cap;
    score += 3.0 * mean_term * mean_term * cap * 0.1 - 2.0 * mean_term;

    // Lookahead: reward leaving room for the next item (smooth quadratic coupling)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        score -= 8.0 * (-gap * gap / (2.0 * 25.0)).exp(); // gaussian reward for perfect lookahead fit
        score += 0.02 * gap;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Mild penalty for proliferating open bins early (encourages consolidation)
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 25.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
