pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: strongly reward small post_residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic class of post_residual: dead space that can't hold small items
    // (sizes >= 10 in classic streams; use class thresholds at 10/25/50).
    let dead = if post_residual < 10 { 0.0 }
        else if post_residual < 25 { 12.0 }
        else if post_residual < 50 { 22.0 }
        else { 30.0 };
    score += dead;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // reward proportionally, penalize leftover waste after next item too
        let waste2 = post_residual - next_item_size;
        score -= 25.0 - 0.2 * waste2 as f64;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item can't use this residual at all: penalize large leftovers
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Modulo / class structure of residual: residuals in "nice" classes
    // (multiples of 10, 25) are more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 10.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current bin fits are poor and mean residual is large.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score = bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open
        } else if mean_residual > 45.0 {
            score -= 30.0; // open bins are fragmented; new bin ok
        } else {
            score += 15.0 + 0.3 * mean_residual; // prefer existing bins
        }
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 10.0; // fresh bin keeps room for medium next item
        }
    }

    // Late-stream consolidation: near the end, prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * tightness;

    // Many open bins: encourage packing into them rather than spreading.
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0) * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
