pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny dead gap is worst outcome
    } else if post_residual < 20 {
        score += 8.0;
    } else if post_residual < 30 {
        score += 3.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // Tight fit reward: fraction of bin consumed by this placement
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // Last-chance bin pressure: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    // rather than opening new bins; when few open, opening is cheaper.
    let open_pressure = (open_bins_count as f64).sqrt() * 1.5;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; discount when item is large
        score += 10.0 + open_pressure - 0.05 * item_size as f64;
    } else {
        score -= open_pressure * 0.5;
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_fit = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - gap_fit / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // next item cannot use the leftover; penalize leaving a stranded gap
        score += 4.0;
    }

    // Progress scaling: early in the stream, be more willing to open bins;
    // late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 2.0 * (bin_residual == bin_capacity) as i32 as f64;
    score -= progress * 5.0 * (bin_residual != bin_capacity) as i32 as f64;

    // Mean residual coupling: if this bin's residual is far below mean, it's a
    // laggard bin that should be drained first.
    let dev = mean_residual - post_residual as f64;
    score += 0.1 * dev;

    score
}

