            // next item won't fit: penalize wasted capacity
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.35;
        }
    }

    // Tightness of current fit relative to mean residual across open bins
    let tightness = post_residual as f64 - mean_residual;
    score += tightness * 0.5;

    // Penalize large dead space relative to capacity
    score += (post_residual as f64 / bin_capacity as f64) * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is very poor
    if bin_residual == bin_capacity {
        score += 12.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 20.0; // lookahead match exists elsewhere -> prefer open bins
