    }

    // Early stream: be slightly greedy about tight fits; late stream: consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

