    }

    // Late-stream small-residual refinement.
    if progress > 0.85 && pr > 0 && pr <= 2 {
        score -= 21.0;
    }
    if progress > 0.8 && pr > 0 {
        score += (pr as f64) * (progress - 0.8) * 1.9;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: penalize wasted residual, quadratically coupled with stream progress
    let mut score = post * (1.0 + 1.5 * progress * progress);

    // Reward tight fits: sharp non-linear bonus as post_residual approaches zero
    let tightness = 1.0 - (post / cap);
    score -= 12.0 * tightness * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items
    if post > 0.0 {
        let useless = (1.0 - post / cap).min(1.0);
        score += 6.0 * (post / cap) * (1.0 - useless) * (1.0 - progress);
    }

    // Lookahead coupling: reward residual that fits the next item, penalize near-miss residuals
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let fit_quality = 1.0 - (post - nxt) / cap;
            score -= 8.0 * fit_quality * fit_quality;
        } else {
            let miss = (nxt - post) / cap;
            score += 4.0 * miss * (1.0 - progress);
        }
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Mild penalty for spreading across too many open bins relative to mean residual
    score += 0.05 * (open_bins_count as f64) * (1.0 - post / cap);

    // New-bin candidate: penalize opening a new bin unless progress is low or fit is bad
    if bin_residual == bin_capacity {
        score += 10.0 * progress + 0.3 * (post / cap) * (open_bins_count as f64);
    }

    // Smooth interaction of item size with residual balance
    let size_frac = item_size as f64 / cap;
    score -= 3.0 * size_frac * (1.0 - (post / cap)) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: capacity divided into octiles.
    // Residuals in the "unusable sliver" class (1..=10) are dead space -> penalize.
    let octile = (post_residual * 8) / bin_capacity; // 0..=7 integer division class
    match octile {
        0 => score += 45.0,                       // dead sliver, wasted bin space
        1 => score -= 12.0,                       // near-perfect fit, reward
        2 => score -= 18.0,                       // excellent fit
        3 => score -= 8.0,                        // good fit
        4 => score -= 2.0,                        // half-full, neutral
        5 => score += 3.0,
        6 => score += 6.0,
        _ => score += 10.0,                       // very roomy bin, low priority
    }

    // Modulo-10 harmonic class of post_residual: residuals congruent to small
    // values mod 10 pair poorly with typical item granules.
    let m = post_residual % 10;
    if m != 0 && m <= 3 {
        score += 7.0;                             // awkward remainder class
    } else if m == 0 {
        score -= 5.0;                             // round residual, reusable
    }

    // Lookahead coupling: if the next item fits the post-residual exactly or well,
    // strongly reward; if it just barely doesn't, penalize slightly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 25.0;                    // perfect chain fit
            } else if gap <= 5 {
                score -= 14.0;
            } else if gap <= 15 {
                score -= 6.0;
            }
        } else {
            let over = next_item_size - post_residual;
            if over <= 10 {
                score += 8.0;                     // next item nearly fits, tempting but wasteful
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: opening a fresh bin is only attractive when all open bins
    // fit poorly (post_residual small relative to item) or few bins are open.
    if bin_residual == bin_capacity {
        score = 55.0
            + 0.15 * open_bins_count as f64
            - 0.10 * mean_residual
            + (step_index as f64 / total_items.max(1) as f64) * 5.0;
        if fitting_bins_count == 0 {
            score -= 100.0;                       // nothing fits anywhere: must open
        }
        return score;
    }

    // Late in the stream, consolidate aggressively: favor bins below mean residual
    // (filling down) to close bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.10 * (mean_residual - bin_residual as f64) * (1.0 - progress);

    score
}

