    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is smaller than the minimum plausible item (1..100 interface,
    // but keep a conservative small-gap threshold around 10).
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 10.0 {
        score += 25.0 * (10.0 - gap);
    }

    // Reward tight fits (small post_residual relative to capacity) with a non-linear bonus.
    score -= 30.0 * (1.0 - gap / bin_capacity as f64).powi(4);

    // Open-bin pressure: prefer existing bins when many bins are already open.
    score += 3.0 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: make an empty bin attractive only when the
    // current item would leave a bad fit elsewhere or lookahead suggests a
    // large item better suited to a fresh bin.
    if bin_residual == bin_capacity {
        // Default slight penalty: reusing bins is generally preferred.
        score += 15.0;
