        if (mean_residual - item_size as f64).abs() > 25.0 {
            score -= 10.0;
        }
    }

    // Lookahead coupling: if the post-fit residual can host the next item, reward.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
