                score -= 40.0;
            } else {
                // Reward closeness of next item to leftover
                score -= 15.0 * (1.0 - gap / cap).max(0.0);
            }
        } else {
            // Next item won't fit here; penalize proportionally to wasted potential
            score += 8.0 * (1.0 - post / cap);
        }
    }

    // Compare against mean residual across open bins:
    // favor bins with residual far below average (already tight bins)
    let dev = mean_residual - post;
    score -= 0.3 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize creating dead space below smallest plausible item
    if post > 0.0 && post < 10.0 {
        score += 12.0;
    }

    // Early in stream: slightly prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
