    // New-bin candidate: penalize mildly so only genuinely bad fits
    // trigger opening a new bin (empty bin has post == cap).
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if no tight lookahead match exists, opening fresh is fine:
        if next_item_size > 0 && post >= next_item_size as f64 {
            score -= 10.0;
        }
    }

    score
}

