    } else if pr <= 5 {
        score -= 134.0;
    } else if pr <= 16 {
        score -= 86.0;
    } else if pr <= 40 {
        score -= 16.0;
    } else if pr <= 66 {
        score -= 4.0;
    }

    // Dead-space penalty for residuals too small for typical items.
    if pr > 0 && pr < 20 {
        score += (20.0 - pr as f64) * (20.0 - pr as f64) * 0.58;
    }

    // Two-step lookahead: exact pair fill is excellent; proportional waste reward otherwise.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 350.0;
        } else if next_item_size + 1 == pr {
            score -= 195.0;
        } else if next_item_size <= pr {
            let waste = (pr - next_item_size) as f64;
            score -= waste * 2.4;
            if (waste as u32) % 10 == 0 {
