    if dead > 0.0 {
        let dead_frac = dead / capf;
        if next_item_size > 0 && dead < nf {
            score += 12.0 + dead * 0.18 + (nf - dead) * 0.95;
        } else if next_item_size > 0 && dead as u32 == next_item_size {
            score -= 55.0;
        } else {
            let rem_frac = (1.0 - progress).min(1.0);
