        // Wide pockets that can host half of next item: keep them.
        if dead_frac >= 0.55 && dead_frac < 0.75 && next_item_size > 0 && nf <= dead * 0.5 {
            score -= 6.5 * dead_frac * (1.0 - progress);
        }
        // Mid-range dead-space bump: penalize awkward pockets.
        if dead_frac > 0.1 && dead_frac < 0.45 {
