        }
        if dead_frac > 0.3 && progress > 0.6 {
            score += dead_frac * (progress - 0.6) * 32.0;
        }
        // Small usable pockets late in stream are worth keeping.
        if dead_frac > 0.05 && dead_frac < 0.25 && progress > 0.35 {
            score += dead_frac * (progress - 0.35) * 23.0;
        }
        if next_item_size > 0 && dead > nf && dead <= nf + 3.0 {
            score -= 18.0 * (1.0 - progress);
        }
        // Dead space exactly divisible by next item is reusable.
        if next_item_size > 0 && (dead as u32) % next_item_size == 0 && dead >= nf && dead <= 2.0 * nf {
            score -= 13.0 * (1.0 - progress);
        }
        // Combined: dead fits next item exactly with margin.
        if next_item_size > 0 && dead >= nf && dead <= 1.5 * nf && progress > 0.5 {
            score -= 9.0 * (1.0 - progress);
        }
        if dead_frac >= 0.45 && dead_frac <= 0.5 && next_item_size > 0 && nf >= dead * 0.5 && nf <= dead {
            score -= 11.0 * (1.0 - progress);
        }
        // Dead space fits two next-items: reusable pocket.
        if next_item_size > 0 && dead >= 2.0 * nf && dead <= 2.5 * nf && progress > 0.45 {
            score -= 7.0 * (1.0 - progress);
        }
        if next_item_size > 0 && dead_frac < 0.12 && dead >= nf {
            score -= 5.0 * (1.0 - dead_frac / 0.12) * (1.0 - progress);
        }
        // Mean residual comparison for pocket utility.
        if dead_frac > 0.15 && mean_residual > dead && dead > 0.0 {
            score += (mean_residual - dead).min(40.0) * 0.09 * (1.0 - progress);
        }
        // Dead hosts two copies of next item cleanly.
        if next_item_size > 1 && dead as u32 >= 2 * next_item_size && (dead as u32) % next_item_size == 0 {
            score -= 8.0 * (1.0 - progress);
        }
        // Gap above next item scales with tightness.
        if next_item_size > 0 && dead > nf && dead <= nf + 6.0 {
            let gap = dead - nf;
            score += gap * (1.6 + 0.9 * gap) * (1.0 - progress);
        }
        // Dead can host next item plus a mean-residual pocket.
        if next_item_size > 0 && dead >= nf + mean_residual.min(nf) && dead <= nf + nf {
            score -= 16.0 * (1.0 - progress);
        } else if next_item_size > 0 && dead > nf && dead < nf + 2.0 {
            score -= 8.0;
