    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    score -= bin_pressure * 2.2 * (1.0 - progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 52.0;
    }

    // Mean-residual anchoring, stronger later in the stream.
    score -= (0.40 + 0.17 * progress) * (mean_residual - pr as f64);

