            score -= 34.0;
        } else {
            score += 38.0 + 1.5 * bin_pressure;
        }
        if fitting_bins_count > 1 && progress > 0.5 {
            score += 26.0;
        }
        // Large items fragment open bins; better to open fresh for them.
        if item_size as f64 > 0.6 * capf {
            score -= 13.0;
        }
        if next_item_size > 0 && (item_size as f64 + nf) > capf {
