        if fitting_bins_count > 2 && mean_residual > 0.55 * capf {
            score += 7.5 * (1.0 - progress);
        }
        // Mean residual can host item+next pair; prefer existing bin.
        if next_item_size > 0 && mean_residual >= nf && mean_residual < (item_size as f64 + nf).min(capf) {
            score -= 6.5 * (1.0 - progress);
        }
