        }
        // Next item large and mean residual generous: don't open fresh.
        if next_item_size > 0 && nf > 0.5 * capf && mean_residual > 0.3 * capf {
            score -= 10.5;
        }
        // Poor fits available: fresh bin attractive.
        if fitting_bins_count > 1 && mean_residual < item_size as f64 * 0.4 {
            score += 12.0;
        }
        // Fragmenting a wide-open bin for a large item when a deep pocket exists elsewhere.
        if fitting_bins_count > 1 && dead > 0.35 * capf && item_size as f64 > mean_residual * 1.25 {
            score -= 11.0 * (1.0 - progress);
        }
        // Large item whose complement is below next item -> fresh bin pairs better.
