    }
    // pr + dead together can't host next item -> wasted pocket.
    if pr > 0 && dead > 0.0 && next_item_size > 0 && (pr as f64 + dead) <= nf && progress > 0.3 {
        score += 8.7 * (1.0 - progress);
    }
    // Very small pr with alternatives available.
    if pr > 0 && (pr as f64) < 0.06 * capf && fitting_bins_count > 2 {
        score += 5.0 * (1.0 - progress);
    }
    // pr exactly divisible by next item is reusable.
    if pr > 0 && next_item_size > 0 && (pr as u32) % next_item_size == 0 && pr >= next_item_size {
        score -= 6.2 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 60.0 * fill_ratio * fill_ratio;

    // Penalize leaving small unusable slivers (dead space) after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    } else if post_residual < 20 {
        score += 12.0 * (20 - post_residual) as f64 / 10.0;
    }

    // Lookahead coupling: reward residuals that can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Post residual too small for next item: mild penalty scaled by wasted fraction.
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, heavily favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // Many open bins: encourage consolidating into existing bins rather than spreading.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64).sqrt();
    score -= 15.0 * pressure * fill_ratio;

    // Mean-residual coupling: prefer bins below mean residual (denser bins) when pressure is high.
    if mean_residual > 0.0 {
        let rel = bin_residual as f64 / mean_residual;
        if rel < 1.0 {
            score -= 10.0 * (1.0 - rel);
        } else {
            score += 6.0 * (rel - 1.0);
        }
    }

    // Time horizon: early in the stream, allow more exploration (mild new-bin tolerance);
    // late in the stream, be conservative and pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * (1.0 - progress) * fill_ratio;
    score += 25.0 * progress * (1.0 - fill_ratio);

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else {
            // Compare best possible fit quality among open bins via mean residual.
            (1.0 - (mean_residual / bin_capacity as f64)).clamp(0.0, 1.0)
        };
        score = bin_capacity as f64 - 40.0 * desperation * (1.0 - progress) - 20.0 * desperation * progress;
        // Penalize opening new bins when many bins are already open.
        score += 5.0 * (open_bins_count as f64).ln().max(0.0);
        // If next item is large, a fresh bin is more valuable.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    score
}

