pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common
    // item sizes (or small enough to be "dead") deserve special treatment.
    let r = post_residual;
    let cap = bin_capacity as f64;

    // Dead-space penalty: residual too small for the smallest plausible item.
    if r > 0 && r < 10 {
        score += 40.0;
    }

    // Reward residuals that are exactly reusable by the lookahead item.
    if next_item_size > 0 && r >= next_item_size {
        // Harmonic fit classes: residual mod next_item_size near 0 is great.
        let m = (r % next_item_size) as f64;
        score -= 12.0 * (1.0 - m / next_item_size as f64);
    } else if next_item_size > 0 && r > 0 {
        // Residual cannot host the next item: penalize proportionally.
        score += 8.0 * (1.0 - r as f64 / cap);
    }

    // Modulo arithmetic on capacity fractions: residuals in "nice" classes
    // (multiples of 10 or 25) are more likely reusable.
    if r % 10 == 0 && r > 0 {
        score -= 6.0;
    }
    if r % 25 == 0 && r > 0 {
        score -= 4.0;
    }

    // Integer division thresholds: classify residual into thirds of capacity.
    let third = bin_capacity / 3;
    if r <= third {
        score += 10.0; // tiny leftover, likely waste
    } else if r <= 2 * third {
        score -= 3.0; // mid-range, moderately useful
    } else {
        score -= 8.0; // large residual, bin stays flexible
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is
    // huge relative to capacity (poor fit everywhere) or many bins are open.
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size * 4 >= bin_capacity * 3 {
            score -= 35.0; // big item: fresh bin is fine
        }
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        score += 2.0 * open_bins_count as f64;
    }

    // Slight preference for fuller bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space): residuals that are too small
    // for even the smallest plausible item are wasted capacity.
    let dead_threshold: u32 = 12;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 6.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += 4.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize the empty new-bin candidate more when open_bins_count is already high).
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * open_bins_count as f64;
    }

    // Mean residual coupling: bins far below mean residual are less attractive
    // when mean residual is small (few bins, tight packing); encourage balanced use.
    let dev = mean_residual - post_residual as f64;
    score += 0.3 * dev;

    // Slight time pressure: later in the stream, favor tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progression factor: pack tighter as stream advances.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tight = 1.0 + 2.0 * progress;

    // Aggressive 2-step lookahead: perfect match with next item is gold.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0 + 20.0 * progress; // exact 2-item fill
        } else {
            let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
            // Penalize mismatch; small gaps still good, huge gaps waste space.
            score += gap * 0.35 * tight;
            // Bonus if next item still fits afterwards.
            if post_residual >= next_item_size {
                score -= 8.0;
            }
        }
    }

    // Reward being below mean residual (tighter than average bin).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Penalize unusable dead space (too small for smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New empty bin candidate: penalize unless item is large relative to capacity
    // or no existing bin offers a decent fit signal.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score = bin_capacity as f64 * 0.6 - fill_ratio * 30.0;
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a new bin anyway
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // new bin can host both items
        }
    }

    // Slight preference for fewer open bins (consolidation).
    score += open_bins_count as f64 * 0.05;

    score
}

