            score -= waste * 2.4;
            if (waste as u32) % 10 == 0 {
                score -= 25.0;
            }
        } else {
            let miss = (next_item_size - pr) as f64;
            score += miss.min(50.0) * 0.7 + 7.5;
        }
    }

    let dead = bin_residual as f64 - item_size as f64;
    if dead > 0.0 {
        let dead_frac = dead / capf;
        if next_item_size > 0 && dead < nf {
            score += 12.0 + dead * 0.18 + (nf - dead) * 0.95;
        } else if next_item_size > 0 && dead as u32 == next_item_size {
            score -= 55.0;
        } else {
            let rem = if total_items > step_index { (total_items - step_index) as f64 } else { 0.0 };
            let rem_frac = (rem / total_items.max(1) as f64).min(1.0);
            score -= dead * (0.06 + 0.05 * rem_frac) + dead_frac * dead_frac * 46.0;
        }
        if dead < 0.05 * capf && open_bins_count > 2 {
            score += 5.0 * (1.0 - dead / (0.05 * capf));
        }
        if dead > 0.0 && dead < 4.0 && pr > 4 {
            score += 14.0;
        }
        if dead_frac > 0.2 && dead_frac < 0.55 {
            score += dead_frac * (1.0 - progress) * 18.0;
        }
        // Wide dead space that next item cannot use: penalize.
        if dead_frac > 0.55 && next_item_size > 0 && nf > dead {
            score += 9.5 * dead_frac;
        }
        // Wide dead space that next item can halve into: reward.
        if dead_frac >= 0.55 && dead_frac < 0.75 && next_item_size > 0 && nf <= dead * 0.5 {
            score -= 6.5 * dead_frac * (1.0 - progress);
        }
        if dead_frac > 0.1 && dead_frac < 0.45 {
            let bump = (dead_frac - 0.275) * (dead_frac - 0.275);
            score += bump * 28.0 * (0.4 + 0.6 * (1.0 - progress));
        }
        // After-next-item leftover shaping.
        if next_item_size > 0 && dead as u32 >= next_item_size {
            let after = dead as u32 - next_item_size;
            if after == 0 || after <= 2 {
                score -= 24.0;
            } else if after as f64 <= 0.04 * capf {
                score -= 10.0;
            }
        }
        if dead_frac > 0.3 && progress > 0.6 {
            score += dead_frac * (progress - 0.6) * 32.0;
        }
        // Small usable pockets late in stream are worth keeping.
        if dead_frac > 0.05 && dead_frac < 0.25 && progress > 0.35 {
            score += dead_frac * (progress - 0.35) * 23.0;
        }
        if next_item_size > 0 && dead > nf && dead <= nf + 3.0 {
            score -= 18.0 * (1.0 - progress);
        }
        // Dead space exactly divisible by next item is reusable.
        if next_item_size > 0 && (dead as u32) % next_item_size == 0 && dead >= nf && dead <= 2.0 * nf {
            score -= 13.0 * (1.0 - progress);
        }
        if next_item_size > 0 && dead >= nf && dead <= 1.5 * nf && progress > 0.5 {
            score -= 9.0 * (1.0 - progress);
        }
        if dead_frac >= 0.45 && dead_frac <= 0.5 && next_item_size > 0 && nf >= dead * 0.5 && nf <= dead {
            score -= 11.0 * (1.0 - progress);
        }
        // Dead space fits two next-items: reusable pocket.
        if next_item_size > 0 && dead >= 2.0 * nf && dead <= 2.5 * nf && progress > 0.45 {
            score -= 7.0 * (1.0 - progress);
        }
        if next_item_size > 0 && dead_frac < 0.12 && dead >= nf {
            score -= 5.0 * (1.0 - dead_frac / 0.12) * (1.0 - progress);
        }
        // Mean residual comparison for pocket utility.
        if dead_frac > 0.15 && mean_residual > dead && dead > 0.0 {
            score += (mean_residual - dead).min(40.0) * 0.09 * (1.0 - progress);
        }
        // Dead hosts two copies of next item cleanly.
        if next_item_size > 1 && dead as u32 >= 2 * next_item_size && (dead as u32) % next_item_size == 0 {
            score -= 8.0 * (1.0 - progress);
        }
        // Gap above next item scales with tightness.
        if next_item_size > 0 && dead > nf && dead <= nf + 6.0 {
            let gap = dead - nf;
            score += gap * (1.6 + 0.9 * gap) * (1.0 - progress);
        }
        // Dead can host next item plus a mean-residual pocket.
        if next_item_size > 0 && dead >= nf + mean_residual.min(nf) && dead <= nf + nf {
            score -= 16.0 * (1.0 - progress);
        } else if next_item_size > 0 && dead > nf && dead < nf + 2.0 {
            score -= 8.0;
        }
        // Tiny dead pockets next item cannot use.
        if dead_frac > 0.02 && dead_frac < 0.08 && next_item_size > 0 && nf > dead {
            score += (0.08 - dead_frac) * 30.0 * (1.0 - progress);
        }
    }

    // Pair-fill reward when bin can host item + next item together.
    if next_item_size > 0 {
        let pair = item_size as f64 + nf;
        if bin_residual as f64 >= pair {
            let slack = bin_residual as f64 - pair;
            score -= 40.0 - (slack / capf) * 30.0;
        }
        if pr > 0 && (pr as f64) >= nf && (pr as f64) < nf + 4.0 {
            score -= 14.0 * (1.0 - progress);
        }
    }

    // Consolidation pressure when many bins are open, stronger early.
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    score -= bin_pressure * 1.8 * (1.0 - progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 52.0;
    }

    // Mean-residual anchoring, stronger later in the stream.
    score -= (0.40 + 0.17 * progress) * (mean_residual - pr as f64);

    // Residual-vs-mean-ratio shaping: prefer post residual near fleet mean.
    if pr > 0 {
        let dev = ((pr as f64) - mean_residual).abs() / capf;
        score += dev * 7.0 * (1.0 - progress);
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let next_tight = next_item_size > 0 && mean_residual < nf;
        if next_tight || fitting_bins_count <= 1 {
            score -= 34.0;
        } else {
            score += 38.0 + 1.5 * bin_pressure;
        }
        if fitting_bins_count > 1 && progress > 0.5 {
            score += 26.0;
        }
        // Large items fragment open bins; better to open fresh for them.
        if item_size as f64 > 0.6 * capf {
            score -= 13.0;
        }
        if next_item_size > 0 && (item_size as f64 + nf) > capf {
            score -= 17.0;
        }
        if item_size as f64 > 0.78 * capf && mean_residual < 0.22 * capf {
            score -= 27.0;
        }
        if item_size as f64 > 0.85 * capf && mean_residual < 0.12 * capf {
            score -= 32.0;
        }
        if item_size as f64 > 0.93 * capf {
            score -= 21.0;
        }
        if progress > 0.7 && open_bins_count > 3 {
            score += 19.0 * progress;
        }
        if next_item_size > 0 && nf > mean_residual {
            score -= 6.0 + (nf - mean_residual) * 0.13;
        }
        let spread = (mean_residual - item_size as f64).abs();
        if spread < 0.08 * capf && fitting_bins_count > 2 {
            score += 9.5;
        }
        if item_size as f64 > mean_residual * 1.6 && fitting_bins_count > 1 && open_bins_count > 2 {
            score -= 15.0 * (1.0 - progress);
        }
        let rem_items = if total_items > step_index { (total_items - step_index) as f64 } else { 0.0 };
        if rem_items > 0.15 * total_items.max(1) as f64 && mean_residual < 0.5 * (next_item_size.max(1) as f64) {
            score -= 15.0 * (1.0 - progress);
        }
        // With many open bins and generous mean residual, fresh bin is wasteful.
        if fitting_bins_count > 2 && mean_residual > 0.55 * capf {
            score += 7.5 * (1.0 - progress);
        }
        // Mean residual can host item+next pair; prefer existing bin.
        if next_item_size > 0 && mean_residual >= nf && mean_residual < (item_size as f64 + nf).min(capf) {
            score -= 6.5 * (1.0 - progress);
        }
        // Next item nearly fills mean residual; don't fragment.
        if next_item_size > 0 && nf > mean_residual * 0.85 && nf <= mean_residual && progress > 0.4 {
            score -= 8.0 * (1.0 - progress);
        }
        // Next item large and mean residual generous: don't open fresh.
        if next_item_size > 0 && nf > 0.5 * capf && mean_residual > 0.3 * capf {
            score -= 10.5;
        }
        // Poor fits available: fresh bin attractive.
        if fitting_bins_count > 1 && mean_residual < item_size as f64 * 0.4 {
            score += 12.0;
        }
        // Fragmenting a wide-open bin for a large item when a deep pocket exists elsewhere.
        if fitting_bins_count > 1 && dead > 0.35 * capf && item_size as f64 > mean_residual * 1.25 {
            score -= 11.0 * (1.0 - progress);
        }
        // Large item whose complement is below next item -> fresh bin pairs better.
        if next_item_size > 0 && item_size as f64 > 0.55 * capf && (capf - item_size as f64) < nf && fitting_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 24.0 * (1.0 - progress);
        }
        // Fresh bin leaves exact next-item complement.
        if next_item_size > 0 && pr > 0 && pr == next_item_size && fitting_bins_count > 0 {
            score -= 12.0 * (1.0 - progress);
        }
        // Mean residual just above next item; existing bins can absorb it.
        if next_item_size > 0 && fitting_bins_count > 0 && mean_residual >= nf && mean_residual < nf + 5.0 {
            score -= 9.0 * (1.0 - progress);
        }
        if open_bins_count > 4 && fitting_bins_count > 1 && mean_residual > 0.45 * capf {
            score += 5.0 * progress;
        }
    }

    // Usable-pocket bonus: residual after placement that can host next item tightly.
    if next_item_size > 0 && pr >= next_item_size && pr - next_item_size > 0 && (pr - next_item_size) < item_size.max(next_item_size) {
        score -= 16.0;
    }

    // Penalize leaving residual that next item cannot use, but only if small.
    if next_item_size > pr && pr > 0 && pr < 30 {
        score += 8.0;
    }

    // Usable-floor bonus: post residual above next-item floor is worth keeping.
    if pr > 0 {
        let usable_floor = (next_item_size.max(1) as f64).min(0.35 * capf);
        if (pr as f64) >= usable_floor {
            score -= 8.5 * (1.0 - progress) * ((pr as f64) / capf);
        }
    }
    if pr > 0 && (pr as f64) < 0.5 * (next_item_size.max(1) as f64) && fitting_bins_count > 1 {
        score += 6.5 * (1.0 - progress);
    }

    // Late-stream fine finishing: reward near-exact closes.
    if progress > 0.85 && pr <= 2 && pr > 0 {
        score -= 21.0;
    }
    if progress > 0.8 && pr > 0 {
        score += (pr as f64) * 0.38 * (progress - 0.8) * 5.0;
    }

    // Tiny post-residual with many fitting bins is wasteful fragmentation.
    if pr > 0 && fitting_bins_count > 1 && (pr as f64) < 0.1 * capf && next_item_size > 0 && nf > pr as f64 {
        score += 4.5 * (1.0 - progress);
    }
    // pr + dead together can't host next item -> wasted pocket.
    if pr > 0 && dead > 0.0 && next_item_size > 0 && (pr as f64 + dead) <= nf && progress > 0.3 {
        score += 8.7 * (1.0 - progress);
    }
    // Very small pr with alternatives available.
    if pr > 0 && (pr as f64) < 0.06 * capf && fitting_bins_count > 2 {
        score += 5.0 * (1.0 - progress);
    }
    // pr exactly divisible by next item is reusable.
    if pr > 0 && next_item_size > 0 && (pr as u32) % next_item_size == 0 && pr >= next_item_size {
        score -= 6.2 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 24.0 * fit_ratio * fit_ratio;

    // Penalize small dead space left after placement (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 14.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 5.0;
    }

    // Lookahead: reward if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use this residual; mild penalty proportional to waste.
            score += 3.0 * (1.0 - (post_residual as f64 / next_item_size as f64)).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Global state: when many bins are open with high mean residual,
    // prefer consolidating into existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate score: base cost plus pressure terms.
        score = bin_capacity as f64 * 0.9;
        score += open_bins_count as f64 * 1.5;
        score += mean_residual * 0.4;
        score -= 20.0 * progress; // late in the stream, new bins are slightly cheaper to justify
        if fitting_bins_count == 1 {
            score += 25.0; // discourage abandoning a last-chance bin
        }
    } else {
        // Favor bins with residual close to the mean (balanced packing),
        // penalize outliers that would strand capacity.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
        score += open_bins_count as f64 * 0.3 * (1.0 - fit_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
