            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fitting_bins_count > 0 && mean_residual >= next_item_size as f64 && mean_residual < next_item_size as f64 + 5.0 {
            score -= 9.0 * (1.0 - progress);
        }
        // Borrowed: next item fits mean residual but not item+next combined.
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && mean_residual < (item_size as f64 + next_item_size as f64).min(capf) {
            score -= 6.5 * (1.0 - progress);
        }
        // Borrowed: large dead space in a fitting bin with oversized item.
        if fitting_bins_count > 1 && dead as f64 > 0.35 * capf && item_size as f64 > mean_residual * 1.25 {
            score -= 11.0 * (1.0 - progress);
        }
    }

    // Usable-pocket bonus: residual after placement that can host next item tightly.
    if next_item_size > 0 && pr >= next_item_size && pr - next_item_size > 0 && (pr - next_item_size) < item_size.max(next_item_size) {
        score -= 15.0;
    }

    // Penalize leaving residual that next item cannot use, but only if small.
    if next_item_size > pr && pr > 0 && pr < 30 {
        score += 8.0;
    }
    if pr > 0 && (pr as f64) < 0.5 * (next_item_size.max(1) as f64) && fitting_bins_count > 1 {
        score += 6.5 * (1.0 - progress);
    }
    if pr > 0 && (pr as f64) < 0.06 * capf && fitting_bins_count > 2 {
        score += 5.0 * (1.0 - progress);
    }
    if pr > 0 && fitting_bins_count > 1 && (pr as f64) < 0.1 * capf && next_item_size > 0 && (next_item_size as f64) > pr as f64 {
        score += 4.5 * (1.0 - progress);
    }

    // Late-stream small-residual refinement.
    if progress > 0.85 && pr > 0 && pr <= 2 {
        score -= 21.0;
    }
    if progress > 0.8 && pr > 0 {
        score += (pr as f64) * (progress - 0.8) * 1.9;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer tight fits (small post_residual), with non-linear shaping.
    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, mildly favor leaving medium space; late, strongly favor tight fits.
    let progress_coupling = x * (1.0 - x) * 4.0; // peaks at x=0.5
    score += progress_coupling * (30.0 * (1.0 - progress) - 10.0);

    // Penalize large dead space quadratically, scaled by progress.
    score += (x * x) * 40.0 * (0.5 + progress);

    // Reward bins whose residual matches the next item size (smooth Gaussian-like term).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt) / cap;
        score -= 25.0 * (-(diff * diff) * 200.0).exp();
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 35.0 + 20.0 * progress;
    } else if fitting_bins_count > 1 {
        // Slight penalty when many alternatives exist, scaled by fit quality.
        score += (fitting_bins_count as f64).ln() * 3.0 * x;
    }

    // Penalize bins far from the mean residual (encourage balanced residual profile),
    // with a smooth non-linear saturating term.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * (dev * dev).tanh();

    // Mild preference for consolidating into fewer bins as stream progresses.
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - x) * 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space that is a multiple of common
    // item sizes (or their complements) is more reusable than arbitrary slack.
    let cap = bin_capacity as f64;

    // Fractional fill of the bin after placement.
    let fill_frac = 1.0 - (post_residual as f64) / cap;
    score -= 40.0 * fill_frac * fill_frac; // reward high fill, superlinear

    // Harmonic classes: post_residual divisible by small item sizes is "friendly"
    // residual space. Penalize awkward residuals (prime-like, mid-range).
    if post_residual > 0 {
        let pr = post_residual;
        let mut friendly = 0u32;
        if pr % 10 == 0 { friendly += 2; }
        if pr % 20 == 0 { friendly += 2; }
        if pr % 25 == 0 { friendly += 1; }
        if pr % 50 == 0 { friendly += 2; }
        score -= 6.0 * friendly as f64;

        // Mid-range dead zones (31..49 and 51..69) are hard to fill later.
        let cls = pr / 10;
        if cls >= 3 && cls <= 6 {
            score += 8.0;
        }
    } else {
        score -= 25.0; // perfect fit is excellent
    }

    // Lookahead: if next item fits into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 15.0 + 0.2 * slack as f64;
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize more if residual is near-but-below.
        let gap = next_item_size - post_residual;
        if gap <= 10 {
            score += 6.0 + gap as f64;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin residual is truly bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, reduced when many bins are open and mean
        // residual is fragmented.
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 - 20.0 * fragmentation - 15.0 * progress;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative
        }
    }

    // Mild preference to keep number of open bins from exploding early.
    score += 0.5 * open_bins_count as f64 * (1.0 - fill_frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - post_residual as f64) * 12.0;
    }
    // Medium gaps are moderately penalized since few item sizes can use them.
    else if post_residual > 10 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 3.0;
    }

    // Reward near-perfect fits (very low post_residual waste relative to capacity).
    if post_residual == 0 {
        score -= 40.0;
    } else if item_size as f64 / bin_capacity as f64 > 0.85 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation into existing bins
    // (penalize the empty new-bin candidate).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 5.0 + progress * 20.0;
    } else {
        score -= open_bins_count as f64 * 2.0;
    }

    // Lookahead: if the next item fits the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item is large and would not fit anywhere after this placement,
    // slightly favor bins with more room left.
    if next_item_size > post_residual && next_item_size > 50 {
        score += post_residual as f64 * 0.3;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect match: post residual exactly equals the next item's size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item also fits after this placement: strong lookahead reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + (post_residual - next_item_size) as f64 * 0.15;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space that the next item cannot use: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Prefer tighter fits relative to mean residual across open bins.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a brand-new bin when other bins can fit the item.
    if bin_residual == bin_capacity {
        score += 70.0;
        // But if no open bin fits, opening is the only option: soften penalty.
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
        // Late in the stream, avoid leaving a nearly-empty new bin.
        if step_index as f64 / total_items.max(1) as f64 > 0.8 {
            score += 10.0;
        }
    }

    // Mild preference for compacting bins with low residual early on.
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 30 {
        score += 6.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize wasting residual.
            score += 4.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Many open bins with slack: prefer consolidating into fuller bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if (bin_residual as f64) > mean_residual {
        score += 3.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64 * (1.0 + progress);
    }

    // New-bin candidate: allow opening a new bin only when current fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 30.0;
        // More attractive early in the stream (future flexibility worth more).
        score -= 20.0 * (1.0 - progress);
        // Very attractive if no open bin fits well (post_residual would be bad elsewhere).
        if next_item_size > 0 && post_residual >= next_item_size {
            // New bin also fits the next item comfortably.
            score -= 10.0;
        }
        // If many bins are open and this is the only fitting option, opening is fine.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
