    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bin fit is poor
    if bin_residual == bin_capacity {
        let tight = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score += 18.0;                 // default: prefer existing bins
        if post_residual > 40 || post_residual == 0 {
            score -= 22.0;             // but open fresh when this would waste/half-fill
