        // But if no existing bin leaves room for the next item, new bin is fine.
        if next_item_size > 0 && post_residual == bin_capacity {
            score -= 5.0;
        }
    }

    // Mild penalty for deviating from mean residual (avoid fragmentation drift).
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
