pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * tightness * tightness * item_size as f64;

    // Penalize dead space: residuals too small to hold the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this bin strongly.
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 8.0 + 0.5 * next_item_size as f64;
        } else {
            // Post-residual unusable for the next item: mild penalty scaled by wasted fraction.
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: pure tightness, no future to plan for.
        score -= 5.0 * tightness;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual < 10 {
            score += 10.0; // still avoid extreme fragmentation
        }
    }

    // New-bin candidate handling: make an empty bin moderately attractive only when
    // open bins are fragmented or the fit elsewhere is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; decreases as stream progresses (sunk planning).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
