        // If many bins are open and mean residual is high, prefer reusing them.
        score += 0.3 * open_bins_count as f64 + 0.4 * mean_residual;
        // If the next item is large, a fresh bin is valuable.
        if next_item_size >= 50 {
            score -= 10.0;
        }
        // Last chance: never prefer a new bin when only one bin fits.
        if fitting_bins_count == 1 {
            score += 40.0;
        }
    }

    // Global fragmentation pressure: when mean residual is low overall, squeeze
    // existing bins harder (favor bins below the mean residual).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.5 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // Mild bonus for bins that leave residual matching common item sizes (multiples of 10).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Reward tight fits: subtract a smooth quadratic of normalized fill.
    let fill = 1.0 - pr / cap;
    score -= 12.0 * fill * fill;

    // Penalize large residuals that waste capacity, scaled by stream progress
    // (late in the stream, dead space is more costly).
    score += pr * pr / cap * (0.4 + 1.2 * progress);

    // Lookahead: reward leaving room for the next item, penalize blocking it.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack_fit = 1.0 - ((pr - ni) / cap).min(1.0);
            score -= 6.0 * slack_fit * slack_fit;
        } else {
            score += 4.0 * (ni - pr) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: make empty bin attractive only when open-bin fits are poor
    // (large post_residual elsewhere or many open bins with fragmented space).
