        if open_bins_count > 0 && fitting_bins_count > 1 && progress > 0.5 {
            score += 26.0;
        }
        if item_size as f64 > 0.6 * capf {
            score -= 14.0;
        }
        if item_size as f64 > 0.78 * capf && mean_residual < 0.22 * capf {
            score -= 27.0;
        }
        if item_size as f64 > 0.85 * capf && mean_residual < 0.12 * capf {
            score -= 32.0;
        }
        if item_size as f64 > 0.93 * capf {
            score -= 21.0;
        }
        if next_item_size > 0 && (item_size as f64 + next_item_size as f64) > capf {
            score -= 17.0;
        }
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 6.0 + (next_item_size as f64 - mean_residual) * 0.13;
        }
        if progress > 0.7 && open_bins_count > 3 {
            score += 19.0 * progress;
        }
        let spread = (mean_residual - item_size as f64).abs();
        if spread < 0.08 * capf && fitting_bins_count > 2 {
            score += 9.5;
        }
        if item_size as f64 > mean_residual * 1.6 && fitting_bins_count > 1 && open_bins_count > 2 {
            score -= 15.0 * (1.0 - progress);
        }
        if fitting_bins_count > 1 && mean_residual < item_size as f64 * 0.4 {
            score += 12.0;
        }
        if next_item_size > 0 && next_item_size as f64 > 0.5 * capf && mean_residual > 0.3 * capf {
            score -= 10.5;
        }
        if next_item_size > 0 && item_size as f64 > 0.55 * capf && (capf - item_size as f64) < next_item_size as f64 && fitting_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 24.0 * (1.0 - progress);
        }
        let rem_items = if total_items > step_index { (total_items - step_index) as f64 } else { 0.0 };
        if rem_items > 0.15 * total_items.max(1) as f64 && mean_residual < 0.5 * (next_item_size.max(1) as f64) {
            score -= 15.0 * (1.0 - progress);
        }
        if fitting_bins_count > 2 && mean_residual > 0.55 * capf {
            score += 7.5 * (1.0 - progress);
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 0.85 && next_item_size as f64 <= mean_residual && progress > 0.4 {
            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fitting_bins_count > 0 && mean_residual >= next_item_size as f64 && mean_residual < next_item_size as f64 + 5.0 {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && mean_residual < (item_size as f64 + next_item_size as f64).min(capf) {
            score -= 6.5 * (1.0 - progress);
        }
        if fitting_bins_count > 1 && dead as f64 > 0.35 * capf && item_size as f64 > mean_residual * 1.25 {
            score -= 11.0 * (1.0 - progress);
        }
        if open_bins_count > 4 && fitting_bins_count > 1 && mean_residual > 0.45 * capf {
            score += 5.0 * progress;
        }
    }

    if next_item_size > 0 && pr >= next_item_size && pr - next_item_size > 0 && (pr - next_item_size) < item_size.max(next_item_size) {
        score -= 15.0;
    }

    if next_item_size > pr && pr > 0 && pr < 30 {
        score += 8.0;
    }
    if pr > 0 && (pr as f64) < 0.5 * (next_item_size.max(1) as f64) && fitting_bins_count > 1 {
        score += 6.5 * (1.0 - progress);
    }
    if pr > 0 && (pr as f64) < 0.06 * capf && fitting_bins_count > 2 {
        score += 5.0 * (1.0 - progress);
    }
    if pr > 0 && fitting_bins_count > 1 && (pr as f64) < 0.1 * capf && next_item_size > 0 && (next_item_size as f64) > pr as f64 {
        score += 4.5 * (1.0 - progress);
    }

    if progress > 0.85 && pr > 0 && pr <= 2 {
        score -= 21.0;
    }
    if progress > 0.8 && pr > 0 {
        score += (pr as f64) * (progress - 0.8) * 1.9;
    }

    // New: usable-residual floor reward borrowed from best heuristic.
    if pr > 0 {
        let usable_floor = (next_item_size.max(1) as f64).min(0.35 * capf);
        if (pr as f64) >= usable_floor {
            score -= 8.5 * (1.0 - progress) * ((pr as f64) / capf);
        }
    }
    // New: exact next-item post-residual match with fitting alternatives.
    if next_item_size > 0 && pr > 0 && pr == next_item_size && fitting_bins_count > 0 {
        score -= 12.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to be reliably usable
    // (below the minimum plausible item size band) are heavily penalized,
    // except a perfect fit (post_residual == 0) which is ideal.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0; // mild penalty for awkward mid-small gaps
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize so we only open a new bin when existing
    // fits are truly poor; penalty grows with wasted capacity for small items.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score += 18.0 + 0.35 * waste;
    }

    // Open-bins pressure: mild reward for consolidating into existing bins
    // (lower score for bins in a crowded field), discouraging bin sprawl.
    score += 0.05 * open_bins_count as f64;

    // Lookahead coupling: reward leaving a gap the next item can use;
    // penalize leaving a gap that strands the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 4.0;
        }
    } else {
        // Last item: perfect fits are maximally rewarded.
        if post_residual == 0 {
            score -= 15.0;
        }
    }

    // Prefer bins whose residual is close to the item (tight packing signal).
    score += 0.1 * ((bin_residual as f64 - item_size as f64).abs());

    score
}

