pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score as post_residual approaches 0.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 55.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items
    // (residual < 10 is useless; residual 10..40 has partial value).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // unusable sliver
    } else if post_residual < 40 {
        score += 0.35 * (40 - post_residual) as f64;
    }

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item can fit into the post-residual,
    // reward this bin; if not, penalize creating a blocking residual.
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
        // Bonus for chains: current + next exactly fill the bin.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    // before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: make an empty bin moderately attractive
    // only when existing residuals are poor or the item is large.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64;
        let mean_waste = mean_residual;
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        let mut new_bin_score = 45.0;
        if large_item {
            new_bin_score -= 20.0;
        }
        if mean_waste > item_size as f64 {
            // open bins collectively have room; discourage new bin
            new_bin_score += 15.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_score += 25.0 * progress;
        // Many open bins -> discourage spreading.
        new_bin_score += 1.5 * open_pressure;
        score = score.max(new_bin_score) * 0.0 + new_bin_score;
        return score;
    }

    // Global state coupling: when mean residual across open bins is high,
    // favor bins whose residual is below the mean (compact them first).
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        if res < mean_residual {
            score -= 4.0 * (mean_residual - res) / mean_residual;
        } else {
            score += 3.0 * (res - mean_residual) / mean_residual;
        }
    }

    // Slight preference early in the stream to keep options open
    // (avoid ultra-tight placements that fragment future flexibility).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual < 20 {
        score += 8.0 * (1.0 - progress);
    }

    score
}

