        }
        // Borrowed: near-half dead space with next item fitting half.
        if dead_frac >= 0.45 && dead_frac <= 0.5 && next_item_size > 0 && (next_item_size as f64) >= dead * 0.5 && (next_item_size as f64) <= dead {
            score -= 11.0 * (1.0 - progress);
        }
        // Borrowed: dead space sized for next item plus a mean-sized pocket.
        if next_item_size > 0 {
            let nf = next_item_size as f64;
            if dead >= nf + mean_residual.min(nf) && dead <= nf + nf {
                score -= 16.0 * (1.0 - progress);
            } else if dead > nf && dead < nf + 2.0 {
                score -= 8.0;
            }
        }
        // Large dead pockets: usable if next item fits within half the pocket.
        if dead_frac >= 0.55 && dead_frac < 0.75 && next_item_size > 0 && (next_item_size as f64) <= dead * 0.5 {
            score -= 6.5 * dead_frac * (1.0 - progress);
        }
        // Small tight dead-space that still hosts next item: reward.
        if next_item_size > 0 && dead_frac < 0.12 && dead >= next_item_size as f64 {
            score -= 5.0 * (1.0 - dead_frac / 0.12) * (1.0 - progress);
        }
    }

    // Pair-fill reward when bin can host item + next item together.
    if next_item_size > 0 {
        let pair = item_size as f64 + next_item_size as f64;
