    }
    if pr > 0 && (pr as f64) < 0.5 * (next_item_size.max(1) as f64) && fitting_bins_count > 1 {
        score += 6.5 * (1.0 - progress);
    }
    if pr > 0 && (pr as f64) < 0.06 * capf && fitting_bins_count > 2 {
        score += 5.0 * (1.0 - progress);
    }
    if pr > 0 && fitting_bins_count > 1 && (pr as f64) < 0.1 * capf && next_item_size > 0 && (next_item_size as f64) > pr as f64 {
        score += 4.5 * (1.0 - progress);
    }

    // Late-stream small-residual refinement.
    if progress > 0.85 && pr > 0 && pr <= 2 {
        score -= 21.0;
    }
    if progress > 0.8 && pr > 0 {
        score += (pr as f64) * (progress - 0.8) * 1.9;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fit (dead-space elimination)
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    }

    // 2-step lookahead: reward when next item fits the post residual exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 100.0 - (slack as f64) * 5.0;
            } else {
                // next item leaves big unusable gap; mild penalty
                score += slack as f64 * 0.3;
            }
        } else {
            // next item cannot fit here: penalize proportionally to mismatch
            let gap = next_item_size - post_residual;
            score += gap as f64 * 1.5;
        }
    } else {
        // last item: strongly prefer filling existing bins
        score -= 200.0;
    }

    // Compare post residual against mean residual across open bins
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Late in the stream, prefer closing out bins tightly
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 - 0.3 * progress;

    // Mild penalty for very small post residuals that are > 0 but unusable
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

