    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // near-perfect fill bonus
    } else if post_residual >= 10 && post_residual < 20 {
        score += 3.0; // awkward gap zone
    } else if post_residual >= 40 {
        score += 6.0 * (post_residual as f64 - 40.0) / 60.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual > 0 {
            let reuse = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * reuse; // chainable fit is valuable
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 4.0; // blocks the next item in this bin
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate logic: opening a fresh bin is only attractive for
    // large items that would otherwise leave big gaps, or late in the stream
    // with many open bins (diversification of residual sizes).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        let gap_elsewhere = (bin_residual - item_size).max(0) as f64;
