pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post residual (tight fit), scaled smoothly
    let mut score = post;

    // Non-linear coupling of post_residual with stream progress:
    // early on tolerate larger post residuals; late, demand tight fits.
    let progress_coupling = post * (0.5 + 1.5 * progress * progress);
    score += progress_coupling * 0.3;

    // Quadratic dead-space penalty: unusable space (< smallest plausible item) hurts more
    let dead = if post < item.min(10.0) { post * post } else { 0.0 };
    score += dead * 0.05;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin, more so mid/late stream,
    // unless the item would leave a large residual in existing bins anyway.
    if bin_residual == bin_capacity {
        let waste_elsewhere = (mean_residual - item).max(0.0);
        score += 40.0 + 60.0 * (1.0 - progress) - waste_elsewhere * 0.5;
        // If next item is large and current item is small, new bin is more attractive
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if nx > post + 10.0 {
                score -= 10.0;
            }
        }
    } else {
        // Slight reward for bins whose post residual still fits the lookahead item
        if next_item_size > 0 && (post as u32) >= next_item_size {
            score -= 8.0;
        }
    }

    // Mild penalty proportional to number of open bins to discourage fragmentation
    score += (open_bins_count as f64).ln() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: classify post_residual into capacity fractions.
    let frac = post_residual as f64 / cap;
    // Dead-space penalty grows super-linearly for small leftovers (unusable slivers).
    if post_residual > 0 {
        let class = post_residual / (bin_capacity / 10); // decile class 0..10
        score += match class {
            0 => 40.0,          // 1..9 leftover: nearly dead space
            1 => 18.0,          // 10..19
            2 => 8.0,           // 20..29
            3 => 2.0,
            _ => 0.0,
        };
        // Modulo-5 harmonic: leftovers divisible by 5 pair better with typical sizes.
        if post_residual % 5 == 0 {
            score -= 3.0;
        }
        if post_residual % 10 == 0 {
            score -= 3.0;
        }
    } else {
        // Perfect fill: strongly rewarded.
        score -= 60.0;
    }

    // Lookahead coupling: reward leftovers that can host the next item exactly/nicely.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 35.0; // next item closes this bin perfectly
        } else if slack <= 10 {
            score -= 12.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this leftover: penalize proportionally to its smallness.
        score += (next_item_size as f64) * (1.0 - frac) * 0.15;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when current leftovers are poor fits.
    if bin_residual == bin_capacity {
        let base = 55.0 + 0.35 * mean_residual;
        // Early in stream: slightly favor consolidation; late: fresh bins cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = base - 20.0 * progress;
        // Big items justify a fresh bin more.
        score -= (item_size as f64 / cap) * 10.0;
    }

    // Mild consolidation bias: prefer bins below mean residual (tighter bins).
    score += 0.10 * (mean_residual - bin_residual as f64).max(0.0);
    // Prefer fewer open bins overall (encourage filling existing bins).
    score -= 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to accept
    // typical future items are heavily penalized (non-linearly).
    if post_residual > 0 {
        if post_residual <= 9 {
            // Unusable micro-gap: dead space.
            score += (10 - post_residual as i32) as f64 * 8.0;
        } else if post_residual <= 20 {
            // Marginal gap: only fits tiny items; mild penalty.
            score += 3.0;
        }
    } else {
        // Perfect fit: strongly reward exact closure.
        score -= 25.0;
    }

    // Reward bins whose post_residual can still host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Lookahead won't fit: this bin becomes dead after placement.
            score += 4.0;
        }
    }

    // Open-bins pressure: when many bins are open, prefer compacting into
    // existing bins rather than spreading; when few are open, allow slack.
    let bin_pressure = open_bins_count as f64;
    score += bin_pressure * (post_residual as f64 / bin_capacity as f64) * 4.0;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // (i.e., mean residual is small relative to the item).
    if bin_residual == bin_capacity {
        let tight_fit_exists = mean_residual >= item_size as f64 + 10.0;
        if tight_fit_exists {
            // Existing bins are roomy enough: discourage new bin.
            score += 15.0 + mean_residual * 0.1;
        } else {
            // No good home elsewhere: opening a fresh bin is reasonable.
            score -= 8.0;
        }
    }

    // Slight preference for bins with larger pre-existing residual (keep
    // tight bins tight, place into roomy bins).
    score -= (bin_residual as f64 / bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to zero is good.
    score -= 30.0 * (-post_residual as f64 / 25.0).exp();

    // 2-step lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (-gap / 15.0).exp();
    } else if next_item_size > 0 {
        // penalize if next item cannot use leftover space
        score += 8.0;
    }

    // Compare post_residual relative to mean residual: avoid leaving space far above mean
    // when mean is small (wasteful), but reward when post_residual is small.
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it over new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize opening new bins late in the stream when open bins exist.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress;
    }

    // Slight preference for more filled bins when many bins are open.
    score -= 0.05 * (bin_capacity - post_residual) as f64 / open_bins_count.max(1) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fit (small post_residual), but weight it.
    let fit_quality = (post_residual as f64) / (bin_capacity as f64);
    score = 10.0 * fit_quality;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Penalize large dead space relative to the smallest possible item (1)
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 5.0; // unusable sliver
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits in the post-residual, reward heavily
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
        // extra reward if next item exactly fills remaining space
        if (post_residual as u32) == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 && (next_item_size as f64) > dead {
        // next item won't fit here; mild penalty proportional to gap
        score += 0.3 * (next_item_size as f64 - dead);
    }

    // Time horizon: early in stream, be more conservative with new bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate handling: empty bin gets a baseline cost that shrinks
    // as the stream progresses or when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let mut new_bin_cost = 40.0;
        // late in the stream, opening new bins is cheaper (fewer future regrets)
        new_bin_cost -= 20.0 * progress;
        // if many bins already open and mean residual is high, prefer packing
        new_bin_cost += 0.1 * (open_bins_count as f64);
        if mean_residual > (item_size as f64) {
            new_bin_cost += 10.0;
        }
        // if only this bin can fit, new bin is mandatory anyway
        if fitting_bins_count == 0 {
            new_bin_cost -= 100.0;
        }
        score += new_bin_cost;
    }

    // Global state: if mean residual across open bins is small (bins nearly full),
    // favor packing into existing bins more aggressively.
    score += 0.2 * (mean_residual - (bin_residual as f64)).max(0.0);

    // Slight preference for filling bins that are already heavily loaded
    let load_frac = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 10.0 * load_frac;

    // Penalize opening bins when few items remain
    let remaining = (total_items.saturating_sub(step_index)) as f64;
    if bin_residual == bin_capacity && remaining < 5.0 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.17;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = post * (1.0 + 0.35 * progress * norm_post);

    // smooth polynomial coupling of fill ratio with stream progress
    let fill = 1.0 - norm_post;
    score -= 14.0 * fill * fill * (0.5 + 0.5 * progress);

    // penalize tiny dead space non-linearly
    if post > 0.0 {
        score += 6.0 * (1.0 - norm_post).powi(3) * norm_item;
    }

    // lookahead: reward leaving room for next item smoothly
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (post - n).abs();
        score += 0.08 * gap * gap / cap;
        if post >= n {
            score -= 4.0 * (1.0 - gap / cap);
        }
    }

    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 8.0 + 10.0 * fill;
    }

    // mild penalty for spreading across many bins
    score += 0.4 * open_bins_count as f64 * norm_post;

    // deviation from mean residual, smooth quadratic
    score += 0.02 * (post - mean_residual) * (post - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
