pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: small residues (< 10) are dead space
    if post_residual < 10 {
        score -= 40.0; // reward near-perfect fit strongly
    } else {
        // penalty grows for residues that are hard to fill later
        let class = post_residual % 25;
        score += class as f64 * 0.15;
    }

    // Reward using the bin if the next item fits into the post-residue (chaining)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // extra reward if next item then leaves a tiny residue again
        let r2 = post_residual - next_item_size;
        if r2 < 10 { score -= 15.0; }
    } else if next_item_size > 0 {
        // post-residue too small for next item: penalize proportionally to waste
        score += (next_item_size - post_residual) as f64 * 0.2;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer filling bins that are already relatively full
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * 10.0;

    // New-bin candidate: make it moderately attractive only when few bins fit
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else {
            // discourage opening new bins when decent fits exist
            score += 20.0 + (fitting_bins_count as f64) * 2.0;
        }
    }

    // Slight preference to spread across bins when many are open
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Progress-aware mild tightening
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capf = bin_capacity as f64;
    let pr = post_residual;
    let dead = bin_residual as f64 - item_size as f64;
    let dead_frac = if dead > 0.0 { dead / capf } else { 0.0 };
    let progress = step_index as f64 / total_items.max(2) as f64;
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    let mut score = pr as f64;

    // Tiered post-residual rewards: exact and near-exact fills dominate.
    if pr == 0 {
        score -= 560.0;
    } else if pr <= 3 {
        score -= 268.0;
    } else if pr <= 5 {
        score -= 134.0;
    } else if pr <= 16 {
        score -= 86.0;
    } else if pr <= 40 {
        score -= 16.0;
    } else if pr <= 66 {
        score -= 4.0;
    }

    // Dead-space penalty: residuals too small for typical items are waste.
    if pr > 0 && pr < 20 {
        score += (20.0 - pr as f64) * (20.0 - pr as f64) * 0.58;
    }

    // Two-step lookahead with modular waste bonus.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 350.0;
        } else if next_item_size + 1 == pr {
            score -= 195.0;
        } else if next_item_size <= pr {
            let waste = (pr - next_item_size) as f64;
            score -= waste * 2.4;
            if (waste as u32) % 10 == 0 && waste > 0.0 {
                score -= 25.0;
            }
        } else {
            let miss = (next_item_size - pr) as f64;
            score += miss.min(50.0) * 0.7 + 7.5;
        }
    }

    // Dead-space shaping: prefer residuals that leave usable pockets for the next item.
    if dead > 0.0 {
        if next_item_size > 0 && dead < next_item_size as f64 {
            score += 12.0 + dead * 0.18;
            score += (next_item_size as f64 - dead) * 0.95;
        } else if next_item_size > 0 && dead as u32 == next_item_size {
            score -= 55.0;
        } else {
            let rem = if total_items > step_index { (total_items - step_index) as f64 } else { 0.0 };
            let rem_frac = (rem / total_items.max(1) as f64).min(1.0);
            score -= dead * (0.06 + 0.05 * rem_frac) + dead_frac * dead_frac * 46.0;
        }
        if next_item_size > 0 && dead as u32 >= next_item_size {
            let after = dead as u32 - next_item_size;
            if after == 0 || after <= 2 {
                score -= 24.0;
            } else if (after as f64) <= 0.04 * capf {
                score -= 10.0;
            }
        }
        if dead_frac > 0.1 && dead_frac < 0.45 {
            let bump = (dead_frac - 0.275) * (dead_frac - 0.275);
            score += bump * 28.0 * (0.4 + 0.6 * (1.0 - progress));
        }
        if dead_frac > 0.3 && progress > 0.6 {
            score += dead_frac * (progress - 0.6) * 32.0;
        }
        if dead_frac > 0.05 && dead_frac < 0.25 && progress > 0.35 {
            score += dead_frac * (progress - 0.35) * 23.0;
        }
        // Divisible dead-space: residual that exactly hosts multiples of next item.
        if next_item_size > 1 && dead as u32 >= 2 * next_item_size && (dead as u32) % next_item_size == 0 {
            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && dead > next_item_size as f64 && dead <= next_item_size as f64 + 3.0 {
            score -= 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 && dead as f64 >= next_item_size as f64 && dead as f64 <= 1.5 * next_item_size as f64 && progress > 0.5 {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && dead as f64 > next_item_size as f64 && dead as f64 <= next_item_size as f64 + 6.0 {
            let gap = dead as f64 - next_item_size as f64;
            score += gap * (1.6 + 0.9 * gap) * (1.0 - progress);
        }
        // Tight small dead-space with next item not fitting: avoid.
        if dead_frac > 0.02 && dead_frac < 0.08 && next_item_size > 0 && (next_item_size as f64) > dead {
            score += (0.08 - dead_frac) * 30.0 * (1.0 - progress);
        }
        if dead < 0.05 * capf && open_bins_count > 2 {
            score += 5.0 * (1.0 - dead / (0.05 * capf));
        }
        if dead > 0.0 && dead < 4.0 && pr > 4 {
            score += 14.0;
        }
        // Mid-range dead-space: prefer when mean residual is larger (consolidation).
        if dead_frac > 0.15 && mean_residual > dead {
            score += (mean_residual - dead).min(40.0) * 0.09 * (1.0 - progress);
        }
        // Dead-space hosting next item plus a mean-residual margin.
        if next_item_size > 0 {
            let nf = next_item_size as f64;
            if dead >= nf + mean_residual.min(nf) && dead <= nf + nf {
                score -= 16.0 * (1.0 - progress);
            } else if dead > nf && dead < nf + 2.0 {
                score -= 8.0;
            }
        }
        if next_item_size > 0 && dead_frac < 0.12 && dead >= next_item_size as f64 {
            score -= 5.0 * (1.0 - dead_frac / 0.12) * (1.0 - progress);
        }
        if dead_frac >= 0.45 && dead_frac <= 0.5 && next_item_size > 0 && (next_item_size as f64) >= dead * 0.5 && (next_item_size as f64) <= dead {
            score -= 11.0 * (1.0 - progress);
        }
    }

    // Pair-fill reward when bin can host item + next item together.
    if next_item_size > 0 {
        let pair = item_size as f64 + next_item_size as f64;
        if bin_residual as f64 >= pair {
            let slack = bin_residual as f64 - pair;
            score -= 40.0 - (slack / capf) * 30.0;
        }
        if pr > 0 && (pr as f64) >= next_item_size as f64 && (pr as f64) < next_item_size as f64 + 4.0 {
            score -= 14.0 * (1.0 - progress);
        }
    }

    // Consolidation pressure when many bins are open, stronger early.
    score -= bin_pressure * 2.4 * (1.0 - progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 52.0;
    }

    // Mean-residual anchoring, stronger later in the stream.
    score -= (0.4 + 0.17 * progress) * (mean_residual - pr as f64);

    // New-bin candidate: open only when lookahead is tight or alternatives are poor.
    if bin_residual == bin_capacity {
        let next_tight = next_item_size > 0 && mean_residual < next_item_size as f64;
        if next_tight || fitting_bins_count <= 1 {
            score -= 34.0;
        } else {
            score += 38.0 + 1.5 * bin_pressure;
        }
        if open_bins_count > 0 && fitting_bins_count > 1 && progress > 0.5 {
            score += 26.0;
        }
        // Large items fragment open bins; better to open fresh for them.
        if item_size as f64 > 0.6 * capf {
            score -= 13.0;
        }
        if item_size as f64 > 0.78 * capf && mean_residual < 0.22 * capf {
            score -= 27.0;
        }
        if item_size as f64 > 0.85 * capf && mean_residual < 0.12 * capf {
            score -= 32.0;
        }
        if item_size as f64 > 0.93 * capf {
            score -= 21.0;
        }
        if next_item_size > 0 && (item_size as f64 + next_item_size as f64) > capf {
            score -= 17.0;
        }
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 6.0 + (next_item_size as f64 - mean_residual) * 0.13;
        }
        if progress > 0.7 && open_bins_count > 3 {
            score += 19.0 * progress;
        }
        let spread = (mean_residual - item_size as f64).abs();
        if spread < 0.08 * capf && fitting_bins_count > 2 {
            score += 9.5;
        }
        if item_size as f64 > mean_residual * 1.6 && fitting_bins_count > 1 && open_bins_count > 2 {
            score -= 15.0 * (1.0 - progress);
        }
        if fitting_bins_count > 1 && mean_residual < item_size as f64 * 0.4 {
            score += 12.0;
        }
        if next_item_size > 0 && next_item_size as f64 > 0.5 * capf && mean_residual > 0.3 * capf {
            score -= 10.5;
        }
        if fitting_bins_count > 1 && dead as f64 > 0.35 * capf && item_size as f64 > mean_residual * 1.25 {
            score -= 11.0 * (1.0 - progress);
        }
        if next_item_size > 0 && item_size as f64 > 0.55 * capf && (capf - item_size as f64) < next_item_size as f64 && fitting_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 24.0 * (1.0 - progress);
        }
        let rem_items = if total_items > step_index { (total_items - step_index) as f64 } else { 0.0 };
        if rem_items > 0.15 * total_items.max(1) as f64 && mean_residual < 0.5 * (next_item_size.max(1) as f64) {
            score -= 15.0 * (1.0 - progress);
        }
        if fitting_bins_count > 2 && mean_residual > 0.55 * capf {
            score += 7.5 * (1.0 - progress);
        }
        // Next item barely fits mean residual: prefer keeping it for open bins.
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 0.85 && next_item_size as f64 <= mean_residual && progress > 0.4 {
            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fitting_bins_count > 0 && mean_residual >= next_item_size as f64 && mean_residual < next_item_size as f64 + 5.0 {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0 && pr == next_item_size && fitting_bins_count > 0 {
            score -= 12.0 * (1.0 - progress);
        }
        if open_bins_count > 4 && fitting_bins_count > 1 && mean_residual > 0.45 * capf {
            score += 5.0 * progress;
        }
    }

    // Usable-pocket bonus: residual after placement that can host next item tightly.
    if next_item_size > 0 && pr >= next_item_size && pr - next_item_size > 0 && (pr - next_item_size) < item_size.max(next_item_size) {
        score -= 15.0;
    }

    // Penalize leaving residual that next item cannot use, but only if small.
    if next_item_size > pr && pr > 0 && pr < 30 {
        score += 8.0;
    }
    if pr > 0 && (pr as f64) < 0.5 * (next_item_size.max(1) as f64) && fitting_bins_count > 1 {
        score += 6.5 * (1.0 - progress);
    }
    if pr > 0 && (pr as f64) < 0.06 * capf && fitting_bins_count > 2 {
        score += 5.0 * (1.0 - progress);
    }
    if pr > 0 && fitting_bins_count > 1 && (pr as f64) < 0.1 * capf && next_item_size > 0 && (next_item_size as f64) > pr as f64 {
        score += 4.5 * (1.0 - progress);
    }
    // Usable-floor reward: post-residual at least as large as a capped next item.
    if pr > 0 {
        let usable_floor = (next_item_size.max(1) as f64).min(0.35 * capf);
        if (pr as f64) >= usable_floor {
            score -= 8.5 * (1.0 - progress) * ((pr as f64) / capf);
        }
    }

    // Late-stream small-residual refinement.
    if progress > 0.85 && pr > 0 && pr <= 2 {
        score -= 21.0;
    }
    if progress > 0.8 && pr > 0 {
        score += (pr as f64) * 0.38 * (progress - 0.8) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // smallest plausible future item (<= 10) are "dead". Penalize hard.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual <= 20 {
        // Small gap zone: mildly risky but potentially usable.
        score += 6.0;
    }

    // Reward tight fits strongly (low post_residual relative to item size).
    if item_size > 0 {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 12.0 * tightness;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post-residual can't host next item; penalize proportional to how close it is.
        score += 5.0;
    }

    // Open bins pressure: discourage scattering across many bins.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: if this is the only fitting bin, prefer using it over
    // opening a new bin (new bin would add a whole fresh residual).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only attractive when the item is large or no good fit exists among
    // open bins. Penalize the fresh bin baseline so it wins only when needed.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Large items deserve a fresh bin more readily.
        score -= 0.35 * item_size as f64;
        // If existing bins are fragmented (high mean residual spread), new bin less bad.
        score -= 0.1 * mean_residual;
    }

    // Slight preference to fill earlier-opened bins as stream progresses.
    score += 0.5 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect match of next item into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward tight two-item packing: post_residual - next_item_size small is great
            let leftover = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - leftover / bin_capacity as f64);
            // Perfect chain: next item exactly fills the remainder
            if leftover == 0.0 {
                score -= 40.0;
            }
        } else {
            // Next item cannot use the dead space; penalize proportionally to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap.min(40.0);
        }
    } else {
        // Last item: just minimize waste
        score += 0.2 * post_residual as f64;
    }

    // Penalize large dead space relative to mean residual across open bins
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when item is large or stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 / bin_capacity as f64;
        let pull = 70.0 * big_item * (1.0 - progress) + 30.0 * big_item * (1.0 - big_item);
        // Next item likely fits the fresh residual too?
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= pull + 20.0;
        } else {
            score -= pull;
        }
    }

    // Mild preference for compacting into fuller bins as stream progresses
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 15.0 * fill_ratio * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
