pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward filling the bin well (low post-residual is better).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 20.0;

    // Penalize dead space that is too small for typical items (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 30 {
        score += 8.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large and no open bin fits well, or bin count is low.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_open = if open_bins_count > 0 { mean_residual } else { 0.0 };
        // Penalize new bins mildly; reduce penalty when item is huge and
        // mean residual across bins is small (nothing fits well).
        let mut new_bin_penalty = 15.0 + progress * 10.0;
        if item_size >= 60 && avg_open < item_size as f64 {
            new_bin_penalty -= 20.0;
        }
        if fitting_bins_count == 0 {
            new_bin_penalty -= 25.0;
        }
        score += new_bin_penalty.max(-5.0);
    }

    // Mild preference for bins with residual close to mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Prefer using existing bins as the stream progresses (avoid bin sprawl).
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let fit_ratio = item_size as f64 / cap;
    let post_norm = post / cap;

    // Base: prefer small post residual, with smooth non-linear (quadratic) scaling.
    let mut score = post + 60.0 * post_norm * post_norm;

    // Reward tight fits: coupling between fit ratio and post residual.
    score -= 25.0 * fit_ratio * (1.0 - post_norm) * (1.0 - post_norm);

    // Stream progress coupling: later in the stream, compactness matters more.
    let p2 = progress * progress;
    score -= 20.0 * progress * fit_ratio;
    score += 15.0 * p2 * post_norm;

    // Dead-space penalty: post residual too small for typical future items.
    if post > 0.0 && post < 10.0 {
        score += 30.0 * (10.0 - post) / 10.0;
    }

    // Lookahead: bonus if the next item fits exactly in the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = (post - nxt) / cap;
            score -= 18.0 * (1.0 - slack * slack) * (1.0 - progress * 0.5);
        } else {
            score += 8.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New empty bin candidate: penalize mildly early, more when open bins exist
    // and mean residual is large; allow opening when residuals are fragmented.
    if bin_residual == bin_capacity {
        let mean_frac = mean_residual / cap;
        score += 12.0 + 30.0 * (1.0 - mean_frac) * (1.0 - progress);
        if open_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 10.0;
        }
    }

    // Slight preference for bins with residual close to the item (best-fit flavor)
    // via smooth coupling with mean residual dispersion.
    let disp = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 10.0 * disp * disp * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: quarter-capacity bands
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter.max(1);
    match class {
        0 => score -= 12.0,          // near-perfect fill: dead space minimal
        1 => score -= 3.0,           // good leftover
        2 => score += 2.0,           // mediocre leftover
        _ => score += 8.0,           // large waste unless bin is fresh
    }

    // Exact-fill or tiny remainder bonus (harmonic residue 0)
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Modulo arithmetic on post_residual: leftovers divisible into small
    // item sizes (10..=20) are reusable, penalize odd dead zones.
    let pr = post_residual;
    if pr > 0 {
        let reusable = (10..=20).any(|s| pr % s == 0 || pr >= s);
        if reusable && pr >= 10 {
            score -= 2.0;
        }
        if pr < 10 {
            score += 10.0; // unusable sliver
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly,
    // reward heavily (chained harmonic fill).
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = post_residual - next_item_size;
        if diff == 0 {
            score -= 18.0;
        } else if diff <= 10 {
            score -= 8.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use this leftover: mild penalty proportional
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // New-bin candidate handling: fresh bins start neutral; prefer them
    // only when all open bins would leave terrible leftovers.
    if bin_residual == bin_capacity {
        score = 30.0 + 0.1 * mean_residual - 5.0 * (fitting_bins_count as f64);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // a fresh bin can host both items if they sum near capacity
            if item_size + next_item_size <= bin_capacity {
                score -= 6.0;
            }
        }
    }

    // Stream progression: late in the stream, be more conservative about
    // opening bins; tighten packing by rewarding tight fits more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * (post_residual as f64) * 0.05;

    // Crowding: many open bins -> discourage new bins implicitly by
    // rewarding reuse of any bin.
    if bin_residual != bin_capacity {
        score -= 0.5 * (open_bins_count.min(20) as f64).ln().max(0.0);
    }

    // Mean-residual alignment: prefer bins whose residual is close to
    // what this item would consume (harmonic matching).
    score += ((mean_residual - item_size as f64).abs()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
