pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // accept a meaningful item (below the minimum plausible item size ~1..10)
    // are pure waste. Penalize the "unusable gap" band hard.
    let dead_threshold = 8.0;
    if (post_residual as f64) < dead_threshold {
        score += 3.0 * (dead_threshold - post_residual as f64);
    }

    // Perfect / near-perfect fits get a strong bonus (subtract score).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual <= 15 {
        score -= 4.0;
    }

    // Reward placements that leave room for the lookahead item if it fits
    // exactly in the post residual (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            score -= 2.0;
        } else {
            // Lookahead cannot fit here; mildly penalize tight-but-wasted fits.
            score += 1.5;
        }
    }

    // Open-bin pressure: discourage scattering across many bins when
    // open_bins_count grows; prefer filling existing bins.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when the item is large relative
    // to capacity or no open bin is a decent fit. Make empty-bin baseline
    // moderately high so it's chosen only when open bins score badly.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Large items are fine to start a fresh bin.
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
        // Early in stream, opening bins is cheaper.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score -= 10.0 * (1.0 - progress);
        }
    }

    // Coupling with mean residual: if this bin's residual is far above the
    // mean, it's a laggard bin — prefer packing it down.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.1 * dev;

    // Mild tightness reward scaled by fill ratio.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 8.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
