pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step fit: post_residual == next_item_size is perfect
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        // Strong reward when the next item exactly consumes the remainder
        if gap == 0.0 {
            score -= 60.0;
        } else {
            // Reward proportional to how close the next item comes to filling the remainder
            score -= 25.0 * (1.0 - gap / post_residual as f64);
        }
    } else if next_item_size > 0 {
        // Next item cannot follow in this bin: penalize if we leave a small dead sliver
        let sliver = post_residual as f64;
        if sliver < next_item_size as f64 && sliver > 0.0 {
            score += 12.0 * (1.0 - sliver / next_item_size as f64);
        }
    }

    // Penalize small unusable leftovers (dead space below minimum item size 1..10)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Reward tight fits relative to bin capacity
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it unattractive unless current bins are very full
    if bin_residual == bin_capacity {
        let avg_fullness = 1.0 - mean_residual / bin_capacity as f64;
        score += 10.0 + 40.0 * avg_fullness;
    }

    // Prefer bins whose residual is far below the mean (i.e., filling the emptiest-but-usable bin)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Late in the stream, be greedier about exact packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, with a quadratic penalty on large leftovers.
    score += 0.045 * (post_residual as f64).powi(2);

    // Reward near-perfect packing (residual below small-item threshold).
    if post_residual < 10 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }
    // Many alternatives: mild penalty so best-fit among many wins.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
            // Dead space that neither fits next item nor is small: penalize.
            if post_residual > 0 && post_residual < 10 {
                score += 6.0;
            }
        }
    }

    // Time horizon: early in the stream, keep bins flexible; late, just fill tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.35 {
        score += 0.25 * post_residual as f64; // flexibility matters early
    } else if progress > 0.75 {
        score -= 0.10 * item_size as f64; // aggressive filling late
    }

    // Global state: if mean residual is high, bins are loose — encourage consolidation.
    if mean_residual > 40.0 {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let open_fit_pressure = if fitting_bins_count == 0 { 0.0 } else { 60.0 };
        score += open_fit_pressure;
        // Opening a new bin is more acceptable when many items remain.
        score -= 20.0 * progress;
        // Don't open new bins if existing open bins are nearly empty anyway.
        if open_bins_count > 0 && mean_residual > 60.0 {
            score += 30.0;
        }
    }

    // Prefer placing large items into bins with just enough room.
    score -= 0.20 * item_size as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, but with progress-dependent curvature
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear coupling: dead space penalty grows quadratically as stream progresses
    score += 20.0 * norm_pr * norm_pr * (0.5 + progress);

    // Lookahead: reward if next item fits into post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 6.0 * (1.0 - slack) * (1.0 - progress);
        } else {
            // penalize post-residuals too small for the next item
            score += 4.0 * (1.0 - progress) * (nxt - pr) / cap;
        }
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // Mild preference for bins below mean residual (keeps balance)
    score += 0.5 * (mean_residual - pr) * (1.0 - progress);

    // New-bin candidate: neutral baseline, penalize opening new bins when good fits exist
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
