pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into residue classes
    // modulo 10 (the canonical item quantum). Residuals that are "harmonically
    // compatible" with likely future item sizes are less wasteful.
    let class = post_residual % 10;
    let class_penalty = match class {
        0 => -8.0,          // perfectly reusable (exact multiple)
        5 => -4.0,          // half-class: still very usable
        2 | 8 => -1.5,      // near-multiple classes
        1 | 9 => 2.0,       // awkward slivers
        _ => 0.5,
    };
    score += class_penalty;

    // Integer-division threshold on post_residual: bins whose residual drops
    // below the smallest item quantum are effectively closed; penalize mildly
    // so they are not preferred over partially reusable bins.
    if post_residual < 10 {
        score += 6.0;
    } else if post_residual < 20 {
        score += 2.0;
    }

    // Lookahead coupling: reward a bin whose post residual exactly (or nearly)
    // accommodates the next item's harmonic class.
    if next_item_size > 0 {
        let fits_next = post_residual >= next_item_size;
        let gap = if fits_next { post_residual - next_item_size } else { next_item_size - post_residual };
        if fits_next {
            score -= 10.0 + (gap == 0) as i32 as f64 * 6.0;
        } else {
            // small gap means next item almost fits: mild bonus to keep bin alive
            if gap <= 10 {
                score -= 2.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current residuals are fragmented
    // or the item is large relative to all residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let pressure = (item_size as f64 / bin_capacity as f64) * 30.0;
        score += 12.0 - pressure + fragmentation * 0.3 + progress * 5.0;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Slight preference for tighter (fuller) bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

