pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness;

    // Aggressive 2-step lookahead: reward if next item fits the post residual exactly/well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_waste = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - next_waste / (bin_capacity as f64));
            // Perfect chain match bonus.
            if next_waste == 0.0 {
                score -= 20.0;
            }
        } else {
            // Next item won't fit here: penalize dead space proportional to gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        }
    } else {
        // Last item: purely minimize post residual.
        score -= 8.0 * tightness;
    }

    // Compare post residual against mean residual: avoid making bin worse than average.
    let mean_post = mean_residual - item_size as f64;
    if (post_residual as f64) < mean_post {
        score -= 3.0;
    } else {
        score += 0.05 * (post_residual as f64 - mean_post);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so mid-stream or when good fits exist.
    if bin_residual == bin_capacity {
        score += 30.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
        // But if next item is large and this bin is empty, opening can be attractive.
        if next_item_size > 60 && post_residual >= next_item_size {
            score -= 18.0;
        }
    }

    // Slight preference to fill bins with larger residuals when many bins are open.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

