    if pr > 0 && (pr as f64) < 0.06 * capf && fitting_bins_count > 2 {
        score += 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let post_norm = post / cap;

    // Base: prefer tight fits, with non-linear (quadratic/cubic) shaping of post_residual
    let mut score = post + 12.0 * post_norm * post_norm + 30.0 * post_norm.powi(3);

    // Non-linear coupling of tightness with stream progress: later in the stream,
    // dead space becomes more costly (bins opened early amortize poorly).
    let tightness = 1.0 - post_norm;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Lookahead synergy: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
