            let slack = (post - nx) / cap;
            score -= 18.0 * (1.0 - slack) * (1.0 - progress);
        } else {
            score += 8.0 * (1.0 - post / nx) * (1.0 - progress);
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate handling: only attractive when existing fits are very poor
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        let openness = (open_bins_count as f64).ln() + 1.0;
        score += 20.0 * openness * (1.0 - fit_ratio) * (1.0 - progress)
            + 10.0 * (mean_residual / cap).powi(2);
        if post_norm < 0.2 && fitting_bins_count >= 1 {
            score += 40.0; // never open a bin for a near-perfect existing fit
        }
    }

    // Mild penalty scaled by item size asymmetry with mean residual
    score += 3.0 * ((mean_residual - post) / cap).abs();

    score
}

