pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits (small dead space)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // Perfect chaining: next item fits exactly into leftover
        if post_residual == next_item_size {
            score -= 200.0;
        }
        // Penalize leftover too small for next item (dead space)
        if post_residual < next_item_size && post_residual > 0 {
            score += 30.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin when decent fits exist, especially late in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 40.0 + 60.0 * progress;
        // But allow new bin if current bin would leave large awkward residual
        if post_residual > 0 && post_residual < 10 {
            score -= 30.0;
        }
    }

    // Slight preference for fuller bins overall
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

