    let mut score = post_residual as f64;

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_ratio;

    // Penalize dead space that is too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead (k=2): if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_tightness = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= 30.0 * next_fit_tightness;
    }
    // If next item cannot fit here, mild penalty for stranding this residual.
    else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Last-chance bonus: this is the only open bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Prefer bins with residuals below the mean (consolidate large residuals for later big items).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Time horizon: early in the stream, be more willing to open new bins (keep options open).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening unless item is large or stream is late.
        score += 20.0 - 25.0 * progress + 20.0 * fill_ratio;
    } else {
        // Late in the stream, avoid opening new bins more aggressively.
        score += 10.0 * progress;
    }

    // Many open bins: discourage spreading items across too many bins.
    score += open_bins_count as f64 * 0.5;

    score
}

