pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = fitting_bins_count as f64;
    let open = open_bins_count as f64;

    // Base: prefer small post_residual (tight fit), non-linearly.
    let mut score = pr as f64;
    score += 40.0 * norm_pr * norm_pr * (1.0 + progress);

    // Dead-space penalty: very small post_residual is great, but reward it more
    // smoothly via a cubic coupling with stream progress.
    score -= 25.0 * (1.0 - norm_pr).powi(3) * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - 0.5 * progress);
    }

    // Scarcity pressure: when few bins fit the item relative to open bins,
    // tighten preference toward this bin proportionally.
    let scarcity = 1.0 / (fit + 1.0);
    score -= 15.0 * scarcity * (1.0 - norm_pr);

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 20.0 * (1.0 - pr / (next_item_size as f64 + pr));
    }

    // Mean-residual coupling: prefer bins whose residual differs from the mean
    // in a smooth quadratic way (diversify residual sizes).
    let dev = (bin_residual as f64 - mean_residual) / cap;
