    // Late-stream penalty on opening new bins: as stream progresses,
    // make the empty-bin candidate less attractive unless it is a perfect fit.
    let is_new_bin = (bin_residual as u32 == bin_capacity);
    if is_new_bin {
        score += 30.0 * (0.3 + progress);
        if (item_size as f64 / cap) > 0.9 {
            score -= 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / c; // 0..1 fraction of capacity left

    // Dead-space penalty: post_residual in awkward "harmonic" classes (odd gaps)
    // Residuals that are small but nonzero (1..=9) are nearly unusable dead space
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 - 2.0 * post_residual as f64;
    }

    // Perfect fit reward: post_residual 0 is ideal
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic class via integer division: post_residual in [50..100) is "half-full class"
    // These are reusable; reward keeping them tidy
    let class = post_residual / 10; // 0..10 harmonic decile
    match class {
        0 => score -= 10.0,          // near-perfect fit
        5 | 6 => score -= 15.0,      // half-capacity class, very reusable
        7 => score -= 5.0,
        _ => {}
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            let nxt_frac = next_item_size as f64 / c;
            // reward when next item leaves a good harmonic class residual too
            let nxt_post = post_residual - next_item_size;
            if nxt_post % 10 == 0 {
                score -= 20.0;
            }
            // penalize if next item would create dead space
            if nxt_post < 10 && nxt_post > 0 {
                score += 10.0;
            }
            let _ = nxt_frac;
        } else {
            // next item won't fit here; slight penalty if we consume a scarce bin
            if fitting_bins_count == 1 {
                score += 30.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it unattractive unless current bins are crowded/fragmented
    if bin_residual == bin_capacity {
        let base = 55.0 + 0.35 * (open_bins_count as f64);
        // open a new bin when mean residual is small relative to item size
        let scarcity = (item_size as f64 - mean_residual).max(0.0);
        score = base + scarcity * 0.5 - 0.3 * frac * c;
        // early stream: prefer fewer bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Mild preference for tighter bins overall
    score += 0.1 * (mean_residual - pr);

    score
}

