    }

    // Lookahead: if the next item fits exactly into the post-residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // Penalize leaving a gap that the next item cannot use.
    if next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    // New-bin candidate handling: an empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 - progress * 10.0;
        // Encourage new bins for large items that would wreck an open bin's balance.
        if item_size >= 60 {
            score -= 12.0;
        }
        if fitting_bins_count <= 2 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
