        }
        if next_item_size > 0 && next_item_size as f64 > 0.5 * capf && mean_residual > 0.3 * capf {
            score -= 10.5;
        }
        if fitting_bins_count > 1 && dead_frac > 0.35 && item_size as f64 > mean_residual * 1.25 {
            score -= 11.0 * (1.0 - progress);
        }
        if next_item_size > 0 && item_size as f64 > 0.55 * capf && (capf - item_size as f64) < next_item_size as f64 && mean_residual >= item_size as f64 {
            score += 24.0 * (1.0 - progress);
        }
        let rem_items = if total_items > step_index { (total_items - step_index) as f64 } else { 0.0 };
        if rem_items > 0.15 * total_items.max(1) as f64 && mean_residual < 0.5 * (next_item_size.max(1) as f64) {
            score -= 15.0 * (1.0 - progress);
        }
        if fitting_bins_count > 2 && mean_residual > 0.55 * capf {
            score += 7.5 * (1.0 - progress);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && mean_residual < (item_size as f64 + next_item_size as f64).min(capf) {
            score -= 6.5 * (1.0 - progress);
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 0.85 && next_item_size as f64 <= mean_residual && progress > 0.4 {
            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fitting_bins_count > 0 && mean_residual >= next_item_size as f64 && mean_residual < next_item_size as f64 + 5.0 {
            score -= 9.0 * (1.0 - progress);
        }
        if open_bins_count > 4 && fitting_bins_count > 1 && mean_residual > 0.45 * capf {
            score += 5.0 * progress;
        }
    }

    // Usable-pocket bonus: residual after placement that can host next item tightly.
    if next_item_size > 0 && pr >= next_item_size && pr - next_item_size > 0 && (pr - next_item_size) < item_size.max(next_item_size) {
        score -= 15.0;
    }

    // Penalize leaving residual that next item cannot use, but only if small.
    if next_item_size > pr && pr > 0 && pr < 30 {
        score += 8.0;
    }
    if pr > 0 && (pr as f64) < 0.5 * (next_item_size.max(1) as f64) && fitting_bins_count > 1 {
        score += 6.5 * (1.0 - progress);
    }
    if pr > 0 && (pr as f64) < 0.06 * capf && fitting_bins_count > 2 {
        score += 5.0 * (1.0 - progress);
    }
    if pr > 0 && fitting_bins_count > 1 && (pr as f64) < 0.1 * capf && next_item_size > 0 && (next_item_size as f64) > pr as f64 {
        score += 4.5 * (1.0 - progress);
    }
    if pr > 0 {
        let usable_floor = (next_item_size.max(1) as f64).min(0.35 * capf);
        if (pr as f64) >= usable_floor {
            score -= 8.5 * (1.0 - progress) * ((pr as f64) / capf);
        }
    }

    // Late-stream small-residual refinement.
    if progress > 0.85 && pr > 0 && pr <= 2 {
        score -= 21.0;
    }
    if progress > 0.8 && pr > 0 {
        score += (pr as f64) * 1.9 * (progress - 0.8);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: item + next item exactly fills the bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item can still fit into the residual (good chain).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 + next_item_size as f64 * 0.5;
    } else if next_item_size > 0 {
        // Dead space for the next item: penalize proportionally to wasted space.
        let waste = post_residual as f64;
        score += waste * 0.3;
    }

    // Small residuals are hard to fill: penalize tight leftover space.
    if post_residual < 10 {
        score += 20.0;
    }

    // Prefer bins tighter than the mean (best-fit bias).
    score -= (bin_residual as f64 - mean_residual) * 0.1;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize slightly so we only open when fits are bad.
    if bin_residual == bin_capacity {
        score += 40.0;
        // Early in the stream, opening bins is cheaper; late, expensive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    score -= (1.0 - (post_residual as f64) / (bin_capacity as f64)) * 30.0;

    // Penalize dead space: residuals too small to be useful (below min item size ~1..100 range, use 10 as safe floor).
    if post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
        // Chain fit bonus: item + next item nearly fill the bin.
        if next_item_size <= post_residual && (post_residual - next_item_size) < 10 {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 40.0;
        // Cheaper to open new bins early in the stream or when many bins are open with slack.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 15.0;
        if mean_residual < item_size as f64 {
            score -= 25.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer filling bins that deviate below the mean residual (consolidate emptier bins).
    score += ((bin_residual as f64) - mean_residual) * 0.15;

    // Mild penalty when many bins are already open (contain bin proliferation).
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Smooth polynomial coupling of post_residual with stream progress.
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) - norm_pr * progress * 0.5;
    let mut score = 100.0 * poly + pr;

    // Reward tight fits, more strongly as stream progresses.
    score -= (cap - pr) / cap * (1.0 + progress) * 20.0;

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 {
            score += gap * gap / cap * (0.5 + progress);
        } else {
            score -= 10.0 + 10.0 * progress;
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty when many bins are open and this placement wastes space.
    score += (open_bins_count as f64).ln().max(0.0) * norm_pr * 5.0;

    // New-bin candidate: keep neutral-ish, slightly penalized early.
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
