pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: small classes are dead space.
    let cls = post_residual / 10; // integer division thresholds 0..=9
    match cls {
        0 => score -= 30.0,                 // near-perfect fit
        1 => score -= 12.0,                 // good fit
        2 => score -= 4.0,                  // decent
        3 | 4 => score += 2.0,              // mediocre
        5 | 6 => score += 6.0,              // wasteful
        _ => score += 10.0,                 // >70 free: bad use of a bin
    }

    // If leftover can host the lookahead item, reward it strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 15.0 + (slack / 10) as f64 * 2.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Leftover too small for next item: penalize proportionally to how stranded it is.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 18.0 };
        score += pressure;
        // Late in the stream, prefer closing out open bins rather than spawning.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
    }

    // Coupling with mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold = 9u32; // smallest item is ~10, gaps below that are dead
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual) as f64;
    }
    // Exact fit is maximally rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Large leftover space is good (keeps bin usable for future items).
    if post_residual >= 50 {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // (penalize spreading into new bins / lightly-filled bins).
    let open_pressure = (open_bins_count as f64).powf(1.3) * 1.5;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: if this bin is much emptier than average,
    // it is a good consolidation target.
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 10.0; // dead space relative to known next item
        }
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (many fitting bins => discourage opening a new bin).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 1 {
            score += 30.0;
        } else if fitting_bins_count == 1 {
            score += 8.0;
        }
        // Fresh bin full capacity is flexible early on
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
    }

    score
}

