    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when many open bins still have room
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 15.0 + 20.0 * (1.0 - progress) + 3.0 * pressure;
        // New bin is OK if the item is large and nothing fits well
        if item_size > bin_capacity / 2 && fitting_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        // Mild preference for filling bins that are already low on residual
        score += 0.15 * (bin_residual as f64 - mean_residual).abs().signum() * (bin_residual as f64 - mean_residual);
    }

    // Time horizon: early in stream, be frugal with bins (favor reuse); late, prioritize completion
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / capacity;
    let norm_item = item_size as f64 / capacity;

    // Base: penalize wasted residual, but with a non-linear (quartic) waste curve
    let mut score = post * (1.0 + 2.0 * norm_post * norm_post);

    // Smooth coupling: waste matters more as the stream progresses
    score += 30.0 * norm_post * norm_post * (0.5 + progress);

    // Perfect-fit reward via smooth bump around zero residual
    score -= 25.0 * (1.0 - norm_post) * (1.0 - norm_post) * norm_item;

    // Lookahead: if next item fits the post residual, reward this placement smoothly
    if next_item_size > 0 {
        let next = next_item_size as f64 / capacity;
        let slack = (post - next_item_size as f64) / capacity;
        if slack >= 0.0 {
            score -= 20.0 * next * (1.0 - slack * slack);
        } else {
            score += 10.0 * next * slack * slack;
        }
    }

    // Last-chance bin: strong smooth reward to use it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_post);
    }

    // Congestion pressure: many open bins with high mean residual -> favor filling existing bins
    let pressure = (open_bins_count as f64) * mean_residual / (capacity * (open_bins_count as f64 + 5.0));
    score -= 20.0 * pressure * norm_item;

    // New-bin candidate: make empty bins mildly attractive early, penalized later
    if bin_residual == bin_capacity {
        score += 5.0 + 40.0 * progress * progress - 10.0 * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (class 0) are gold.
    let quarter = bin_capacity / 4;
    let fifth = bin_capacity / 5;
    let post_mod_q = post_residual % quarter.max(1);
    let post_mod_f = post_residual % fifth.max(1);

    // Reward residuals near zero (tight fits) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 30.0 * tightness * tightness;

    // Reward post_residual landing exactly on harmonic class boundaries
    // (divisible by quarter or fifth => likely reusable by future items).
    if post_mod_q == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_mod_f == 0 && post_residual > 0 {
        score -= 5.0;
    }
    // Penalize awkward mid-class residuals (dead space zones).
    if post_residual > 0 && post_mod_q > 0 && post_mod_q < quarter / 3 {
        score += 6.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit here; penalize small leftovers more.
            score += 4.0 * (1.0 - post_residual as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer opening a fresh bin only when no open bin
    // gives a good fit; make fresh bins mildly unattractive by default.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if item is large and mean residual across open bins is small,
        // opening fresh is reasonable.
        if item_size as f64 > mean_residual {
            score -= 18.0;
        }
    }

    // Early in stream, encourage consolidation (fewer open bins);
    // late in stream, allow more spread since bins are sunk cost.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * (1.0 - progress) * (open_bins_count as f64).ln().max(0.0);

    // Mild penalty when this bin's residual deviates far from mean residual
    // (keeps residual distribution balanced for future fits).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capf = bin_capacity as f64;
    let pr = post_residual;
    let dead = bin_residual as f64 - item_size as f64;
    let dead_frac = if dead > 0.0 { dead / capf } else { 0.0 };
    let progress = step_index as f64 / total_items.max(2) as f64;
