    let mut score = pr as f64;

    // Tiered post-residual rewards: exact and near-exact fills dominate.
    if pr == 0 {
        score -= 560.0;
    } else if pr <= 3 {
        score -= 268.0;
    } else if pr <= 5 {
        score -= 134.0;
    } else if pr <= 16 {
        score -= 80.0;
    } else if pr <= 40 {
        score -= 15.5;
    } else if pr <= 66 {
        score -= 3.5;
    }

    // Dead-space penalty: residuals too small for typical items are waste.
    if pr > 0 && pr < 20 {
        score += (20.0 - pr as f64) * (20.0 - pr as f64) * 0.58;
    }

    // Two-step lookahead with modular waste bonus.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 350.0;
        } else if next_item_size + 1 == pr {
