        if item_size as f64 > 0.78 * capf && mean_residual < 0.22 * capf {
            score -= 27.0;
        }
        if item_size as f64 > 0.85 * capf && mean_residual < 0.12 * capf {
            score -= 32.0;
        }
        if item_size as f64 > 0.93 * capf {
            score -= 21.0;
        }
        if next_item_size > 0 && (item_size as f64 + next_item_size as f64) > capf {
            score -= 17.0;
        }
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 6.0 + (next_item_size as f64 - mean_residual) * 0.13;
        }
        if progress > 0.7 && open_bins_count > 3 {
            score += 19.0 * progress;
        }
        let spread = (mean_residual - item_size as f64).abs();
        if spread < 0.08 * capf && fitting_bins_count > 2 {
            score += 9.0;
        }
        if item_size as f64 > mean_residual * 1.6 && fitting_bins_count > 1 && open_bins_count > 2 {
            score -= 15.0 * (1.0 - progress);
        }
        if fitting_bins_count > 1 && mean_residual < item_size as f64 * 0.4 {
            score += 12.0;
        }
        if next_item_size > 0 && next_item_size as f64 > 0.5 * capf && mean_residual > 0.3 * capf {
            score -= 10.5;
        }
        if next_item_size > 0 && item_size as f64 > 0.55 * capf && (capf - item_size as f64) < next_item_size as f64 && mean_residual >= item_size as f64 {
            score += 23.5 * (1.0 - progress);
        }
        let rem_items = if total_items > step_index { (total_items - step_index) as f64 } else { 0.0 };
        if rem_items > 0.15 * total_items.max(1) as f64 && mean_residual < 0.5 * (next_item_size.max(1) as f64) {
            score -= 15.0 * (1.0 - progress);
        }
        if fitting_bins_count > 2 && mean_residual > 0.55 * capf {
            score += 7.5 * (1.0 - progress);
        }
        // Next item barely fits mean residual: prefer keeping it for open bins.
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 0.85 && next_item_size as f64 <= mean_residual && progress > 0.4 {
            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fitting_bins_count > 0 && mean_residual >= next_item_size as f64 && mean_residual < next_item_size as f64 + 5.0 {
            score -= 9.0 * (1.0 - progress);
        }
        // Borrowed: next item fits mean residual but not item+next combined.
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && mean_residual < (item_size as f64 + next_item_size as f64).min(capf) {
            score -= 6.5 * (1.0 - progress);
        }
        // Borrowed: large dead space in a fitting bin with oversized item.
        if fitting_bins_count > 1 && dead as f64 > 0.35 * capf && item_size as f64 > mean_residual * 1.25 {
            score -= 11.0 * (1.0 - progress);
        }
        // Borrowed: pr matches next item exactly in a fitting bin.
        if next_item_size > 0 && pr > 0 && pr == next_item_size && fitting_bins_count > 0 {
            score -= 12.0 * (1.0 - progress);
        }
    }

    // Usable-pocket bonus: residual after placement that can host next item tightly.
    if next_item_size > 0 && pr >= next_item_size && pr - next_item_size > 0 && (pr - next_item_size) < item_size.max(next_item_size) {
        score -= 15.0;
    }

    // Penalize leaving residual that next item cannot use, but only if small.
    if next_item_size > pr && pr > 0 && pr < 30 {
        score += 8.0;
    }
    if pr > 0 && (pr as f64) < 0.5 * (next_item_size.max(1) as f64) && fitting_bins_count > 1 {
        score += 6.5 * (1.0 - progress);
    }
    if pr > 0 && (pr as f64) < 0.06 * capf && fitting_bins_count > 2 {
        score += 5.0 * (1.0 - progress);
    }
    if pr > 0 && fitting_bins_count > 1 && (pr as f64) < 0.1 * capf && next_item_size > 0 && (next_item_size as f64) > pr as f64 {
        score += 4.5 * (1.0 - progress);
    }

    // Late-stream small-residual refinement.
    if progress > 0.85 && pr > 0 && pr <= 2 {
        score -= 21.0;
    }
    if progress > 0.8 && pr > 0 {
        score += (pr as f64) * (progress - 0.8) * 1.9;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item are pure waste; penalize them heavily.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 60.0 } else if post_residual < 20 { 25.0 } else { 0.0 };
        score += dead;
    } else {
        // Perfect fill is ideal
        score -= 40.0;
    }

    // Reward tight fits (small post_residual relative to capacity)
    score -= 30.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(3);

    // Prefer bins whose current residual was already small (best-fit flavor)
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    // Open-bin pressure: reuse existing bins rather than spawning new ones
    score += (open_bins_count as f64) * 0.5;

    // Last chance: strongly favor the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make opening a new bin unattractive unless dead-space
    // penalties on all open bins dominate (handled by the big dead-space adds).
    if bin_residual == bin_capacity {
        score += 20.0 + (open_bins_count as f64) * 0.3;
        // If the next item is small, a fresh bin keeps flexibility
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 10.0;
        }
    }

    // Lookahead: if the next item fits exactly in the resulting residual,
    // strongly favor this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Mild stream-progress damping of the open-bin pressure late in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fit (low post_residual) is good.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * fit_ratio;

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: this bin will be exactly closed
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how much of post_residual it consumes
            let consume = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * consume;
            // bonus if the pair (item, next) closes the bin tightly overall
            let chain_res = post_residual - next_item_size;
            if chain_res < 10 {
                score -= 15.0;
            }
        } else {
            // next item does NOT fit in residual: penalize leaving a gap that
            // next_item_size just barely misses (dead space)
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 20.0 {
                score += 12.0 + 0.8 * miss; // near-miss dead space is costly
            }
        }
    }

    // Compare residual against mean residual of open bins:
    // bins with above-mean residual should be drained first.
    if post_residual as f64 > mean_residual {
        score -= 6.0 * (post_residual as f64 - mean_residual) / bin_capacity as f64;
    } else {
        score += 4.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: neutral baseline, opened only when
    // no open bin offers a decent fit or a lookahead chain exists elsewhere.
    if bin_residual == bin_capacity {
        // Empty bin: score is its full capacity minus lookahead potential.
        score = bin_capacity as f64 - 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0;
        }
        // Late in the stream, prefer closing existing bins rather than spreading.
        let progress = step_index as f64 / total_items as f64;
        score += 10.0 * progress;
        // If many bins are open, discourage adding more.
        score += 2.0 * open_bins_count as f64;
        // But if no other bin fits well, new bin becomes attractive.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mild preference to keep busy bins consolidated when few bins are open.
    if open_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of stream processed (dynamic time horizon).
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward placing items into bins they fill well.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Lookahead: strongly reward if the next item fits exactly in the post-residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 5.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize leaving a residual that wastes the next item's fit potential.
        score += 1.5 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Many fitting bins: mild penalty for squandering choice on a mediocre fit.
    if fitting_bins_count > 2 {
        score += 0.8 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Global state coupling: penalize placements that push residual far below mean
