pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prog_sq = progress * progress;
    let prog_cu = prog_sq * progress;
    score += 24.0 * norm_pr * norm_pr * (0.5 + progress);
    score -= 18.0 * norm_pr * (1.0 - prog_sq) * (1.0 - progress);
    score += 10.0 * prog_cu * (norm_pr - 0.5) * (norm_pr - 0.5);

    // Reward tight fits, modulated by progress
    let tightness = 1.0 - norm_pr;
    score -= 14.0 * tightness * tightness * (0.6 + 0.4 * (1.0 - progress));

    // Last-chance bin bonus (smooth in fitting_bins_count)
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    } else {
        score += 4.0 * (fitting_bins_count as f64).ln_1p() * (1.0 - progress);
    }

    // Lookahead coupling: favor leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = (pr - nxt).max(0.0) / cap;
        score -= 12.0 * fit_next * (1.0 - prog_sq);
        score += 8.0 * (nxt / cap) * norm_pr * progress;
    }

    // Mean residual dispersion penalty (smooth)
    let dev = (pr - mean_residual).abs() / cap;
    score += 6.0 * dev * dev * (0.4 + 0.6 * progress);

    // Mild penalty for proliferating open bins late in the stream
    score += 2.0 * (open_bins_count as f64).ln_1p() * prog_sq;

    score
}

