    let ob = open_bins_count as f64;
    score += 0.8 * ob;

    // Mean residual coupling: prefer bins whose residual is below mean
    // (i.e., more filled bins get priority, consolidating usage).
    let res = bin_residual as f64;
    score += 0.25 * (res - mean_residual);

    // --- New-bin candidate handling ---
