        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    }

    // Slight preference for larger residual bins when gaps are equal,
    // keeping small residuals for small future items.
    score += 0.05 * res;

    score
}

