pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: minimize post_residual, but reward exact 2-step lookahead match.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward when the next item exactly fills the remaining space
        let match_bonus = if post_residual == next_item_size {
            60.0
        } else if post_residual > next_item_size {
            // next item still fits: reward tightness of the match
            (40.0 * (1.0 - diff / bin_capacity as f64)).max(0.0)
        } else {
            // next item would NOT fit: penalize dead space relative to mean residual
            15.0 + diff / 8.0
        };
        score -= match_bonus;

        // Extra coupling: if post_residual is small but nonzero and unusable
        // by the next item, treat it as pure waste.
        if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // Last item: just minimize waste
