    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer denser bins overall when many bins are open.
    score += 0.1 * (open_bins_count as f64);

    // Late in the stream, consolidate aggressively: penalize leaving large holes.
    let progress = step_index as f64 / total_items.max(1) as f64;
