    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let base = 8.0 + 0.5 * open_bins_count as f64;
        score += base;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 5.0; // fresh bin trivially fits everything, mild bonus
        }
    }

    score
}

