pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Smooth polynomial coupling of post_residual with stream progress
    let poly = 1.0 + 0.8 * progress - 1.2 * progress * progress + 0.6 * progress * progress * progress;
    score *= poly;
    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * item_size as f64 * (0.5 + progress);
    // Penalize dead space relative to mean residual
    let dead = (pr as f64 - mean_residual).max(0.0);
    score += dead * dead / cap * (1.0 + progress);
    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }
    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 && pr >= next_item_size as f64 {
        score -= 5.0 * (1.0 - (pr - next_item_size as f64) / cap) * (0.5 + progress);
    } else if next_item_size > 0 {
        score += 4.0;
    }
    // Mild penalty for proliferating bins late in the stream
    score += open_bins_count as f64 * 0.05 * progress;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by large
    // "harmonic" divisors (10, 20, 25, 50) are more reusable by future items.
    let pr = post_residual;
    let mut harmony_bonus = 0.0;
    if pr == 0 {
        harmony_bonus += 30.0; // perfect fit, ideal
    } else {
        if pr % 50 == 0 { harmony_bonus += 12.0; }
        else if pr % 25 == 0 { harmony_bonus += 8.0; }
        else if pr % 20 == 0 { harmony_bonus += 6.0; }
        else if pr % 10 == 0 { harmony_bonus += 4.0; }
        // Penalize awkward dead space classes (prime-ish / odd small leftovers)
        if pr < 10 {
            harmony_bonus -= 15.0 * (10 - pr) as f64 / 10.0;
        } else if pr % 10 != 0 && pr < 30 {
            harmony_bonus -= 5.0;
        }
    }
    score -= harmony_bonus;

    // Lookahead coupling: if next item exactly harmonizes with post_residual,
    // strongly reward; if next item cannot use the post-residual, penalize.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            let gap = pr - next_item_size;
            if gap % 10 == 0 { score -= 8.0; } else { score += gap as f64 * 0.15; }
        }
        // Next item fits current residual better than post-residual? mild penalty
        if next_item_size > pr && next_item_size <= bin_residual {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin is a fallback; make it moderately
    // attractive only when the stream is early or mean residual is very low.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 60.0 + 40.0 * progress - 0.5 * open_bins_count as f64;
        if mean_residual < 15.0 { score -= 10.0; }
        return score;
    }

    // Prefer fuller bins: normalize by fraction of capacity used.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill;

    // Slight preference for bins whose residual is close to mean residual
    // (keeps the pool of residuals homogeneous, easier future packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
