pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize moderate dead space proportionally (super-linear).
    if post_residual > 0 && post_residual <= 30 {
        score += (31 - post_residual) as f64 * 0.6;
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 8.0;

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    }
    // If next item nearly fits (small miss), penalize leaving that awkward gap.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual && next_item_size - post_residual <= 5 {
        score += 8.0;
    }

    // New-bin candidate: prefer it only when residuals are tight overall.
    if bin_residual == bin_capacity {
        score -= (mean_residual - 15.0).max(0.0) * 0.8;
        score -= (open_bins_count as f64) * 0.3;
    }

    // Progression: early in stream, slightly favor consolidating into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
