    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in post-residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 4.0 * (post_residual as f64 - next_item_size as f64).min(30.0) / 30.0;
        } else {
            // Next item cannot use this bin's leftover; penalize large leftovers.
            score += 3.0 * (post_residual as f64 - next_item_size as f64).max(0.0) / 20.0;
        }
    }

    // Global state coupling: prefer filling bins when many bins are open
    // relative to stream progress, to consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bins_pressure = open_bins_count as f64 / (progress + 0.1);
    if bins_pressure > 20.0 {
        score -= 1.5 * (bins_pressure - 20.0).min(20.0) / 20.0;
    }

    // Mean residual coupling: if this bin's residual is far below mean,
    // it's an outlier worth closing out; favor placing here.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= 2.0 * diff.min(50.0) / 50.0;
    } else {
        score += 1.0 * (-diff).min(50.0) / 50.0;
    }

    // New-bin candidate bias: only attractive when no open bin is a decent fit.
    if bin_residual == bin_capacity {
        // Baseline penalty so existing bins usually win; relax late in stream
        // or when many bins are open and mean residual is small.
        let mut penalty = 6.0;
        if mean_residual < 15.0 {
            penalty -= 3.0;
        }
        if open_bins_count > 10 {
            penalty -= 2.0;
        }
        score += penalty.max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
