pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: penalize wasted space quadratically (dead space is worse the larger it is)
    let mut score = pr * pr / (cap * cap) * 40.0 + pr * 0.6;

    // Smooth non-linear coupling with stream progress:
    // late in the stream, tight fits (small post_residual) matter more;
    // early on, prefer keeping bins flexible (larger post_residual less penalized).
    let tightness = 1.0 - (pr / cap).powf(2.0);
    score -= tightness * (progress * 30.0 + 5.0);

    // Interaction: post_residual vs mean residual — bins deviating from mean are penalized
    let dev = (pr - mean_residual) / cap;
    score += dev.abs() * 8.0 * (0.5 + progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: if next item fits the post-residual, reward; quadratic falloff otherwise
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        if gap >= 0.0 {
            score -= 12.0 * (1.0 - gap / cap).powf(2.0);
        } else {
            score += (-gap / cap).powf(2.0) * 10.0;
        }
    }

    // Mild penalty for spreading across many bins when post_residual is large
    score += (open_bins_count as f64).ln() * pr / cap * 2.0;

    // New-bin candidate: neutral-ish but slightly penalized unless it enables a great fit
    if bin_residual == bin_capacity {
        score += 6.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
