pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: which capacity fraction band it lands in.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // 0..1

    // Modulo classes on post_residual (harmonic bands: /8, /5, /3 of capacity)
    let band8 = post_residual % (bin_capacity / 8);   // 12.5-unit band
    let band5 = post_residual % (bin_capacity / 5);   // 20-unit band
    let band3 = post_residual % (bin_capacity / 3);   // ~33-unit band

    // Reward residuals that fall near the bottom of a harmonic band (cleaner packing classes)
    score -= (band8 as f64) * 0.05;
    score -= (band5 as f64) * 0.02;
    score -= (band3 as f64) * 0.01;

    // Perfect fit: strongly favored
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tiny dead space classes: penalize residuals that no item (1..100) can use well
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    }
    // Residual in the "harmonically useful" range: exactly fillable by common sizes
    if post_residual % 10 == 0 && post_residual >= 10 {
        score -= 15.0;
    }

    // Fraction thresholds on capacity fraction
    if frac > 0.5 {
        score -= 8.0; // still half-full, fine
    } else if frac < 0.1 {
        score += 10.0 * (0.1 - frac); // approaching dead space
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits the post residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
        // Harmonic bonus: next item leaves another clean class
        if (post_residual - next_item_size) % 10 == 0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // next item won't fit here; penalize mildly if post residual is wasted for it
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.05;
    }

    // New-bin candidate handling: only open a new bin when current fit is poor
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 30.0;
        // But if all existing bins are badly fragmented, opening is attractive
        if mean_residual < 25.0 && open_bins_count > 0 {
            score -= 45.0;
        }
        // Early in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 10.0;
    }

    // Fragmentation pressure: prefer bins whose residual is below mean (tighten tight bins)
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Open-bins pressure: with many open bins, favor reusing existing ones
    score += open_bins_count as f64 * 0.5;

    score
}

