    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 {
        // Penalize post_residual that cannot fit the next item (dead space for lookahead).
        if post_residual < next_item_size {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        } else {
            // Reward leaving room for the next item, scaled by tightness of fit.
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - slack.min(20.0) * 0.5;
        }
    }

    // Prefer bins tighter than the mean residual (good fits concentrate space).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last chance: strongly favor using this bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Late in the stream, prefer closing bins tightly (small post_residual).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    // New empty bin candidate: penalize moderately so it's chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

