pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with non-linear penalty growth
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Smooth stream-progress coupling: late in the stream, tighten residual preference
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Interaction: post_residual vs mean_residual — prefer bins below/at mean residual
    let mean_term = (pr - mean_residual) / cap;
    score += 20.0 * mean_term * mean_term - 10.0 * mean_term * progress;

    // Dead-space penalty: residuals too small for any plausible item (1..100)
    let dead_threshold = 12.0;
    if pr_norm < dead_threshold / cap {
        let t = 1.0 - pr / dead_threshold;
        score += 15.0 * t * t;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Lookahead: reward if next item fits the post-residual exactly-ish
    if next_item_size > 0 {
        let gap = (pr as i64 - next_item_size as i64).abs() as f64;
        let fit_next = if next_item_size as f64 <= pr {
            -18.0 * (1.0 - gap / cap)
        } else {
            0.0
        };
        score += fit_next;
        // penalize leaving residual that neither helps nor matches next item
        score += 4.0 * (gap / cap) * (1.0 - progress);
    }

    // Mild penalty for many open bins to encourage consolidation
    score += (open_bins_count as f64).ln().max(0.0) * 1.5 * (1.0 - progress);

    // New-bin candidate: make empty bin attractive only when item is large relative to residual norms
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / cap;
        score = 30.0 + 60.0 * tightness - 40.0 * progress * tightness
            + (mean_residual / cap) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into
    // "reusable" classes (small multiples of common item sizes), penalize
    // dead-space classes (residuals too small for typical items).
    let pr = post_residual;
    if pr > 0 {
        // class by integer division into capacity fractions
        let class = pr / 10; // 0..10 harmonic slots
        match class {
            0 => score += 60.0,                 // 1..9: nearly dead space
            1 => score += 25.0,                 // 10..19: marginal
            2 => score += 5.0,                  // 20..29: usable
            3 | 4 => score -= 10.0,             // 30..49: sweet zone
            5 | 6 => score -= 15.0,             // 50..69: very reusable
            _ => score -= 5.0,                  // 70+: large but wasteful now
        }
        // Modulo-10 harmonic coupling: residuals congruent to 0 mod 10
        // align with integer item sizes; reward exact alignment.
        if pr % 10 == 0 { score -= 8.0; }
    } else {
        // Perfect fit: best possible outcome.
        score -= 200.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 120.0;
        } else if next_item_size <= pr {
            // next item fits: mild reward scaled by tightness
            score -= 20.0 * (next_item_size as f64 / pr as f64);
        } else {
            // next item cannot use this residual: penalize leaving large gaps
            score += 0.15 * (pr as f64 - (pr % next_item_size.max(1)) as f64).min(pr as f64);
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or this is a huge item that would wreck an open bin's flexibility.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 > 2.0 + 8.0 * progress;
        let huge = item_size > bin_capacity / 2;
        if huge || crowded || fitting_bins_count == 0 {
            score -= 55.0 + 0.3 * mean_residual;
        } else {
            // Prefer filling existing bins early on.
            score += 40.0;
        }
    }

    // Mild preference for tighter fits overall (waste minimization).
    score += 0.1 * (item_size as f64 / cap) * (bin_residual - item_size) as f64 * 0.0
           + 0.05 * (bin_residual as f64 - item_size as f64);

    // Slight tie-break toward bins below mean residual (consolidation).
    score += 0.02 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
