pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is smaller than the smallest plausible item.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 40.0;
    }

    // Reward near-perfect fits strongly (post_residual close to 0).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer
    // compacting into existing bins; few open bins -> new bins are cheaper.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    score += open_pressure;

    // New-bin candidate (empty bin): baseline penalty so it only wins when
    // existing fits are poor. Modulate by how much dead space the best
    // alternative would create: if this item would leave a large residual
    // anyway, a fresh bin is fine.
    if bin_residual == bin_capacity {
        score += 25.0;
        // If the next item is large, a fresh bin with room is attractive.
        if next_item_size > 0 && next_item_size as f64 > (bin_capacity as f64) * 0.6 {
            score -= 15.0;
        }
        // Late in the stream, prefer closing out bins rather than opening new.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Prefer bins whose residual is already below average (compact bins);
    // avoid dumping into large-residual bins that could serve bigger items.
    let res = bin_residual as f64;
    if res > mean_residual + 20.0 {
        score += (res - mean_residual - 20.0) * 0.5;
    } else if res < mean_residual {
        score -= (mean_residual - res) * 0.3;
    }

    // Lookahead: if the next item could exactly use the post_residual,
    // reward this placement (chains well).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_after_next = post_residual - next_item_size;
        if gap_after_next <= 10 {
            score -= 20.0;
        }
    }
    // If next item cannot fit in the leftover, leftover is more likely dead.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Mild preference for tighter fits overall.
    score -= (1.0 - (post_residual as f64) / (bin_capacity as f64)) * 0.0
        + (item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 8.0 * tightness * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Exact-fit bonus: post_residual below smallest possible item (1) is impossible,
    // so reward near-zero post residual heavily
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 15.0 * (10 - post_residual) as f64 / 10.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual can host next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_waste = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - chain_waste / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize leaving residual that cannot fit the next item
        score += 6.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
    }

    // Compare residual against mean residual: prefer bins with less residual (tighter)
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize opening a new bin when decent open bins exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 - 10.0 * progress;
        // But if next item is large and this item is small, opening fresh may be fine
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 12.0;
        }
    }

    // Mild pressure to consolidate: fewer open bins is better
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
