pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that can never hold typical items (below 10).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits, but leaves further residue: partial reward
            let chain_waste = post_residual - next_item_size;
            score -= 20.0 - (chain_waste as f64).min(20.0);
        } else {
            // next item will not fit here: slight penalty for blocking a big item
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin wastes residual capacity of all open bins.
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual.max(0.0);
        // Penalize new bins more when many open bins still have room.
        score += 15.0 + avg_waste * 0.3 + (open_bins_count as f64) * 1.5;
        // Early in stream, avoid proliferation of bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
        // If no open bin fits, new bin is fine: fitting_bins_count == 0.
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
        // If next item is large and this bin would take current small item, mild penalty.
        if next_item_size > 60 {
            score += 5.0;
        }
    } else {
        // Prefer bins whose residual is close to mean (balance) mildly.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Mild preference for filling fuller bins first (larger item_size relative to residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let fit = item_size as f64 / cap;

    // Core: quadratic waste penalty, sharpened as the stream progresses.
    let mut score = post + 60.0 * norm_post * norm_post * (0.5 + progress);

    // Reward tight fits (post_residual near zero) with a smooth exponential dip.
    score -= 45.0 * (-post / (0.15 * cap)).exp();

    // Interaction: item size vs post residual — large items prefer small leftovers.
    score -= 12.0 * fit * (1.0 - norm_post);

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward it.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let exact = ((next_item_size as f64 - post) / cap).abs();
        score -= 18.0 * (1.0 - exact) * (1.0 - progress);
    } else if next_item_size > 0 && (next_item_size as f64) > post {
        score += 6.0 * progress;
    }

    // Mild penalty for spreading across too many open bins relative to mean residual.
    score += 0.5 * ((open_bins_count as f64) - mean_residual / 10.0).abs() * 0.05;

    // New-bin candidate (empty bin): penalize opening a new bin unless the item is
    // large and current residuals are poor; smooth logistic gate.
    if bin_residual == bin_capacity {
        let gate = 1.0 / (1.0 + (-(fit - 0.6) * 8.0).exp());
        score += 25.0 * (1.0 - gate) * (0.6 + 0.4 * (1.0 - progress));
        score -= 10.0 * fit * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead-aware dead-space logic
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            // residual cannot host the next item -> dead space penalty,
            // scaled by how much space is wasted
            score += 0.6 * post_residual as f64 + 12.0;
        } else if post_residual >= next_item_size {
            // residual can host the next item -> reward chainability
            score -= 6.0;
            // extra reward if next item fits snugly afterwards too
            let second = post_residual as i64 - next_item_size as i64;
            if second >= 0 && second < 10 {
                score -= 4.0;
            }
        }
    } else {
        // last item: only tightness matters
        score -= 10.0;
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Harmonic class of residual (quarters of capacity): penalize classes
    // that tend to be unusable (very small fractions), reward mid classes
    let frac = post_residual as f64 / cap;
    let class = (frac * 4.0).floor(); // 0..4
    match class as i32 {
        0 => score += 8.0,   // <25% left: likely dead space
        1 => score += 0.0,
        2 => score -= 3.0,   // 50-75%: flexible
        3 => score -= 1.0,
        _ => {}
    }

    // New-bin candidate: score by its own post residual, discourage unless
    // item is large (new bin for big items is efficient) or no good fit exists
    if bin_residual == bin_capacity {
        score = cap - item_size as f64;
