    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that likely can never be used are heavily penalized.
    // Treat gaps below the minimum plausible item size (<= ~10) or awkward mid-range gaps as dead.
    let pr = post_residual as f64;
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    } else if post_residual <= 10 {
        // Tiny unusable gap: nearly as bad as a fresh bin's waste.
        score += 25.0;
    } else if post_residual < 20 {
        // Small awkward gap: moderate penalty.
        score += 10.0;
    } else {
        // Usable gap: mildly reward tightness (smaller gap = better).
        score += 0.05 * pr;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Next item cannot use this gap: penalize proportionally to how stranded the gap is.
        score += 6.0;
    }

