pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward small post_residual nonlinearly.
    if post_residual == 0 {
        score -= 500.0; // perfect fit
    } else if post_residual < 10 {
        score -= 300.0;
    } else {
        // dead-space penalty grows superlinearly for large leftover gaps
        let pr = post_residual as f64;
        score += 0.02 * pr * pr;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new one.
