        score -= 200.0;
    }

    // Penalize the new-bin candidate mildly; only allow opening a new bin when
    // the fit is bad or the item is huge relative to residuals.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        // opening a new bin is attractive for large items (poor future fit in residuals)
