        score += 60.0 * progress;
        // many open bins already -> discourage more
        score += 3.0 * open_bins_count as f64;
    } else {
        // reward using existing bins, more so when residuals are large on average
        score -= 0.5 * mean_residual;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
