            score -= 250.0; // enables a perfect follow-up fit
        } else if gap < 10 {
            score -= 100.0;
        }
    }
    // If next item cannot fit here anyway, slight penalty for wasting a good residual
    if next_item_size > post_residual && post_residual < 10 && !is_new_bin {
        score += 20.0;
    }

    // Prefer bins whose residual is close to the item (good global packing)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * tightness;

    // Slight preference for fuller bins early (first-fit-like), less late
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 50.0 * (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;
    score += 30.0 * norm_pr * norm_pr * (1.0 - progress);
    score -= 25.0 * norm_pr * progress * progress;
    score += 12.0 * norm_pr * norm_pr * norm_pr * progress;

