        // Dead space class (<10): nothing in 1..100 range except tiny items fits; penalize.
        score += 15.0;
    } else {
        // Usable leftover classes via integer-division thresholds on post_residual.
        // Reward leftovers that form "harmonic" fractions of capacity (25, 33, 50, 66, 75)
        // which future items commonly complement.
        let harmonic = |x: u32| -> f64 {
            match x {
                25 | 33 | 50 | 66 | 67 | 75 => 8.0,
                _ => 0.0,
            }
        };
        score -= harmonic(post_residual);
        // Class by quartile of remaining capacity: prefer mid-size leftovers
        // that can host next_item_size exactly.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 500.0; // lookahead exact fit
        } else if next_item_size > 0 && next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            if nxt_post <= 5 {
                score -= 60.0; // lookahead near-perfect fill
            } else if nxt_post < 10 {
                score += 10.0; // lookahead creates dead space
            } else {
                score -= harmonic(nxt_post) * 0.5;
            }
        }
    }

    // New-bin candidate handling: bin_residual == bin_capacity means empty bin.
    if bin_residual == bin_capacity {
        // Opening a new bin is wasteful if any open bin can fit the item.
        if fitting_bins_count > 0 {
            // Scale penalty with how many alternatives exist and how fresh the stream is.
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += 40.0 + 10.0 * (fitting_bins_count as f64) + 20.0 * progress;
        } else {
            // Last resort: opening a new bin is fine; slight reward.
            score -= 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mild preference for filling bins that are already relatively full,
    // keeping many partially-filled bins flexible (mean residual coupling).
    if bin_residual < bin_capacity {
        let fullness = 1.0 - (bin_residual as f64) / cap;
        score -= 5.0 * fullness;
        // If this bin is much fuller than average, favor it (consolidation).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

