pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact two-step lookahead match: leave exactly the space the next item needs.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Small slack after next item's fit is good; large slack wastes space.
            score += slack * 0.35;
        } else {
            // Next item cannot fit here: dead space relative to lookahead.
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.8;
        }
    }

    // Reward tight fits of the current item (small post_residual).
    score -= (bin_capacity - post_residual.min(bin_capacity)) as f64 * 0.15;

    // Penalize creating tiny unusable residuals (dead space trap).
    if post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Compare against mean residual: bins below-mean residual are precious, prefer filling them.
    if (post_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.2;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., item is large relative to typical residual) — otherwise discourage.
    if bin_residual == bin_capacity {
        let poor_alternatives = fitting_bins_count <= 1 || (item_size as f64) > mean_residual + 10.0;
        if poor_alternatives {
            score -= 30.0;
        } else {
            score += 50.0;
        }
    }

    // Mild penalty for spreading across too many open bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count as f64 > 4.0 + 10.0 * progress {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capf = bin_capacity as f64;
    let pr = post_residual;
    let dead = bin_residual as f64 - item_size as f64;
