    // Reward perfectly empty bin after placement
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is costly unless
    // the current fit is poor or the next item needs the space
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_penalty = 18.0;
        // Early in stream: more willing to open bins (builds diversity)
        new_bin_penalty -= 8.0 * (1.0 - t);
        // Many open bins: discourage opening more
        new_bin_penalty += (open_bins_count as f64).ln().max(0.0) * 3.0;
        // If next item won't fit alongside in a fresh pairing, mild relief
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            new_bin_penalty -= 5.0;
        }
        // Poor fit in existing bins (fit_ratio low) makes new bin more attractive
        if fit_ratio < 0.5 {
            new_bin_penalty -= 6.0;
        }
        score += new_bin_penalty;
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 20.0;
