            score -= 5.0;
        } else {
            // next item cannot use this bin's leftover; penalize wasting space
            score += 3.0;
        }
    }

    // Global state: if mean residual is high, prefer consolidating into bins
    // with residual far from the mean (reduces variance of dead space)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.05 * dev;

    // Prefer bins whose residual is closest to item size (best-fit flavor)
    score += 0.1 * (bin_residual as f64 - item_size as f64).abs();

    // Mild time-horizon coupling: late in stream, be greedier about tight fits
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * t * fit_ratio;

    score
}

