        }
        // Dead-space that can host next item twice: strong keeper.
        if next_item_size > 0 && dead as f64 >= 2.0 * next_item_size as f64 && dead as f64 <= 2.5 * next_item_size as f64 && progress > 0.45 {
            score -= 7.0 * (1.0 - progress);
        }
        // Half-zone: residual between 45% and 55% that hosts half-size next items.
        if dead_frac >= 0.45 && dead_frac <= 0.5 && next_item_size > 0 && (next_item_size as f64) >= dead * 0.5 && (next_item_size as f64) <= dead {
            score -= 11.0 * (1.0 - progress);
        }
        // Small but usable residual: bonus when tight.
        if next_item_size > 0 && dead_frac < 0.12 && dead >= next_item_size as f64 {
            score -= 5.0 * (1.0 - dead_frac / 0.12) * (1.0 - progress);
        }
        // Dead-space hosting next plus mean-residual-sized pocket.
        if next_item_size > 0 {
            let nf = next_item_size as f64;
            if dead >= nf + mean_residual.min(nf) && dead <= nf + nf {
                score -= 16.0 * (1.0 - progress);
            } else if dead > nf && dead < nf + 2.0 {
                score -= 8.0;
            }
        }
        // Wide residual pockets that cannot host the next item: penalize late.
        if dead_frac > 0.55 && next_item_size > 0 && (next_item_size as f64) > dead {
            score += 9.5 * dead_frac;
        }
        if dead_frac >= 0.55 && dead_frac < 0.75 && next_item_size > 0 && (next_item_size as f64) <= dead * 0.5 {
