        }
        if fitting_bins_count > 2 && mean_residual > 0.55 * capf {
            score += 7.5 * (1.0 - progress);
        }
        // Next item barely fits mean residual: prefer keeping it for open bins.
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 0.85 && next_item_size as f64 <= mean_residual && progress > 0.4 {
            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fitting_bins_count > 0 && mean_residual >= next_item_size as f64 && mean_residual < next_item_size as f64 + 5.0 {
            score -= 9.0 * (1.0 - progress);
        }
        if open_bins_count > 4 && fitting_bins_count > 1 && mean_residual > 0.45 * capf {
            score += 5.0 * progress;
        }
        // Perfect post-residual match for next item: keep item with open bins.
        if next_item_size > 0 && pr > 0 && pr == next_item_size && fitting_bins_count > 0 {
            score -= 12.0 * (1.0 - progress);
        }
        // Pair of item + next cannot fit mean residual either: open fresh.
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && mean_residual < (item_size as f64 + next_item_size as f64).min(capf) {
            score -= 6.5 * (1.0 - progress);
        }
        // Fresh-bin lookahead: opening now when next item is large keeps open residuals intact.
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.3 && fitting_bins_count > 1 {
            score -= 4.5 * (1.0 - progress);
        }
    }

    // Usable-floor bonus: post-residual that can host a meaningful next item.
    if pr > 0 {
        let usable_floor = (next_item_size.max(1) as f64).min(0.35 * capf);
        if (pr as f64) >= usable_floor {
            score -= 8.5 * (1.0 - progress) * ((pr as f64) / capf);
        }
    }

    // Penalize leaving residual that next item cannot use, but only if small.
    if next_item_size > pr && pr > 0 && pr < 30 {
        score += 8.0;
    }
    if pr > 0 && (pr as f64) < 0.5 * (next_item_size.max(1) as f64) && fitting_bins_count > 1 {
        score += 6.5 * (1.0 - progress);
    }
    if pr > 0 && (pr as f64) < 0.06 * capf && fitting_bins_count > 2 {
        score += 5.0 * (1.0 - progress);
    }
    if pr > 0 && fitting_bins_count > 1 && (pr as f64) < 0.1 * capf && next_item_size > 0 && (next_item_size as f64) > pr as f64 {
        score += 4.5 * (1.0 - progress);
    }

    // Late-stream small-residual refinement.
    if progress > 0.85 && pr > 0 && pr <= 2 {
        score -= 21.0;
    }
    if progress > 0.8 && pr > 0 {
        score += (pr as f64) * 0.38 * (progress - 0.8) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 (dead-space classes)
    let post_class = post_residual % 10;
    let post_quot = post_residual / 10;

    // Penalize small unusable residues (dead space < 10 is pure loss)
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }
    // Reward exact fits strongly
    if post_residual == 0 {
        score -= 40.0;
    }

    // Harmonic ladder: residues divisible by 5 are more reusable
    if post_class == 0 {
        score -= 8.0;
    } else if post_class == 5 {
        score -= 4.0;
    } else {
        score += (post_class as f64) * 0.6;
    }

    // Prefer bins whose residual pairs with next item (lookahead harmonic match)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 30.0;
            } else if slack % 10 == 0 {
                score -= 10.0;
            } else if slack < 10 {
                score += 6.0;
            }
        } else {
            // next item cannot fit here: mild penalty for wasting good residual
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when existing residuals are poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // base cost of opening a new bin
        score += 30.0;
        // open new bin if mean residual is fragmented (many unusable classes)
        if mean_residual < item_size as f64 {
            score -= 45.0 * (1.0 - progress);
        }
        // large items early benefit from fresh bin
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
        // harmonic alignment of item with capacity
        if bin_capacity % item_size == 0 {
            score -= 15.0;
        }
    }

    // Prefer tighter existing bins: lower residual before placement is better fit
    score += (bin_residual as f64 - item_size as f64) * 0.15;

    // Slight preference for bins far below mean residual (keeps big gaps for big items)
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
