pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize post_residuals that are too small
    // to be usable later (below the minimum item size of 1..100 range, use 10
    // as conservative dead-space threshold, and treat "tiny gaps" harshly).
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable sliver: heavy penalty proportional to its uselessness.
            score += 25.0 + (10 - post_residual) as f64 * 3.0;
        } else if post_residual < 20 {
            // Marginal gap: moderate penalty.
            score += 8.0 + (20 - post_residual) as f64 * 1.5;
        } else {
            // Usable gap: mild reward scaled to how much room remains.
            score -= (post_residual as f64 - 20.0) * 0.05;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 15.0;
    }

    // Reward exact-tight fits relative to bin capacity.
    let fill_ratio = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + (post_residual - next_item_size) as f64 * 0.1;
    } else if next_item_size > 0 {
        // Next item won't fit here: slight penalty for leaving a mismatched gap.
        score += 3.0;
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (compact the fuller bins, keep loose bins as long-term buffers).
    score += (mean_residual - post_residual as f64) * 0.05;

    // New-bin candidate: add a base cost so a fresh bin is only chosen when
    // it genuinely beats all open bins (dead-space logic above can override).
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual is good, but avoid tiny dead space (<10) that is unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // penalize nearly-full but useless slivers
    }

    // Aggressive 2-step lookahead: reward when next item fits into post_residual exactly/well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_post = post_residual - next_item_size;
            // Reward a two-item perfect fill strongly.
            if next_post == 0 {
                score -= 60.0;
            } else {
                score -= 30.0 - (next_post as f64) * 0.4;
            }
        } else {
            // Next item cannot follow into this bin: mild penalty scaled by overflow gap.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: prefer it only when the item is large and fits would be poor.
    if bin_residual == bin_capacity {
        let waste = bin_capacity - item_size;
        // Opening a new bin costs ~1 bin; only attractive if it leaves a large, reusable residual
        // and the current item leaves bad fit among open bins.
        let lookahead_bonus = if next_item_size > 0 && next_item_size <= waste { 15.0 } else { 0.0 };
        score = (bin_capacity - item_size.min(bin_capacity)) as f64 * 0.9 - lookahead_bonus + 20.0;
