            score -= 11.0 * (1.0 - progress);
        }
        // Large dead pocket unusable by next item: mild penalty late.
        if dead_frac > 0.55 && next_item_size > 0 && (next_item_size as f64) > dead {
            score += 9.5 * dead_frac;
        }
        // NEW: dead pocket that hosts next item plus mean residual slack.
        if next_item_size > 0 && dead >= next_item_size as f64 + mean_residual.min(next_item_size as f64) && dead <= next_item_size as f64 + next_item_size as f64 {
            score -= 16.0 * (1.0 - progress);
        }
    }

    // Pair-fill reward when bin can host item + next item together.
    if next_item_size > 0 {
        let pair = item_size as f64 + next_item_size as f64;
        if bin_residual as f64 >= pair {
            let slack = bin_residual as f64 - pair;
            score -= 42.0 - (slack / capf) * 30.0;
