        if next_item_size > 0 && mean_residual >= next_item_size as f64 && mean_residual < (item_size as f64 + next_item_size as f64).min(capf) {
            score -= 6.5 * (1.0 - progress);
        }
    }

    // Usable-pocket bonus: residual after placement that can host next item tightly.
    if next_item_size > 0 && pr >= next_item_size && pr - next_item_size > 0 && (pr - next_item_size) < item_size.max(next_item_size) {
        score -= 15.0;
    }

    // Penalize leaving residual that next item cannot use, but only if small.
    if next_item_size > pr && pr > 0 && pr < 30 {
        score += 8.0;
    }
    if pr > 0 && (pr as f64) < 0.5 * (next_item_size.max(1) as f64) && fitting_bins_count > 1 {
        score += 6.5 * (1.0 - progress);
    }
    if pr > 0 && (pr as f64) < 0.06 * capf && fitting_bins_count > 2 {
        score += 5.0 * (1.0 - progress);
    }
    if pr > 0 && fitting_bins_count > 1 && (pr as f64) < 0.1 * capf && next_item_size > 0 && (next_item_size as f64) > pr as f64 {
        score += 4.5 * (1.0 - progress);
    }
    // Usable-floor bonus: post-residual above the next item's size is worth keeping.
    if pr > 0 {
        let usable_floor = (next_item_size.max(1) as f64).min(0.35 * capf);
        if (pr as f64) >= usable_floor {
            score -= 8.5 * (1.0 - progress) * ((pr as f64) / capf);
        }
    }

    // Late-stream small-residual refinement.
    if progress > 0.85 && pr > 0 && pr <= 2 {
        score -= 21.0;
    }
    if progress > 0.8 && pr > 0 {
        score += (pr as f64) * (progress - 0.8) * 1.9;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Polynomial coupling: residual scaled by capacity, shaped by progress
    let x = pr / cap; // normalized post residual in [0,1]
    let p = 1.0 - progress;
    let coupling = x * x * (1.0 - x) * (2.0 + p) * cap * 0.5;
    score += coupling;

    // Penalize large residuals more as stream progresses (less time to fill leftovers)
    score += x.powi(3) * cap * (0.3 + 0.7 * progress);

    // Lookahead: reward residuals that fit the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= (next_item_size as f64 / cap) * (8.0 + 10.0 * progress);
    } else if next_item_size > 0 {
        // dead space that cannot host the next item
        score += x * (2.0 + 4.0 * progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0 + 20.0 * progress;
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * x;

    // Reward tight fits relative to mean residual
    score -= (mean_residual - pr).max(0.0) * 0.15;

    // Brand-new bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 10.0 - scarcity * 25.0 + 8.0 * progress;
    }

    score
}

