    score += class_penalty[post_class as usize % 5];

    // Reward near-exact fits: post_residual small is already low score; extra bonus for tiny remainder
    if post_residual <= 5 {
        score -= 10.0;
    }

    // Lookahead: does next item fit into the post residual? Harmonic modulo check
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item chains nicely; reward proportional to how "clean" the chained residual is
            let chained = post_residual - next_item_size;
            let chain_class = (chained * 4) / bin_capacity;
            score -= 4.0 + (3 - chain_class as i32) as f64 * 2.0;
            // exact chain bonus
            if chained == 0 { score -= 8.0; }
        } else {
            // next item cannot use this bin's leftover; penalize wasted potential
            let gap = next_item_size - post_residual;
            score += (gap as f64).min(20.0) * 0.4;
        }
        // modulo pairing: if next_item_size divides post_residual harmonically, favor
        if post_residual > 0 && next_item_size % (post_residual.max(1)) == 0 {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: keep it neutral-high unless open bins are nearly full
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score = cap_f * 0.5 - avg_fill * 10.0;
