        if fitting_bins_count > 1 {
            score += 20.0 * (fitting_bins_count as f64);
        }
    }

    // Mild preference for bins with residuals below mean (tighter bins first).
    score += (mean_residual - bin_residual as f64) * 0.1;

    // Early stream: slightly discourage proliferation of bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 15.0;
    }

    score
}

