    // Is this a brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // 2-step lookahead: reward exact match between post_residual and next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect fit for the next item: strongly favor this bin.
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits after this placement: mild reward scaled by tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.35 * slack;
        } else {
