            let dead = post_residual as f64;
            score += 8.0 + 0.30 * dead;
        }
    } else {
        // Last item: just prefer tightest fit (already via post_residual base).
        score -= 10.0;
    }

    // Reward tight fits relative to mean residual across open bins.
    score += 0.15 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // Penalize opening a new bin when other bins could fit (encourage consolidation),
