pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.35 * (post_residual - next_item_size) as f64;
        } else {
            score += 0.25 * (next_item_size - post_residual) as f64;
        }
    }

    // Perfect fit bonus (near-zero waste).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Dead space penalty: small unusable leftovers (below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last chance: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Crowding: when many bins are open, tighten waste tolerance.
    let crowd = (open_bins_count as f64).ln().max(1.0);
    score += 0.08 * crowd * (post_residual as f64 / bin_capacity as f64);

    // Global mean residual coupling: prefer bins near the mean residual
    // (keeps bin portfolio balanced).
    score += 0.10 * (post_residual as f64 - mean_residual).abs();

    // Time horizon: late in the stream, prioritize compact packing;
    // early, allow opening bins to build a residual pool.
    let t = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - t) * 6.0 * (post_residual as f64 / bin_capacity as f64);
    score -= t * 10.0;

    // New-bin candidate: open a fresh bin only when fits are bad
    // (large dead space) or the stream is early and bins are few.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let bad_fit = post_residual as f64 > 0.55 * bin_capacity as f64;
        if bad_fit || (t < 0.3 && open_bins_count < 3) {
            score -= 18.0;
        } else {
            score += 15.0 + 10.0 * t;
        }
    }

    score
}

