    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: post-residual (waste left behind)
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, leftover space is more costly (fewer chances to fill it)
    let pr_norm = pr / cap;
    let progress_curve = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 12.0 * pr_norm * pr_norm * progress_curve * cap / 100.0;

