    let tightness = 1.0 - pr_norm;
    score -= 8.0 * tightness * tightness * tightness;

    // Penalize bins whose residual was large relative to the item (poor packing density)
    let fill_ratio = it / br.max(1.0);
    score -= 5.0 * fill_ratio * fill_ratio;

