pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual (integer division thresholds) ---
    // Class 0: post_residual == 0 (perfect fill) -> huge reward
    // Class 1: post_residual in 1..=10  (dead space, can't fit smallest item)
    // Class 2: post_residual in 11..=25 (fits only tiny items)
    // Class 3: post_residual in 26..=50 (half-bin class, useful)
    // Class 4: post_residual > 50       (large residual, very reusable)
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 10 {
        // Dead space: penalize relative to how much was wasted
        score += 25.0 + (10 - pr) as f64 * 0.8;
    } else if pr <= 25 {
        score += 8.0;
    } else if pr <= 50 {
        score -= 6.0;
    } else {
        score -= 10.0;
    }

    // --- Modulo coupling: residual divisible by common item classes is reusable ---
    if pr > 0 {
        let m = pr % 10;
        if m == 0 {
            score -= 4.0; // aligns with decade item sizes
        } else {
            score += m as f64 * 0.3; // fragmentation penalty
        }
    }

    // --- Lookahead: does this bin still fit the NEXT item? ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0; // keeps a viable bin for the next arrival
            // Extra reward if post_residual exactly harmonically matches next item class
            if post_residual % next_item_size.max(1) == 0 {
                score -= 5.0;
            }
        } else {
            // Post-residual too small for next item: penalize proportionally
            let gap = next_item_size - post_residual;
            score += gap as f64 * 0.15;
        }
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // Only this bin can fit the item: strongly favor using it
        score -= 30.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Fresh bin: baseline preference unless open bins offer great fits.
        // Base score equals post_residual (== cap - item), adjust mildly.
        score += 15.0;
        // If stream is early or many bins open, slightly discourage hoarding new bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
        if open_bins_count > 0 && next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // A fresh bin can host item + next item chained: mild reward
            score -= 8.0;
        }
    }

    // --- Mean residual coupling: avoid worsening bin-pool balance ---
    let prf = post_residual as f64;
    if prf > mean_residual {
        score += (prf - mean_residual) * 0.1;
    } else {
        score -= (mean_residual - prf) * 0.05;
    }

    // --- Tight-fit reward: fill fraction of the bin ---
    let fill = (item_size as f64) / cap;
    score -= fill * 10.0;

    // --- Pressure term: when many bins open, prefer consolidating ---
    score += open_bins_count as f64 * 0.05;

    score
}

