}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: strongly reward leaving exactly next_item_size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Reward leaving enough room for the next item (usable residual).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 8.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
    }
    // Penalize dead space below the next item's need (unusable for lookahead).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 10.0 * (next_item_size as f64 - post_residual as f64);
    }

    // Tight fit reward: small post_residual generally good.
    score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Relative to mean residual: prefer bins that are already tight (below mean residual).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize slightly so we only open when fits are bad.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.1 * open_bins_count as f64;
    }

    // Late-stream consolidation: favor filling existing bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

