pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual relative to capacity
    let tight = post_residual as f64 / bin_capacity as f64;
    score += tight * 30.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 80.0;
    }

    // Last chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Lookahead: penalize if post_residual can't fit next item but bin_residual could
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 40.0; // chain placement possible
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 25.0; // wastes a spot for the next item
        }
        // small residual left that next item can't use = dead space
        if post_residual > 0 && post_residual < next_item_size {
            score += (post_residual as f64) * 0.5;
        }
    }

    // Prefer filling bins with larger residual first when many bins are open
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Late in stream: consolidate, avoid opening new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as stream progresses
        score += 20.0 + 80.0 * progress;
        if fitting_bins_count > 0 {
            score += 60.0;
        }
    } else {
        score -= 20.0 * progress;
    }

    // Penalize large unusable residuals relative to mean
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.2;
    }

