    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that are "dead space"
    // (too small to hold the minimum item size) are heavily penalized.
    let min_item = 1u32;
    let dead = post_residual < min_item;
    if dead {
        score += 1000.0;
    } else {
