pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits: mild reward proportional to tightness
            score -= 50.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize large dead space
            score += 30.0 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize residual far above mean residual (wasteful bin)
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Prefer fuller bins early; slight penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 50.0 + 5.0 * open_bins_count as f64;
    }

    // Progression: later in stream, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on post_residual
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 20.0;

    // Perfect fit gets strong bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: penalize if post_residual is small but insufficient for next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // residual usable by next item: reward proportionally
            score -= (next_item_size as f64 / bin_capacity as f64) * 10.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // dead space relative to lookahead item
            let waste = post_residual as f64 / next_item_size as f64;
            score += waste * 15.0;
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer it only when it's early in stream or existing fit is terrible
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 30.0;
        // cheaper to open new bin early in the stream
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 20.0;
        // cheaper when few bins are open (load balancing early)
        score -= 5.0 / (1.0 + open_bins_count as f64);
        // cheaper when open bins have small residuals (poor candidates)
        score += (mean_residual / bin_capacity as f64 - 0.5) * 10.0;
    } else {
        // Prefer bins with less residual among fitting bins (best-fit bias)
        score += (bin_residual as f64 / bin_capacity as f64) * 8.0;
    }

    // Penalize creating residuals that no typical item (>=10) can use
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    score
}

