pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space avoidance: small gaps (1..=10) are nearly unusable -> heavy penalty
    if post_residual >= 1 && post_residual <= 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual > 10 {
        // gaps that fit the next item are valuable
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 25.0;
        }
        // mid-size gaps that fit nothing likely -> mild penalty scaled by waste fraction
        let waste_frac = post / cap;
        score += 20.0 * waste_frac;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when current fit is terrible
    if bin_residual == bin_capacity {
        let fit_ratio = item / cap; // small item -> new bin cheap
        score = cap - 40.0 * (1.0 - fit_ratio);
        // discourage hoarding new bins when many already open
        score += (open_bins_count as f64) * 3.0;
        // early in stream, new bins are fine
        score -= 20.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Open-bin pressure: mild penalty per open bin for non-perfect fits
    if post_residual > 0 {
        score += (open_bins_count as f64) * 1.5;
    }

    // Reward using bins with large residuals (consolidation)
    score -= (bin_residual as f64) * 0.05;

    // Lookahead: if next item exactly fills post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 150.0;
    }

    score
}

