    let mut score = post_residual as f64;

    // Progress through the stream: early on, be more willing to open new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Dead-space penalty: residuals too small for typical future items are waste.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 1.5;
    }

    // Perfect-ish fit reward: leaving exactly 0 residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize hoarding space it can't use.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste.min(40.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + 0.3 * item_size as f64;
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // consolidating into existing bins rather than spreading.
    if open_bins_count > 2 {
        let consolidation = (mean_residual - post_residual as f64).abs();
        score += 0.05 * consolidation * (open_bins_count as f64).ln();
        // Reward bins below mean residual (tighter bins) when bins are plentiful.
        if (post_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // New-bin candidate handling: empty bin gets a baseline cost that shrinks
    // late in the stream or when the item is large relative to capacity.
