pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item (<=5)
    // are essentially unusable; penalize them strongly.
    if post_residual <= 5 {
        score += 40.0 * (1.0 - post_residual as f64 / 6.0);
    } else if post_residual <= 10 {
        score += 12.0;
    }

    // Reward tight fits (small usable post_residual relative to item size).
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 15.0 * tightness * tightness;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few,
    // opening a new bin is cheap so don't over-penalize existing bins.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 2.0;

    // New-bin candidate handling: only attractive if current bin would leave
    // a large unusable gap or cannot nicely host the lookahead item.
    if bin_residual == bin_capacity {
        let gap_bad = post_residual as f64 > 0.0 && post_residual <= 10;
        let mut s = 35.0 + pressure * 3.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            s -= 10.0; // fresh bin guarantees fit for next item too
        }
        if gap_bad {
            s += 20.0; // opening new bin won't fix a bad fit here anyway
        }
        score = s;
    }

    // Lookahead: reward if post_residual still fits the next item (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize leaving a gap that is just barely below the next item size.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Early in the stream, be slightly more willing to fill existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress);

    // Mild attraction toward bins with larger residuals (waste big spaces first).
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    score
