            // to how snugly the next item fills the remainder (best: post == next).
            let snug = 1.0 - ((post - next) / bin_capacity as f64);
            score -= 12.0 * snug;
        } else {
            // Dead space: leftover is too small for the next item.
            // Penalize more when the gap is large relative to the next item.
            let gap = (next - post) / next;
            score += 15.0 * gap;
        }

