        if post_residual == next_item_size {
            score -= 8.0;
        }
    }

    // --- Relative-to-mean-residual coupling ---
    // Prefer bins whose residual is below the mean (tight bins) for tight fits,
    // penalize wasting large-residual bins on small items.
    let post_f = post_residual as f64;
    if post_f > mean_residual {
        score += 0.6 * (post_f - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_f);
    }

    // --- Last-chance bin: strongly favor using it to avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // --- New-bin candidate handling ---
    // Only open a new bin when current fits are terrible (huge dead space)
    // and many bins are already open (pressure to keep bins tight).
    if bin_residual == bin_capacity {
        // Baseline score for a fresh bin: its residual is the capacity.
        // Make new bins attractive only if the best alternative leaves lots of waste.
        let waste_threshold = 0.35 * bin_capacity as f64;
        if post_residual as f64 > waste_threshold {
            score -= 18.0; // prefer fresh bin over wasteful placement
