    }

    // --- Fragmentation guard: penalize leaving small unusable slivers ---
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // --- Early stream: be slightly conservative, keep bins open for flexibility ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * (1.0 - progress);

    score
}

