pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: best-fit preference with slight superlinear penalty on wasted space
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
        // Penalize leaving residual that no typical item can use (dead space)
        if post_residual > 0 && post_residual < 10 {
            score += 15.0;
        }
    } else {
        // Last item: prefer tightest fill
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 0.1 * step_index as f64;
    }

    // Many open bins: prefer consolidating into existing bins
    let crowding = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
    if bin_residual < bin_capacity {
        score -= 2.0 * crowding;
    }

    // Mean residual coupling: bins below mean residual are "fuller", favor them
    if bin_residual < bin_capacity {
        score -= 0.5 * (mean_residual - bin_residual as f64);
    }

    // Time horizon: late in stream, tighten packing (favor near-full bins more)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New empty bin candidate: penalize unless existing options are poor
    if bin_residual == bin_capacity {
        score += 40.0 + 20.0 * (1.0 - progress);
        // But if item is large relative to mean residual, new bin is attractive
        if (item_size as f64) > mean_residual + 20.0 {
            score -= 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capf = bin_capacity as f64;
    let pr = post_residual;
    let dead = bin_residual as f64 - item_size as f64;
    let dead_frac = if dead > 0.0 { dead / capf } else { 0.0 };
    let progress = step_index as f64 / total_items.max(2) as f64;
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    let rem_frac = if total_items > step_index { (total_items - step_index) as f64 / total_items.max(1) as f64 } else { 0.0 };
    let mut score = pr as f64;

    // Tiered post-residual rewards.
    if pr == 0 {
        score -= 520.0;
    } else if pr <= 3 {
        score -= 240.0;
    } else if pr <= 5 {
        score -= 120.0;
    } else if pr <= 16 {
        score -= 70.0;
    } else if pr <= 40 {
        score -= 14.0;
    } else if pr <= 66 {
        score -= 3.0;
    }

    // Dead-space penalty: residuals too small for typical items are waste.
    if pr > 0 && pr < 20 {
        score += (20.0 - pr as f64) * (20.0 - pr as f64) * 0.58;
    }

    // Two-step lookahead.
    if next_item_size > 0 {
        let nf = next_item_size as f64;
        if next_item_size == pr {
            score -= 320.0;
        } else if next_item_size + 1 == pr {
            score -= 175.0;
        } else if next_item_size <= pr {
            let waste = (pr - next_item_size) as f64;
            score -= waste * 2.3;
            if (waste as u32) % 10 == 0 && waste > 0.0 {
                score -= 22.0;
            }
        } else {
            let miss = (next_item_size - pr) as f64;
            score += miss.min(50.0) * 0.65 + 7.0;
        }
        // Dead-space shaping relative to next item.
        if dead > 0.0 {
            if dead < nf {
                score += 11.0 + (nf - dead) * 0.9;
            } else if dead as u32 == next_item_size {
                score -= 50.0;
            } else {
                score -= dead * (0.05 + 0.05 * rem_frac) + dead_frac * dead_frac * 44.0;
            }
            if dead as u32 >= next_item_size {
                let after = dead as u32 - next_item_size;
                if after <= 2 {
                    score -= 22.0;
                } else if (after as f64) <= 0.04 * capf {
                    score -= 9.0;
                }
            }
            if dead > nf && dead <= nf + 3.0 {
                score -= 16.0 * (1.0 - progress);
            }
            if dead >= nf && dead <= 1.5 * nf && progress > 0.5 {
                score -= 8.0 * (1.0 - progress);
            }
            if dead > nf + 6.0 && dead < nf + mean_residual.max(nf) {
                score += (dead - nf) * 0.32 * (0.3 + 0.7 * (1.0 - progress));
            }
            if dead > nf + mean_residual {
                score += (dead - nf - mean_residual) * 0.2 * (0.5 + 0.5 * progress);
            }
        }
        // Pair-fill reward.
        let pair = item_size as f64 + nf;
        if bin_residual as f64 >= pair {
            let slack = bin_residual as f64 - pair;
            score -= 38.0 - (slack / capf) * 28.0;
        }
        if pr > 0 && (pr as f64) >= nf && (pr as f64) < nf + 4.0 {
            score -= 13.0 * (1.0 - progress);
        }
        if pr > 0 && (pr as f64) >= nf && (pr as f64) <= nf * 2.0 {
            score -= 6.0 * (1.0 - progress) * (1.0 - ((pr as f64) - nf) / next_item_size.max(1) as f64 * 0.5);
        }
    } else if dead > 0.0 {
        score -= dead * (0.05 + 0.05 * rem_frac) + dead_frac * dead_frac * 44.0;
    }

    if dead_frac > 0.1 && dead_frac < 0.45 {
        let bump = (dead_frac - 0.275) * (dead_frac - 0.275);
        score += bump * 26.0 * (0.4 + 0.6 * (1.0 - progress));
    }
    if dead_frac > 0.3 && progress > 0.6 {
        score += dead_frac * (progress - 0.6) * 30.0;
    }
    if dead_frac > 0.05 && dead_frac < 0.25 && progress > 0.35 {
        score += dead_frac * (progress - 0.35) * 21.0;
    }
    if dead < 0.05 * capf && open_bins_count > 2 {
        score += 5.0 * (1.0 - dead / (0.05 * capf));
    }
    if dead > 0.0 && dead < 4.0 && pr > 4 {
        score += 13.0;
    }
    if dead > 0.0 && dead_frac > 0.1 && (dead - mean_residual).abs() < 3.0 {
        score -= 8.0 * (1.0 - progress);
    }
    if dead > 0.0 && progress < 0.7 && (dead - mean_residual).abs() < 2.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // Consolidation pressure.
    score -= bin_pressure * 2.0 * (1.0 - progress);

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Mean-residual anchoring.
    score -= (0.35 + 0.16 * progress) * (mean_residual - pr as f64);

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let next_tight = next_item_size > 0 && mean_residual < next_item_size as f64;
        if next_tight || fitting_bins_count <= 1 {
            score -= 32.0;
        } else {
            score += 36.0 + 1.8 * bin_pressure;
        }
        if item_size as f64 > 0.6 * capf {
            score -= 13.0;
        }
        if item_size as f64 > 0.78 * capf && mean_residual < 0.22 * capf {
            score -= 27.0;
        }
        if item_size as f64 > 0.85 * capf && mean_residual < 0.12 * capf {
            score -= 30.0;
        }
        if item_size as f64 > 0.93 * capf {
            score -= 20.0;
        }
        if next_item_size > 0 && (item_size as f64 + next_item_size as f64) > capf {
            score -= 16.0;
        }
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 6.0 + (next_item_size as f64 - mean_residual) * 0.12;
        }
        if progress > 0.7 && open_bins_count > 3 {
            score += 18.0 * progress;
        }
        let spread = (mean_residual - item_size as f64).abs();
        if spread < 0.08 * capf && fitting_bins_count > 2 {
            score += 9.0;
        }
        if item_size as f64 > mean_residual * 1.6 && fitting_bins_count > 1 && open_bins_count > 2 {
            score -= 14.0 * (1.0 - progress);
        }
        if fitting_bins_count > 1 && mean_residual < item_size as f64 * 0.4 {
            score += 11.0;
        }
        if next_item_size > 0 && next_item_size as f64 > 0.5 * capf && mean_residual > 0.3 * capf {
            score -= 10.0;
        }
        if next_item_size > 0 && item_size as f64 > 0.55 * capf && (capf - item_size as f64) < next_item_size as f64 && mean_residual >= item_size as f64 {
            score += 22.0 * (1.0 - progress);
        }
        let rem_items = if total_items > step_index { (total_items - step_index) as f64 } else { 0.0 };
        if rem_items > 0.15 * total_items.max(1) as f64 && mean_residual < 0.5 * (next_item_size.max(1) as f64) {
            score -= 14.0 * (1.0 - progress);
        }
        if fitting_bins_count > 2 && mean_residual > 0.55 * capf {
            score += 7.0 * (1.0 - progress);
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 0.85 && next_item_size as f64 <= mean_residual && progress > 0.4 {
            score -= 7.5 * (1.0 - progress);
        }
        if open_bins_count > 4 && fitting_bins_count > 1 && mean_residual > 0.45 * capf {
            score += 5.0 * progress;
        }
    }

    // Usable-pocket bonus.
    if next_item_size > 0 && pr >= next_item_size && pr - next_item_size > 0 && (pr - next_item_size) < item_size.max(next_item_size) {
        score -= 14.0;
    }

    // Penalize residual next item cannot use.
    if next_item_size > pr && pr > 0 && pr < 30 {
        score += 8.0;
    }
    if pr > 0 && (pr as f64) < 0.5 * (next_item_size.max(1) as f64) && fitting_bins_count > 1 {
        score += 6.0 * (1.0 - progress);
    }
    if pr > 0 && (pr as f64) < 0.06 * capf && fitting_bins_count > 2 {
        score += 5.0 * (1.0 - progress);
    }

    // Late-stream tightness.
    if progress > 0.85 && pr > 0 && pr <= 2 {
        score -= 21.0;
    }
    if progress > 0.8 && pr > 0 {
        score += pr as f64 * 0.37 * (progress - 0.8) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += poly * cap * 0.5;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (20.0 + 60.0 * progress);

    // Penalize dead space relative to mean residual
    score += (pr - mean_residual).max(0.0) * (0.3 + 0.7 * progress);

    // Last-chance bonus: strongly prefer this bin if it is the only fitting one
    if fitting_bins_count == 1 {
        score -= 50.0 * (1.0 + progress);
    }

    // Lookahead: reward leaving space usable by next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 15.0 * (1.0 - ((pr - nx) / cap).abs());
        } else {
            score += 10.0;
        }
    }

    // Mild penalty for spreading across too many open bins early
    score += (open_bins_count as f64).ln() * (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by capacity fraction.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity wasted after placement

    // Harmonic buckets: 0 (perfect), 1 (tiny slack), 2 (medium), 3 (large dead space)
    let class = if post_residual == 0 { 0u32 }
        else if post_residual <= bin_capacity / 10 { 1 }
        else if post_residual <= bin_capacity / 4 { 2 }
        else { 3 };

    match class {
        0 => score -= 40.0,                       // perfect fit: strong reward
        1 => score -= 18.0,                       // near-perfect
        2 => score += 6.0,                        // mildly wasteful
        _ => score += 14.0 * frac,                // penalize large dead space
    }

    // Modulo arithmetic on post_residual: residuals divisible by common item
    // granularity (gcd-style classes) are more reusable.
    if post_residual > 0 {
        let m = post_residual % 10;
        if m == 0 { score -= 8.0; }               // multiple of 10: highly reusable
        else if m <= 2 { score -= 3.0; }          // near multiple
        else { score += 2.0 + 0.5 * m as f64; }   // awkward remainder
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
        // bonus if next item exactly divides the post residual (harmonic pair)
        if post_residual % next_item_size == 0 {
            score -= 6.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // dead space the known next item cannot use
        score += 4.0 + 0.25 * pr;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless current bin would leave
    // large dead space and mean residual is already high.
    if bin_residual == bin_capacity {
        score += 30.0;
        if mean_residual > 0.5 * cap {
            score -= 20.0; // open bins are bloated; a fresh bin is reasonable
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin can serve the next item too
        }
    }

    // Progress-aware tie-breaking: late in the stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += frac * 10.0 * progress;
    score -= (bin_capacity - bin_residual) as f64 * 0.05; // favor fuller bins

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capf = bin_capacity as f64;
    let pr = post_residual;
    let dead = bin_residual as f64 - item_size as f64;
    let dead_frac = if dead > 0.0 { dead / capf } else { 0.0 };
    let mut score = pr as f64;
