pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward filling bins that are mostly empty of dead space relative to mean residual.
    score -= (bin_residual as f64 - mean_residual) * 0.15;

    // Open-bins pressure: encourage reusing bins when many are open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    }

    // New-bin candidate: penalize opening a new bin unless current bins are nearly full.
    if bin_residual == bin_capacity {
        let pressure = if mean_residual > 0.0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        score += 30.0 + (1.0 - pressure) * 40.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
        // Late in the stream, avoid opening bins for small items.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 && item_size < 40 {
            score += 25.0;
        }
    }

    score
}

