    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 {
        // Penalize distance between post_residual and next item size.
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        score += diff as f64 * 0.25;
        // Small bonus if next item still fits after this placement.
        if post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Penalize dead space (residual too small to ever be useful, min item = 1).
    if post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (compact packing).
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Early in stream: mildly prefer opening fresh bins to build structure.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline competitive score, adjusted by progress.
        score = 45.0 + 25.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Many open bins: discourage opening more bins.
    if bin_residual != bin_capacity {
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    score
}

