    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tightness reward: fraction of bin consumed by this item.
    let fill_ratio = item / cap;
    score -= 30.0 * fill_ratio;

    // Penalize large dead space relative to typical incoming item sizes.
    // Dead space is only "wasted" if no plausible future item can use it.
    let small_item_bound = 1.0f64.min(post / 80.0);
    if post > 0.0 {
        score += 10.0 * (1.0 - small_item_bound) * (post / cap);
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = post - nxt;
            // Perfect follow-up match is highly desirable.
            if slack == 0.0 {
                score -= 45.0;
            } else {
                score -= 20.0 * (1.0 - slack / cap);
            }
        } else {
            // Next item cannot use the leftover: penalize proportional waste.
            score += 8.0 * ((nxt - post) / cap);
        }
    } else {
        // Last item in stream: filling an existing bin is always better than a new bin.
        score -= 60.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * (1.0 - post / cap);
    }

    // New-bin candidate handling: opening a bin is expensive when open bins exist
    // and residuals are still useful.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let useful_open = mean_residual / cap;
        // Cost of a new bin grows with number of open bins and remaining stream.
        let new_bin_cost = 35.0 + 20.0 * (1.0 - progress) + 3.0 * open_bins_count as f64;
        // But a new bin is attractive if all existing residuals are too fragmented
