        score = new_bin_cost - 40.0 * fragmentation * useful_open + post;
        if next_item_size > 0 && (next_item_size as f64) <= cap - item {
            score -= 15.0; // fresh bin can host the next item too
        }
    }

    // Slight preference for bins whose residual is close to the mean (keep balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

