        let pair = item_size as f64 + next_item_size as f64;
        if bin_residual as f64 >= pair {
            let slack = bin_residual as f64 - pair;
            score -= 40.0 - (slack / capf) * 30.0;
        }
        if pr > 0 && (pr as f64) >= next_item_size as f64 && (pr as f64) < next_item_size as f64 + 4.0 {
            score -= 14.0 * (1.0 - progress);
        }
    }

    // Consolidation pressure when many bins are open, stronger early.
    score -= bin_pressure * 2.4 * (1.0 - progress);

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 52.0;
    }

    // Mean-residual anchoring.
    score -= (0.4 + 0.17 * progress) * (mean_residual - pr as f64);

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let next_tight = next_item_size > 0 && mean_residual < next_item_size as f64;
        if next_tight || fitting_bins_count <= 1 {
            score -= 34.0;
        } else {
            score += 38.0 + 1.5 * bin_pressure;
        }
        if open_bins_count > 0 && fitting_bins_count > 1 && progress > 0.5 {
            score += 26.0;
        }
        if item_size as f64 > 0.6 * capf {
            score -= 13.0;
        }
        if item_size as f64 > 0.78 * capf && mean_residual < 0.22 * capf {
            score -= 27.0;
        }
        if item_size as f64 > 0.85 * capf && mean_residual < 0.12 * capf {
            score -= 32.0;
        }
        if item_size as f64 > 0.93 * capf {
            score -= 21.0;
        }
        if next_item_size > 0 && (item_size as f64 + next_item_size as f64) > capf {
            score -= 17.0;
        }
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 6.0 + (next_item_size as f64 - mean_residual) * 0.13;
        }
        if progress > 0.7 && open_bins_count > 3 {
            score += 19.0 * progress;
        }
        let spread = (mean_residual - item_size as f64).abs();
        if spread < 0.08 * capf && fitting_bins_count > 2 {
            score += 9.5;
        }
        if item_size as f64 > mean_residual * 1.6 && fitting_bins_count > 1 && open_bins_count > 2 {
            score -= 15.0 * (1.0 - progress);
        }
        if fitting_bins_count > 1 && mean_residual < item_size as f64 * 0.4 {
            score += 12.0;
        }
        if next_item_size > 0 && next_item_size as f64 > 0.5 * capf && mean_residual > 0.3 * capf {
            score -= 10.5;
        }
        if fitting_bins_count > 1 && dead as f64 > 0.35 * capf && item_size as f64 > mean_residual * 1.25 {
            score -= 11.0 * (1.0 - progress);
        }
        if next_item_size > 0 && item_size as f64 > 0.55 * capf && (capf - item_size as f64) < next_item_size as f64 && fitting_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 24.0 * (1.0 - progress);
        }
        let rem_items = if total_items > step_index { (total_items - step_index) as f64 } else { 0.0 };
        if rem_items > 0.15 * total_items.max(1) as f64 && mean_residual < 0.5 * (next_item_size.max(1) as f64) {
            score -= 15.0 * (1.0 - progress);
        }
        if fitting_bins_count > 2 && mean_residual > 0.55 * capf {
            score += 7.5 * (1.0 - progress);
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 0.85 && next_item_size as f64 <= mean_residual && progress > 0.4 {
            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fitting_bins_count > 0 && mean_residual >= next_item_size as f64 && mean_residual < next_item_size as f64 + 5.0 {
            score -= 9.0 * (1.0 - progress);
        }
        if open_bins_count > 4 && fitting_bins_count > 1 && mean_residual > 0.45 * capf {
            score += 5.0 * progress;
        }
        if next_item_size > 0 && pr > 0 && pr == next_item_size && fitting_bins_count > 0 {
            score -= 12.0 * (1.0 - progress);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && mean_residual < (item_size as f64 + next_item_size as f64).min(capf) {
            score -= 6.5 * (1.0 - progress);
        }
        if fitting_bins_count > 0 && progress > 0.55 && mean_residual > item_size as f64 {
            score += 8.0 * progress;
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let nf = next_item_size as f64;
            if dead >= 0.0 && dead <= nf + 2.0 {
                score += 6.0 * (1.0 - progress);
            }
        }
        if fitting_bins_count > 0 && open_bins_count > 2 && progress > 0.35 && mean_residual >= item_size as f64 {
            score += 5.0 + 6.0 * progress;
        }
        if progress > 0.6 && fitting_bins_count > 1 && next_item_size > 0 && item_size as f64 <= 0.5 * capf {
            score += 14.0 * progress;
        }
    }

    // Usable-pocket bonus: residual after placement tightly hosts next item.
    if next_item_size > 0 && pr >= next_item_size && pr - next_item_size > 0 && (pr - next_item_size) < item_size.max(next_item_size) {
        score -= 15.0;
    }

    // Penalize residual next item cannot use, if small.
    if next_item_size > pr && pr > 0 && pr < 30 {
        score += 8.0;
    }

    if pr > 0 {
        let usable_floor = (next_item_size.max(1) as f64).min(0.35 * capf);
        if (pr as f64) >= usable_floor {
            score -= 8.5 * (1.0 - progress) * ((pr as f64) / capf);
        }
    }
    if pr > 0 && (pr as f64) < 0.5 * (next_item_size.max(1) as f64) && fitting_bins_count > 1 {
        score += 6.5 * (1.0 - progress);
    }
    if pr > 0 && (pr as f64) < 0.06 * capf && fitting_bins_count > 2 {
        score += 5.0 * (1.0 - progress);
    }
    if pr > 0 && fitting_bins_count > 1 && (pr as f64) < 0.1 * capf && next_item_size > 0 && (next_item_size as f64) > pr as f64 {
        score += 4.5 * (1.0 - progress);
    }

    // Late-stream small-residual refinement.
    if progress > 0.85 && pr > 0 && pr <= 2 {
        score -= 21.0;
    }
    if progress > 0.8 && pr > 0 {
        score += (pr as f64) * (progress - 0.8) * 1.9;
    }

    if pr > 0 && next_item_size > 0 {
        let nf = next_item_size as f64;
        if (pr as f64) >= nf && (pr as f64) - nf <= mean_residual.max(nf) {
            score -= 5.0 * (1.0 - progress);
        }
        if (pr as f64) > nf && (pr as f64) < nf + 3.0 {
            score -= 10.0 * (1.0 - progress);
        }
        if (pr as f64) >= nf && (pr as f64) <= nf * 2.0 {
            score -= 6.0 * (1.0 - progress) * (1.0 - ((pr as f64) - nf) / nf.max(1.0) * 0.5);
        }
    }

    if dead > 0.0 && progress < 0.7 && (dead - mean_residual).abs() < 2.5 {
        score -= 7.0 * (1.0 - progress);
    }
    if dead > 0.0 && dead_frac > 0.1 && (dead - mean_residual).abs() < 3.0 {
        score -= 9.0 * (1.0 - progress);
    }
    if pr > 0 && next_item_size > 0 && dead > 0.0 {
        let nf = next_item_size as f64;
        if (pr as f64) >= nf && dead <= mean_residual.max(nf) {
            score -= 4.5 * (1.0 - progress) * (1.0 - dead_frac);
        }
        if (pr as f64) < nf && dead < 0.5 * nf {
            score += 5.0 * (1.0 - progress);
        }
    }
    if dead > 0.0 && next_item_size > 0 && dead > next_item_size as f64 + mean_residual {
        score += (dead - next_item_size as f64 - mean_residual) * 0.22 * (0.5 + 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear waste penalty: squared normalized residual, growing with progress
    let waste = (pr / cap).powi(2) * (1.0 + 3.0 * progress) * 30.0;

    // Reward tight fits: smooth coupling of post_residual with item_size
    let tightness = (item_size as f64 / cap).powi(2) * (cap - pr) * 0.8;

    // Lookahead: penalize if leftover residual cannot host next item (smooth logistic)
    let lookahead_pen = if next_item_size > 0 {
        let fits = (pr >= next_item_size as f64) as i32 as f64;
        let margin = (pr - next_item_size as f64) / cap;
        let logistic = 1.0 / (1.0 + (-margin * 8.0).exp());
        (1.0 - fits) * 25.0 + fits * (1.0 - logistic) * 12.0
    } else {
        0.0
    };

    // Last-chance bin: strong reward to use it rather than open a new bin
    let last_chance = if fitting_bins_count == 1 { -20.0 } else { 0.0 };

    // New-bin candidate: mildly discourage unless open bins are nearly full on average
    let is_new = (bin_residual as f64 == cap) as i32 as f64;
    let crowding = (mean_residual / cap).powi(2);
    let new_bin_pen = is_new * (10.0 + 40.0 * (1.0 - crowding)) + is_new * open_bins_count as f64 * 0.5;

    // Smooth interaction: residual spread vs mean residual
    let spread = (pr - mean_residual) / cap;
    let spread_pen = spread * spread * 10.0;

    let mut score = base + waste + lookahead_pen + spread_pen + new_bin_pen - tightness + last_chance;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit classes are highly desirable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;

    // Reward tight fits (small post residual) with a nonlinear bonus.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 25.0;
    } else {
        // Dead-space penalty grows quadratically for large residuals,
        // but only if it cannot host the lookahead item.
        if next_item_size == 0 || post_residual < next_item_size {
            score += (pr * pr) / cap;
        } else {
            score -= 8.0; // residual is useful for next item
        }
    }

    // Harmonic classes: residuals near capacity fractions are "clean" states.
    let quarters = (pr * 4.0 / cap).round();
    let harmonic_dev = (pr - quarters * cap / 4.0).abs();
    score += harmonic_dev * 0.15;

    // Modulo logic on post_residual: multiples of common item sizes (10, 20, 25, 50)
    // are easier to fill later.
    let mod_bonus = if post_residual % 50 == 0 {
        12.0
    } else if post_residual % 25 == 0 {
        8.0
    } else if post_residual % 20 == 0 {
        6.0
    } else if post_residual % 10 == 0 {
        4.0
    } else {
        0.0
    };
    score -= mod_bonus;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // bin would leave a very awkward residual.
    if bin_residual == bin_capacity {
        // Fresh bin: baseline score, slightly penalized so we prefer good fits
        // into existing bins, but attractive when existing fits are bad.
        score += 15.0;
        // If lookahead item is large and this item is small, a fresh bin is fine.
        if next_item_size >= item_size as u32 {
            score -= 10.0;
        }
    }

    // Lookahead pairing: if the post residual exactly fits next item, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Progress-aware tightening: later in the stream, prefer tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    // Mild preference to keep mean residual balanced (avoid skew).
    score += (mean_residual - pr).abs() * 0.05;

    score
}
